        // Army.PAS:5524
        public override void Show(int XhpSurf, int YhpSurf, in TSurfaceDesc SurfaceDesc)
        {
            TSurfaceDesc SurfaceDesc__value = SurfaceDesc;
            TImageSequence Sequence;
            int Frame;
            void ShowGlobal(bool Shadow, bool Inverse)
            {
                int Brightness = default;
                var count = FPath.Count;
                Brightness = 100 - FFrame * 100 / count - (FFrame % 10 * 2 + ObjectToInt(this)) % 20;
                if (Brightness < 0)
                {
                    Brightness = 0;
                }

                if (Shadow)
                {
                    Brightness += 20;
                }

                if (Brightness > 100)
                {
                    Brightness = 100;
                }

                while (Sequence != null)
                {
                    // { Original uses the instance address as the animation phase. }
                    Frame = Sequence.GetUnloopedFrameIndex(ObjectToInt(this) % 3);
                    if (Frame != -1)
                    {
                        if (Shadow)
                        {
                            if (Sequence.ImageLibrary.ImageExist(Frame))
                            {
                                var item = FPath[FFrame];
                                var fPathItem = FPath[FFrame];
                                var item2 = FPath[FFrame];
                                Sequence.ImageLibrary[Frame].ShowBlended(item2.X + (SurfaceDesc__value.Width * FX / 100 + Sequence.dXshift), item.Y + (SurfaceDesc__value.Height * FY / 100 + Sequence.dYshift) - fPathItem.Z, SurfaceDesc__value, ShadowBlendTable.LookupTables[Brightness]);
                            }
                        }
                        else
                        {
                            if (Inverse)
                            {
                                if (Sequence.ImageLibrary.ImageExist(Frame))
                                {
                                    var item = FPath[FFrame];
                                    var fPathItem = FPath[FFrame];
                                    var item2 = FPath[FFrame];
                                    Sequence.ImageLibrary[Frame].ShowBlended(item2.X + (SurfaceDesc__value.Width * FX / 100 + Sequence.dXshift), item.Y + (SurfaceDesc__value.Height * FY / 100 + Sequence.dYshift) - fPathItem.Z, SurfaceDesc__value, IntensityBlendTable.LookupTables[100 - Brightness]);
                                }
                            }
                            else
                            {
                                if (Sequence.ImageLibrary.ImageExist(Frame))
                                {
                                    var item = FPath[FFrame];
                                    var fPathItem = FPath[FFrame];
                                    var item2 = FPath[FFrame];
                                    Sequence.ImageLibrary[Frame].ShowBlended(item2.X + (SurfaceDesc__value.Width * FX / 100 + Sequence.dXshift), item.Y + (SurfaceDesc__value.Height * FY / 100 + Sequence.dYshift) - fPathItem.Z, SurfaceDesc__value, IntensityBlendTable.LookupTables[Brightness]);
                                }
                            }
                        }
                    }

                    Sequence = Sequence.Next;
                }
            }

            void ShowLocal(bool Shadow)
            {
                int Brightness = default;
                var count = FPath.Count;
                Brightness = 100 - FFrame * 100 / count - (FFrame % 10 * 2 + ObjectToInt(this)) % 20;
                if (Brightness < 0)
                {
                    Brightness = 0;
                }

