                                var item2 = FPath[FFrame];
                                Sequence.ImageLibrary[Frame].ShowBlended(item2.X + Sequence.dXshift - XhpSurf, item.Y + Sequence.dYshift - fPathItem.Z - YhpSurf, SurfaceDesc__value, ShadowBlendTable.LookupTables[Brightness]);
