                                for (int I = 0; I <= 29; I++)
                                {
                                    Effect = AoWE.AoWHSMap.AddEffect(TworldFXType.fxSWParticle);
                                    Effect.FX = 50;
                                    Effect.FY = 50;
                                    RadiusX = -RadiusX;
                                    var pi = Math.PI;
                                    var sin = Math.Sin((double)((double)(I * 12 + FFrame * 5) * pi) / 180);
                                    var random = Random(10);
                                    var mathPI = Math.PI;
                                    MakeArcPathXY((short)Round((double)Math.Cos((double)((double)(I * 12 + FFrame * 5) * mathPI) / 180) * (RadiusX + Random(10))), (short)(Round((double)sin * (RadiusY + random)) / 2), 0, -150, 100, 10, ref Effect.FPath);
                                    for (int J = 0, last = Effect.FPath.Count - 1; J <= last; J++)
                                    {
                                        var item = Effect.FPath[J];
                                        Effect.FPath[J].Z = -item.Z;
                                    }
                                }
                            }

                                break;
                        }

                        switch (FFrame)
                        {
                            case >= 15 and <= 44:
                                if (FFrame % 5 == 0)
                                {
                                    Count = Random(10) + 100;
                                    for (int J = 0; J <= Count; J++)
                                    {
                                        Effect = AoWE.AoWHSMap.AddEffect(TworldFXType.fxSWBeamParticle);
                                        Effect.FX = 50;
                                        Effect.FY = 50;
                                        Speed = (float)((double)(Random(50) + 50) * 0.1);
                                        Gravity = (float)0.1;
                                        VZ = (float)((double)(Random(5) + 5) * 0.1);
                                        Z = 0;
                                        MakeArcPath(0, -150, Random(360), ref Z, ref Speed, ref VZ, ref Gravity, ref Effect.FPath);
                                    }
                                }

                                break;
                            case 120:
                                FFrame = -1;
                                break;
                        }

                        break;
                    case TworldFXType.fxEarthMastery:
                        switch (FFrame)
                        {
                            case >= 0 and <= 49:
                            {
                                for (int I = 0; I <= 29; I++)
                                {
                                    Effect = AoWE.AoWHSMap.AddEffect(TworldFXType.fxEMParticle);
                                    RadiusX = Random(12);
                                    var pi = Math.PI;
                                    Effect.FX = Round((double)Math.Cos((double)((double)(I * 12 + RadiusX) * pi) / 180) * FFrame) + 50;
                                    var mathPI = Math.PI;
                                    Effect.FY = Round((double)Math.Sin((double)((double)(I * 12 + RadiusX) * mathPI) / 180) * FFrame) / 2 + 50;
                                    MakeLinePath(0, 0, 0, FFrame * 3 - 200, 30, ref Effect.FPath);
                                }
                            }

                                break;
                            case 200:
                                FFrame = -1;
                                break;
                        }

                        break;
                    case TworldFXType.fxWMParticle:
                    case TworldFXType.fxWMLParticle:
                    case TworldFXType.fxHatredParticle:
                    case TworldFXType.fxSWParticle:
                    case TworldFXType.fxSWBeamParticle:
                    case TworldFXType.fxEMParticle:
                    case TworldFXType.fxTranqParticle:
                        var count = FPath.Count;
                        if (FFrame >= count - 1)
                        {
                            FFrame = FPath.Count - 1;
                            FDone = true;
                        }

                        break;
                }

                if (FFrame == -1)
                {
                    FDone = true;
                }
            }
            catch (System.Exception)
            {
                MessageBox(0, (AnsiString)"Error - WorldfxHS " + IntToStr((int)FEffectType), (AnsiString)"Error during NewFrame", 0);
            }
        }

