        // Structur.PAS:295
        public virtual void ExecuteCancelProduction()
        {
            sbyte Player;
            if (FStatus == TProductionControlStatus.pcsProducing)
            {
                if (FSettings.FGroupID != 0)
                {
                    UnregisterGroupProduction();
                }

                Player = GetPlayer();
                if (Player > -1)
                {
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    var cancelProductionReturnGold = CancelProductionReturnGold();
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).SetGems(players.FGems + cancelProductionReturnGold);
                    var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    var cancelProductionReturnMana = CancelProductionReturnMana();
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + cancelProductionReturnMana);
                }

                FSettings.Clear();
                FStatus = TProductionControlStatus.pcsWaiting;
                Update();
            }
