            {
                ExecuteDeleteProductions();
                Item = new TProductionItem(null);
                Item.FProductionID = 2;
                Item.FParameter = Index;
                ExecuteAddProduction(Item);
                Item.Free();
                Result = true;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Structur.PAS:392
        public virtual bool ExecuteProduction(TProductionItem Item)
        {
            bool Result;
            AnsiString Reason = default;
            if (CanExecuteProduction(Item, ref Reason))
            {
                BeginUpdate();
                ExecuteCancelProduction();
                FStatus = TProductionControlStatus.pcsWaiting;
                switch (Item.FProductionID)
                {
                    case 1:
                        FSettings.Clear();
                        FSettings.FUnitProductionIndex = Item.FParameter;
                        var unitProduction = CreateUnitProduction(Item.FParameter);
                        FSettings.FUnit = unitProduction;
                        var unitProductionGold = UnitProductionGold(Item.FParameter);
                        FSettings.FGold = unitProductionGold;
                        var unitProductionMana = UnitProductionMana(Item.FParameter);
                        FSettings.FMana = unitProductionMana;
                        var unitProductionGoldUpkeep = UnitProductionGoldUpkeep(Item.FParameter);
                        FSettings.FGoldUpkeep = unitProductionGoldUpkeep;
                        var unitProductionManaUpkeep = UnitProductionManaUpkeep(Item.FParameter);
                        FSettings.FManaUpkeep = unitProductionManaUpkeep;
                        FSettings.FGroupID = Item.FGroupID;
                        var unitProductionTime = UnitProductionTime(Item.FParameter);
                        FSettings.FTurnsTotal = (sbyte)unitProductionTime;
                        var player3 = GetPlayer();
                        FSettings.FPlayer = player3;
                        FSettings.FTurnsLeft = FSettings.FTurnsTotal;
                    {
                        var player = AoWE.AoWHSMap.FPlayers.GetPlayers(FSettings.FPlayer);
                        player.SetGems(player.FGems - this.FSettings.FGold);
                        player.FMagicControl.SetMana(player.FMagicControl.FMana - this.FSettings.FMana);
                    }

                        FStatus = TProductionControlStatus.pcsProducing;
                        if (FSettings.FGroupID != 0)
                        {
                            RegisterGroupProduction();
                        }

                        break;
                    case 2:
                        FSettings.Clear();
                        FSettings.FUnitProductionIndex = Item.FParameter;
                        var unitResearchGold = UnitResearchGold(Item.FParameter);
                        FSettings.FGold = unitResearchGold;
                        FSettings.FMana = 0;
                        var unitResearchTime = UnitResearchTime(Item.FParameter);
                        FSettings.FTurnsTotal = (sbyte)unitResearchTime;
                        var player4 = GetPlayer();
                        FSettings.FPlayer = player4;
                        FSettings.FTurnsLeft = FSettings.FTurnsTotal;
                    {
                        var player2 = AoWE.AoWHSMap.FPlayers.GetPlayers(FSettings.FPlayer);
                        player2.SetGems(player2.FGems - this.FSettings.FGold);
                        player2.FMagicControl.SetMana(player2.FMagicControl.FMana - this.FSettings.FMana);
                    }

                        FStatus = TProductionControlStatus.pcsProducing;
                        break;
                }

                EndUpdate();
                Result = true;
            }
            else
            {
                FStatus = TProductionControlStatus.pcsWaiting;
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:450
        public virtual void ExecuteAddProduction(TProductionItem Item)
        {
            TProductionItem NewItem;
            BeginUpdate();
            NewItem = (TProductionItem)Item.Copy(AoWE.AoWEngine);
            NewItem.SetOwner(FQueue);
            if (FQueue.Count == 1)
            {
                ExecuteProduction(NewItem);
            }

            EndUpdate();
        }

        // Structur.PAS:461
        public virtual void ExecuteDeleteProduction(int Index)
        {
            BeginUpdate();
            if (Index == 0)
            {
                ExecuteCancelProduction();
                FQueue.GetItem(Index).Free();
                if (FQueue.Count != 0)
                {
                    ExecuteProduction(FQueue.GetItem(0));
                }
                else
                {
                    FStatus = TProductionControlStatus.pcsIdle;
                }
            }
            else
            {
                FQueue.GetItem(Index).Free();
            }

            EndUpdate();
        }

        // Structur.PAS:475
        public virtual void ExecuteDeleteProductions()
        {
            BeginUpdate();
            ExecuteCancelProduction();
            FQueue.Clear();
            EndUpdate();
        }

        // Structur.PAS:514
        public virtual TExecuteResult ExecuteProductionTE(TProductionTE Event)
        {
            TExecuteResult Result;
            switch (Event.FCommand)
            {
                case 0:
                    BeginUpdate();
                    if (!Event.FQueue)
                    {
                        ExecuteDeleteProductions();
                    }

                    ExecuteAddProduction(Event.FItem);
                    Result = TExecuteResult.erDone;
                    EndUpdate();
                    break;
                case 1:
                    ExecuteDeleteProduction(Event.FIndex);
                    Result = TExecuteResult.erDone;
                    break;
                case 2:
                    ExecuteDeleteProductions();
                    Result = TExecuteResult.erDone;
                    break;
                case 3:
                    if (FQueue.Count != 0 && FStatus == TProductionControlStatus.pcsWaiting)
                    {
                        ExecuteProduction(FQueue.GetItem(0));
                    }

                    Result = TExecuteResult.erDone;
                    break;
                case 4:
                    FLoopQueue = Event.FIndex == 1;
                    Update();
                    Result = TExecuteResult.erDone;
                    break;
                default:
                    Result = TExecuteResult.erDone;
                    break;
            }

            return Result;
        }

