        // Structur.PAS:804
        public virtual void NewTurn(sbyte Player)
        {
            if (FStatus == TProductionControlStatus.pcsWaiting && Player == GetPlayer())
            {
                if (FQueue.Count != 0)
                {
                    ExecuteProduction(FQueue.GetItem(0));
                }
                else
                {
                    FStatus = TProductionControlStatus.pcsIdle;
                }
            }
            else
            {
                if (FStatus == TProductionControlStatus.pcsProducing && Player == FSettings.FPlayer)
                {
                    if (FSettings.FTurnsLeft > 0)
                    {
                        FSettings.FTurnsLeft = (sbyte)(FSettings.FTurnsLeft - 1);
                    }

                    if (FSettings.FTurnsLeft == 0)
                    {
                        switch (FQueue.GetItem(0).FProductionID)
                        {
                            case 1:
                                if (UnitProduced())
                                {
                                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman && FSettings.FGroupID != 0)
                                    {
                                        GroupProductionProduced(FSettings.FUnit, FSettings.FGroupID);
                                    }

                                    FSettings.Clear();
                                    ProductionDone();
                                }

                                break;
                            case 2:
                                UnitResearched();
                                FSettings.Clear();
                                ProductionDone();
                                break;
                        }
                    }
