            {
                Reason = AnsiString.FromBytes(40) + LowerCase(AoWE.TranslateRStr(AoWE.WaitingRStr)) + AnsiString.FromBytes(41);
            }

            // { Original continues checking costs after assigning the waiting text. }
            switch (Item.FProductionID)
            {
                case 1:
                    var player = GetPlayer();
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(player);
                    if (UnitProductionGold(Item.FParameter) <= players.FGems)
                    {
                        var player2 = GetPlayer();
                        var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(player2);
                        if (UnitProductionMana(Item.FParameter) <= fPlayersPlayers.FMagicControl.FMana)
                        {
                            Result = true;
                        }
                        else
                        {
                            Result = false;
                            Reason = AoWE.TranslateRStr(AoWE.NotEnoughManaRStr);
                        }
                    }
                    else
                    {
                        Result = false;
                        Reason = AoWE.TranslateRStr(AoWE.NotEnoughGoldRStr);
                    }

                    break;
                case 2:
                    var player3 = GetPlayer();
                    var players2 = AoWE.AoWHSMap.FPlayers.GetPlayers(player3);
                    if (UnitResearchGold(Item.FParameter) <= players2.FGems)
                    {
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                        Reason = AoWE.TranslateRStr(AoWE.NotEnoughGoldRStr);
                    }

                    break;
                default:
                    Result = false;
                    break;
            }

            return Result;
        }

