        // Structur.PAS:793
        public void ProductionDone()
        {
            BeginUpdate();
            if (FLoopQueue && LoopableProduction(FQueue.GetItem(0)))
            {
                var count = FQueue.Count;
                FQueue.FChildren.Move(0, count - 1);
            }
            else
            {
                FQueue.GetItem(0).Free();
            }

            if (FQueue.Count != 0)
            {
                ExecuteProduction(FQueue.GetItem(0));
            }
            else
            {
                FStatus = TProductionControlStatus.pcsIdle;
            }

            EndUpdate();
        }

        // Structur.PAS:890
        public int FindOptimalResearchProduction(TCombatPredictor Predictor, int Gold)
        {
            int Result;
            TPlayer Player;
            TUnit AUnit;
            TDoubleItemList Productions;
            int Priority;
            int Minimum;
            bool Include;
            var player = GetPlayer();
            Player = AoWE.AoWHSMap.FPlayers.GetPlayers(player);
            AUnit = new TUnit(null);
            Productions = new TDoubleItemList();
            for (int I = FUnitProductions.Count - 1; I >= 0; I--)
            {
                if (!FUnitProductions.GetItem(I).FResearched)
                {
                    Include = UnitResearchGold(I) <= Gold;
                    if (Predictor != null)
                    {
                        var item = FUnitProductions.GetItem(I);
                        AUnit.SetUnitResource(AoWE.AoWHSSet.FUnitResources.GetUnitResource(item.FUnitIndex));
                        Priority = Predictor.Usefullness(AUnit);
                        // { Original replaces the affordability check here. }
                        Include = (Priority & 8388608) != 0;
                    }
                    else
                    {
                        Priority = AoWE.GetUnitIndexAIPriority(FUnitProductions.GetItem(I).FUnitIndex, Player.FPlayerIndex, 0);
                    }

                    if (Include)
                    {
                        Productions.AddAB(I, Priority);
                    }
                }
            }

            if (Productions.Count != 0)
            {
                Productions.SortDescendingItemB();
                Result = 0;
                Minimum = Round((double)Productions[0].B * 0.8);
                while (Result + 1 < Productions.Count && Productions[Result + 1].B >= Minimum)
                {
                    Result += 1;
                }

                if (AoWE.AoWHSMap.Random(2) == 1)
                {
                    Result = 0;
                }
                else
                {
                    Result = AoWE.AoWHSMap.Random(Result + 1);
                }

                Result = Productions[Result].A;
            }
            else
            {
                Result = -1;
            }

            Productions.Free();
            AUnit.Free();
            return Result;
        }

        // intf_P1_02.inc:120

    }

