        public override AnsiString GetText()
        {
            AnsiString Result = default;
            switch (FMode)
            {
                case TPlayerMagicEventMode.pmemSpellResearched:
                    var spell = AoWE.AoWHSSet.FSpellControl.GetSpell(FSpellID);
                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P4XResearchedRStr), [spell.FSpellName]);
                    break;
                case TPlayerMagicEventMode.pmemOutOfMana:
                    if (AoWE.AoWHSMap.FSeatedPlayer == FPlayer)
                    {
                        Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P4XRemovedOutOfManaRStr), [FEnchantmentName]);
                    }
                    else
                    {
                        Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P4XRemovedRStr), [FEnchantmentName]);
                    }

                    break;
            }

            return Result;
        }

        // Spells.PAS:1874
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool Result = default;
            bool Show;
            switch (FMode)
            {
                case TPlayerMagicEventMode.pmemOutOfMana:
                    Show = Trigger == TExecuteTrigger.etUser;
                    break;
                case TPlayerMagicEventMode.pmemSpellResearched:
                    if (Trigger != TExecuteTrigger.etUser)
                    {
                        if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmTurn)
                        {
                            Show = AoWE.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpSpellResearched);
                        }
                        else
                        {
                            Show = AoWE.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpSpellResearched);
                        }
                    }
                    else
                    {
                        Show = true;
                    }

                    break;
                case TPlayerMagicEventMode.pmemStartResearch:
                    Show = true;
                    break;
                default:
                    Show = false;
                    break;
            }

            if (Show)
            {
                Result = base.Execute(Mode, Trigger, Done);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

