        // Spells.PAS:2023
        public void OutOfMana(int A1)
        {
            int I;
            int Index;
            TPlayerMagicEventLog Log;
            while (A1 > 0 && FEnchantments.GetCount() != 0)
            {
                I = FEnchantments.GetCount();
                Index = I - 1;
                while (I != 0)
                {
                    I -= 1;
                    var enchantments = FEnchantments.GetEnchantments(I);
                    var fEnchantmentsEnchantments = FEnchantments.GetEnchantments(Index);
                    if (enchantments.FUpkeep < fEnchantmentsEnchantments.FUpkeep)
                    {
                        Index = I;
                    }
                }

                if (Index != -1)
                {
                    A1 -= FEnchantments.GetEnchantments(Index).FUpkeep;
                    Log = new TPlayerMagicEventLog(null);
                    Log.FPlayer = FPlayer.FPlayerIndex;
                    Log.FMode = TPlayerMagicEventMode.pmemOutOfMana;
                    FEnchantments.GetEnchantments(Index).GetLocation(ref Log.FLocation.X, ref Log.FLocation.Y, ref Log.FLocation.L);
                    Log.FEnchantmentName = FEnchantments.GetEnchantments(Index).GetName();
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer.FPlayerIndex).FEventLogbook.AddEvent(Log);
                    Log.Release();
                    ExecuteDispelEnchantment(Index);
                }
            }

            if (A1 > 0)
            {
                AoWE.AoWHSMap.FGlobalMagicControl.OutOfMana((sbyte)(byte)FPlayer.FPlayerIndex, A1);
            }
        }

        // Spells.PAS:2052
        public void RemoveEnchantments()
        {
            while (FEnchantments.GetCount() != 0)
            {
                ExecuteDispelEnchantment(FEnchantments.GetCount() - 1);
            }
        }

        // Spells.PAS:2056
        public bool ValidateEnchantmentsUpkeep()
        {
            bool Result;
            int Balance;
            var manaIncome = GetManaIncome();
            var manaUpkeep = GetManaUpkeep();
            Balance = FMana + manaIncome - manaUpkeep;
            if (Balance < 0 && GetManaUpkeep() != 0)
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Spells.PAS:2064
        public bool ExecuteSpellResearched(int A1)
        {
            if (FSpells.IndexOf(A1) == -1)
            {
                FSpells.Add(A1);
            }

            if (A1 == FResearchSpellID)
            {
                FResearchPointsLeft = 0;
                FResearchSpellID = 0;
            }

            return true;
        }

        // Spells.PAS:2074
        public void NewTurn()
        {
            TSpellType Kind = default;
            TIntegerList Candidates = default;
            int Index = default;
            TSpell Spell = default;
            TPlayerMagicEventLog Log;
            if (AoWE.AoWHSMap.FDay == 1 && FPlayer.FPlayerIndex != 0 && (AoWE.AoWHSMap.FGameType != TGameType.gtCampaign || FSpells.Count == 0))
            {
                Candidates = new TIntegerList();
                for (int kindOrdinal = (int)(TSpellType)0; kindOrdinal <= (int)(TSpellType)2; kindOrdinal++)
                {
                    Kind = (TSpellType)kindOrdinal;
                    Candidates.Clear();
                    for (int I = 0, last = AoWE.AoWHSSet.FSpellControl.GetCount() - 1; I <= last; I++)
                    {
                        Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(I);
                        if (Spell != null && FSpells.IndexOf(I) == -1 && Spell.FSpellType == Kind && (Spell.FMagicSphere == TMagicSphere.msCosmos || FPlayer.FLeader.GetSpherePicks(Spell.FMagicSphere) > 0) && Spell.FSpellLevel == 1)
                        {
                            Candidates.Add(I);
                        }
                    }

                    if (Candidates.Count > 0)
                    {
                        Index = AoWE.AoWHSMap.Random(Candidates.Count);
                        var item = Candidates[Index];
                        FSpells.Add(item);
                    }
                }

                Candidates.Free();
            }

            if (FResearchSpellID != 0)
            {
                if (FSpells.IndexOf(FResearchSpellID) == -1)
                {
                    var netPowerToResearch = GetNetPowerToResearch();
                    FResearchPointsLeft -= netPowerToResearch;
                    if (FResearchPointsLeft <= 0)
                    {
                        if (FResearchPointsLeft < 0)
                        {
                            FMana += Math.Abs(FResearchPointsLeft);
                        }

                        Log = new TPlayerMagicEventLog(null);
                        Log.FPlayer = FPlayer.FPlayerIndex;
                        Log.FMode = TPlayerMagicEventMode.pmemSpellResearched;
                        Log.FSpellID = FResearchSpellID;
                        FPlayer.FEventLogbook.AddEvent(Log);
                        ExecuteSpellResearched(FResearchSpellID);
                        if (FPlayer.FPlayerIndex == AoWE.AoWHSMap.FSeatedPlayer && FPlayer.FPlayerType == TPlayerType.ptHuman)
                        {
                            Log.Execute(false, TExecuteTrigger.etEvent, null);
                        }

                        Log.Release();
                    }
                }
                else
                {
                    FResearchSpellID = 0;
                    var netPowerToResearch = GetNetPowerToResearch();
                    FMana += netPowerToResearch;
                }
            }
            else
            {
                var netPowerToResearch = GetNetPowerToResearch();
                FMana += netPowerToResearch;
            }

            var manaIncome = GetManaIncome();
            var manaUpkeep = GetManaUpkeep();
            FMana = FMana + manaIncome - manaUpkeep;
            if (FMana < 0)
            {
                OutOfMana(-FMana);
                FMana = 0;
            }

            // { Original bug: SetMana sees the value already stored and skips its victory check. }
            SetMana(FMana);
            Update();
        }

        // Spells.PAS:2140
        public void SetSpheres(TSet<TMagicSphere> Value)
        {
            if ((Value & TSet<TMagicSphere>.Of(TMagicSphere.msEarth, TMagicSphere.msAir)) != TSet<TMagicSphere>.Of(TMagicSphere.msEarth, TMagicSphere.msAir) && (Value & TSet<TMagicSphere>.Of(TMagicSphere.msFire, TMagicSphere.msWater)) != TSet<TMagicSphere>.Of(TMagicSphere.msFire, TMagicSphere.msWater) && (Value & TSet<TMagicSphere>.Of(TMagicSphere.msLife, TMagicSphere.msDeath)) != TSet<TMagicSphere>.Of(TMagicSphere.msLife, TMagicSphere.msDeath))
            {
                FSpheres = Value;
            }
        }

        // Spells.PAS:2146
        public int GetNetPower()
        {
            int Result = GetPower();
            if (AoWE.AoWHSMap.FGlobalMagicControl.FActiveEnchantments.Contains(TGlobalEnchantmentType.getPowerLeak))
            {
                Result = (Result + 1) / 2;
            }

            return Result;
        }

        // Spells.PAS:2151
        public int GetNetPowerToMana()
        {
            int Result = GetNetPower() - GetNetPowerToResearch();
            switch (FPlayer.FPlayerType)
            {
                case TPlayerType.ptCPU2:
                    Result = Round((double)Result * 1.25);
                    break;
                case TPlayerType.ptCPU3:
                    Result = Round((double)Result * 1.5);
                    break;
                case TPlayerType.ptCPU4:
                    Result = Round((double)Result * 1.75);
                    break;
                case TPlayerType.ptCPU5:
                    Result = Round((double)Result * 2);
                    break;
            }

            return Result;
        }

        // Spells.PAS:2161
        public int GetNetPowerToResearch() => Round((double)(GetNetPower() * FResearchPercentage) * 0.01);

        // Spells.PAS:2163
        public int ResearchTurns(int Power, int Points)
        {
            int Result;
            if (Power > 0)
            {
                Result = Points / Power;
                if (Points % Power != 0)
                {
                    Result += 1;
                }
            }
            else
            {
                Result = 999;
            }

            return Result;
        }

        // Spells.PAS:2172
        public int GetResearchTurnsLeft() => ResearchTurns(GetNetPowerToResearch(), FResearchPointsLeft);

        // Spells.PAS:2176
        public bool ValidResearchSpell(TSpell Spell)
        {
            bool Result;
            FixedArray_int_4 Counts;
            int Level;
            TSpell Known;
            if (FPlayer.FLeader.GetSpherePicks(Spell.FMagicSphere) >= Spell.FSpellLevel && FSpells.IndexOf(Spell.FSpellID) == -1)
            {
                Counts = default;
                for (int I = FSpells.Count - 1; I >= 0; I--)
                {
                    var item = FSpells[I];
                    Known = AoWE.AoWHSSet.FSpellControl.GetSpell(item);
                    if (Known.FSpellLevel > 0 && Known.GetEnabled() && Spell.FMagicSphere == Known.FMagicSphere)
                    {
                        Counts[Known.FSpellLevel - 1] += 1;
                    }
                }

                Level = 1;
                while (Counts[Level - 1] >= 2 && Level < 4)
                {
                    Level += 1;
                }

                if (AoWE.AoWEngine.FDemo)
                {
                    Level = 2;
                }

                Result = Level >= Spell.FSpellLevel;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2199
        public void ListResearchSpells(ref TSpellList List, TSet<TSpellType> SpellTypes)
        {
            TSpell Spell;
            for (int I = 0, last = AoWE.AoWHSSet.FSpellControl.GetCount() - 1; I <= last; I++)
            {
                Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(I);
                if (Spell != null && SpellTypes.Contains(Spell.FSpellType) && ValidResearchSpell(Spell))
                {
                    List.Add(Spell);
                }
            }
        }

        // Spells.PAS:2211
        public void ListSpells(ref TSpellList List, TSet<TSpellType> SpellTypes)
        {
            TSpell Spell;
            if (FCheatEnabled && FPlayer.FPlayerType == TPlayerType.ptHuman)
            {
                for (int I = 0, last = AoWE.AoWHSSet.FSpellControl.GetCount() - 1; I <= last; I++)
                {
                    Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(I);
                    if (Spell != null && Spell.GetEnabled() && SpellTypes.Contains(Spell.FSpellType))
                    {
                        List.Add(Spell);
                    }
                }
            }
            else
            {
                for (int I = 0, last = FSpells.Count - 1; I <= last; I++)
                {
                    var item = FSpells[I];
                    Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(item);
                    if (Spell != null && Spell.GetEnabled() && SpellTypes.Contains(Spell.FSpellType))
                    {
                        List.Add(Spell);
                    }
                }
            }
        }

