            int Index;
            Index = IndexOfID(EnchantmentID);
            if (Index != -1)
            {
                Result = FEnchantments.GetEnchantments(Index).Remove((byte)Player);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:2716
        public bool RemoveEnchantment(sbyte Player, TGlobalEnchantment Enchantment)
        {
            bool Result;
            TChangeGlobalMagicTE Event;
            AnsiString Reason = default;
            if (!AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetBusy() && IndexOfID(Enchantment.FEnchantmentID) != -1)
            {
                if (Enchantment.CanRemove(Player, ref Reason))
                {
                    Event = CreateChangeMagicTE();
                    Event.FMode = TChangeGlobalMagicMode.cgmRemoveEnchantment;
                    Event.FEnchantmentID = Enchantment.FEnchantmentID;
                    Event.FPlayerIndex = (byte)Player;
                    AoWE.AoWHSMap.FTokenManager.GetTokenControl(Player).AddEvent(Event);
                    Event.Release();
                    Result = true;
                }
                else
                {
                    if (Player == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        AoWE.AoWHSMap.ShowWarning(Reason);
                    }

                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // intf_P4_01.inc:258

    }

