        // Ability.PAS:271
        public void NewDay()
        {
            int DefaultValue;
            if (AoWE.AoWHSMap.FDay != 1)
            {
                if ((AoWE.AoWHSMap.FGlobalMagicControl.FActiveEnchantments & TSet<TGlobalEnchantmentType>.Of(TGlobalEnchantmentType.getHatred, TGlobalEnchantmentType.getHarmony)) == TSet<TGlobalEnchantmentType>.Of())
                {
                    for (int I = 0, last = FPlayerRelations.Count - 1; I <= last; I++)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(I + 1);
                        DefaultValue = AoWE.StatusToStatusValue((TStatus)FDefaultRelations[players.FPlayerRace]);
                        if (FPlayerRelations[I] > DefaultValue)
                        {
                            var item = FPlayerRelations[I];
                            FPlayerRelations[I] = item - 1;
                            if (FPlayerRelations[I] < DefaultValue)
                            {
                                FPlayerRelations[I] = DefaultValue;
                            }
                        }

                        if (FPlayerRelations[I] < DefaultValue)
                        {
                            var item = FPlayerRelations[I];
                            FPlayerRelations[I] = item + 1;
                            if (FPlayerRelations[I] > DefaultValue)
                            {
                                FPlayerRelations[I] = DefaultValue;
                            }
                        }
                    }
                }
            }
            else
            {
                ResetPlayerRelations();
            }
        }

        // Ability.PAS:298
        public TStatus GetDefaultRaceRelation(sbyte Race)
        {
            TStatus Result;
            if (Race >= 0 && Race < FDefaultRelations.Count)
            {
                Result = (TStatus)FDefaultRelations[Race];
            }
            else
            {
                Result = TStatus.sNeutral;
            }

            return Result;
        }

        // Ability.PAS:308
        public void ResetDefaultRaceRelations()
        {
            FDefaultRelations.Clear();
            if (FRace >= 0 && FRace <= 11)
            {
                for (int I = 0; I <= 11; I++)
                {
                    FDefaultRelations.Add((byte)(int)AoWE.DefaultRaceRelations[FRace][I]);
                }
            }
        }

        // Ability.PAS:317
        public void ResetPlayerRelations()
        {
            FPlayerRelations.Clear();
            for (int I = 1, last = AoWE.AoWHSMap.FPlayers.GetCount() - 1; I <= last; I++)
            {
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(I);
                var statusToStatusValue = AoWE.StatusToStatusValue((TStatus)FDefaultRelations[players.FPlayerRace]);
                FPlayerRelations.Add(statusToStatusValue);
            }
        }

        // Ability.PAS:326
        public void SetRace(sbyte Value)
        {
            FRace = Value;
            ResetDefaultRaceRelations();
        }

        // Ability.PAS:332
        public void SetEnabled(bool Value)
        {
            if (Value != FEnabled)
            {
                if (AoWE.AoWHSSet.FRaceResources.GetRaceResource(FRace) != null)
                {
                    if (Value)
                    {
                        AoWE.AoWHSSet.FRaceResources.GetRaceResource(FRace).AddRef();
                    }
                    else
                    {
                        AoWE.AoWHSSet.FRaceResources.GetRaceResource(FRace).Release();
                    }

                    FEnabled = Value;
                }
            }
        }

        // intf_P1_03.inc:13

