        public TDiplomaticRelationHistoryList GetHistory(sbyte Player) => (TDiplomaticRelationHistoryList)FHistory.FChildren.List[Player - 1];

        // Player.PAS:119
        public void ValidateHistory()
        {
            while (FHistory.Count + 1 < AoWE.AoWHSMap.FPlayers.Count)
            {
                new TDiplomaticRelationHistoryList(null).Owner = FHistory;
            }

            while (FHistory.Count + 1 > AoWE.AoWHSMap.FPlayers.Count)
            {
                var count = FHistory.Count;
                FHistory.Children[count - 1].Free();
            }
        }

