        // Player.PAS:315
        public override void Destroy()
        {
            TPlayerStructureList Structures;
            TArmyList Armies;
            try
            {
                FIncomeChangedEvents.Clear();
                FGemsChangedEvents.Clear();
                FUpkeepChangedEvents.Clear();
                try
                {
                    if (AoWE.AoWHSMap != null && AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msDestroying))
                    {
                        Assert(FVictoryLocations.Count == 0, (AnsiString)"Victory Locations not correctly cleared (TPlayer)", "Player.PAS", 326);
                        Assert(FStructures.Count == 0, (AnsiString)"Registered Player Structures not correctly cleared (TPlayer)", "Player.PAS", 327);
                        Assert(FArmies.Count == 0, (AnsiString)"Registered Player Armies not correctly cleared (TPlayer)", "Player.PAS", 328);
                    }
                    else
                    {
                        Structures = FStructures;
                        for (int I = Structures.Count - 1; I >= 0; I--)
                        {
                            FStructures.GetStructure(I).SetPlayer(0);
                        }

                        Armies = FArmies;
                        for (int I = Armies.Count - 1; I >= 0; I--)
                        {
                            FArmies.GetArmy(I).SetPlayer(0);
                        }
                    }
                }
                catch (System.Exception)
                {
                }

                FMessages.Free();
                FMessages = null;
                FDiplomaticActions.Free();
                FDiplomaticActions = null;
                FAIValidAttackPlayers.Free();
                FAIValidAttackPlayers = null;
                FLegacyRelations.Free();
                try
                {
                    FLogbookChangedEvents.Clear();
                    FEventLogbook.Free();
                    FLogbookChangedEvents.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FLegacyNewRelations.Free();
                    FDiplomaticRelations.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FProductionControls.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FAIControl.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FStatistics.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FMagicControl.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FLeaderSetup.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FFirstDaySeen.Free();
                    FLastDaySeen.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FHeroes.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    FArmies.Free();
                    FAIGroups.Free();
                    FAIBudget.Free();
                    FStructures.Free();
                    FVictoryLocations.Free();
                    FIncomeSources.Free();
                    FKnownStructures.Free();
                }
                catch (System.Exception)
                {
                }

                try
                {
                    base.Destroy();
                }
                catch (System.Exception)
                {
                }

                FPBEMSettings.Free();
                FPBEMSettings = null;
                FIncomeChangedEvents.Free();
                FIncomeChangedEvents = null;
                FGemsChangedEvents.Free();
                FGemsChangedEvents = null;
                FUpkeepChangedEvents.Free();
                FUpkeepChangedEvents = null;
            }
            catch (System.Exception)
            {
            }
        }

        // Player.PAS:1023
        public override void ReadWrite(TEStorageStream Stream)
        {
            int X = default;
            int Y = default;
            int L = default;
            base.ReadWrite(Stream);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayerRace), 2);
            Stream.rwData(Bytes.Of(ref FPlayerType, 1), 1, 3);
            Stream.rwBool(ref FParticipating, 4);
            Stream.rwInteger(ref FInitialGold, 5);
            Stream.rwInteger(ref FBaseIncome, 6);
            Stream.rwData(Bytes.Of(ref FStatus, 1), 1, 10);
            if (!Stream.StorageMode().Contains(TStorageModeElement.smTextOnly))
            {
                Stream.rwString(ref FSettings, 11);
            }

            Stream.rwString(ref FDescription, 12);
            Stream.rwInteger(ref FGems, 16);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayerIndex), 18);
            if ((AoWE.AoWEngine.Status & TSet<THSEngineStatusElement>.Of(THSEngineStatusElement.esLoadingHSM, THSEngineStatusElement.esSavingHSM)) != TSet<THSEngineStatusElement>.Of() || Stream.StorageMode().Contains(TStorageModeElement.smTextOnly))
            {
                if (!Stream.StorageMode().Contains(TStorageModeElement.smWrite))
                {
                    Stream.rwCreateEObject(ref FLeader, null, 19);
                    if (FLeader != null && !Stream.StorageMode().Contains(TStorageModeElement.smPreview))
                    {
                        FLeader.FPlayer = FPlayerIndex;
                        AoWE.AoWHSMap.FHeroControl.RegisterHero(FLeader);
                    }
                }
            }

            if (Stream.StorageMode().Contains(TStorageModeElement.smWrite))
            {
                if (AoWE.AoWHSMap.FSeatedPlayer == FPlayerIndex && AoWE.AoWHSMap.FConnectionType != TPlayerConnectionType.pcNetwork)
                {
                    AoWE.AoWHSMap.GetViewCenter(ref X, ref Y, ref L);
                    FViewX = (byte)X;
                    FViewY = (byte)Y;
                    FViewL = (byte)L;
                    Stream.rwByte(ref FViewX, 20);
                    Stream.rwByte(ref FViewY, 21);
                    Stream.rwByte(ref FViewL, 22);
                }
            }
            else
            {
                Stream.rwByte(ref FViewX, 20);
                Stream.rwByte(ref FViewY, 21);
                Stream.rwByte(ref FViewL, 22);
            }

            if (!Stream.StorageMode().Contains(TStorageModeElement.smPreview))
            {
                Stream.rwEObject(FEventLogbook, 23);
            }

            Stream.rwString(ref FPassword, 24);
            Stream.rwData(Bytes.Of(ref FGameOverStatus, 1), 1, 25);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                Stream.rwStreamProc(26, FLegacyNewRelations.LoadFromStream, FLegacyNewRelations.SaveToStream);
            }

            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FMoraleValue), 27);
            Stream.rwEObject(FAIControl, 28);
            Stream.rwData(Bytes.Of(ref FBehavior, 1), 1, 29);
            if (FPlayerIndex != 0)
            {
                if (Stream.StorageMode().Contains(TStorageModeElement.smWrite) && AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && FLeader != null)
                {
                    Stream.rwEObject(FLeader, 30);
                }
                else
                {
                    Stream.rwEObject(FLeaderSetup, 30);
                }
            }

            Stream.rwEObject(FMagicControl, 31);
            Stream.rwStreamProc(32, FFirstDaySeen.LoadFromStream, FFirstDaySeen.SaveToStream);
            Stream.rwStreamProc(33, FLastDaySeen.LoadFromStream, FLastDaySeen.SaveToStream);
            Stream.rwInteger(ref FDay, 34);
            Stream.rwEObject(FStatistics, 35);
            Stream.rwInteger(ref FBaseHeroJoinLevel, 36);
            Stream.rwInteger(ref FLastHeroJoinDay, 37);
            Stream.rwInteger(ref FLastHeroEmergeDay, 38);
            Stream.rwInteger(ref FHighestHeroLevel, 39);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                SetRace(FPlayerRace);
                FEventLogbook.FPlayer = FPlayerIndex;
                FLegacyNewRelations.Default = (int)TDiplomaticRelation.drUnknown;
            }

            Stream.rwStrings(FMessages, 40);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
            {
                Stream.rwStreamProc(41, FLegacyRelations.LoadFromStream, FLegacyRelations.SaveToStream);
            }

            Stream.rwInteger(ref FEmergingHeroID, 50);
            Stream.rwEObject(FAIBudget, 51);
            Stream.rwEObject(FDiplomaticActions, 52);
            Stream.rwStreamProc(53, FAIValidAttackPlayers.LoadFromStream, FAIValidAttackPlayers.SaveToStream);
            Stream.rwEObject(FPBEMSettings, 54);
            Stream.rwBool(ref FHeroEmerging, 56);
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead) || AoWE.AoWHSMap.FConnectionType != TPlayerConnectionType.pcNetwork)
            {
                Stream.rwInteger(ref FBaseHeroJoinDay, 57);
            }

            Stream.rwEObject(FDiplomaticRelations, 58);
            if (FPlayerIndex == 0)
            {
                FPlayerType = TPlayerType.ptIndependent;
            }
        }

        // Player.PAS:974
        public override void MsgProc(ref TEMsg Msg, TEObject Sender)
        {
            base.MsgProc(ref Msg, Sender);
            FDiplomaticRelations.MsgProc(ref Msg, Sender);
            if (Msg.MsgID == 536870920 && AoWE.AoWHSMap.FDay == 0)
            {
                FFirstDaySeen.Clear();
                FLastDaySeen.Clear();
            }

            if (Msg.MsgID == 537001989)
            {
                ValidateLeader();
            }

            if (Msg.MsgID == 537001985)
            {
                try
                {
                    UpdateLogbook();
                    if (AoWE.AoWHSMap.FDay == 1)
                    {
                        FViewX = 255;
                        if (AoWE.AoWHSMap.FGameType != TGameType.gtCampaign && !AoWE.AoWHSMap.FFixedLeaders && FLeader != null)
                        {
                            FLeader.Owner = null;
                            FMagicControl.UnregisterPowerSource(FLeader.FPowerSource);
                            // { Original removes the player, not the leader. }
                            FHeroes.RemoveChild(this);
                        }

                        UpdateAlliedPlayersSeen();
                        SetupAIValidAttackPlayers();
                    }
                }
                catch (System.Exception)
                {
                }
            }

            if (Msg.MsgID == 537002243)
            {
                if (!Validate(Msg.Payload.As<TStrings>()))
                {
                    Msg.Data[0] = 1;
                }
            }

            if (Msg.MsgID == 537001986 && Msg.Value == FPlayerIndex)
            {
                UpdateAlliedPlayersSeen();
            }

            if (Msg.MsgID == 537001987 && Msg.Value == FPlayerIndex)
            {
                UpdateTurnInfo();
                if (FPlayerIndex != 0)
                {
                    UpdateHeroJoin();
                }
            }

            if (Msg.MsgID == 536870920 && AoWE.AoWHSMap.FDay == 0)
            {
                FViewX = 255;
                FViewY = 255;
                FViewL = 255;
            }

            FMagicControl.MsgProc(ref Msg, Sender);
            FAIControl.MsgProc(ref Msg, Sender);
            FAIBudget.MsgProc(ref Msg, Sender);
            FEventLogbook.MsgProc(ref Msg, Sender);
        }

        // Player.PAS:394
        public bool GetBusy()
        {
            bool Result = FBusyCount != 0 || !AoWE.AoWHSMap.FTokenManager.PlayerReady(FPlayerIndex);
            Result = Result || (AoWE.AoWHSMap.FCombat == null && AoWE.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWE.AoWHSMap.FCurrentPlayer != FPlayerIndex);
            Result = Result || AoWE.AoWHSMap.FCombat != null && AoWE.AoWHSMap.FCombat.FCombatData.FPlayers.GetPlayers((sbyte)AoWE.AoWHSMap.FCombat.FCombatData.FCurrentPlayer).FPlayer != FPlayerIndex;
            Result = Result || FGameOverStatus != TGameOverStatus.goNone || !GetLocal();
            return Result || FPlayerType == TPlayerType.ptHuman && AoWE.AoWHSMap.GetTurnTimerEnabled() && AoWE.AoWHSMap.GetTurnTimeLeft() <= 0;
        }

