        // Player.PAS:425
        public void SetGameOverStatus(TGameOverStatus Value)
        {
            TGameOverEventLog Event;
            TPlayerStructureList Structures;
            TArmyList Armies;
            TAoWCampaign Campaign;
            if (Value != FGameOverStatus && FGameOverStatus == TGameOverStatus.goNone)
            {
                FGameOverStatus = Value;
                AoWE.AoWHSMap.FAIExecuter.DeactivatePlayer(FPlayerIndex);
                if (AoWE.AoWHSMap.FGameType == TGameType.gtCampaign && FPlayerType == TPlayerType.ptHuman)
                {
                    if (FGameOverStatus == TGameOverStatus.goLost)
                    {
                        AoWE.AoWHSMap.FGameResult = TGameResult.grFailed;
                        Campaign = AoWE.AoWEngine.FCampaign;
                        if (Campaign != null)
                        {
                            Campaign.RestartScenario();
                        }
                    }
                    else
                    {
                        if (FGameOverStatus == TGameOverStatus.goWon)
                        {
                            AoWE.AoWHSMap.FGameResult = TGameResult.grSucceeded;
                            Campaign = AoWE.AoWEngine.FCampaign;
                            if (Campaign != null)
                            {
                                Campaign.FinishScenario();
                            }
                        }
                    }
                }

                if (FGameOverStatus == TGameOverStatus.goLost)
                {
                    BeginUpdate();
                    FMagicControl.RemoveEnchantments();
                    Structures = FStructures;
                    for (int I = Structures.Count - 1; I >= 0; I--)
                    {
                        FStructures.GetStructure(I).SetPlayer(0);
                    }

                    Armies = FArmies;
                    for (int I = Armies.Count - 1; I >= 0; I--)
                    {
                        FArmies.GetArmy(I).SetPlayer(0);
                    }

                    FMagicControl.SetMana(0);
                    FGems = 0;
                    EndUpdate();
                    AoWE.AoWHSMap.FPlayers.Update();
                }

                Event = new TGameOverEventLog(null);
                Event.FPlayer = FPlayerIndex;
                if (Value == TGameOverStatus.goLost)
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.RaceNamesPluralRStr[FPlayerRace]);
                    var name = GetName();
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.GameOverDefeatMessageRStr), [IntToStr(AoWE.AoWHSMap.FDay), translateRStr, name]);
                    Event.FMessage.Text = format;
                }
                else
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.RaceNamesPluralRStr[FPlayerRace]);
                    var name = GetName();
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.GameOverVictoryMessageRStr), [IntToStr(AoWE.AoWHSMap.FDay), translateRStr, name]);
                    Event.FMessage.Text = format;
                }

                AoWE.AoWHSMap.ExecuteGameOverEvent(Event);
                Event.Release();
                if (FGameOverStatus == TGameOverStatus.goLost)
                {
                    AoWE.AoWHSMap.FGlobalMagicControl.RemovePlayerEnchantments(FPlayerIndex);
                }
            }
        }

        // Player.PAS:484
        public bool Surrender()
        {
            bool Result;
            TGameOverTE TE;
            if (!GetBusy() && FGameOverStatus == TGameOverStatus.goNone)
            {
                TE = new TGameOverTE(null);
                TE.FPlayer = FPlayerIndex;
                TE.FGameOverStatus = TGameOverStatus.goLost;
                AoWE.AoWHSMap.FTokenManager.GetTokenControl(FPlayerIndex).AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Player.PAS:499
        public bool Win()
        {
            bool Result;
            TGameOverTE TE;
            if (!GetBusy() && FGameOverStatus == TGameOverStatus.goNone)
            {
                TE = new TGameOverTE(null);
                TE.FPlayer = FPlayerIndex;
                TE.FGameOverStatus = TGameOverStatus.goWon;
                AoWE.AoWHSMap.FTokenManager.GetTokenControl(FPlayerIndex).AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Player.PAS:515
        public bool Validate(TStrings Errors)
        {
            bool Result;
            AnsiString S;
            AnsiString LeaderName;
            if (FPlayerIndex > 0)
            {
                Result = true;
                if (FLeader.GetSphereCount() != AoWE.AoWHSMap.FSphereCount)
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.RaceNamesRStr[FPlayerRace]);
                    LeaderName = AoWE.Format(AoWE.XLeaderRStr, [translateRStr]);
                    S = LeaderName + (AnsiString)": " + AoWE.TranslateRStr(AoWE.NotAllSpheresAssignedRStr);
                    Errors.Add(S);
                    Result = false;
                }

                if (FLeader.Owner == null)
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.RaceNamesRStr[FPlayerRace]);
                    LeaderName = AoWE.Format(AoWE.XLeaderRStr, [translateRStr]);
                    S = LeaderName + (AnsiString)": " + AoWE.TranslateRStr(AoWE.NotPlacedOnMapRStr);
                    Errors.Add(S);
                    Result = false;
                }

                if (FLeader.GetSkillPoints() != 0)
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.RaceNamesRStr[FPlayerRace]);
                    LeaderName = AoWE.Format(AoWE.XLeaderRStr, [translateRStr]);
                    S = LeaderName + (AnsiString)": " + AoWE.TranslateRStr(AoWE.NotAllSkillPointsAssignedRStr);
                    Errors.Add(S);
                }
            }
            else
            {
                // { Original reports unassigned skill points without failing validation. }
                Result = true;
            }

            return Result;
        }

