            }
        }

        // Player.PAS:563
        public void BeginUpdate()
        {
            FUpdateCount += 1;
            FStructures.BeginUpdate();
            FArmies.BeginUpdate();
            FMagicControl.BeginUpdate();
        }

        // Player.PAS:571
        public void EndUpdate()
        {
            FUpdateCount -= 1;
            if (FUpdateCount == 0)
            {
                FGemsChangedEvents.TriggerNotifyEvents(this);
                FUpkeepChangedEvents.TriggerNotifyEvents(this);
                UpdateIncome();
                FLogbookChangedEvents.TriggerNotifyEvents(this);
            }

            FStructures.EndUpdate();
            FArmies.EndUpdate();
            FMagicControl.EndUpdate();
        }

        // Player.PAS:586
        public void ArmiesChanged(TObject Sender)
        {
            if (FArmies.Count == 0)
            {
                AoWE.AoWHSMap.GameOver(FPlayerIndex, TGameOverStatus.goLost);
            }
        }

        // Player.PAS:591
        public void SetGems(int Value)
        {
            FGems = Value;
            if (FUpdateCount == 0)
            {
                FGemsChangedEvents.TriggerNotifyEvents(this);
            }

            if (AoWE.AoWHSMap.FVictoryCondition == TVictoryCondition.vcAccumulateGold && AoWE.AoWHSMap.FVictoryGold <= FGems)
            {
                AoWE.AoWHSMap.GameOver(FPlayerIndex, TGameOverStatus.goWon);
            }
        }

        // Player.PAS:600
        public void UpdateIncome()
        {
            FIncome = FBaseIncome;
            for (int I = FIncomeSources.Count - 1; I >= 0; I--)
            {
                var income = ((TIncomeSource)FIncomeSources.FChildren.List[I]).Income();
                FIncome += income;
            }

            if (FPlayerType == TPlayerType.ptCPU2)
            {
                FIncome = Round((double)FIncome * 1);
            }
            else
            {
                if (FPlayerType == TPlayerType.ptCPU3)
                {
                    FIncome = Round((double)FIncome * 2);
                }
                else
                {
                    if (FPlayerType == TPlayerType.ptCPU4)
                    {
                        FIncome = Round((double)FIncome * 2.5) + 50;
                    }
                    else
                    {
                        if (FPlayerType == TPlayerType.ptCPU5)
                        {
                            FIncome = Round(FIncome * 3) + 100;
                        }
                    }
                }
            }

            if (FUpdateCount == 0)
            {
                FIncomeChangedEvents.TriggerNotifyEvents(this);
            }
        }

        // Player.PAS:614
        public void RegisterIncomeSource(TIncomeSource Source)
        {
