        // Player.PAS:1203
        public bool DiplomaticActionAleadySend(TDiplomaticActionType Action, sbyte Target, sbyte Other)
        {
            TEventLogbook Logbook;
            int I;
            TDiplomaticAction Item;
            Logbook = AoWE.AoWHSMap.FPlayers.GetPlayers(Target).FEventLogbook;
            bool Result = false;
            I = Logbook.GetCount();
            while (!Result && I != 0)
            {
                I -= 1;
                if (Logbook.GetLogs(I).FDay == AoWE.AoWHSMap.FDay)
                {
                    if (Logbook.GetLogs(I) is TDiplomaticActionEventLog)
                    {
                        Item = ((TDiplomaticActionEventLog)Logbook.GetLogs(I)).FAction;
                        Result = Item.FActionType == Action && Item.FSource == FPlayerIndex && Item.FTarget == Target && (Other == -1 || Item.FOtherPlayer == Other);
                    }
                }
            }

            return Result;
        }

        // Player.PAS:1226
        public int ListDiplomaticActions(sbyte Player, ref TDiplomaticActionList Actions)
        {
            int Count;
            TDiplomaticRelation Relation;
            TDiplomaticAction Action;
            if (Player != FPlayerIndex && GetFirstDaySeen(Player) != -1)
            {
                Count = Actions.Count;
                Relation = AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation(Player, FPlayerIndex);
                if (FPlayerType == TPlayerType.ptHuman && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    Action = CreateDiplomaticAction(TDiplomaticActionType.daSendMessage, Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drWar, TDiplomaticRelation.drUnknown).Contains(Relation) && !DiplomaticActionAleadySend(TDiplomaticActionType.daOfferPeace, Player, -1))
                {
                    Action = CreateDiplomaticAction(TDiplomaticActionType.daOfferPeace, Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (Relation != TDiplomaticRelation.drWar && Relation != TDiplomaticRelation.drAlliance)
                {
                    Action = CreateDiplomaticAction(TDiplomaticActionType.daDeclareWar, Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace).Contains(Relation) && !DiplomaticActionAleadySend(TDiplomaticActionType.daProposeAlliance, Player, -1))
                {
                    Action = CreateDiplomaticAction(TDiplomaticActionType.daProposeAlliance, Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drUnknown).Contains(Relation) && !DiplomaticActionAleadySend(TDiplomaticActionType.daThreatenToAttack, Player, -1))
                {
                    Action = CreateDiplomaticAction(TDiplomaticActionType.daThreatenToAttack, Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                Action = CreateDiplomaticAction(TDiplomaticActionType.daMakeTribute, Player, -1);
                if (Action != null)
                {
                    Actions.AddChild(Action);
                    Action.Release();
                }

                if (TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drAlliance).Contains(Relation))
                {
                    Action = CreateDiplomaticAction(TDiplomaticActionType.daBreakAlliance, Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                {
                    if (I != Player && I != FPlayerIndex && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                    {
                        bool condition = !DiplomaticActionAleadySend(TDiplomaticActionType.daDeclareWarToY, Player, (sbyte)I) && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayerIndex).GetFirstDaySeen((sbyte)I) != -1 && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetFirstDaySeen((sbyte)I) != -1;
                        if (condition)
                        {
                            var diplomaticRelation = AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation(Player, (sbyte)I);
                            condition = TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drUnknown).Contains(diplomaticRelation);
                        }

                        if (condition)
                        {
                            Action = CreateDiplomaticAction(TDiplomaticActionType.daDeclareWarToY, Player, (sbyte)I);
                            if (Action != null)
                            {
                                Actions.AddChild(Action);
                                Action.Release();
                            }
                        }
                    }
                }

                for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                {
                    if (I != Player && I != FPlayerIndex && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                    {
                        if (!DiplomaticActionAleadySend(TDiplomaticActionType.daBreakAllianceWithY, Player, (sbyte)I) && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayerIndex).GetFirstDaySeen((sbyte)I) != -1 && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetFirstDaySeen((sbyte)I) != -1 && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation(Player, (sbyte)I) == TDiplomaticRelation.drAlliance)
                        {
                            Action = CreateDiplomaticAction(TDiplomaticActionType.daBreakAllianceWithY, Player, (sbyte)I);
                            if (Action != null)
                            {
                                Actions.AddChild(Action);
                                Action.Release();
                            }
                        }
                    }
                }

                if (FPlayerRace == 5 && FHeroEmerging && FPlayerType == TPlayerType.ptHuman && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        if (I != Player && I != FPlayerIndex && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType == TPlayerType.ptHuman)
                        {
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayerIndex).GetFirstDaySeen((sbyte)I) != -1 && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetFirstDaySeen((sbyte)I) != -1 && AoWE.AoWHSMap.FPlayers.GetPlayers(I).GetFirstDaySeen(Player) != -1)
                            {
                                Action = CreateDiplomaticAction(TDiplomaticActionType.daSendMessageAsY, Player, (sbyte)I);
                                if (Action != null)
                                {
                                    Actions.AddChild(Action);
                                    Action.Release();
                                }
                            }
                        }
                    }
                }

                Count = Actions.Count - Count;
            }
            else
            {
                Count = 0;
            }

            return Count;
        }

