                if (Valid)
                {
                    J = 1;
                    while (Valid && J != FChildren.Count)
                    {
                        Valid = J == I || GetPlayers(J).FPlayerRace != Player.FPlayerRace;
                        J += 1;
                    }
                }

                if (Valid)
                {
                    I += 1;
                }
            }

            if (Valid)
            {
                Result = 0;
            }
            else
            {
                Result = I;
            }

            return Result;
        }

