            int Points;
            Valid = true;
            I = Path.Count - 2;
            Points = 0;
            Settings.FMovePointsMax = Path.PosToMovePoints(0);
            ProcessMove(Settings);
            while (I > 0 && Valid)
            {
                Points += Path[I].Flag;
                var item = Path[I];
                var pathItem = Path[I];
                Valid = Points == Settings.GetMovePoints(Path[I].X, pathItem.Y, item.L);
                I -= 1;
