        // PlayerC.PAS:76
        public virtual void NewDay()
        {
            TEMsg Msg = default;
            TTextEventLog Log = default;
            TMessageEventLog MessageLog;
            AoWE.AoWHSMap.FDay += 1;
            AoWE.AoWHSMap.FPlayers.BeginUpdate();
            AoWE.AoWHSMap.LockRelationsChanged();
            for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                Log = new TNewDayEventLog(null);
                Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.NewDayRStr), [AoWE.AoWHSMap.FDay]);
                if (AoWE.AoWHSMap.FDayLimit != 0 && AoWE.AoWHSMap.FDayLimit - AoWE.AoWHSMap.FDay <= 10)
                {
                    var fmtDaysLeftStr = AoWE.FmtDaysLeftStr(AoWE.AoWHSMap.FDayLimit - AoWE.AoWHSMap.FDay);
                    Log.FText = Log.FText + (AnsiString)" (" + fmtDaysLeftStr + AnsiString.FromBytes(41);
                }

                Log.FPlayer = (sbyte)I;
                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FEventLogbook.AddEvent(Log);
                Log.Release();
            }

            if (AoWE.AoWHSMap.FTurnOrderMode == TTurnOrderMode.toChanging)
            {
                AoWE.AoWHSMap.GenerateNewTurnOrder();
            }

            if (AoWE.AoWHSMap.FDay == 1)
            {
                AoWE.AoWHSMap.FRaces.ResetPlayerRelations();
                if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcLocal)
                {
                    Randomize();
                    AoWE.AoWHSMap.FInitialRandomSeed = RandSeed;
                }

                AoWE.AoWHSMap.FDefendersSeed = AoWE.AoWHSMap.FInitialRandomSeed;
            }

            try
            {
                InitMsg(ref Msg, 537001985, this);
                AoWE.AoWHSMap.SendMsg(ref Msg, this);
            }
            catch (System.Exception)
            {
            }

            try
            {
                AoWE.AoWHSMap.FNewDayEvents.TriggerNotifyEvents(this);
            }
            catch (System.Exception)
            {
            }

            if (AoWE.AoWHSMap.FDayLimit == AoWE.AoWHSMap.FDay)
            {
                MessageLog = new TMessageEventLog(null);
                MessageLog.FTitle = AoWE.TranslateRStr(AoWE.InfoRStr);
                MessageLog.FButtons = TMessageEventLogButtons.mebOk;
                MessageLog.FLayout = TMessageEventLogLayout.melNormal;
                var translateRStr = AoWE.TranslateRStr(AoWE.TurnLimitReachedRStr);
                MessageLog.FMessage.Text = translateRStr;
                AoWE.AoWHSMap.TriggerExecuteEventLog(MessageLog, false, null);
                MessageLog.Release();
                AoWE.AoWHSMap.GameOver(AoWE.AoWHSMap.FSeatedPlayer, TGameOverStatus.goLost);
                for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                {
                    AoWE.AoWHSMap.GameOver((sbyte)I, TGameOverStatus.goLost);
                }
            }

            AoWE.AoWHSMap.UnlockRelationsChanged();
            AoWE.AoWHSMap.TriggerRelationsChanged();
            AoWE.AoWHSMap.FPlayers.EndUpdate();
        }

        // PlayerC.PAS:177
        public virtual void NewTurn(sbyte Player)
        {
            TEMsg Msg = default;
            if (AoWE.AoWHSMap.FDay != 1)
            {
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                var upkeep = AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetUpkeep();
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).SetGems(players.FGems + fPlayersPlayers.FIncome - upkeep);
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FGems < 0)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).SetGems(0);
                    var players2 = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    players2.FMoraleValue = (sbyte)(players2.FMoraleValue - 5);
                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue < -50)
                    {
                        AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue = -50;
                    }
                }
                else
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMoraleValue = 0;
                }

                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).SetEndTurn(false);
            }

            var players3 = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
            players3.FDay += 1;
            AoWE.AoWHSMap.LockUpdateVisibility();
            InitMsg(ref Msg, 537001986, this);
            Msg.Value = Player;
            AoWE.AoWHSMap.SendMsg(ref Msg, this);
            AoWE.AoWHSMap.FNewTurnEvents.TriggerNotifyEvents(IntToObject(Player));
            InitMsg(ref Msg, 537001987, this);
            Msg.Value = Player;
            AoWE.AoWHSMap.SendMsg(ref Msg, this);
            AoWE.AoWHSMap.UnLockUpdateVisibility();
            if (AoWE.AoWHSMap.FDebugSave)
            {
                try
                {
                    if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous)
                    {
                        if (Player == 0)
                        {
                            AoWE.AoWEngine.SaveHSM(AoWE.AoWEngine.StartupDirectory + (AnsiString)"DEBUG\\" + AoWE.AoWHSMap.FMapName + IntToStr(AoWE.AoWHSMap.FDay) + (AnsiString)"_p" + IntToStr(AoWE.AoWHSMap.FSeatedPlayer) + (AnsiString)".asg", null);
                        }
                    }
                    else
                    {
                        AoWE.AoWEngine.SaveHSM(AoWE.AoWEngine.StartupDirectory + (AnsiString)"DEBUG\\" + AoWE.AoWHSMap.FMapName + IntToStr(AoWE.AoWHSMap.FDay) + AnsiString.FromBytes(45) + IntToStr(Player) + (AnsiString)"_p" + IntToStr(AoWE.AoWHSMap.FSeatedPlayer) + (AnsiString)".asg", null);
                    }
                }
                catch (System.Exception)
                {
                }
            }
        }

