        public virtual void Setup()
        {
            TLocalPCC PCC = default;
            if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork && !AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                if (AoWE.AoWHSMap.FPlayerCommunicator.PCC == null)
                {
                    throw Exception.Create((AnsiString)"Please setup DirectPlayPCC");
                }

                var tokenExecuter = AoWE.AoWHSMap.FTokenManager.TokenExecuter;
                tokenExecuter.OnGetSyncValue = this.GetSyncValue;
                tokenExecuter.OnSyncError = OutOfSync;
            }
            else
            {
                if ((AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) || TSet<TPlayerConnectionType>.Of(TPlayerConnectionType.pcLocal, TPlayerConnectionType.pcEmail).Contains(AoWE.AoWHSMap.FConnectionType)) && AoWE.AoWHSMap.FPlayerCommunicator.PCC == null)
                {
                    PCC = new TLocalPCC();
                    PCC.Setup(AoWE.AoWHSMap.FPlayers.Count);
                    for (int I = 0, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType == TPlayerType.ptHuman)
                        {
                            PCC.SetConnectionMode(I, TConnectionMode.cmLocal);
                        }
                        else
                        {
                            PCC.SetConnectionMode(I, TConnectionMode.cmGlobal);
                        }
                    }

                    AoWE.AoWHSMap.FPlayerCommunicator.ActivatePCC(PCC);
                    PCC.Release();
                    AoWE.AoWHSMap.FPlayers.Update();
                }
            }
        }

