        // PlayerC.PAS:241
        public virtual void GameOver(sbyte Player, TGameOverStatus Status)
        {
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FGameOverStatus != Status && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus != TPlayerStatus.psTerminated)
            {
                AoWE.AoWHSMap.LockGameOverEvent();
                SetPlayerGameOverStatus(Player, Status);
                if (Status == TGameOverStatus.goLost)
                {
                    if (!AoWE.AoWHSMap.FAlliedVictory)
                    {
                        if (AoWE.AoWHSMap.FPlayers.FActivePlayers.Count == 1)
                        {
                            GameOver((sbyte)AoWE.AoWHSMap.FPlayers.FActivePlayers[0], TGameOverStatus.goWon);
                        }
                    }
                    else
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetActivePlayersAllied())
                        {
                            for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                            {
                                if (I != Player && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FGameOverStatus != TGameOverStatus.goLost)
                                {
                                    SetPlayerGameOverStatus((sbyte)I, TGameOverStatus.goWon);
                                }
                            }
                        }
                    }
                }
                else
                {
                    if (Status == TGameOverStatus.goWon)
                    {
                        for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                        {
                            if (I != Player && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying && AoWE.AoWHSMap.FPlayers.GetPlayers(I).FGameOverStatus != TGameOverStatus.goLost)
                            {
                                if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation(Player, (sbyte)I) == TDiplomaticRelation.drAlliance && AoWE.AoWHSMap.FAlliedVictory)
                                {
                                    SetPlayerGameOverStatus((sbyte)I, TGameOverStatus.goWon);
                                }
                                else
                                {
                                    SetPlayerGameOverStatus((sbyte)I, TGameOverStatus.goLost);
                                }
                            }
                        }
                    }
                }

                AoWE.AoWHSMap.UnlockGameOverEvent();
            }
        }

