        // PlayerC.PAS:388
        public virtual void ExitGame(TExitGameMode Mode, TExitGameCallBack Done)
        {
            TMessageEventLog Log = default;
            if (AoWE.AoWHSMap.FCombat == null)
            {
                if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork && AoWE.AoWHSMap.FGameStatus != TGameStatus.gsTerminated && AoWE.AoWHSMap.FGameType != TGameType.gtTutorial && AoWE.AoWHSMap.FPlayers.FLocalPlayers.Count > 1)
                {
                    if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous || AoWE.AoWHSMap.FCurrentPlayer == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        FExitMode = Mode;
                        FExitCallBack = Done;
                        Log = new TMessageEventLog(null);
                        Log.FTitle = AoWE.TranslateRStr(AoWE.ConfirmRStr);
                        Log.FButtons = TMessageEventLogButtons.mebYesNoCancel;
                        Log.FLayout = TMessageEventLogLayout.melNormal;
                        var translateRStr = AoWE.TranslateRStr(AoWE.YourAboutToExitAMultiPlayerGameRStr);
                        Log.FMessage.Add(translateRStr);
                        var aoWETranslateRStr = AoWE.TranslateRStr(AoWE.DoYouWantToContinueExitingRStr);
                        Log.FMessage.Add(aoWETranslateRStr);
                        AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, ExitNetworkGameCallBack);
                        Log.Release();
                    }
                    else
                    {
                        Log = new TMessageEventLog(null);
                        Log.FTitle = AoWE.TranslateRStr(AoWE.MessageRStr);
                        Log.FButtons = TMessageEventLogButtons.mebOk;
                        Log.FLayout = TMessageEventLogLayout.melNormal;
                        var translateRStr = AoWE.TranslateRStr(AoWE.PleaseWaitTillItIsYourTurnRStr);
                        Log.FMessage.Add(translateRStr);
                        AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                        Log.Release();
                    }
                }
                else
                {
                    if (AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msModified) && AoWE.AoWHSMap.FGameStatus != TGameStatus.gsTerminated && AoWE.AoWHSMap.FGameType != TGameType.gtTutorial)
                    {
                        if (!(FExitCallBack != null))
                        {
                            if (Mode != TExitGameMode.egmReload)
                            {
                                FExitMode = Mode;
                                FExitCallBack = Done;
                                Log = new TMessageEventLog(null);
                                Log.FTitle = AoWE.TranslateRStr(AoWE.ConfirmRStr);
                                Log.FButtons = TMessageEventLogButtons.mebYesNoCancel;
                                if (AoWE.AoWEngine.FCampaign == null && AoWE.AoWHSMap.FileName != (AnsiString)"" && CompareText(ExtractFileExt(AoWE.AoWHSMap.FileName), (AnsiString)".hsm") != 0)
                                {
                                    Log.FLayout = TMessageEventLogLayout.melNormal;
                                    var fileName = ExtractFileName(AoWE.AoWHSMap.FileName);
                                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.SaveGameToXRStr), [fileName]);
                                    Log.FMessage.Add(format);
                                }
                                else
                                {
                                    if (AoWE.AoWEngine.FCampaign != null && AoWE.AoWEngine.FCampaign.FFileName != (AnsiString)"" && CompareText(ExtractFileExt(AoWE.AoWHSMap.FileName), (AnsiString)".csm") != 0)
                                    {
                                        // { Original tests the map extension when saving a campaign. }
                                        Log.FLayout = TMessageEventLogLayout.melNormal;
                                        var fileName = ExtractFileName(AoWE.AoWEngine.FCampaign.FFileName);
                                        var format = AoWE.Format(AoWE.TranslateRStr(AoWE.SaveGameToXRStr), [fileName]);
                                        Log.FMessage.Add(format);
                                    }
                                    else
                                    {
                                        Log.FLayout = TMessageEventLogLayout.melNormal;
                                        var translateRStr = AoWE.TranslateRStr(AoWE.DoYouWantToSaveThisGameRStr);
                                        Log.FMessage.Add(translateRStr);
                                    }
                                }

                                AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, SaveGameOnExitCallBack);
                                Log.Release();
                            }
                            else
                            {
                                Done(Mode, true);
                            }
                        }
                        else
                        {
                            FExitCallBack(FExitMode, false);
                        }
                    }
                    else
                    {
                        AoWE.AoWHSMap.ExecuteExitGame();
                    }
                }
            }
            else
            {
                if (Done != null)
                {
                    Done(Mode, false);
                }
            }
        }

