                AoWE.AoWEngine.OutputDebugStr(Text);
            }
        }

        // PlayerC.PAS:313
        public void ExitSaveGameCallBack(TEventLog Log)
        {
            if (((TSaveGameEventLog)Log).FFileName != (AnsiString)"")
            {
                if (AoWE.AoWEngine.FCampaign != null)
                {
                    AoWE.AoWEngine.SaveCampaign(((TSaveGameEventLog)Log).FFileName);
                }
                else
                {
                    AoWE.AoWEngine.SaveHSM(((TSaveGameEventLog)Log).FFileName, null);
                }

                AoWE.AoWHSMap.ExecuteExitGame();
                if (FExitCallBack != null)
                {
                    FExitCallBack(FExitMode, true);
                }
            }
            else
            {
                if (FExitCallBack != null)
                {
                    FExitCallBack(FExitMode, false);
                }
            }

            FExitCallBack = null;
        }

        // PlayerC.PAS:326
        public void SaveGameOnExitCallBack(TEventLog Log)
        {
            TSaveGameEventLog SaveLog = default;
            if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebYes)
            {
                if (AoWE.AoWEngine.FCampaign == null && (AoWE.AoWHSMap.FileName == (AnsiString)"" || CompareText(ExtractFileExt(AoWE.AoWHSMap.FileName), (AnsiString)".hsm") == 0) || AoWE.AoWEngine.FCampaign != null && (AoWE.AoWEngine.FCampaign.FFileName == (AnsiString)"" || CompareText(ExtractFileExt(AoWE.AoWHSMap.FileName), (AnsiString)".csm") == 0))
                {
                    SaveLog = new TSaveGameEventLog(null);
                    if (AoWE.AoWHSMap.FileName != (AnsiString)"")
                    {
                        SaveLog.FDefaultName = ExtractFileName(AoWE.AoWHSMap.FileName);
                        if (Pos(AnsiString.FromBytes(46), SaveLog.FDefaultName) != 0)
                        {
                            SaveLog.FDefaultName = Rtl.Rtl.Copy(SaveLog.FDefaultName, 1, Pos(AnsiString.FromBytes(46), SaveLog.FDefaultName) - 1);
                        }
                    }
                    else
                    {
                        SaveLog.FDefaultName = AoWE.AoWHSMap.FMapName;
                    }

                    SaveLog.FDirectory = AoWE.AoWEngine.StartupDirectory + (AnsiString)"Save\\";
                    AoWE.AoWHSMap.TriggerExecuteEventLog(SaveLog, false, ExitSaveGameCallBack);
                    SaveLog.Release();
                }
                else
                {
                    var aoWEngine = AoWE.AoWEngine;
                    if (aoWEngine.FCampaign != null)
                    {
                        aoWEngine.SaveCampaign(aoWEngine.FCampaign.FFileName);
                    }
                    else
                    {
                        aoWEngine.SaveHSM(AoWE.AoWHSMap.FileName, null);
                    }

                    AoWE.AoWHSMap.ExecuteExitGame();
                    if (FExitCallBack != null)
                    {
                        FExitCallBack(FExitMode, true);
                    }

                    FExitCallBack = null;
                }
            }
            else
            {
                if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebNo)
                {
                    AoWE.AoWHSMap.ExecuteExitGame();
                    if (FExitCallBack != null)
                    {
                        FExitCallBack(FExitMode, true);
                    }

                    FExitCallBack = null;
                }
                else
                {
                    if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebCancel)
                    {
                        if (FExitCallBack != null)
                        {
                            FExitCallBack(FExitMode, false);
                        }

                        FExitCallBack = null;
                    }
                }
            }
        }

        // PlayerC.PAS:372
        public void ExitNetworkGameCallBack(TEventLog Log)
        {
            TTerminatePlayerTE TE;
            if (((TMessageEventLog)Log).FPressedButton == TPressedEventLogButton.pebYes)
            {
                if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous || AoWE.AoWHSMap.FCurrentPlayer == AoWE.AoWHSMap.FSeatedPlayer)
                {
                    TE = new TTerminatePlayerTE(null);
                    TE.FPlayer = AoWE.AoWHSMap.FSeatedPlayer;
                    TE.FExitCallBack = FExitCallBack;
                    TE.FExitMode = FExitMode;
                    AoWE.AoWHSMap.FTokenManager.GetTokenControl(AoWE.AoWHSMap.FSeatedPlayer).AddEvent(TE);
                    TE.Release();
                }
            }
        }

