        // Structur.PAS:4436
        public TTextControlItem FindID(int ID)
        {
            int I;
            I = Count;
            TTextControlItem Result = null;
            while (Result == null && I != 0)
            {
                I -= 1;
                if (((TTextControlItem)FChildren.List[I]).FID == ID)
                {
                    Result = (TTextControlItem)FChildren.List[I];
                }
            }

            return Result;
        }

