    public partial class TTurnPlayerControl : TPlayerControl
    {
        public new const int ClassID = 131664;

        public TTurnPlayerControl(TECustomNode owner) : base(owner)
        {}

        // PlayerC.PAS:589
        public override void NewTurn(sbyte Player)
        {
            TNewTurnEventLog Log = default;
            TShowBookEventLog BookLog = default;
            TSpellList Spells = default;
            TPlayerMagicEventLog MagicLog = default;
            AoWE.AoWHSMap.LockMapChangedEvent();
            AoWE.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(Player);
            if (AoWE.AoWHSMap.FRequestCombatType)
            {
                if (AoWE.AoWHSMap.FSeatedPlayer != -1)
                {
                    AoWE.AoWHSMap.SetSeatedPlayer(-1);
                }

                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWE.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWE.TranslateRStr(AoWE.ItsYourTurnRStr);
                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, ShowNewTurnCallBack);
                    Log.Release();
                }
                else
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWE.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of();
                    if (Player == 0)
                    {
                        Log.FText = AoWE.TranslateRStr(AoWE.IndependentsAreMovingRStr);
                    }
                    else
                    {
                        var name = AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetName();
                        Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.PlayerIsMovingRStr), [name]);
                    }

                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, true, null);
                    Log.Release();
                }
            }
            else
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman && Player == AoWE.AoWHSMap.FSeatedPlayer)
                {
                    if (AoWE.AoWHSMap.FGameType != TGameType.gtTutorial || AoWE.AoWHSMap.FDay != 1)
                    {
                        AoWE.AoWHSMap.ResetTurnTimer();
                        AoWE.AoWHSMap.EnableTurnTimer();
                        AoWE.AoWHSMap.ResetSeatedPlayerView();
                        Log = new TNewTurnEventLog(null);
                        Log.FTurnPlayer = Player;
                        Log.FMode = TNewTurnEventLogMode.ntDialog;
                        Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                        Log.FText = AoWE.TranslateRStr(AoWE.ItsYourTurnRStr);
                        AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                        Log.Release();
                        ReplayLogbook();
                    }
                    else
                    {
                        AoWE.AoWHSMap.FTutorialControl.ShowMessage(50, false, true);
                    }
                }
            }

            base.NewTurn(Player);
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman && AoWE.AoWHSMap.FConnectionType != TPlayerConnectionType.pcEmail && AoWE.AoWEngine.FRegistry.GetAutoSave())
            {
                AutoSave();
            }

            AoWE.AoWHSMap.UnlockMapChangedEvent();
            AoWE.AoWHSMap.InvalidateMap();
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                AoWE.AoWHSMap.FAIExecuter.ActivatePlayer(Player);
                if (Player == 0)
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.IndependentsRStr);
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.AreMovingRStr), [translateRStr]);
                    AoWE.AoWHSMap.ShowMessage(format);
                }
                else
                {
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    var translateRStr = AoWE.TranslateRStr(AoWE.RaceNamesPluralRStr[players.FPlayerRace]);
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.AreMovingRStr), [translateRStr]);
                    AoWE.AoWHSMap.ShowMessage(format);
                }
            }
            else
            {
                PlaySample((AnsiString)"SFX\\EVENTS\\NEWTURN.WAV");
                if (AoWE.AoWHSMap.FDay == 1 && (AoWE.AoWHSMap.FRequestCombatType || Player == AoWE.AoWHSMap.FSeatedPlayer))
                {
                    if (TSet<TGameType>.Of(TGameType.gtCustom, TGameType.gtTutorial).Contains(AoWE.AoWHSMap.FGameType))
                    {
                        BookLog = new TShowBookEventLog(null);
                        AoWE.AoWHSMap.TriggerExecuteEventLog(BookLog, false, null);
                        BookLog.Release();
                    }

                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchSpellID == 0)
                    {
                        Spells = new TSpellList();
                        AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.ListResearchSpells(ref Spells, TSet<TSpellType>.Of(TSpellType.stCombat, TSpellType.stUnit, TSpellType.stGlobal));
                        if (Spells.GetCount() > 0)
                        {
                            MagicLog = new TPlayerMagicEventLog(null);
                            MagicLog.FMode = TPlayerMagicEventMode.pmemStartResearch;
                            AoWE.AoWHSMap.TriggerExecuteEventLog(MagicLog, false, null);
                            MagicLog.Release();
                        }

                        Spells.Free();
                    }

                    AoWE.AoWHSMap.FTutorialControl.ShowMessage(52, false, true);
                }
            }
        }

