        // PlayerC.PAS:854
        public override void SetPlayerGameOverStatus(sbyte Player, TGameOverStatus Status)
        {
            base.SetPlayerGameOverStatus(Player, Status);
            if (!AoWE.AoWHSMap.FRequestCombatType || AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus = TPlayerStatus.psTerminated;
                AoWE.AoWHSMap.FPlayers.Update();
                AoWE.AoWHSMap.TriggerPlayerTerminatedEvent(Player);
                if (AoWE.AoWHSMap.FCurrentPlayer == Player && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetLocal())
                {
                    AoWE.EndPlayerTurn(AoWE.AoWHSMap.FCurrentPlayer);
                }

                if (AoWE.AoWHSMap.FPlayers.FLocalHumanPlayers.Count == 0)
                {
                    AoWE.AoWHSMap.TriggerGameTerminatedEvent();
                }
            }
        }

