        // PlayerC.PAS:842
        public override void GameOverEventHandled(sbyte Player)
        {
            if (AoWE.AoWHSMap.FRequestCombatType)
            {
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus = TPlayerStatus.psTerminated;
                AoWE.AoWHSMap.FPlayers.Update();
                AoWE.AoWHSMap.TriggerPlayerTerminatedEvent(Player);
                if (AoWE.AoWHSMap.FPlayers.FLocalHumanPlayers.Count == 0)
                {
                    AoWE.AoWHSMap.TriggerGameTerminatedEvent();
                }
                else
                {
                    AoWE.EndPlayerTurn(AoWE.AoWHSMap.FCurrentPlayer);
                }
            }
        }

        // PlayerC.PAS:715
        public override void EndTurn(sbyte Player)
        {
            TEndTurnEventLog Log;
            int Index;
            bool Found;
            sbyte NextPlayer;
            base.EndTurn(Player);
            if (Player == AoWE.AoWHSMap.FSeatedPlayer)
            {
                AoWE.AoWHSMap.ZeroTurnTimer();
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psPlaying)
                {
                    AoWE.AoWHSMap.ClearExecuteEventLogBuffer();
                }

                AoWE.AoWHSMap.Selection.UnselectLocation();
            }

            if (Player == AoWE.AoWHSMap.FCurrentPlayer)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
                {
                    AoWE.AoWHSMap.FAIExecuter.DeactivatePlayer(Player);
                }

                Log = new TEndTurnEventLog(null);
                AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FEventLogbook.AddEvent(Log);
                Log.Release();
                Index = AoWE.AoWHSMap.FTurnOrder.IndexOf((byte)AoWE.AoWHSMap.FCurrentPlayer);
                Found = false;
                while (!Found)
                {
                    Index += 1;
                    if (Index == AoWE.AoWHSMap.FTurnOrder.Count)
                    {
                        NewDay();
                        Index = 0;
                    }

                    NextPlayer = (sbyte)AoWE.AoWHSMap.FTurnOrder[Index];
                    Found = AoWE.AoWHSMap.FPlayers.GetPlayers(NextPlayer).FStatus == TPlayerStatus.psPlaying;
                    if (!Found)
                    {
                        base.NewTurn(NextPlayer);
                        base.EndTurn(NextPlayer);
                    }
                }

                if (AoWE.AoWHSMap.FTurnOrder.Count != 0)
                {
                    NewTurn((sbyte)AoWE.AoWHSMap.FTurnOrder[Index]);
                }
                else
                {
                    NewTurn(0);
                }
            }
        }

