        public override void SetSeatedPlayer(sbyte Player)
        {
            AoWE.AoWHSMap.LockMapChangedEvent();
            base.SetSeatedPlayer(Player);
            AoWE.AoWHSMap.UnlockMapChangedEvent();
            AoWE.AoWHSMap.InvalidateMap();
        }

        // PlayerC.PAS:779
        public virtual void StartLoadedMapEx()
        {
            TNewTurnEventLog Log = default;
            DefaultStartMap();
            AoWE.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(AoWE.AoWHSMap.FCurrentPlayer);
            if (AoWE.AoWHSMap.FRequestCombatType)
            {
                AoWE.AoWHSMap.SetSeatedPlayer(-1);
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FPlayerType == TPlayerType.ptHuman)
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWE.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWE.TranslateRStr(AoWE.YourTurnContinuesRStr);
                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, StartGameCallBack);
                    Log.Release();
                }
                else
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWE.AoWHSMap.FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of();
                    if (AoWE.AoWHSMap.FCurrentPlayer == 0)
                    {
                        Log.FText = AoWE.TranslateRStr(AoWE.IndependentsAreMovingRStr);
                    }
                    else
                    {
                        var name = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).GetName();
                        Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.PlayerIsMovingRStr), [name]);
                    }

                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, true, null);
                    Log.Release();
                }
            }
            else
            {
                var item = AoWE.AoWHSMap.FPlayers.FLocalHumanPlayers[0];
                AoWE.AoWHSMap.SetSeatedPlayer((sbyte)item);
                AoWE.AoWHSMap.ResetSeatedPlayerView();
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FPlayerType == TPlayerType.ptHuman && AoWE.AoWHSMap.FCurrentPlayer == AoWE.AoWHSMap.FSeatedPlayer)
                {
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = AoWE.AoWHSMap.FSeatedPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWE.TranslateRStr(AoWE.YourTurnContinuesRStr);
                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, StartGameCallBack);
                    Log.Release();
                }
            }

            if (AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FPlayerType != TPlayerType.ptHuman)
            {
                AoWE.AoWHSMap.FAIExecuter.ActivatePlayer(AoWE.AoWHSMap.FCurrentPlayer);
            }

            AoWE.AoWEngine.OutputDebugStr((AnsiString)"Random Seed: " + IntToStr(AoWE.AoWHSMap.FDefendersSeed));
        }

        // PlayerC.PAS:683
        public void ReplayLogbook()
        {
            TEventLogbook Book;
            int Index;
            Book = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FEventLogbook;
            Index = Book.FindFirstLogEx(131811, AoWE.AoWHSMap.FCurrentPlayer, AoWE.AoWHSMap.FDay - 1);
            for (int I = Index + 1, last = Book.GetCount() - 1; I <= last; I++)
            {
                Book.GetLogs(I).Execute(false, TExecuteTrigger.etNewTurn, null);
            }
        }

