        // PlayerC.PAS:984
        public override void NewTurn(sbyte Player)
        {
            TSendEmailGameEventLog Log = default;
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus.Contains(TPBEMPlayerStatusElement.pbsNewTurn) || AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman || AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psTerminated)
            {
                base.NewTurn(Player);
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus - TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn, TPBEMPlayerStatusElement.pbsTurnDone) + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsPlaying);
            }
            else
            {
                if (AoWE.AoWHSMap.FPlayers.FLocalPlayers.Count > 1 || Player != FLocalPlayer)
                {
                    AoWE.AoWHSMap.SetCurrentPlayer(Player);
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn);
                    Log = new TSendEmailGameEventLog(null);
                    Log.FMode = 2;
                    Log.FSendPlayer = Player;
                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, SendEmailGameCallBack);
                    Log.Release();
                }
                else
                {
                    base.NewTurn(Player);
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = players.FPBEMSettings.FStatus - TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn, TPBEMPlayerStatusElement.pbsTurnDone) + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsPlaying);
                }
            }
        }

        // PlayerC.PAS:1194
        public override void StartNewMap()
        {
            int I;
            int Player;
            DefaultStartMap();
            NewDay();
            I = 0;
            int last = AoWE.AoWHSMap.FPlayers.Count - 1;
            for (; I <= last; I += 1)
            {
                if (I == 0 || AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptIndependent)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus = TPlayerStatus.psPlaying;
                }
            }

            I = 0;
            while (true)
            {
                bool condition = I < AoWE.AoWHSMap.FTurnOrder.Count;
                if (condition)
                {
                    var item = AoWE.AoWHSMap.FTurnOrder[I];
                    condition = AoWE.AoWHSMap.FPlayers.GetPlayers(item).FPlayerType != TPlayerType.ptHuman;
                }

                if (!condition)
                    break;
                I += 1;
            }

            Player = AoWE.AoWHSMap.FTurnOrder[I];
            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
            bool test = AoWE.AoWEngine.FEmailGames.FindEmailGame(players.FPBEMSettings.FEmailGame) != null;
            if (test)
            {
                var localEmailAddress = AoWE.AoWEngine.FRegistry.GetLocalEmailAddress();
                test = CompareText(AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FEmailGame.FEmailAddress, localEmailAddress) == 0;
            }

            if (test)
            {
                FLocalPlayer = (sbyte)Player;
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPBEMSettings.FStatus = fPlayersPlayers.FPBEMSettings.FStatus + TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn);
            }
            else
            {
                AoWE.AoWHSMap.SetSeatedPlayer(-1);
            }

            NewTurn((sbyte)AoWE.AoWHSMap.FTurnOrder[1]);
        }

