        // PlayerC.PAS:1136
        public void ValidateLoadedMap()
        {
            bool Restarted = default;
            TMessageEventLog Log = default;
            FLocalPlayer = AoWE.AoWHSMap.FCurrentPlayer;
            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer);
            if (AoWE.AoWEngine.FEmailGames.FindEmailGame(players.FPBEMSettings.FEmailGame) == null)
            {
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer);
                Restarted = AoWE.AoWEngine.FEmailGames.EmailGameRestarted(fPlayersPlayers.FPBEMSettings.FEmailGame);
                var players2 = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer);
                var players3 = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer);
                var emailGame = AoWE.AoWEngine.FEmailGames.CreateEmailGame(players3.FPBEMSettings.FEmailGame.FName, players2.FPBEMSettings.FEmailGame.FEmailAddress);
                AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FPBEMSettings.SetGame(emailGame);
                if (Restarted)
                {
                    TriggerGameRestartedEvents(AoWE.AoWHSMap.FCurrentPlayer);
                }

                StartLoadedEmailGame();
            }
            else
            {
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer);
                if (AoWE.AoWEngine.FEmailGames.EmailGameRestarted(fPlayersPlayers.FPBEMSettings.FEmailGame))
                {
                    SetSeatedPlayer(-1);
                    Log = new TMessageEventLog(null);
                    Log.FButtons = TMessageEventLogButtons.mebYesNo;
                    Log.FTitle = AoWE.TranslateRStr(AoWE.WarningRStr);
                    var translateRStr = AoWE.TranslateRStr(AoWE.PBEMRestartCheatRStr);
                    Log.FMessage.Text = translateRStr;
                    Log.FMessage.Add((AnsiString)"");
                    var aoWETranslateRStr = AoWE.TranslateRStr(AoWE.DoYouWantToContinueRStr);
                    Log.FMessage.Add(aoWETranslateRStr);
                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, ContinueRestartedGameCallBack);
                    Log.Release();
                }
                else
                {
                    SetSeatedPlayer(-1);
                    if ((AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).FPBEMSettings.FStatus & TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsNewTurn, TPBEMPlayerStatusElement.pbsTurnDone)) == TSet<TPBEMPlayerStatusElement>.Of(TPBEMPlayerStatusElement.pbsTurnDone))
                    {
                        Log = new TMessageEventLog(null);
                        Log.FTitle = AoWE.TranslateRStr(AoWE.WarningRStr);
                        Log.FButtons = TMessageEventLogButtons.mebYesNo;
                        var translateRStr = AoWE.TranslateRStr(AoWE.PBEMGameEndedRStr);
                        Log.FMessage.Text = translateRStr;
                        Log.FMessage.Add((AnsiString)"");
                        var aoWETranslateRStr = AoWE.TranslateRStr(AoWE.DoYouWantToContinueRStr);
                        Log.FMessage.Add(aoWETranslateRStr);
                        AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, ContinueTurnDoneGameCallBack);
                        Log.Release();
                    }
                    else
                    {
                        StartLoadedEmailGame();
                    }
                }
            }
        }

