        // PlayerC.PAS:1258
        public override void NewTurn(sbyte Player)
        {
            TEventLog Log;
            TSpellList Spells = default;
            if (Player == AoWE.AoWHSMap.FSeatedPlayer)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType == TPlayerType.ptHuman)
                {
                    if (AoWE.AoWHSMap.FDay == 1)
                    {
                        if (AoWE.AoWHSMap.FGameType == TGameType.gtCustom)
                        {
                            Log = new TShowBookEventLog(null);
                            AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                            Log.Release();
                        }

                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.FResearchSpellID == 0)
                        {
                            Spells = new TSpellList();
                            AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FMagicControl.ListResearchSpells(ref Spells, TSet<TSpellType>.Of(TSpellType.stCombat, TSpellType.stUnit, TSpellType.stGlobal));
                            if (Spells.GetCount() > 0)
                            {
                                Log = new TPlayerMagicEventLog(null);
                                ((TPlayerMagicEventLog)Log).FMode = TPlayerMagicEventMode.pmemStartResearch;
                                AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, null);
                                Log.Release();
