                            Spells.Free();
                        }
                    }
                    else
                    {
                        AoWE.AoWHSMap.ResetTurnTimer();
                        AoWE.AoWHSMap.EnableTurnTimer();
                    }
                }
            }

            base.NewTurn(Player);
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus == TPlayerStatus.psPlaying)
                {
