        // PlayerC.PAS:1305
        public override void EndTurn(sbyte Player)
        {
            int I;
            bool AllDone;
            TEndTurnEventLog Log;
            TEMsg Msg = default;
            AoWE.AoWHSMap.FPlayers.GetPlayers(Player).SetEndTurn(true);
            AllDone = true;
            I = 1;
            while (AllDone && I != AoWE.AoWHSMap.FPlayers.Count)
            {
                AllDone = AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus != TPlayerStatus.psPlaying || AoWE.AoWHSMap.FPlayers.GetPlayers(I).FSingleProcessCycle;
                I += 1;
            }

            if (AllDone)
            {
                if (AoWE.AoWHSMap.FSeatedPlayer == Player)
                {
                    AoWE.AoWHSMap.ClearExecuteEventLogBuffer();
                }

                AoWE.AoWHSMap.LockRelationsChanged();
                I = 0;
                int last = AoWE.AoWHSMap.FPlayers.Count - 1;
                for (; I <= last; I += 1)
                {
                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus == TPlayerStatus.psPlaying)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptHuman)
                        {
                            AoWE.AoWHSMap.FAIExecuter.DeactivatePlayer((sbyte)I);
                        }

                        Log = new TEndTurnEventLog(null);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(I).FEventLogbook.AddEvent(Log);
                        Log.Release();
                    }

                    InitMsg(ref Msg, 537001991, this);
                    Msg.Value = I;
                    AoWE.AoWHSMap.SendMsg(ref Msg, this);
                }

                AoWE.AoWHSMap.UnlockRelationsChanged();
                NewDay();
            }
        }

