            AoWE.AoWHSMap.SetSeatedPlayer((sbyte)item);
            AoWE.AoWHSMap.SeatedPlayerChanged();
            AoWE.AoWHSMap.ResetSeatedPlayerView();
            for (int I = 0, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                Player = AoWE.AoWHSMap.FPlayers.GetPlayers(I);
                if (Player.FStatus == TPlayerStatus.psPlaying && Player.FPlayerType != TPlayerType.ptHuman)
                {
                    AoWE.AoWHSMap.FAIExecuter.ActivatePlayer((sbyte)I);
                }
            }

            for (int I = 0, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FStatus != TPlayerStatus.psPlaying)
                {
                    AoWE.AoWHSMap.FTokenManager.TokenControls[I].Active = false;
                }
            }

            AoWE.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(AoWE.AoWHSMap.FCurrentPlayer);
            Log = new TNewTurnEventLog(null);
            Log.FTurnPlayer = AoWE.AoWHSMap.FSeatedPlayer;
            Log.FMode = TNewTurnEventLogMode.ntDialog;
            Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
            Log.FText = AoWE.TranslateRStr(AoWE.TheGameContinuesRStr);
            AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, StartGameCallBack);
            Log.Release();
            if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork)
            {
                AoWE.AoWHSMap.ResetTurnTimer();
                AoWE.AoWHSMap.EnableTurnTimer();
            }
            else
            {
                AoWE.AoWHSMap.FAIExecuter.Lock();
            }
        }

