        public int AddMoveObject(THexagonSprite Obj)
        {
            TMoveSettings Settings;
            Settings = new TMoveSettings(null);
            Settings.FMoveObject = Obj;
            Settings.SetOwner(FMoveSettingsList);
            return FMoveSettingsList.Count - 1;
