        // Structur.PAS:4167
        public void DeleteMoveObject(int A1)
        {
            TObject Obj;
            if (FCurrentMove != -1)
            {
                Obj = FMoveSettingsList.GetMoveSettings(FCurrentMove).FMoveObject;
            }
            else
            {
                Obj = null;
            }

            ((TObject)FMoveSettingsList.FChildren.List[A1]).Free();
            if (Obj != null)
            {
                A1 = FMoveSettingsList.IndexOfMoveObject(Obj);
                if (A1 == -1)
                {
                    SetCurrentMove(FMoveSettingsList.Count - 1);
                }
                else
                {
                    SetCurrentMove(A1);
                }
            }
        }

        // Structur.PAS:4183
        public void DeleteMoves()
        {
            while (FMoveSettingsList.Count != 0)
            {
                DeleteMoveObject(FMoveSettingsList.Count - 1);
            }
        }

