    // { Interface declaration run owned by P1. }
    public partial class TTargetSelectionControl : TObject
    {
        // Structur.PAS:3785
        // images, HNs, status, mode, callbacks, range, source coordinates, source, change events,
        // change, target, text, title, cancel text, images
        public TTargetSelectionControl()
        {
            FOnChange = new TEventList();
            FHNs = new TShortIntList();
            FText = new TStringList();
        }

        public TCustomImageLibrary FImageLibrary;
        public TShortIntList FHNs;
        public TSet<TTargetSelectionStatusElement> FStatus;
        public TSet<TTargetSelectionModeElement> FTargetMode;
        public TShowTargetSelectionEvent FOnShow;
        public TValidateTargetEvent FOnValidateTarget;
        public int FRange;
        public int FSourceX;
        public int FSourceY;
        public int FSourceL;
        public TObject FSource;
        public TEventList FOnChange;
        public TTargetSelectionChange FChange;
        public sbyte FTargetX;
        public sbyte FTargetY;
        public sbyte FTargetL;
        public TStrings FText;
        public AnsiString FTitle;
        public AnsiString FCancelText;
        public int FSourceUnitID;
        public ImageLib.TLibraryImage FSourceImage;
        public ImageLib.TLibraryImage FValidTargetImage;
        public ImageLib.TLibraryImage FInvalidTargetImage;
        // Structur.PAS:3793
        public override void Destroy()
        {
            FText.Free();
            FOnChange.Free();
            FOnChange = null;
            FHNs.Free();
            FHNs = null;
            if (FImageLibrary != null)
            {
                // { Original links the image library again when destroying the control. }
                AoWE.AoWHSSet.ImageLibraryManager.LinkToIL(TSet<TILManagerCategoryElement>.Of(TILManagerCategoryElement.icDisk), (AnsiString)"TARGHEX.ILB");
                FImageLibrary = null;
            }

            base.Destroy();
        }


        // Structur.PAS:3809
        public void TriggerOnChangeEvent(TTargetSelectionChange Change)
        {
            FChange = Change;
            FOnChange.TriggerNotifyEvents(this);
            FChange = TTargetSelectionChange.tscNone;
        }

        // Structur.PAS:3816
        public void DeselectHS(TObject Sender)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                Deactivate();
            }
        }

        // Structur.PAS:3821
        public void MouseDownEvent(TObject Sender)
        {
            THSMapMouse Mouse;
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                if (AoWE.AoWHSMap.Mouse.Capture != this || AoWE.AoWHSMap.Mouse.Button == TMouseButton.mbRight)
                {
                    Deactivate();
                    AoWE.AoWHSMap.FSelectedArmy.FIgnoreMouseDown = true;
                }
                else
                {
                    Mouse = AoWE.AoWHSMap.Mouse;
                    if (Mouse.Capture == this && Mouse.Button == TMouseButton.mbLeft)
                    {
                        if (ValidTarget(FTargetX, FTargetY, FTargetL))
                        {
                            TriggerOnChangeEvent(TTargetSelectionChange.tscSelected);
                            if (!FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
                            {
                                AoWE.AoWHSMap.FSelectedArmy.FIgnoreMouseDown = true;
                            }
                        }
                    }
                }
            }
        }

        // Structur.PAS:3845
        public bool ValidTarget(sbyte X, sbyte Y, sbyte L)
        {
            bool Result = default;
            TMapField MapField;
            if (X != -1 && Y != -1)
            {
                if (FTargetMode.Contains(TTargetSelectionModeElement.tmValidateDistance))
                {
                    Result = dHXtoRad(FSourceX, FSourceY, X, Y) <= FRange;
                }
                else
                {
                    Result = true;
                }

                if (FTargetMode.Contains(TTargetSelectionModeElement.tmFixedLevel))
                {
                    Result = Result && L == FSourceL;
                }

                MapField = AoWE.AoWHSMap.MapContainer.GetField(X, Y, L);
                Result = Result && MapField.TerrainType != 15;
                if (Result && FOnValidateTarget != null)
                {
                    FOnValidateTarget(this, X, Y, L, ref Result);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:3862
        public void NewFrameEvent(TObject Sender)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                if (FStatus.Contains(TTargetSelectionStatusElement.tsVisible))
                {
                    AoWE.AoWHSMap.Mouse.SetCursor(110 + (int)(((uint)AoWE.AoWHSMap.Frame) >> 2) % 10);
                    AoWE.AoWHSMap.Mouse.CursorVisible = true;
                }
                else
                {
                    AoWE.AoWHSMap.Mouse.SetCursor(120);
                    AoWE.AoWHSMap.Mouse.CursorVisible = false;
                }
            }
        }

        // Structur.PAS:3877
        public void MouseMoveEvent(TObject Sender)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FTargetX = (sbyte)AoWE.AoWHSMap.Mouse.GetXhx();
                FTargetY = (sbyte)AoWE.AoWHSMap.Mouse.GetYhx();
                FTargetL = (sbyte)AoWE.AoWHSMap.ViewL;
                bool condition = AoWE.AoWHSMap.Mouse.GetXhx() != -1 && AoWE.AoWHSMap.Mouse.GetYhx() != -1;
                if (condition)
                {
                    var yhx = AoWE.AoWHSMap.Mouse.GetYhx();
                    condition = ValidTarget((sbyte)AoWE.AoWHSMap.Mouse.GetXhx(), (sbyte)yhx, (sbyte)AoWE.AoWHSMap.ViewL);
                }

                if (condition)
                {
                    FStatus = FStatus + TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsVisible);
                }
                else
                {
                    FStatus = FStatus - TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsVisible);
                }
            }
        }

        // Structur.PAS:3891
        public void ShowSelection(int XhpSurf, int YhpSurf, in TSurfaceDesc SurfaceDesc)
        {
            int DX = default;
            int DY = default;
            int X = default;
            int Y = default;
            int XS;
            int YS;
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated) && FTargetX != -1 && FStatus.Contains(TTargetSelectionStatusElement.tsVisible))
            {
                HXtoHP(FTargetX, FTargetY, ref X, ref Y);
                X -= XhpSurf;
                Y -= YhpSurf;
                for (int I = 0, last = FHNs.Count - 1; I <= last; I++)
                {
                    if (FHNs[I] >= 0)
                    {
                        HNtoHP(I, ref DX, ref DY);
                        XS = X + DX;
                        YS = Y + DY;
                        if (FTargetMode.Contains(TTargetSelectionModeElement.tmOwnerDraw))
                        {
                            if (FOnShow != null)
                            {
                                FOnShow(this, I, XS, YS, SurfaceDesc);
                            }
                        }
                        else
                        {
                            var item = FHNs[I];
                            FImageLibrary.Get(item).Show(XS - 8, YS, SurfaceDesc);
                        }
                    }
                }
            }
        }

        // Structur.PAS:3915
        public void Initialize(TObject A1)
        {
            if (FImageLibrary == null)
            {
                FImageLibrary = AoWE.AoWHSSet.ImageLibraryManager.LinkToIL(TSet<TILManagerCategoryElement>.Of(TILManagerCategoryElement.icDisk), (AnsiString)"TARGHEX.ILB");
            }

            if (!FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FHNs.Clear();
                FSource = A1;
                FTargetMode = TSet<TTargetSelectionModeElement>.Of(TTargetSelectionModeElement.tmFixedLevel);
            }
            else
            {
                throw Exception.Create((AnsiString)"please deactivate before initializing (TTargetSelectionControl)");
            }
        }

        // Structur.PAS:3928
        public void Activate()
        {
            if (!FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FStatus = FStatus + TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsActivated);
                AoWE.AoWHSMap.Mouse.SetCapture(this);
                AoWE.AoWHSMap.Mouse.OnDown.Add(MouseDownEvent);
                AoWE.AoWHSMap.Mouse.OnMove.Add(MouseMoveEvent);
                AoWE.AoWHSMap.NewFrameEvents.Add(NewFrameEvent);
                AoWE.AoWHSMap.Selection.OnDeselect.Add(DeselectHS);
                AoWE.AoWHSMap.Mouse.CursorMode = 256;
                AoWE.AoWHSMap.FKeyboard.Lock();
                TriggerOnChangeEvent(TTargetSelectionChange.tscActivated);
                MouseMoveEvent(this);
            }
            else
            {
                throw Exception.Create((AnsiString)"Already activated");
            }
        }

        // Structur.PAS:3946
        public void Deactivate()
        {
            TArmyHS ArmyHS = default;
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated))
            {
                FStatus = FStatus - TSet<TTargetSelectionStatusElement>.Of(TTargetSelectionStatusElement.tsActivated);
                AoWE.AoWHSMap.Mouse.OnDown.Remove(MouseDownEvent);
                AoWE.AoWHSMap.Mouse.OnMove.Remove(MouseMoveEvent);
                AoWE.AoWHSMap.NewFrameEvents.Remove(NewFrameEvent);
                AoWE.AoWHSMap.Selection.OnDeselect.Remove(DeselectHS);
                if (AoWE.AoWHSMap.Mouse.Capture == this)
                {
                    if (AoWE.AoWHSMap.FSelectedArmy.GetArmyHS() != null)
                    {
                        ArmyHS = AoWE.AoWHSMap.FSelectedArmy.GetArmyHS();
                        AoWE.AoWHSMap.Mouse.SetCapture(null);
                        AoWE.AoWHSMap.Selection.UnselectLocation();
                        AoWE.AoWHSMap.Selection.SelectLocationHS(ArmyHS);
                    }
                    else
                    {
                        AoWE.AoWHSMap.Mouse.SetCapture(null);
                    }
                }

                AoWE.AoWHSMap.FKeyboard.Unlock();
                TriggerOnChangeEvent(TTargetSelectionChange.tscDeactivated);
                FSource = null;
                FOnShow = null;
                FOnValidateTarget = null;
            }
        }

        // Structur.PAS:3974
        public void UnitChanged(TObject AUnit)
        {
            if (FStatus.Contains(TTargetSelectionStatusElement.tsActivated) && FSource != null && AUnit == FSource && ((TAbstractUnit)AUnit).FUnitStatus.Contains(TUnitStatusElement.usKilled))
            {
                Deactivate();
            }
        }

        // intf_P1_05.inc:31

    }

    // TNotifyEvent target passed directly
    // cheat text, mode, lock count
    public partial class TAoWHSMapKeyboard : TEObject
    {
        public TAoWHSMapKeyboard(TECustomNode owner) : base(owner)
        {}

        public AnsiString FCheatText;
        public TAoWHSMapKeyboardMode FMode;
        public int FLockCount;
        // AoWHSMap.PAS:946
        public virtual void KeyDown(ref ushort Key, TSet<TShiftState> Shift)
        {
            ushort TranslatedKey;
            int I;
            bool Prefix;
            bool Complete;
            TCheatTE Cheat;
            if (FLockCount != 0)
            {
                return;
            }

            // { Original uses OR between the digit bounds, admitting every key. }
            if ((Key >= 65 && Key <= 90) || Key >= 48 || Key <= 57 || Key == 188 || Key == 190 || Key == 13)
            {
                switch (FMode)
                {
                    case TAoWHSMapKeyboardMode.kmDefault:
                        TranslatedKey = Key;
                        switch (AoWE.AoWEngine.FLanguage)
                        {
                            case 3:
                                switch (Key)
                                {
                                    case 83:
                                        TranslatedKey = 78;
                                        break;
                                    case 67:
                                        TranslatedKey = 76;
                                        break;
                                    case 84:
                                        TranslatedKey = 68;
                                        break;
                                    case 86:
                                        TranslatedKey = 67;
                                        break;
                                    case 68:
                                        TranslatedKey = 77;
                                        break;
                                }

                                break;
                            case 5:
                                switch (Key)
                                {
                                    case 86:
                                        TranslatedKey = 78;
                                        break;
                                    case 69:
                                        TranslatedKey = 72;
                                        break;
                                    case 67:
                                        TranslatedKey = 76;
                                        break;
                                    case 70:
                                        TranslatedKey = 68;
                                        break;
                                    case 83:
                                        TranslatedKey = 71;
                                        break;
                                    case 84:
                                        TranslatedKey = 67;
                                        break;
                                }

                                break;
                            case 4:
                                switch (Key)
                                {
                                    case 65:
                                        TranslatedKey = 68;
                                        break;
                                }

                                break;
                        }

                        if (!Shift.Contains(TShiftState.ssCtrl))
                        {
                            switch (TranslatedKey)
                            {
                                case 79:
                                    AoWE.AoWHSMap.FShowIndependentMoves = !AoWE.AoWHSMap.FShowIndependentMoves;
                                    if (AoWE.AoWHSMap.FShowIndependentMoves)
                                    {
                                        var translateRStr = AoWE.TranslateRStr(AoWE.ObserveEnabledRStr);
                                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                                    }
                                    else
                                    {
                                        var translateRStr = AoWE.TranslateRStr(AoWE.ObserveDisabledRStr);
                                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                                    }

                                    break;
                                case 78:
                                case 188:
                                    AoWE.AoWHSMap.SelectNextArmy();
                                    break;
                                case 80:
                                case 190:
                                    AoWE.AoWHSMap.SelectPrevArmy();
                                    break;
                                case 72:
                                    AoWE.AoWHSMap.SelectNextHero();
                                    break;
                                case 77:
                                    AoWE.AoWHSMap.FSelectedArmy.ExecuteMove();
                                    break;
                                case 68:
                                    AoWE.AoWHSMap.FSelectedArmy.TurnDone();
                                    break;
                                case 71:
                                    AoWE.AoWHSMap.FSelectedArmy.ToggleGuard();
                                    break;
                                case 76:
                                    AoWE.AoWHSMap.CenterOnLeader(AoWE.AoWHSMap.FSeatedPlayer, true, false);
                                    break;
                                case 67:
                                    if (!Shift.Contains(TShiftState.ssCtrl))
                                    {
                                        AoWE.AoWHSMap.FSelectedArmy.Center();
                                    }

                                    break;
                                case 82:
                                    if (AoWE.AoWEngine.FDebug)
                                    {
                                        AoWE.AoWEngine.OutputDebugStr((AnsiString)"Random Seed: " + IntToStr(AoWE.AoWHSMap.FDefendersSeed));
                                    }

                                    break;
                                case 83:
                                    if (!Shift.Contains(TShiftState.ssCtrl) && AoWE.AoWEngine.FRegistry.GetDebugMode())
                                    {
                                        RunDefaultTest();
                                    }

                                    break;
                                case 65:
                                    if (AoWE.AoWEngine.FRegistry.GetDeveloper() && AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FSeatedPlayer).FPlayerType != TPlayerType.ptHuman)
                                    {
                                        AoWE.AoWHSMap.FAIExecuter.ActivatePlayer(AoWE.AoWHSMap.FSeatedPlayer);
                                    }

                                    break;
                                case 73:
                                    if (AoWE.AoWEngine.FDebug)
                                    {
                                        var heapStatus = GetHeapStatus();
                                        AoWE.AoWHSMap.ShowMessage((AnsiString)"Allocated Memory: " + IntToStr(heapStatus.TotalAllocated));
                                    }

                                    break;
                            }
                        }

                        if (Shift.Contains(TShiftState.ssCtrl))
                        {
                            switch (Key)
                            {
                                case 69:
                                    AoWE.AoWHSMap.EndTurn();
                                    break;
                                case 13:
                                    AoWE.AoWHSMap.EndTurn();
                                    break;
                            }
                        }

                        break;
                    case TAoWHSMapKeyboardMode.kmCheat:
                        FCheatText = FCheatText + AnsiString.FromBytes((byte)Key);
                        I = 10;
                        Complete = false;
                        Prefix = false;
                        while (I != 0 && !Complete)
                        {
                            I -= 1;
                            Prefix = Prefix || CompareText(FCheatText, Rtl.Rtl.Copy(AoWE.CheatNames[I], 1, FCheatText.Length)) == 0;
                            Complete = CompareText(FCheatText, AoWE.CheatNames[I]) == 0;
                        }

                        if (Complete && AoWE.AoWHSMap.FSeatedPlayer != -1 && !AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FSeatedPlayer).GetBusy())
                        {
                            Cheat = new TCheatTE(null);
                            Cheat.FPlayer = AoWE.AoWHSMap.FSeatedPlayer;
                            Cheat.FCheatID = I;
                            AoWE.AoWHSMap.FTokenManager.GetTokenControl(AoWE.AoWHSMap.FSeatedPlayer).AddEvent(Cheat);
                            Cheat.Release();
                            FCheatText = (AnsiString)"";
                            FMode = TAoWHSMapKeyboardMode.kmDefault;
                        }
                        else
                        {
                            if (!Prefix)
                            {
                                FMode = TAoWHSMapKeyboardMode.kmDefault;
                                FCheatText = (AnsiString)"";
                            }
                        }

                        break;
                }
            }

            if (Key == 67 && (TSet<TShiftState>.Of(TShiftState.ssShift, TShiftState.ssCtrl) & Shift) == TSet<TShiftState>.Of(TShiftState.ssShift, TShiftState.ssCtrl) && CompareText(ParamStr(1), (AnsiString)"beatrix") == 0 && AoWE.AoWHSMap.FConnectionType != TPlayerConnectionType.pcNetwork && AoWE.AoWHSMap.FConnectionType != TPlayerConnectionType.pcEmail && !AoWE.AoWEngine.FDemo)
            {
                PlaySample((AnsiString)"SFX\\ATTACK\\MAGICB02.WAV");
                FMode = TAoWHSMapKeyboardMode.kmCheat;
                FCheatText = (AnsiString)"";
            }
        }

