    // selection rectangle, events
    public partial class TAbstractAoWHSMapMouse : THSMapMouse
    {
        public TAbstractAoWHSMapMouse() : base()
        {
            ResetRectangleSelection();
            FRectangleSelectEvents = new TEventList();
        }

        public TRect FSelectionRectangle;
        public TEventList FRectangleSelectEvents;
        // AoWHSMap.PAS:1057
        public override void Destroy()
        {
            base.Destroy();
            FRectangleSelectEvents.Free();
        }

        // AoWHSMap.PAS:1123
        public override void Down(TMouseButton Button, TSet<TShiftState> Shift, int X, int Y)
        {
            base.Down(Button, Shift, X, Y);
            if (Capture == null && !HSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                StartRectangleSelection(HSMap.ViewXhp + X - 2, HSMap.ViewYhp + Y - 3);
            }
        }

        // AoWHSMap.PAS:1130
        public override void Up(TMouseButton Button, TSet<TShiftState> Shift, int X, int Y)
        {
            base.Up(Button, Shift, X, Y);
            if (Capture == null && FSelectionRectangle.Left != -1)
            {
                if (X != -1 && Y != -1)
                {
                    StopRectangleSelection(HSMap.ViewXhp + X - 2, HSMap.ViewYhp + Y - 3);
                }
                else
                {
                    ResetRectangleSelection();
                }
            }
        }

        // AoWHSMap.PAS:1141
        public override void Move(TSet<TShiftState> Shift, int X, int Y)
        {
            base.Move(Shift, X, Y);
            if (Capture == null)
            {
                UpdateRectangleSelection(HSMap.ViewXhp + X - 2, HSMap.ViewYhp + Y - 3);
            }
        }


        // AoWHSMap.PAS:1063
        public void ResetRectangleSelection()
        {
            FSelectionRectangle.Left = -1;
            FSelectionRectangle.Top = -1;
            FSelectionRectangle.Right = -1;
            FSelectionRectangle.Bottom = -1;
        }

        // AoWHSMap.PAS:1071
        public bool GetSelectingRectangle()
        {
            bool Result;
            if (FSelectionRectangle.Left == -1 || (FSelectionRectangle.Left == FSelectionRectangle.Right && FSelectionRectangle.Top == FSelectionRectangle.Bottom))
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // AoWHSMap.PAS:1079
        public void StartRectangleSelection(int A1, int A2)
        {
            FSelectionRectangle.Left = A1;
            FSelectionRectangle.Top = A2;
            FSelectionRectangle.Right = A1;
            FSelectionRectangle.Bottom = A2;
        }

        // AoWHSMap.PAS:1087
        public void UpdateRectangleSelection(int A1, int A2)
        {
            if (Button == TMouseButton.mbLeft)
            {
                if (A1 > 0 && A2 > 0)
                {
                    if (A1 < FSelectionRectangle.Left - 800)
                    {
                        A1 = FSelectionRectangle.Left - 800;
                    }

                    if (A1 > FSelectionRectangle.Left + 800)
                    {
                        A1 = FSelectionRectangle.Left + 800;
                    }

                    if (A2 < FSelectionRectangle.Top - 600)
                    {
                        A2 = FSelectionRectangle.Top - 600;
                    }

                    if (A2 > FSelectionRectangle.Top + 600)
                    {
                        A2 = FSelectionRectangle.Top + 600;
                    }

                    FSelectionRectangle.Right = A1;
                    FSelectionRectangle.Bottom = A2;
                }
            }
            else
            {
                ResetRectangleSelection();
            }
        }

        // AoWHSMap.PAS:1104
        public void StopRectangleSelection(int A1, int A2)
        {
            TRect R = default;
            FSelectionRectangle.Right = A1;
            FSelectionRectangle.Bottom = A2;
            if (FSelectionRectangle.Left < FSelectionRectangle.Right)
            {
                R.Left = FSelectionRectangle.Left;
            }
            else
            {
                R.Left = FSelectionRectangle.Right;
            }

            if (FSelectionRectangle.Right > FSelectionRectangle.Left)
            {
                R.Right = FSelectionRectangle.Right;
            }
            else
            {
                R.Right = FSelectionRectangle.Left;
            }

            if (FSelectionRectangle.Top < FSelectionRectangle.Bottom)
            {
                R.Top = FSelectionRectangle.Top;
            }
            else
            {
                R.Top = FSelectionRectangle.Bottom;
            }

            if (FSelectionRectangle.Bottom > FSelectionRectangle.Top)
            {
                R.Bottom = FSelectionRectangle.Bottom;
            }
            else
            {
                R.Bottom = FSelectionRectangle.Top;
            }

            FSelectionRectangle = R;
            FRectangleSelectEvents.TriggerNotifyEvents(this);
            ResetRectangleSelection();
        }

        // intf_P1_05.inc:68

    }

