        // AoWHSMap.PAS:759
        public virtual void ShowBackHexagonSelector(int XhpSurf, int YhpSurf, in TSurfaceDesc SurfaceDesc)
        {
            int Xhp = default;
            int Yhp = default;
            if (FSelectorX != -1 && FSelectorY != -1 && AoWE.AoWHSMap.Mouse.Capture == AoWE.AoWHSMap.FSelectedArmy)
            {
                HXtoHP(FSelectorX, FSelectorY, ref Xhp, ref Yhp);
                Xhp = Xhp - XhpSurf - 8;
                Yhp = Yhp - YhpSurf - 32 + 2;
                AoWE.AoWHSSet.FGeneralImages[7].Show(Xhp, Yhp, SurfaceDesc);
            }
        }

        // AoWHSMap.PAS:772
        public virtual void ShowFrontHexagonSelector(int XhpSurf, int YhpSurf, in TSurfaceDesc SurfaceDesc)
        {
            int Xhp = default;
            int Yhp = default;
            if (FSelectorX != -1 && FSelectorY != -1 && AoWE.AoWHSMap.Mouse.Capture == AoWE.AoWHSMap.FSelectedArmy)
            {
                HXtoHP(FSelectorX, FSelectorY, ref Xhp, ref Yhp);
                Xhp = Xhp - XhpSurf - 8;
