        // AoWHSMap.PAS:612
        public bool ExploreArea(int X, int Y, int Level, sbyte Player, int Range)
        {
            bool Result;
            if (!Status.Contains(THSMapStatusElement.msEditting))
            {
                Result = ((TAoWMapLevel)MapContainer.GetMapLevel(Level)).ExploreArea(X, Y, Player, Range);
                if (Result && FMapChangedLockCount == 0 && FFogEnabled)
                {
                    MapChangedRad(X, Y, Level, Range);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWHSMap.PAS:622
        public TSet<TFogExplorationChangedElement> UnFogExploreArea(int X, int Y, int Level, sbyte Player, int Range)
        {
            TSet<TFogExplorationChangedElement> Result = default;
            int Radius;
            // { Preserve the original assertion diagnostic, independent of the build path. }
            Radius = Range;
            if (Radius > 15)
            {
                /* TODO: Implement the inline assembly operation. */
                throw new NotImplementedException();
            }

            // { Original leaves Result undefined when a fog-only operation changes nothing. }
            if (!Status.Contains(THSMapStatusElement.msEditting))
            {
                if (Player >= 0)
                {
                    Result = ((TAoWMapLevel)MapContainer.GetMapLevel(Level)).UnFogExploreArea(X, Y, Player, Radius);
                }
                else
                {
                    if (((TAoWMapLevel)MapContainer.GetMapLevel(Level)).UnFogArea(X, Y, Radius))
                    {
                        Result = TSet<TFogExplorationChangedElement>.Of(TFogExplorationChangedElement.feFog);
                    }
                }
            }
            else
            {
                if (((TAoWMapLevel)MapContainer.GetMapLevel(Level)).UnFogArea(X, Y, Radius))
                {
                    Result = TSet<TFogExplorationChangedElement>.Of(TFogExplorationChangedElement.feFog);
                }
            }

            if (FMapChangedLockCount == 0 && ((Result.Contains(TFogExplorationChangedElement.feFog) && FFogEnabled) || (Result.Contains(TFogExplorationChangedElement.feExploration) && FExplorationEnabled && Player == FSeatedPlayer)))
            {
                MapChangedRad(X, Y, Level, Radius);
            }

            return Result;
        }

