            if (R.Left > 0 && R.Top > 0 && XhpSurf < R.Right && YhpSurf < R.Bottom && R.Right < ViewWidth + XhpSurf && R.Bottom < ViewHeight + YhpSurf)
            {
                DrawLine(R.Left - XhpSurf, R.Top - YhpSurf, R.Right - XhpSurf, R.Top - YhpSurf, 0, Color, SurfaceDesc);
