        // AoWHSMap.PAS:16
        public void ShowMessage(int ID, bool Immediate, bool OnceOnly)
        {
            TTutorialMessageEventLog Log;
            if (AoWE.AoWHSMap.FGameType == TGameType.gtTutorial && AoWE.AoWHSMap.FTextControl.FindID(ID) != null)
            {
                if (OnceOnly && FShownMessages.IndexOf(ID) != -1)
                {
                    return;
                }

                Log = new TTutorialMessageEventLog(null);
                var id = AoWE.AoWHSMap.FTextControl.FindID(ID);
                Log.FMessage.Assign(id.FText);
                AoWE.AoWHSMap.TriggerExecuteEventLog(Log, Immediate, null);
                Log.Release();
                FShownMessages.Add(ID);
            }
        }

