        // AoWHSMap.PAS:2160
        public override void ReadWrite(TEStorageStream Stream)
        {
            int X = default;
            int Y = default;
            int L = default;
            if (Stream.StorageMode().Contains(TStorageModeElement.smRead) && !Stream.StorageMode().Contains(TStorageModeElement.smTranslate))
            {
                Stream.ShowProgress(this, AoWE.TranslateRStr(OneMomentPleaseStr), 0);
            }

            if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smWrite, TStorageModeElement.smTextOnly)) == TSet<TStorageModeElement>.Of(TStorageModeElement.smWrite))
            {
                ResetModified();
            }

            FIgnoreStreamErrors = false;
            if (Status.Contains(THSMapStatusElement.msEditting))
            {
                Stream.OnError = OnStreamError;
            }

            Stream.rwData(Bytes.Of(ref FConnectionType, 1), 1, 31);
            if (FConnectionType == TPlayerConnectionType.pcNetwork)
            {
                X = FViewXhp;
                FViewXhp = 0;
                Y = FViewYhp;
                FViewYhp = 0;
                L = FViewL;
                FViewL = 0;
            }
            else
            {
                X = 0;
                Y = 0;
                L = 0;
            }

            base.ReadWrite(Stream);
            if (FConnectionType == TPlayerConnectionType.pcNetwork)
            {
                FViewXhp = X;
                FViewYhp = Y;
                FViewL = L;
            }

            Stream.rwString(ref FAuthor, 7);
            Stream.rwStrings(FDescription, 11);
            Stream.rwStrings(FObjectives, 12);
            Stream.rwData(Bytes.Of(ref FIndependentAIMode, 1), 1, 13);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FCurrentPlayer), 16);
            Stream.rwData(Bytes.Of(ref FTurnOrderMode, 1), 1, 17);
            Stream.rwStreamProc(18, FTurnOrder.LoadFromStream, FTurnOrder.SaveToStream);
            Stream.rwInteger(ref FDay, 19);
            Stream.rwString(ref FSessionName, 20);
            Stream.rwEObject(FPlayers, 21);
            Stream.rwEObject(FRaces, 22);
            Stream.rwBool(ref FExplorationEnabled, 23);
            if (!Stream.StorageMode().Contains(TStorageModeElement.smPreview))
            {
                Stream.rwEObject(FHeroControl, 24);
            }

            Stream.rwString(ref FMapName, 25);
            Stream.rwBool(ref FFogEnabled, 26);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FHeroCountMax), 27);
            Stream.rwInteger(ref FDefendersSeed, 28);
            if (!Stream.StorageMode().Contains(TStorageModeElement.smTextOnly) && !Stream.StorageMode().Contains(TStorageModeElement.smPreview) && !Stream.StorageMode().Contains(TStorageModeElement.smCompare))
            {
                Stream.rwEObject(FStartupSongs, 29);
            }

            Stream.rwEObject(FItemControl, 30);
