        // AoWHSMap.PAS:1559
        public bool TerrainVisible(sbyte X, sbyte Y, sbyte L, int Radius)
        {
            TMapLevel MapLevel;
            TAoWMapField Field;
            THNWalkData Walk = default;
            // { Original returns true immediately when exploration is enabled. }
            bool Result = AoWE.AoWHSMap.FExplorationEnabled;
            MapLevel = MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Walk.Radius <= Radius && !Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                {
                    Field = (TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y);
                    Result = Field.GetExplored(AoWE.AoWHSMap.FSeatedPlayer);
                }

                if (!Result)
                {
                    WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

        // AoWHSMap.PAS:1580
        public bool Visible(sbyte X, sbyte Y, sbyte L, int Radius)
        {
            TMapLevel MapLevel;
            TAoWMapField Field;
            THNWalkData Walk = default;
            bool Result = false;
            MapLevel = MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Walk.Radius <= Radius && !Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                {
                    Field = (TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y);
                    Result = (Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref Field.FFieldFlags).Hi).Lo != 0 || !AoWE.AoWHSMap.FFogEnabled) && (Field.GetExplored(AoWE.AoWHSMap.FSeatedPlayer) || !AoWE.AoWHSMap.FExplorationEnabled);
                }

                if (!Result)
                {
                    WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

        // AoWHSMap.PAS:1602
        public bool WatchingTerrain(sbyte X, sbyte Y, sbyte L, int Radius)
        {
            TMapLevel MapLevel;
            TAoWMapField Field;
            THNWalkData Walk = default;
            bool Result = false;
            MapLevel = MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Walk.Radius <= Radius && !Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                {
                    Field = (TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y);
                    Result = (Field.GetExplored(AoWE.AoWHSMap.FSeatedPlayer) || !AoWE.AoWHSMap.FExplorationEnabled) && Viewing(Walk.X, Walk.Y, L);
                }

                if (!Result)
                {
                    WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

