        // AoWHSMap.PAS:1904
        public void ExitGame(TExitGameMode Mode, TExitGameCallBack Done)
        {
            TPlayerControl PlayerControl;
            if (!FExitPending)
            {
                PlayerControl = FPlayerControl;
                if (PlayerControl != null)
                {
                    PlayerControl.ExitGame(Mode, Done);
                }
                else
                {
                    ExecuteExitGame();
                    if (Done != null)
                    {
                        Done(Mode, true);
                    }
                }
            }
            else
            {
                if (Done != null)
                {
                    Done(Mode, true);
                }
            }
        }

