        // AoWHSMap.PAS:2401
        public bool VisibleForPlayer(int X, int Y, int Level, sbyte Player)
        {
            bool Result;
            TMapLevel MapLevel;
            TMapFieldMsg Msg = default;
            THNWalkData Walk = default;
            TAoWMapField Field;
            MapLevel = MapContainer.GetMapLevel(Level);
            if (Player >= 0)
            {
                Msg.MsgID = 4362;
                Msg.Result = 0;
                Msg.Param[1] = Player;
                InitHNWalk(ref Walk, X, Y, 0);
                while (Msg.Result.Value == 0 && Walk.Radius <= 12)
                {
                    if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                    {
                        Field = (TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y);
                        if ((Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref Field.FFieldFlags).Lo).Hi & 16) != 0)
                        {
                            Msg.Param[0] = Walk.Radius;
                            Field.SendMapFieldMsg(ref Msg);
                        }
                    }

                    WalkToNextHN(ref Walk);
                }

                Result = Msg.Result.Value != 0;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWHSMap.PAS:2434
        public bool FoggedForPlayer(int X, int Y, int L, sbyte Player)
        {
            bool Result;
            TMapLevel MapLevel;
            TMapFieldMsg Msg = default;
            THNWalkData Walk = default;
            TAoWMapField Field;
            MapLevel = MapContainer.GetMapLevel(L);
            if (!FExplorationEnabled || ((TAoWMapField)MapLevel.GetField(X, Y)).GetExplored(Player))
            {
                if (FFogEnabled)
                {
                    if (Player != AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        Msg.MsgID = 4362;
                        Msg.Result = 0;
                        Msg.Param[1] = Player;
                        InitHNWalk(ref Walk, X, Y, 0);
                        while (Msg.Result.Value == 0 && Walk.Radius <= 12)
                        {
                            if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                            {
                                Field = (TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y);
                                if ((Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref Field.FFieldFlags).Lo).Hi & 16) != 0)
                                {
                                    Msg.Param[0] = Walk.Radius;
                                    Field.SendMapFieldMsg(ref Msg);
                                }
                            }

                            WalkToNextHN(ref Walk);
                        }

                        Result = Msg.Result.Value == 0;
                    }
                    else
                    {
                        var fieldValue = AoWE.AoWHSMap.MapContainer.GetField(X, Y, L);
                        Result = Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref ((TAoWMapField)fieldValue).FFieldFlags).Hi).Lo == 0;
                    }
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // AoWHSMap.PAS:2474
        public void MouseMoved(TObject Sender)
        {
            TAoWMapField Field;
            if (Mouse.Capture == null && Mouse.Xhx != -1)
            {
                var yhx = Mouse.Yhx;
                var xhx = Mouse.Xhx;
                Field = (TAoWMapField)MapContainer.GetField(xhx, yhx, FViewL);
                if (AoWE.AoWHSMap.FExplorationEnabled && !Field.GetExplored(AoWE.AoWHSMap.FSeatedPlayer))
                {
                    return;
                }

                if (!AoWE.AoWHSMap.FFogEnabled || Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref Field.FFieldFlags).Hi).Lo != 0)
                {
                    var yhp = Mouse.Yhp;
                    var xhp = Mouse.Xhp;
                    if (Selection.CanSelectLocation(xhp, yhp, FViewL) && !((TAbstractAoWHSMapMouse)Mouse).GetSelectingRectangle())
                    {
                        Mouse.CursorMode = 257;
                    }
                    else
                    {
                        Mouse.CursorMode = 0;
                    }
                }
            }
        }

        // AoWHSMap.PAS:2490
        public void UpdateCursor()
        {
            switch (Mouse.CursorMode)
            {
                case 0:
                    Mouse.Cursor = 0;
                    break;
                case 257:
                    Mouse.Cursor = (int)(((uint)Frame) >> 2) % 4 + 52;
                    break;
                case 258:
                    Mouse.Cursor = (((int)(((uint)Frame) >> 2)) & 1) + 49;
                    break;
                case 259:
                    Mouse.Cursor = (int)(((uint)Frame) >> 2) % 3 + 58;
                    break;
            }

            Mouse.CursorVisible = Mouse.Cursor != 0;
        }

