                            Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref XYL).Lo).Hi = 0;
                            Unsafe.As<ushort, WordRec>(ref Unsafe.As<int, LongRec>(ref XYL).Hi).Lo = 0;
                        }
                        else
