        // AoWHSMap.PAS:2621
        public void SetupPlayerControl(TPlayMode Mode, TPlayerConnectionType Connection)
        {
            switch (Mode)
            {
                case TPlayMode.pmTurn:
                    if (FConnectionType == TPlayerConnectionType.pcEmail)
                    {
                        if (!(FPlayerControl is TPBEMPlayerControl))
                        {
                            FPlayerControl.Free();
                            FPlayerControl = new TPBEMPlayerControl(null);
                        }
                    }
                    else
                    {
                        // { Original tests TPBEMPlayerControl even in the non-email branch. }
                        if (!(FPlayerControl is TPBEMPlayerControl))
                        {
                            FPlayerControl.Free();
                            FPlayerControl = new TTurnPlayerControl(null);
                        }
                    }

                    break;
                case TPlayMode.pmSimultaneous:
                    if (!(FPlayerControl is TSimultaniousPlayerControl))
                    {
                        FPlayerControl.Free();
                    }

                    // { Original replaces an existing control without freeing it. }
                    FPlayerControl = new TSimultaniousPlayerControl(null);
                    break;
            }

            FConnectionType = Connection;
            FPlayMode = Mode;
            if (FPlayerControl != null)
            {
                FPlayerControl.Setup();
            }
        }

