        // AoWHSMap.PAS:2723
        public void GenerateNewTurnOrder()
        {
            int Index;
            TByteList List;
            List = new TByteList();
            for (int I = 1, last = FPlayers.Count - 1; I <= last; I++)
            {
                List.Add((byte)I);
            }

            FTurnOrder.Clear();
            FTurnOrder.Add(0);
            while (List.Count != 0)
            {
                Index = Random(List.Count);
                var item = List[Index];
                FTurnOrder.Add(item);
                List.Delete(Index);
            }

            List.Free();
        }

