                if (FGameType == TGameType.gtTutorial && AClassID == 2228496)
                {
                    FTutorialControl.ShowMessage(53, false, true);
                }

                if (AClassID == 2228496)
                {
                    ((TAbstractAoWHSMapMouse)AoWE.AoWHSMap.Mouse).ResetRectangleSelection();
