        // AoWHSMap.PAS:2929
        public void DestroyCombat()
        {
            sbyte Player = default;
            int Count = default;
            TNewTurnEventLog Log = default;
            if (FCombat != null)
            {
                AoWE.AoWHSMap.LockGameOverEvent();
                if (FCombat.FStatus.Contains(TCombatStatusElement.cActivated))
                {
                    FCombat.Deactivate();
                }

                if (FCombat.FStatus.Contains(TCombatStatusElement.cExecuting))
                {
                    FCombat.Finalize();
                    Player = FCombat.FCombatData.FPlayers.GetPlayers(FCombat.FCombatData.FAttackerPlayer).FPlayer;
                    if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork && FPlayMode == TPlayMode.pmSimultaneous)
                    {
                        Count = AoWE.AoWHSMap.FPlayers.Count;
                        Player = FCombat.FCombatData.FPlayers.GetPlayers(FCombat.FCombatData.FAttackerPlayer).FPlayer;
                        while (Count != 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FStatus != TPlayerStatus.psPlaying)
                        {
                            Player = (sbyte)(Player + 1);
                            if (Player == AoWE.AoWHSMap.FPlayers.Count)
                            {
                                Player = 0;
                            }

                            Count -= 1;
                        }
                    }

                    AoWE.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(Player);
                    if (FPlayMode == TPlayMode.pmSimultaneous)
                    {
                        AoWE.AoWHSMap.FTokenManager.TokenExecuter.HoldTC = false;
                    }
                }

                if (FRequestCombatType && FCombat.EClass.ClassID != 131760 && FCombat.FCombatData.FRound != 0 && FCombat.FExplorationSite != 1 && FPlayers.GetPlayers(FCurrentPlayer).FPlayerType == TPlayerType.ptHuman)
                {
                    LockExecuteEventLog();
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = FCurrentPlayer;
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWE.TranslateRStr(AoWE.YourTurnContinuesRStr);
                    TriggerExecuteEventLog(Log, false, ShowSeatedPlayerCallBack);
                    Log.Release();
                    UnlockGameOverEvent();
                    SetSeatedPlayer(-1);
                    UnlockExecuteEventLog();
                }
                else
                {
                    if (FCombat.EClass.ClassID == 2228496)
                    {
                        EnableTurnTimer();
                    }

                    UnlockGameOverEvent();
                }

                FCombat.Free();
                FCombat = null;
            }
        }

