        // AoWHSMap.PAS:3061
        public void UpdateTurnTimeBeep()
        {
            int Seconds;
            if (GetTurnTimerEnabled())
            {
                Seconds = GetTurnTimeLeft() / 1000;
                if (FTurnTimeBeep != 0 && Seconds < FTurnTimeBeep && FCombatMap == null)
                {
                    FTurnTimeBeep = Seconds;
                    if (FTurnTimeBeep == 0)
                    {
                        PlaySample((AnsiString)"SFX\\EVENTS\\CLOCK.WAV");
                    }
                    else
                    {
                        PlaySample((AnsiString)"SFX\\EVENTS\\CLOCK.WAV");
                    }
                }
            }
        }

        // AoWHSMap.PAS:3078
        public void ResetTurnTimer()
        {
            FTurnTimeElapsed = FTurnTime * 1000 * 60;
            FTurnTimeBeep = 11;
            FTurnTimerStart = -1;
        }

        // AoWHSMap.PAS:3086
        public int GetTurnTimeLeft()
        {
            int Time;
            int Left;
            Left = FTurnTimeElapsed;
            if (FTurnTimerStart != -1)
            {
                Time = GetElapsedMilliSeconds();
                if (Time >= FTurnTimerStart)
                {
                    Left = Left - (Time - FTurnTimerStart);
                }
                else
                {
                    Left = 0;
                }
            }

            if (Left < 0)
            {
                Left = 0;
            }

            return Left;
        }

        // AoWHSMap.PAS:3102
        public bool GetTurnTimerEnabled() => FTurnTime > 0 && FTurnTimerStart != -1;

        // AoWHSMap.PAS:3108
        public void EnableTurnTimer()
        {
            if (FTurnTimerStart == -1 && FTurnTime > 0)
            {
                FTurnTimerStart = GetElapsedMilliSeconds();
            }
        }

        // AoWHSMap.PAS:3114
        public void DisableTurnTimer()
        {
            int Time;
            Time = GetElapsedMilliSeconds() - FTurnTimerStart;
            if (Time > 0)
            {
                FTurnTimeElapsed -= Time;
            }

            FTurnTimerStart = -1;
        }

        // AoWHSMap.PAS:3124
        public void ZeroTurnTimer()
        {
            FTurnTimeElapsed = 0;
        }

        // AoWHSMap.PAS:3144
        public void CenterOnLeader(sbyte Player, bool Select, bool Animate)
        {
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            TArmyHS Army;
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FLeader != null)
            {
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FLeader.GetLocation(ref X, ref Y, ref L);
                // { Original excludes X = 0. }
                if (X > 0)
                {
                    AoWE.AoWHSMap.CenterViewTo(X, Y, L);
                    if (Animate)
                    {
                        AoWE.AoWHSMap.PlayCenterAnimation(X, Y, L);
                    }

                    Army = ((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L)).GetArmyHS();
                    if (Army != null)
                    {
                        Selection.UnselectLocation();
                        Selection.SelectLocationHS(Army);
                    }
                }
            }
        }

        // AoWHSMap.PAS:3167
        public void PlaceTerrain(sbyte X, sbyte Y, sbyte L, sbyte TerrainType, sbyte OverlayType)
        {
            TEObjectList Resources;
            TList Candidates;
            TMapObjectResource Resource;
            RandSeed = AoWE.AoWHSMap.Random(16777215);
            Resources = AoWE.AoWHSSet.MapObjectResourceList.FChildren;
            if (!TSet<byte>.WithBounds(0, 255).With(4).With(5).Contains((byte)OverlayType))
            {
                Candidates = new TList();
                Candidates.Clear();
                for (int I = 0, last = Resources.Count - 1; I <= last; I++)
                {
                    Resource = (TMapObjectResource)Resources.List[I];
                    if (Resource.EClass.ClassID == 131431 && Resource.TerrainList.UsedTerrain() == 1 && Resource.TerrainList.Terrain[0] == TerrainType && Resource.TerrainList.Overlay[0] == OverlayType)
                    {
                        Candidates.Add(Resource);
                    }
                }

                if (Candidates.Count != 0)
                {
                    ((TMapObjectResource)Candidates[Random(Candidates.Count)]).PlaceResourceUser(AoWE.AoWHSMap, X, Y, L);
                }

                Candidates.Free();
            }
            else
            {
                AoWE.AoWHSSet.RoadControl.Place(AoWE.AoWHSMap.MapContainer, X, Y, L, TerrainType);
            }
        }

        // AoWHSMap.PAS:3195
        public void UpdateEffects()
        {
            int I;
            TWorldFXHS Effect;
            if (!Status.Contains(THSMapStatusElement.msEditting))
            {
                I = 0;
                while (I < FEffects.Count)
                {
                    Effect = (TWorldFXHS)FEffects[I];
                    if (Effect.FDone)
                    {
                        DynamicFixedVisibleHS.RemoveChild(Effect);
                        DynamicVisibleHS.RemoveChild(Effect);
                        Effect.Free();
                        FEffects.Delete(I);
                    }
                    else
                    {
                        I += 1;
                    }
                }
            }
        }

