        // Ability.PAS:2061
        public int GetCount() => FAbilities.Count;

        // Ability.PAS:2078
        public void RegisterAbility(TAbility Ability)
        {
            int ID;
            ID = Ability.FAbilityID;
            if (ID != -1)
            {
                if (ID < this.FAbilities.Count && this.FAbilities[ID] != null)
                {
                    throw Exception.Create((AnsiString)"Ability already registered (" + IntToStr(ID) + AnsiString.FromBytes(41));
                }

                while (ID >= FAbilities.Count)
                {
                    FAbilities.Add(null);
                }

                FAbilities.List[ID] = Ability;
                var abilityType = Ability.GetAbilityType();
                FAbilitiesByType[(int)abilityType].Add(Ability);
                Ability.FImageSequences.LinkToIL();
            }
            else
            {
                throw Exception.Create((AnsiString)"Invalid AbilityID (" + (AnsiString)ClassNameOf(Ability.GetType()) + AnsiString.FromBytes(41));
            }
        }

        // Ability.PAS:2096
        public void UnregisterAbility(TAbility Ability)
        {
            int ID;
            ID = Ability.FAbilityID;
            if (ID != -1)
            {
                if (ID < 0 || ID >= FAbilities.Count || FAbilities[ID] != Ability)
                {
                    throw Exception.Create((AnsiString)"Cannot Unregister Ability (" + IntToStr(ID) + AnsiString.FromBytes(41));
                }

                if (FAbilities.List[ID] != null)
                {
                    var abilityType = Ability.GetAbilityType();
                    FAbilitiesByType[(int)abilityType].Remove(Ability);
                    ((TAbility)FAbilities.List[ID]).FImageSequences.ReleaseIL();
                    ((TObject)FAbilities.List[ID]).Free();
                    FAbilities.List[ID] = null;
                }
            }
            else
            {
                throw Exception.Create((AnsiString)"Invalid AbilityID (" + (AnsiString)ClassNameOf(Ability.GetType()) + AnsiString.FromBytes(41));
            }
        }

        // Ability.PAS:2116
        public void UnregisterAll()
        {
            for (int I = FAbilities.Count - 1; I >= 0; I--)
            {
                if (FAbilities[I] != null)
                {
                    UnregisterAbility((TAbility)FAbilities[I]);
                }
            }
        }

