            Done = false;
            Item = AoWE.AoWHSMap.FItemControl.FindItem(FItemID);
            if (Item != null)
            {
                switch (FAction)
                {
                    case 0:
                        Hero = AoWE.AoWHSMap.FHeroControl.FindID(FHeroID);
                        if (Hero != null)
                        {
                            Done = Item.ExecuteUse(Hero);
                        }
                        else
                        {
                            Done = false;
                        }

                        break;
                }
            }

            if (Done)
            {
                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            return Result;
        }

