        // Unit.PAS:1355
        public virtual void NewTurn(sbyte Player)
        {
            sbyte Heal;
            if (Player == FPlayer)
            {
                SetMovePoints(GetMoves());
                if (GetHits() != GetHitPoints() && !GetAbilityEnabled(93))
                {
                    if (!GetAbilityEnabled(49))
                    {
                        Heal = (sbyte)Round((double)GetHits() * 0.1);
                        if (Heal == 0)
                        {
                            Heal = 1;
                        }
                    }
                    else
                    {
                        Heal = GetHits();
                    }

                    SetHitPoints((sbyte)(GetHitPoints() + Heal));
                }

                if (GetAbilityEnabled(109))
                {
                    UpdatePathOfFrost();
                }
            }
        }

        // Unit.PAS:1375
        public virtual void NewTurnDone(sbyte Player)
        {
            if (Player == FPlayer && FPlayer > 0)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(TPlayerEnchantmentType.petFireMastery))
                {
                    SetFireMasteryProtection();
                }

                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(TPlayerEnchantmentType.petEarthMastery))
                {
                    SetEarthMasteryStoneSkin();
                }

                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(TPlayerEnchantmentType.petLifeMastery))
                {
                    SetLifeMasteryBlessing();
                }

                if ((((byte)AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FEnemyEnchantments.Image) & 16) != 0)
                {
                    ExecuteLifeMasteryFearRole();
                }

                if ((((byte)AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FEnemyEnchantments.Image) & 32) != 0)
                {
                    ExecuteDeathMasteryCurseRole();
                }
            }
        }

