        // Unit.PAS:1100
        public virtual void MovedTo(TMapField OldField, TMapField NewField, int MaxCost)
        {
            int Cost = default;
            bool Transported = default;
            TEObject Army = default;
            Cost = MovePointCost(NewField.TerrainType, NewField.OverlayType);
            if (Cost < 0)
            {
                Cost = MaxCost;
            }
            else
            {
                if (Cost > MaxCost)
                {
                    Cost = MaxCost;
                }
            }

            if (!AoWE.AoWHSMap.FUnlimitedMoves || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType != TPlayerType.ptHuman)
            {
                if (Cost > GetMovePoints())
                {
                    SetMovePoints(0);
                }
                else
                {
                    SetMovePoints((sbyte)(GetMovePoints() - Cost));
                }
            }

            if (NewField.TerrainType == (int)TAoWTerrainType.ttEarth)
            {
                AoWE.AoWHSMap.ChangeTerrain(null, NewField.Xhx, NewField.Yhx, NewField.Lhx, 0, (int)TAoWTerrainType.ttDirt);
            }

            if (OldField != null)
            {
                Army = Owner;
                Transported = Army is TArmy && ((TArmy)Army).Transporter(255) != null;
                if (!Transported)
                {
                    if (OldField.Lhx == 0)
                    {
                        if (GetAbilityEnabled(69))
                        {
                            AoWE.AoWHSMap.ChangeTerrainEx(null, OldField.Xhx, OldField.Yhx, OldField.Lhx, 1, PathOfLifeTerrainChange, null);
                        }
                        else
                        {
                            if (GetAbilityEnabled(68))
                            {
                                AoWE.AoWHSMap.ChangeTerrainEx(null, OldField.Xhx, OldField.Yhx, OldField.Lhx, 1, PathOfDecayTerrainChange, null);
                            }
                        }
                    }

                    if (GetAbilityEnabled(109))
                    {
                        AoWE.AoWHSMap.ChangeTerrainEx(null, OldField.Xhx, OldField.Yhx, OldField.Lhx, 1, PathOfFrostTerrainChange, PathOfFrostTerrainChanged);
                    }
                }

                if (GetAbilityEnabled(26))
                {
                    ExecuteTrailOfDarkness(OldField);
                }
            }
        }

