        // Unit.PAS:1843
        public virtual bool OfferToJoin(sbyte Player)
        {
            bool Result;
            TUnitUserList Group;
            TAlignment Alignment;
            if (CanJoin(Player))
            {
                if (GetRace() != -1)
                {
                    var race = GetRace();
                    Result = AoWE.AoWHSMap.FRaces.GetRace(race).GetPlayerRelation(Player) >= TStatus.sPolite;
                }
                else
                {
                    Group = FGroup;
                    if (Group != null && ((TAIGroup)(object)Group).GroupClass.Behavior == TGroupBehavior.gbRefuge)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                        Alignment = AoWE.AoWHSSet.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                        if ((GetAlignment() != TAlignment.alNone || GetUnitType() == TUnitType.utMachine) && AoWE.dAlignmentToDiplomaticRelation(GetAlignment(), Alignment) != TDiplomaticRelation.drPeace)
                        {
                            Result = false;
                        }
                        else
                        {
                            Result = true;
                        }
                    }
                    else
                    {
                        Result = false;
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

