        public int GetRelationValue(sbyte Player, sbyte IndependentRelation)
        {
            int Result;
            sbyte Race;
            Race = GetRace();
            if (Player != 0)
            {
                if (Race != -1 && !GetAbilityEnabled(107))
                {
                    Result = AoWE.AoWHSMap.FRaces.GetRace(Race).GetPlayerRelationValue(Player);
                }
                else
                {
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                    var alignment = AoWE.AoWHSSet.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                    var alignment2 = GetAlignment();
                    Result = AoWE.P2AlignmentToStatusValue[(int)alignment2][(int)alignment];
                }
            }
            else
            {
                var iRtoAlignment = AoWE.IRtoAlignment(IndependentRelation);
                var alignment = GetAlignment();
                Result = AoWE.P2AlignmentToStatusValue[(int)alignment][(int)iRtoAlignment];
            }

            return Result;
        }

