        public TStatus UnitRelation(TAbstractUnit AUnit)
        {
            TStatus Result;
            sbyte Race;
            sbyte OtherRace;
            Race = GetRace();
            OtherRace = AUnit.GetRace();
            if (Race != -1 && OtherRace != -1)
            {
                Result = AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelation(OtherRace);
            }
            else
            {
                var alignment = AUnit.GetAlignment();
