            GetMoveTypes();
            var moveTypesToInt = AoWE.MoveTypesToInt(GetMoveTypes());
            Cost = AoWE.MovePointTables[moveTypesToInt][TerrainType][OverlayType - -1];
            if (Cost == -1 || Cost > GetMoves())
            {
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Unit.PAS:1011
        public void ExecuteTrailOfDarkness(TMapField MapField)
        {
            TMapLevel Level;
            THNWalkData Walk = default;
            TAoWMapField Field;
            Level = (TMapLevel)MapField.Owner;
            InitHNWalk(ref Walk, MapField.Xhx, MapField.Yhx, 0);
            while (Walk.Radius <= 1)
            {
                if (Walk.X >= 0 && Walk.X < Level.Width && Walk.Y >= 0 && Walk.Y < Level.Height)
                {
                    Field = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                    if (Field.TerrainType != (int)TAoWTerrainType.ttBorder)
                    {
                        for (int Player = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; Player <= last; Player++)
                        {
                            if (Player != FPlayer && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Player) == TDiplomaticRelation.drWar && Field.GetExplored(Player) && !AoWE.AoWHSMap.VisibleForPlayer(Walk.X, Walk.Y, MapField.Lhx, (sbyte)Player))
                            {
                                Field.SetExplored(Player, false);
                            }
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }

            AoWE.AoWHSMap.MapChangedRad(MapField.Xhx, MapField.Yhx, MapField.Lhx, 1);
        }

