        // Unit.PAS:1154
        public int ExecuteStormDamage(TStormType Storm, int Distance)
        {
            int Result;
            sbyte Terrain;
            sbyte Overlay;
            TSet<TMoveType> Moves;
            sbyte Xhx = default;
            sbyte Yhx = default;
            sbyte Lhx = default;
            TMapField Field;
            bool DoubleDamage;
            int Attack;
            Moves = GetMoveTypes();
            DoubleDamage = GetAbilityEnabled(23);
            if (!DoubleDamage && Moves.Contains(TMoveType.mtFlying))
            {
                GetLocation(ref Xhx, ref Yhx, ref Lhx);
                if (Xhx != -1)
                {
                    Field = AoWE.AoWHSMap.MapContainer.GetField(Xhx, Yhx, Lhx);
                    Terrain = Field.TerrainType;
                    Overlay = Field.OverlayType;
                    Moves = Moves - TSet<TMoveType>.Of(TMoveType.mtFlying);
                    var moveTypesToInt = AoWE.MoveTypesToInt(Moves);
                    DoubleDamage = AoWE.MovePointTables[moveTypesToInt][Terrain][Overlay - -1] == 0;
                }
            }

            switch (Storm)
            {
                case TStormType.stIce:
                    Attack = 7;
                    Result = 5;
                    break;
                case TStormType.stLightning:
                    Attack = 8;
                    Result = 7;
                    break;
                case TStormType.stDeath:
                    Attack = 7;
                    Result = 4;
                    break;
                case TStormType.stHoly:
                    Attack = 7;
                    Result = 5;
                    break;
                case TStormType.stFire:
                    Attack = 7;
                    Result = 5;
                    break;
                case TStormType.stPestilence:
                    Attack = 4;
                    Result = 3;
                    break;
                default:
                    Attack = 0;
                    Result = 0;
                    break;
            }

            if (DoubleDamage)
            {
                Result = Result * 2;
            }

            Result = ExecuteDamageRole(Attack, Result, TSet<TDamageType>.Of(AoWE.StormDamageType[(int)Storm]));
            if (Result > GetHitPoints())
            {
                Result = GetHitPoints();
            }

            if (Result > 0)
            {
                switch (Storm)
                {
                    case TStormType.stDeath:
                        ExecuteDamageEffects(TSet<TDamageType>.Of(TDamageType.dtDeath));
                        break;
                    case TStormType.stPestilence:
                        ExecuteDamageEffects(TSet<TDamageType>.Of(TDamageType.dtPoison));
                        break;
                }
            }

            SetHitPoints((sbyte)(GetHitPoints() - Result));
            return Result;
        }

