        // Unit.PAS:1428
        public bool CanPlace(int X, int Y, int L, sbyte Player, TSet<TUnitPlaceModeElement> Mode)
        {
            bool Result;
            TAoWMapField Field;
            TArmyHS ArmyHS;
            sbyte FieldPlayer;
            if (X >= 0 && Y >= 0 && X < AoWE.AoWHSMap.MapContainer.Width && Y < AoWE.AoWHSMap.MapContainer.Height)
            {
                Field = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L);
                FieldPlayer = Field.GetPlayer();
                if (Mode.Contains(TUnitPlaceModeElement.pmNeglectEmptyPlayerLocation) || FieldPlayer == Player || FieldPlayer == -1 || Player == -1)
                {
                    ArmyHS = (TArmyHS)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L).FindOwnedChild(131607);
                    if (ArmyHS != null)
                    {
                        if (Mode.Contains(TUnitPlaceModeElement.pmCreateNewArmy) || (Player != -1 && ArmyHS.FArmy.FPlayer != Player) || !ArmyHS.FArmy.CanAddUnit(this))
                        {
                            Result = false;
                        }
                        else
                        {
                            Result = true;
                        }
                    }
                    else
                    {
                        Result = ValidTerrain(Field.TerrainType, Field.OverlayType);
                    }
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Unit.PAS:1454
        public TArmyHS Place(int X, int Y, int L, sbyte Player, TSet<TUnitPlaceModeElement> Mode)
        {
            THNWalkData Walk = default;
            TArmyHS ArmyHS;
            TArmyHS Result = null;
            InitHNWalk(ref Walk, X, Y, 0);
            while (Result == null && (Walk.Radius == 0 || Mode.Contains(TUnitPlaceModeElement.pmScanArea)) && Walk.Radius < 30)
            {
                if (CanPlace(Walk.X, Walk.Y, L, Player, Mode))
                {
                    ArmyHS = (TArmyHS)AoWE.AoWHSMap.MapContainer.GetField(Walk.X, Walk.Y, L).FindOwnedChild(131607);
                    if (ArmyHS == null)
                    {
                        ArmyHS = new TArmyHS(null);
                        if (Player != -1)
                        {
                            ArmyHS.FArmy.SetPlayer(Player);
                        }

                        if (!ArmyHS.FArmy.AddUnit(this) || !AoWE.AoWHSMap.PlaceHX(ArmyHS, Walk.X, Walk.Y, L))
                        {
                            ArmyHS.Free();
                            ArmyHS = null;
                        }

                        Result = ArmyHS;
                    }
                    else
                    {
                        if (ArmyHS.FArmy.AddUnit(this))
                        {
                            Result = ArmyHS;
                        }
                        else
                        {
                            Result = null;
                        }
                    }
                }

                if (Result == null)
                {
                    WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

