        // Unit.PAS:2132
        public override void ReadWrite(TEStorageStream Stream)
        {
            short ResourceIndex = default;
            TUnitResource Resource;
            base.ReadWrite(Stream);
            Stream.rwByte(ref FExperience, 7);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FMovePoints), 8);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FHitPoints), 9);
            if ((Stream.StorageMode() & TSet<TStorageModeElement>.Of(TStorageModeElement.smTextOnly)) == TSet<TStorageModeElement>.Of())
            {
                if (Stream.StorageMode().Contains(TStorageModeElement.smCompare))
                {
                    ResourceIndex = (short)FUnitResource.UnitResourceIndex();
                    Stream.rwWord(ref Unsafe.As<short, ushort>(ref ResourceIndex), 10);
                }
                else
                {
                    if (Stream.StorageMode().Contains(TStorageModeElement.smRead))
                    {
                        Stream.rwWord(ref Unsafe.As<short, ushort>(ref ResourceIndex), 10);
                        Resource = AoWE.AoWHSSet.FUnitResources.GetUnitResource(ResourceIndex);
                        FUnitResource = Resource;
                        if (Resource == null)
                        {
                            throw Exception.Create((AnsiString)"unit resource missing (" + IntToStr(ResourceIndex) + AnsiString.FromBytes(41));
                        }
                    }
                    else
                    {
                        Resource = FUnitResource;
                        if (Resource != null)
                        {
                            ResourceIndex = (short)Resource.UnitResourceIndex();
                        }
                        else
                        {
                            ResourceIndex = -1;
                        }

                        Stream.rwWord(ref Unsafe.As<short, ushort>(ref ResourceIndex), 10);
                    }
                }
            }
        }

