        }

        // Ability.PAS:820
        public void SetUnitCategoryEnabled(sbyte Category, bool Value)
        {
            if (Category >= 0)
            {
                FRacesEnabled[Category] = Value;
            }
            else
            {
                FTypesEnabled[Math.Abs(Category) - 1] = Value;
            }
        }

        // Ability.PAS:826
        public void Reset()
        {
            FAlignments = AoWE.alsAll;
            FMinimumLevel = 0;
            FMaximumLevel = 255;
            FRacesEnabled.Clear();
            FTypesEnabled.Clear();
            FAllUnits.Clear();
            FSelectedUnitIndex = -1;
            FSelectedHero = null;
            FShowRaceCategories = true;
            FShowAllCategory = false;
            FShowTypeCategories = true;
            if (AoWE.AoWHSMap != null)
            {
                for (int I = 0, last = AoWE.AoWHSMap.FRaces.GetCount() - 1; I <= last; I++)
                {
                    if (AoWE.AoWHSMap.FRaces.GetRace(I) != null)
                    {
                        var race = AoWE.AoWHSMap.FRaces.GetRace(I);
                        FRacesEnabled[I] = race.FEnabled;
                    }
                }
            }
        }

        // Ability.PAS:847
        public void DisableAllCategories()
        {
            for (int I = 0, last = AoWE.AoWHSSet.FRaceResources.GetCount() - 1; I <= last; I++)
            {
                FRacesEnabled[I] = false;
            }

            for (int I = 0, last = FTypesEnabled.Count - 1; I <= last; I++)
            {
                FTypesEnabled[I] = false;
            }
        }

        // Ability.PAS:855
        public void UpdateSelection()
        {
            int Index;
            TUnitResourceList Resources;
            TUnitResource Resource;
            TUnitType UnitType_;
            FRaceUnits.Clear();
            FTypeUnits.Clear();
            FAllUnits.Clear();
            Resources = AoWE.AoWHSSet.FUnitResources;
            // { Original intersects FAlignments with itself, ignoring the unit alignment. }
            if (FShowAllCategory)
            {
                for (int I = 0, last = Resources.GetCount() - 1; I <= last; I++)
                {
                    if (Resources.GetUnitResource(I) != null)
                    {
                        Resource = Resources.GetUnitResource(I);
                        if (Resource.FLevel >= FMinimumLevel && Resource.FLevel <= FMaximumLevel && (FAlignments & FAlignments) != TSet<TAlignment>.Of())
                        {
                            FAllUnits.Add(I);
                        }
                    }
                }
            }

            if (FShowTypeCategories)
            {
                for (int I = 0, last = Resources.GetCount() - 1; I <= last; I++)
                {
                    if (Resources.GetUnitResource(I) != null)
                    {
                        Resource = Resources.GetUnitResource(I);
                        if (Resource.FLevel >= FMinimumLevel && Resource.FLevel <= FMaximumLevel && (FAlignments & FAlignments) != TSet<TAlignment>.Of())
                        {
                            FTypeUnits.AddUnit((int)Resource.FUnitType, I);
                        }
                    }
                }
            }

            if (FShowRaceCategories)
            {
                // { Original bounds this race loop by the unit-resource count. }
                for (int I = 0, last = Resources.GetCount() - 1; I <= last; I++)
                {
                    if (FRacesEnabled[I] && AoWE.AoWHSSet.FRaceResources.GetRaceResource(I) != null)
                    {
                        for (int J = 0, lastJ = AoWE.AoWHSSet.FRaceResources.GetRaceResource(I).FUnitIndexes.Count - 1; J <= lastJ; J++)
                        {
                            Index = AoWE.AoWHSSet.FRaceResources.GetRaceResource(I).FUnitIndexes[J];
                            if (Index != -1)
                            {
                                Resource = Resources.GetUnitResource(Index);
                                if (Resource.FLevel >= FMinimumLevel && Resource.FLevel <= FMaximumLevel && (FAlignments & FAlignments) != TSet<TAlignment>.Of())
                                {
                                    FRaceUnits.AddUnit(I, Index);
                                }
                            }
                        }
                    }
                }
            }

            FTypeUnits.SortUnits();
            FRaceUnits.SortUnits();
            FAllUnits.SortUnits();
            Clear();
            if (FShowAllCategory && (FAllUnits.Count != 0 || FShowEmptyCategories))
            {
                AddObject((AnsiString)"All", IntToObject(-16));
            }

            if (FShowTypeCategories)
            {
                for (int unitTypeOrdinal = (int)(TUnitType)0; unitTypeOrdinal <= (int)(TUnitType)2; unitTypeOrdinal++)
                {
                    UnitType_ = (TUnitType)unitTypeOrdinal;
                    if (FTypesEnabled[(int)UnitType_] && FTypeUnits.GetCategory((int)UnitType_) != null && (FTypeUnits.GetCategory((int)UnitType_).Count != 0 || FShowEmptyCategories))
                    {
                        AddObject(AoWE.TranslateRStr(AoWE.UnitTypePluralRStr[(int)UnitType_]), IntToObject(-((int)UnitType_ + 1)));
                    }
                }
            }

            if (FShowRaceCategories)
            {
                for (int I = 0, last = AoWE.AoWHSSet.FRaceResources.GetCount() - 1; I <= last; I++)
                {
                    if (FRacesEnabled[I] && FRaceUnits.GetCategory(I) != null && (FRaceUnits.GetCategory(I).Count != 0 || FShowEmptyCategories))
                    {
                        AddObject(AoWE.AoWHSSet.FRaceResources.GetRaceResource(I).FRaceName, IntToObject(I));
                    }
                }
            }
        }

        // intf_P1_08.inc:32

    }

