    // { Interface declaration run owned by P5. }
    // FirstUnitID, UnitIDs, Location, Selection, JoinIndex, JoinMessage, Gold, JoinMode, Text
    public partial class TJoinEventLog : TEventLog
    {
        // Diplomacy.pas:1
        public TJoinEventLog(TECustomNode owner) : base(owner)
        {
            FUnitIDs = new TIntegerList();
            FJoinMessage = new TStringList();
            FLocation.X = -1;
            FLocation.Y = -1;
            FLocation.L = -1;
            FJoinIndex = -1;
        }

        public int FFirstUnitID;
        public TIntegerList FUnitIDs;
        public TXYL FLocation;
        public byte FSelection;
        public int FJoinIndex;
        public TStringList FJoinMessage;
        public int FGold;
        public TJoinMode FJoinMode;
        public AnsiString FText;
        // Diplomacy.pas:12
        public override void Destroy()
        {
            FUnitIDs.Free();
            FJoinMessage.Free();
            base.Destroy();
        }

        // Diplomacy.pas:19
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FFirstUnitID, 21);
            Stream.rwStreamProc(22, FUnitIDs.LoadFromStream, FUnitIDs.SaveToStream);
            Stream.rwByte(ref FSelection, 23);
            Stream.rwStrings(FJoinMessage, 24);
            Stream.rwInteger(ref FGold, 25);
            Stream.rwInteger(ref Unsafe.As<TXYL, int>(ref FLocation), 26);
            Stream.rwData(Bytes.Of(ref FJoinMode, 1), 1, 27);
            Stream.rwString(ref FText, 28);
            Stream.rwIntegerEx(ref FJoinIndex, -1, 29);
        }

        // Diplomacy.pas:58
        public virtual bool Validate()
        {
            int I;
            TAbstractUnit AUnit;
            TXYL Location = default;
            bool Result = true;
            I = FUnitIDs.Count;
            while (Result && I != 0)
            {
                I -= 1;
                var item = FUnitIDs[I];
                AUnit = AoWE.AoWHSMap.FUnitControl.FindUnit(item);
                // { Original behavior: missing and dead units do not invalidate the offer. }
                if (AUnit != null && AUnit.FPlayer == 0)
                {
                    AUnit.GetLocation(ref Location.X, ref Location.Y, ref Location.L);
                    Result = FLocation.X == Location.X && FLocation.Y == Location.Y && FLocation.L == Location.L;
                }
            }

            return Result;
        }

        // Diplomacy.pas:80
        public virtual void ListJoinUnits(TUnitList Units, ref byte Selection)
        {
            TAbstractUnit AUnit;
            for (int I = 0, last = FUnitIDs.Count - 1; I <= last; I++)
            {
                var item = FUnitIDs[I];
                AUnit = AoWE.AoWHSMap.FUnitControl.FindUnit(item);
                Units.AddUnit(AUnit);
            }

            Selection = FSelection;
        }

        // Diplomacy.pas:93
        public virtual bool Accept(ref AnsiString ErrorText)
        {
            bool Result;
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FGems >= FGold)
            {
                Result = true;
            }
            else
            {
                Result = false;
                ErrorText = AoWE.TranslateRStr(AoWE.P5NotEnoughGoldRStr);
            }

            return Result;
        }

        // Diplomacy.pas:105
        public virtual bool Cancel() => true;

        // Diplomacy.pas:110
        public virtual bool Reject(ref AnsiString ErrorText) => true;

        // Diplomacy.pas:33
        public void SetupJoinArmy(TArmy Army, sbyte Player, TJoinMode JoinMode)
        {
            FFirstUnitID = 0;
            FPlayer = (sbyte)(byte)Player;
            FSelection = Army.GetJoinSelection(Player);
            FGold = Army.JoinAmount(Player, FSelection);
            FJoinMode = JoinMode;
            FUnitIDs.Clear();
            for (int I = 0, last = Army.Count - 1; I <= last; I++)
            {
                if (FFirstUnitID == 0 && ((1 << I) & FSelection) != 0)
                {
                    FFirstUnitID = Army.GetUnit(I).FUnitID;
                    var selectionCount = Army.SelectionCount(FSelection);
                    Army.GetUnit(I).GetJoinMessage(Player, selectionCount - 1, FGold, JoinMode, FJoinMessage);
                }

                var unit = Army.GetUnit(I);
                FUnitIDs.Add(unit.FUnitID);
            }

            FLocation = PackXYL(Army.FX, Army.FY, Army.FL);
        }

    }

