                ExecuteNow = ExecuteNow || AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWE.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpHeroJoin);
