        // Hero.PAS:148
        public override bool Accept(ref AnsiString ErrorText)
        {
            TNegotiateTE TE;
            TAbstractUnit U;
            TXYL Location = default;
            bool Result = base.Accept(ref ErrorText);
            if (Result && !AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy())
            {
                U = AoWE.AoWHSMap.FUnitControl.FindUnit(FFirstUnitID);
                U.GetLocation(ref Location.X, ref Location.Y, ref Location.L);
                TE = new TNegotiateTE(null);
                TE.FPlayer = FPlayer;
                TE.FObject = TNegotiateObject.noArmy;
                TE.FGold = FGold;
                TE.FOffer = TNegotiateOffer.noOfferBribe;
                TE.FX = (byte)Location.X;
                TE.FY = (byte)Location.Y;
                TE.FL = (byte)Location.L;
                TE.FMode = TSet<TNegotiateModeElement>.Of();
                TE.FResult = TNegotiateResult.nrAccept;
                TE.FEventLogID = FJoinIndex;
                AoWE.AoWHSMap.FTokenManager.GetTokenControl(FPlayer).AddEvent(TE);
                TE.Release();
            }

            return Result;
        }

        // Hero.PAS:132
        public bool ExecuteAI()
        {
            THero Hero;
            AnsiString ErrorText = default;
            bool Result = false;
            Hero = (THero)AoWE.AoWHSMap.FUnitControl.FindUnit(FFirstUnitID);
            if (Hero != null && Hero.FPlayer == 0 && Hero.OfferToJoin(FPlayer))
            {
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIBudget.RequestBudgetExpense(FGold, 0, players.FAIBudget.FDefaultBudget, true))
                {
                    if (Accept(ref ErrorText))
                    {
                        var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIBudget.BudgetExpenseMade(FGold, 0, fPlayersPlayers.FAIBudget.FDefaultBudget, TBudgetExpenseMode.bemBudgetThenPool);
                    }

                    Result = true;
                }
            }

            return Result;
        }

    }

