        // Hero.PAS:1311
        public override void NewTurn(sbyte Player)
        {
            TSpellCastEventLog Log;
            base.NewTurn(Player);
            if (Player == FPlayer)
            {
                ValidateHeroUpgrade();
                Player = GetCastingPointsMax();
                FCastingPoints = Player;
                if (FCastingSpellID != 0 && FCastingMana < FCastingProgress)
                {
                    FCastingMana += Player;
                    FCastingPoints = 0;
                    if (FCastingMana > FCastingProgress)
                    {
                        FCastingPoints = (sbyte)(FCastingMana - FCastingProgress);
                        FCastingMana = FCastingProgress;
                    }

                    if (FCastingMana == FCastingProgress)
                    {
                        Log = new TSpellCastEventLog(null);
                        Log.FPlayer = FPlayer;
                        Log.FUnitID = FUnitID;
                        Log.FSpellID = FCastingSpellID;
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FEventLogbook.AddEvent(Log);
                        if (AoWE.AoWHSMap.FSeatedPlayer == FPlayer && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptHuman)
                        {
                            Log.Execute(false, TExecuteTrigger.etEvent, null);
                        }

                        Log.Release();
                    }
                }
            }
        }

