                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.UnregisterPowerSource(FPowerSource);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.RemoveChild(this);
                }

                base.SetPlayer(Player);
                if (FPlayer != -1)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.AddChild(this);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.RegisterPowerSource(FPowerSource);
