        // Hero.PAS:914
        public override bool CanActivate()
        {
            THero Hero;
            bool Result = base.CanActivate();
            if (Result && !FRegistered && FUnitID != -1)
            {
                Hero = AoWE.AoWHSMap.FHeroControl.FindID(FUnitID);
                if (Hero == null || Hero == this)
                {
                    Result = true;
                }
                else
                {
                    if (Hero.Owner == null && CompatibleHero(Hero))
                    {
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                    }
                }
            }

            return Result;
        }

        // Hero.PAS:964
        public override void Activate()
        {
            THero Hero;
            if (FUnitID != -1)
            {
                Hero = AoWE.AoWHSMap.FHeroControl.FindID(FUnitID);
                if (Hero != null && Hero != this && Hero.Owner == null && CompatibleHero(Hero))
                {
                    AoWE.AoWHSMap.FHeroControl.UnRegisterHero(Hero);
                }
            }

            if (AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
            {
                FLevel = (byte)GetLevel();
            }

            if (FHeroResourceIndex == -1)
            {
                SetHeroResourceIndex(0);
            }

            if (FPlayer > 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer) == null && Owner == null)
            {
                FPlayer = -1;
            }

            if (Owner == null && FGroupID != 0)
            {
                FGroupID = 0;
            }

            base.Activate();
            if (AoWE.AoWHSMap != null)
            {
                if (!FMode.Contains(THeroModeElement.hmSkipLibraryUpdate) && (AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) || AoWE.AoWHSMap.FDay == 0))
                {
                    UpdateFromLibrary();
                }

                if (!FRegistered)
                {
                    AoWE.AoWHSMap.FHeroControl.RegisterHero(this);
                }

                if (FPlayer != -1 && Owner != null)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.RegisterPowerSource(FPowerSource);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.AddChild(this);
                }

                FInventory.RegisterItems();
                FHeroItems.RegisterItems();
            }
        }

