        {
            bool condition = FPlayer != -1;
            if (condition)
            {
                var count = AoWE.AoWHSMap.FPlayers.Count;
                condition = FPlayer < count;
            }

            if (condition)
            {
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.UnregisterPowerSource(FPowerSource);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FHeroes.RemoveChild(this);
            }

            base.Deactivate();
        }

        // Hero.PAS:765
        public override bool CanJoin(sbyte Player)
        {
            bool Result;
            TPlayer APlayer;
            if (FRace != -1)
            {
                APlayer = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                var playerRelation = AoWE.AoWHSMap.FRaces.GetRace(FRace).GetPlayerRelation(Player);
                Result = TSet<TStatus>.Of(TStatus.sPolite, TStatus.sFriendly).Contains(playerRelation);
                if (Result)
                {
                    bool condition = FGroup == null || FGroup.GroupClass.Behavior != TGroupBehavior.gbRefuge;
                    if (condition)
                    {
                        bool test = !GetAbilityEnabled(128) || Player != FDeathPlayer;
                        if (!test)
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                            test = FDeathDay + 2 < players.FDay;
                        }

                        condition = test;
                    }

                    if (condition)
                    {
                        Result = Result && APlayer.FHeroes.Count < APlayer.GetHeroCountMax() && GetLevel() <= APlayer.GetHeroJoinLevelMax();
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:794
        public override bool OfferToJoin(sbyte Player)
        {
            bool Result;
            TPlayer APlayer;
            int Seed;
            int Chance;
            if (CanJoin(Player))
            {
                APlayer = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                if (EmergedToPlayer() == -1)
                {
                    if ((!GetAbilityEnabled(128) || Player != FDeathPlayer) && (FGroup == null || FGroup.GroupClass.Behavior != TGroupBehavior.gbRefuge))
                    {
                        Chance = APlayer.GetHeroJoinChance(GetLevel());
                        Seed = RandSeed;
                        RandSeed = (AoWE.AoWHSMap.FInitialRandomSeed + AoWE.AoWHSMap.FDay + FUnitID * 16) & 4088;
                        Result = Random(100) < Chance;
                        RandSeed = Seed;
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    Result = Player == EmergedToPlayer();
                }
            }
            else
