        // Hero.PAS:885
        public override void Killed()
        {
            THeroItemPosition Position;
            for (int I = FInventory.Count - 1; I >= 0; I--)
            {
                if (FInventory.GetItem(I) != null)
                {
                    ExecutePlaceItem(FInventory.GetItem(I).FItemID, THeroItemPosition.ipGround);
                }
            }

            for (int positionOrdinal = (int)THeroItemPosition.ipAttackSlot; positionOrdinal <= (int)THeroItemPosition.ipRightRingSlot; positionOrdinal++)
            {
                Position = (THeroItemPosition)positionOrdinal;
                if (FHeroItems.GetPositionItem(Position) != null)
                {
                    ExecutePlaceItem(FHeroItems.GetPositionItem(Position).FItemID, THeroItemPosition.ipGround);
                }
            }

            FDeathDay = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDay;
            FDeathPlayer = FPlayer;
            base.Killed();
            FHeroStatus = FHeroStatus + TSet<THeroStatusElement>.Of(THeroStatusElement.hsDied);
            SetPlayer(-1);
            SetOwner(null);
        }

