        // Hero.PAS:751
        public int UsedSkillPoints()
        {
            int Result = FUnitAttack * 5 + FUnitDefense * 5 + FUnitDamage * 10 + FUnitResistance * 5 + FUnitHits * 5 + FUnitMoves * 2;
            for (int I = GetAbCount() - 1; I >= 0; I--)
            {
                if (GetAbSet(I))
                {
                    Result += AoWE.AoWHSSet.FAbilityControl.GetAbility(I).GetSkillPoints(this);
                    if (FHeroResource.FAbilities.GetAbSet(I))
                    {
                        Result -= AoWE.AoWHSSet.FAbilityControl.GetAbility(I).GetSkillPoints(FHeroResource.FAbilities);
                    }
                }
            }

            return Result;
        }

