        // Hero.PAS:1226
        public void ExecuteUpgradeHeroAI()
        {
            TDoubleItemList Choices;
            int Points;
            int Index;
            TDoubleItem Choice;
            Choices = new TDoubleItemList();
            while (true)
            {
                Choices.Clear();
                Points = GetSkillPoints();
                if (Points >= 5 && FUnitAttack + FHeroResource.FAttack < 10)
                {
                    Choices.AddAB(0, 10);
                }

                if (Points >= 5 && FUnitDefense + FHeroResource.FDefense < 10)
                {
                    Choices.AddAB(1, 25);
                }

                if (Points >= 5 && FUnitResistance + FHeroResource.FResistance < 10)
                {
                    Choices.AddAB(2, 10);
                }

                if (Points >= 10 && FUnitDamage + FHeroResource.FDamage < 10)
                {
                    Choices.AddAB(3, 10);
                }

                if (Points >= 5 && FUnitHits + FHeroResource.FHits < 30)
                {
                    Choices.AddAB(4, 10);
                }

                if (AoWE.AoWHSSet.FAbilityControl.GetAbility(46).CanExpand(this) && Points >= AoWE.AoWHSSet.FAbilityControl.GetAbility(46).ExpandCost(this))
                {
                    Choices.AddAB(5, 10);
                }

                if (AoWE.AoWHSSet.FAbilityControl.GetAbility(22).CanExpand(this) && Points >= AoWE.AoWHSSet.FAbilityControl.GetAbility(22).ExpandCost(this))
                {
                    Choices.AddAB(6, 10);
                }

                if (AoWE.AoWHSSet.FAbilityControl.GetAbility(52).CanExpand(this))
                {
                    if (Points >= AoWE.AoWHSSet.FAbilityControl.GetAbility(52).ExpandCost(this))
                    {
                        Choices.AddAB(7, 9999);
                    }
                    else
                    {
                        Choices.AddAB(7, 100);
                    }
                }

                if (Choices.Count != 0)
                {
                    RandSeed = AoWE.AoWHSMap.Random(16777215);
                    Index = Choices.RandomChanceItemB(0);
                    Choice = Choices[Index];
                    switch (Choice.A)
                    {
                        case 0:
                            SetUnitAttack((sbyte)(FUnitAttack + 1));
                            break;
                        case 1:
                            SetUnitDefense((sbyte)(FUnitDefense + 1));
                            break;
                        case 2:
                            SetUnitResistance((sbyte)(FUnitResistance + 1));
                            break;
                        case 3:
                            SetUnitDamage((sbyte)(FUnitDamage + 1));
                            break;
                        case 4:
                            SetUnitHits((sbyte)(FUnitHits + 1));
                            break;
                        case 5:
                            ExpandAbility(46);
                            break;
                        case 6:
                            ExpandAbility(22);
                            break;
                        case 7:
                            if (Points >= AoWE.AoWHSSet.FAbilityControl.GetAbility(52).ExpandCost(this))
                            {
                                ExpandAbility(52);
                            }
                            else
                            {
                                Points = 0;
                            }

                            break;
                    }
                }

                if (Choices.Count == 0 || GetSkillPoints() == 0 || Points == 0)
                    break;
            }

            Choices.Free();
        }

        // Hero.PAS:1269
        public void ValidateHeroUpgrade()
        {
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            int Level;
            int OldLevel;
            THeroUpgradeEventLog Log;
            GetLocation(ref X, ref Y, ref L);
            if (FPlayer != 0 && X != -1)
            {
                FUpgradePending = false;
                Level = GetLevel();
                if (Level < GetLevelMax())
                {
                    if (FPlayer > 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptCPU2)
                    {
                        SetExperience(GetExperience() + (AoWE.HeroExperienceTable[Level / 5].DailyExperience + 1));
                    }
                    else
                    {
                        if (FPlayer > 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptCPU3)
                        {
                            SetExperience(GetExperience() + (AoWE.HeroExperienceTable[Level / 5].DailyExperience + 2));
                        }
                        else
                        {
                            if (FPlayer > 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptCPU4)
                            {
                                SetExperience(GetExperience() + (AoWE.HeroExperienceTable[Level / 5].DailyExperience + 3));
                            }
                            else
                            {
                                if (FPlayer > 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType == TPlayerType.ptCPU5)
                                {
                                    SetExperience(GetExperience() + (AoWE.HeroExperienceTable[Level / 5].DailyExperience + 4));
                                }
                                else
                                {
                                    SetExperience(GetExperience() + AoWE.HeroExperienceTable[Level / 5].DailyExperience);
                                }
                            }
                        }
                    }

                    Level = GetLevel();
                }

                if (FLevel < Level)
                {
                    FUpgradePending = true;
                    OldLevel = FLevel;
                    FLevel = (byte)Level;
                    Log = new THeroUpgradeEventLog(null);
                    Log.FOldLevel = (byte)OldLevel;
                    Log.FNewLevel = FLevel;
                    Log.FDay = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDay;
                    Log.FPlayer = FPlayer;
                    Log.FUnitID = FUnitID;
                    DistributeLocationEventLog(Log, FPlayer, X, Y, L, true);
                    Log.Release();
                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FPlayerType != TPlayerType.ptHuman)
                    {
                        ExecuteUpgradeHeroAI();
                    }
                }
            }
        }

