        // Hero.PAS:1579
        public void SetRace(sbyte Value)
        {
            bool Found;
            int Index;
            THeroResource Resource;
            if (FRace != Value)
            {
                Found = false;
                Index = AoWE.AoWHSSet.FHeroResources.GetCount();
                while (!Found && Index != 0)
                {
                    Index -= 1;
                    Resource = AoWE.AoWHSSet.FHeroResources.GetHeroResource(Index);
                    Found = Resource != null && Resource.FRace == Value && GetHeroType() == Resource.FHeroType;
                }

                if (Found)
                {
                    SetHeroResourceIndex(Index);
                }
            }
        }

