        // Hero.PAS:1742
        public bool CanPlaceItem(int ItemID, THeroItemPosition Position)
        {
            TItem Item;
            sbyte IX = default;
            sbyte IY = default;
            sbyte IL = default;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            bool Result = false;
            Item = AoWE.AoWHSMap.FItemControl.FindItem(ItemID);
