        // Hero.PAS:1804
        public bool ExecuteSwapItem(int ItemID1, int ItemID2)
        {
            bool Result;
            TItem Item1;
            TItem Item2;
            TItemList Owner1;
            TItemList Owner2;
            int Index1;
            int Index2;
            if (CanSwapItem(ItemID1, ItemID2))
            {
                Item1 = AoWE.AoWHSMap.FItemControl.FindItem(ItemID1);
                Item2 = AoWE.AoWHSMap.FItemControl.FindItem(ItemID2);
                Owner1 = (TItemList)Item1.Owner;
                Owner2 = (TItemList)Item2.Owner;
                Owner1.BeginUpdate();
                Owner2.BeginUpdate();
                Index1 = Item1.Owner.FindChildIndex(Item1);
                Index2 = Item2.Owner.FindChildIndex(Item2);
                Item1.SetOwner(null);
                Item2.SetOwner(null);
                if (Owner1.GetControlStyle().Contains(TEControlStyleElement.csArrayMode))
                {
                    Item2.SetArrayOwner(Owner1, Index1);
                }
                else
                {
                    Item2.SetOwner(Owner1);
                }

                if (Owner2.GetControlStyle().Contains(TEControlStyleElement.csArrayMode))
                {
                    Item1.SetArrayOwner(Owner2, Index2);
                }
                else
                {
                    Item1.SetOwner(Owner2);
                }

                Owner2.EndUpdate();
                Owner1.EndUpdate();
                Changed();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:1831
        public bool AutoPlaceItem(TItem Item)
        {
            THeroItemPosition Position;
            int Slot;
            bool Result = false;
            Position = FHeroItems.GetItemTypePosition(Item.FItemType);
            if (FHeroItems.CanPlaceItem(Item, Position))
            {
                FHeroItems.PlaceItem(Item, Position);
                Result = true;
            }
            else
            {
                Slot = FInventory.GetFreeSlot();
                if (Slot != -1)
                {
                    Item.SetArrayOwner(FInventory, Slot);
                    Result = true;
                }
            }

            return Result;
        }

        // Hero.PAS:1852
        public bool ExecutePlaceItem(int ItemID, THeroItemPosition Position)
        {
            bool Result;
            TItem Item;
            TAbstractAoWCombatMap Map;
            if (CanPlaceItem(ItemID, Position))
            {
                Item = AoWE.AoWHSMap.FItemControl.FindItem(ItemID);
                switch (Position)
                {
                    case THeroItemPosition.ipGround:
                        Map = AoWE.AoWHSMap.FCombatMap;
                        if (Map != null)
                        {
                            Map.DropHeroItem(this, Item);
                        }
                        else
                        {
                            AoWE.AoWHSMap.DropHeroItem(this, Item);
                        }

                        Changed();
                        break;
                    case >= THeroItemPosition.ipAttackSlot and <= THeroItemPosition.ipRightRingSlot:
                        FHeroItems.PlaceItem(Item, Position);
                        Changed();
                        break;
                    case >= THeroItemPosition.ipInventorySlot1 and <= THeroItemPosition.ipInventorySlot8:
                        Item.SetArrayOwner(FInventory, (int)Position - 6);
                        Changed();
                        break;
                }

                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:1876
        public bool ExecuteStartCasting(int SpellID)
        {
            bool Result;
            TSpell Spell;
            if (FCastingSpellID != 0)
            {
                ExecuteCancelCasting();
            }

            Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
            var castingMana = CastingMana(Spell);
            if (players.FMagicControl.FMana >= castingMana && CastingMana(Spell) > FCastingPoints)
            {
                FCastingProgress = CastingMana(Spell);
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana - FCastingProgress);
                FCastingMana = FCastingPoints;
                FCastingPoints = 0;
                if (AoWE.AoWHSMap.FSeatedPlayer == FPlayer)
                {
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.CastingXInProgressRStr), [Spell.FSpellName]);
                    AoWE.AoWHSMap.ShowMessage(format);
                }

                FCastingSpellID = SpellID;
                Changed();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:1898
        public void RemoveCastingReadyEventLog()
        {
            TEventLogbook Logbook;
            Logbook = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FEventLogbook;
            for (int I = Logbook.GetCount() - 1; I >= 0; I--)
            {
                if (Logbook.GetLogs(I) is TSpellCastEventLog && ((TSpellCastEventLog)Logbook.GetLogs(I)).FUnitID == FUnitID)
                {
                    Logbook.GetLogs(I).SetOwner(null);
                }
            }
        }

        // Hero.PAS:1907
        public bool ExecuteCancelCasting()
        {
            bool Result;
            if (FCastingSpellID != 0)
            {
                RemoveCastingReadyEventLog();
                if (GetCastingPointsMax() < FCastingPoints + FCastingMana)
                {
                    FCastingPoints = GetCastingPointsMax();
                }
                else
                {
                    FCastingPoints = (sbyte)(FCastingPoints + FCastingMana);
                }

                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.SetMana(players.FMagicControl.FMana + FCastingProgress);
                FCastingSpellID = 0;
                FCastingMana = 0;
                FCastingProgress = 0;
                Changed();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:1925
        public void CastingDone(int SpellID, int Mana)
        {
            if (SpellID == FCastingSpellID)
            {
                Assert(CastingReady(), (AnsiString)"", "Hero.PAS", 2080);
                FCastingMana = 0;
                FCastingProgress = 0;
                FCastingSpellID = 0;
                RemoveCastingReadyEventLog();
            }
            else
            {
                if (FCastingSpellID != 0)
                {
                    ExecuteCancelCasting();
                }

                if (!AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                {
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.SetMana(players.FMagicControl.FMana - Mana);
                    FCastingPoints = (sbyte)(FCastingPoints - Mana);
                }
            }
        }

        // Hero.PAS:2098
        public int CastingMana(TSpell Spell)
        {
            int Result = Spell.FBaseManaCost;
            if (AoWE.AoWHSMap.FGlobalMagicControl.GetSphereManaDoubled(Spell.FMagicSphere))
            {
                Result = Result * 2;
            }

            return Result;
        }

        // Hero.PAS:2104
        public int CastingTurns(TSpell Spell)
        {
            int Result;
            int Mana;
            int Points;
            Mana = CastingMana(Spell);
            Points = FCastingPoints + FCastingMana;
            if (GetCastingPointsMax() < Points)
            {
                Points = GetCastingPointsMax();
            }

            if (Points < Mana)
            {
                Result = (Mana - Points) / GetCastingPointsMax();
                if ((Mana - Points) % GetCastingPointsMax() != 0)
                {
                    Result += 1;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Hero.PAS:2118
        public bool Casting() => FCastingSpellID != 0;

        // Hero.PAS:2121
        public bool CastingReady() => FCastingSpellID != 0 && FCastingMana == FCastingProgress;

        // Hero.PAS:2124
        public int CastingTurnsLeft()
        {
            int Result;
            if (FCastingSpellID != 0 && GetCastingPointsMax() != 0)
            {
                if (FCastingMana < FCastingProgress)
                {
                    var castingPointsMax = GetCastingPointsMax();
                    Result = (FCastingProgress - FCastingMana) / castingPointsMax;
                    var castingPointsMax2 = GetCastingPointsMax();
                    if ((FCastingProgress - FCastingMana) % castingPointsMax2 != 0)
                    {
                        Result += 1;
                    }
                }
                else
                {
                    Result = 0;
                }
            }
            else
            {
                Result = -1;
            }

            return Result;
        }

        // Hero.PAS:2136
        public bool CanCastSpellInstantly(int SpellID, int Mana, ref AnsiString Reason)
        {
            bool Result;
            if (!AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
            {
                if (Mana <= FCastingPoints || SpellID == FCastingSpellID && Casting() && CastingReady())
                {
                    Result = CanCastSpell(SpellID, ref Reason);
                }
                else
                {
                    Result = false;
                    Reason = AoWE.TranslateRStr(AoWE.P2NotEnoughCastingPointsRStr);
                }
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Hero.PAS:2149
        public bool CanCastSpell(int SpellID, ref AnsiString Reason)
        {
            bool Result;
            TSpell Spell;
            if (FCastingSpellID == 0)
            {
                Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                var castingMana = CastingMana(Spell);
                if (players.FMagicControl.FMana >= castingMana || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                {
                    Result = Spell.CanActivate(this, ref Reason);
                }
                else
                {
                    Result = false;
                    Reason = AoWE.TranslateRStr(AoWE.NotEnoughManaRStr);
                }
            }
            else
            {
                Result = SpellID == FCastingSpellID;
                if (Result && AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID).FSpellType == TSpellType.stGlobal && AoWE.AoWHSMap.FCombatMap != null)
                {
                    Reason = AoWE.TranslateRStr(AoWE.CannotCastSpellInCombatRStr);
                    Result = false;
                }
            }

            return Result;
        }

        // Hero.PAS:2176
        public bool CastSpell(int SpellID, ref AnsiString Reason)
        {
            bool Result;
            TSpell Spell;
            THeroUpdateTE TE;
            if (CanCastSpell(SpellID, ref Reason))
            {
                if (FCastingSpellID == 0)
                {
                    Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
                    if (CastingMana(Spell) <= FCastingPoints || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        Result = Spell.CanActivate(this, ref Reason) && Spell.Activate(this);
                    }
                    else
                    {
                        if (!AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy())
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                            var castingMana = CastingMana(Spell);
                            if (players.FMagicControl.FMana >= castingMana)
                            {
                                TE = CreateHeroUpdateTE();
                                TE.FMode = THeroUpdateMode.hmStartCasting;
                                TE.FItemID = SpellID;
                                AoWE.AoWHSMap.FTokenManager.GetTokenControl(FPlayer).AddEvent(TE);
                                TE.Release();
                                Result = true;
                            }
                            else
                            {
                                Result = false;
                                Reason = AoWE.TranslateRStr(AoWE.NotEnoughManaRStr);
                            }
                        }
                        else
                        {
                            Result = false;
                        }
                    }
                }
                else
                {
                    if (CastingReady())
                    {
                        Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
                        Result = Spell.CanActivate(this, ref Reason) && Spell.Activate(this);
                    }
                    else
                    {
                        Result = true;
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2220
        public bool CanCastCombatSpell(int SpellID, ref AnsiString Reason)
        {
            bool Result;
            TSpell Spell;
            if (FCastingSpellID == 0)
            {
                Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
                if (CastingMana(Spell) <= FCastingPoints || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                {
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                    var castingMana = CastingMana(Spell);
                    if (players.FMagicControl.FMana >= castingMana || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        Result = Spell.CanActivateCombat(this, ref Reason);
                    }
                    else
                    {
                        Result = false;
                        Reason = AoWE.TranslateRStr(AoWE.NotEnoughManaRStr);
                    }
                }
                else
                {
                    Result = false;
                    Reason = AoWE.TranslateRStr(AoWE.NotEnoughChannelingPointsRStr);
                }
            }
            else
            {
                Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
                Result = TSet<TSpellType>.Of(TSpellType.stCombat, TSpellType.stUnit).Contains(Spell.FSpellType) && CanCastSpellInstantly(SpellID, CastingMana(Spell), ref Reason);
            }

            return Result;
        }

        // Hero.PAS:2252
        public bool CastCombatSpell(int SpellID, ref AnsiString Reason)
        {
            bool Result;
            TSpell Spell;
            Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(SpellID);
            if (CanCastCombatSpell(SpellID, ref Reason))
            {
                Result = Spell.CanActivateCombat(this, ref Reason) && Spell.ActivateCombat(this);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2264
        public bool CancelCasting()
        {
            bool Result;
            THeroUpdateTE TE;
            // { Original tests -1 although zero is the idle spell ID. }
            if (FCastingSpellID != -1 && !AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy())
            {
                TE = CreateHeroUpdateTE();
                TE.FMode = THeroUpdateMode.hmCancelCasting;
                AoWE.AoWHSMap.FTokenManager.GetTokenControl(FPlayer).AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

    }

    // FSpherePicksMax. FSpheres
    public partial class TLeader : THero
    {
        public new const int ClassID = 131634;

        public byte FSpherePicksMax;
        public TByteList FSpheres;
        // Hero.PAS:2766
        public override void Destroy()
        {
            if (AoWE.AoWHSMap != null && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer) != null && this == AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FLeader)
            {
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetLeader(null);
            }

            base.Destroy();
            FSpheres.Free();
        }

        // Hero.PAS:2898
        public override TEngine GetEngine() => AoWE.AoWEngine;

        // Hero.PAS:2891
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwByteEx(ref FSpherePicksMax, 5, 45);
            Stream.rwStreamProc(46, FSpheres.LoadFromStream, FSpheres.SaveToStream);
        }

        // Hero.PAS:2759
        public TLeader(TECustomNode owner) : base(owner)
        {
            FSpheres = new TByteList();
            FSpherePicksMax = 5;
        }

        // Hero.PAS:2845
        public override void MsgProc(ref TEMsg Msg, TEObject Sender)
        {
            base.MsgProc(ref Msg, Sender);
            if (Msg.MsgID == 537001989)
            {
                SetSpherePicksMax((byte)AoWE.AoWHSMap.FSphereCount);
                if (AoWE.AoWHSMap.FPlayers.GetCount() > FPlayer)
                {
                    // { reload FPlayer }
                    if (AoWE.AoWHSMap.FPlayers.GetPlayers((sbyte)(byte)this.FPlayer).FPlayerRace != FRace)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        SetHeroResourceIndex(AoWE.AoWHSSet.FHeroResources.Find(players.FPlayerRace, THeroType.htHeroLeader));
                        Changed();
                    }
                }
                else
                {
                    Destroy();
                }
            }
        }

        // Hero.PAS:2774
        public override void Changed()
        {
            base.Changed();
            if (AoWE.AoWHSMap != null && !AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msDestroying))
            {
                AoWE.AoWHSMap.FOnLeaderChanged.TriggerNotifyEvents(this);
            }
        }

        // Hero.PAS:2975
        public override byte GetUpkeep() => 0;

        // Hero.PAS:2886
        public override int GetPowerGeneration()
        {
            int Result;
            if (GetAbilityEnabled(52))
            {
                Result = GetAbilityLevel(52) * 5 + 5;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Hero.PAS:2908
        public override void SetPlayer(sbyte Player)
        {
            if (Player != FPlayer)
            {
                if (FPlayer != 0)
                {
                    SetOwner(null);
                    Changed();
                }
                else
                {
                    base.SetPlayer(Player);
                }
            }
        }

        // Hero.PAS:2784
        public override int GetUnitMoraleValue(sbyte Player, sbyte IndependentRelation) => 90;

        // Hero.PAS:2921
        public override bool CanActivate()
        {
            TLeader Leader;
            bool Result = base.CanActivate();
            if (Result)
            {
                Leader = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FLeader;
                if (Leader != null && !CompatibleHero(Leader))
                {
                    Result = false;
                }
            }

            return Result;
        }

        // Hero.PAS:2932
        public override void Activate()
        {
            TLeader Leader;
            FLibraryID = -1;
            if (FPlayer == 0)
            {
                FPlayer = (sbyte)AoWE.AoWHSMap.FPlayers.RaceToPlayer(FRace);
            }

            base.Activate();
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer) != null)
            {
                Leader = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FLeader;
                if (Leader != this)
                {
                    if (Leader != null && Leader.Owner != null)
                    {
                        try
                        {
                            throw Exception.Create((AnsiString)"Double leader used");
                        }
                        catch (System.Exception)
                        {
                        }
                    }

                    // { Original silently swallows this duplicate-leader exception. }
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetLeader(this);
                    Changed();
                }
                else
                {
                    Changed();
                }
            }
            else
            {
                SetOwner(null);
                Release();
            }
        }

        // Hero.PAS:2957
        public override void Deactivate()
        {
            base.Deactivate();
        }

        // Hero.PAS:2972
        public override bool CanDisband(ref AnsiString Reason) => false;

        // Hero.PAS:2915
        public override void Killed()
        {
            if (FUnitStatus.Contains(TUnitStatusElement.usActivated) && AoWE.AoWHSMap.FCombat == null)
            {
                AoWE.AoWHSMap.GameOver(FPlayer, TGameOverStatus.goLost);
            }

            base.Killed();
        }

        // Hero.PAS:2787
        public override AnsiString GetNickname()
        {
            AnsiString Result;
            if (AoWE.AoWHSMap != null)
            {
                if (AoWE.AoWHSMap.FGameType != TGameType.gtCampaign)
                {
