        // Hero.PAS:2800
        public byte GetSpherePicks(TMagicSphere Sphere)
        {
            byte Result;
            if (Sphere != TMagicSphere.msCosmos)
            {
                Result = 0;
                for (int I = FSpheres.Count - 1; I >= 0; I--)
                {
                    if (FSpheres.List[I] == (byte)Sphere)
                    {
                        Result = (byte)(Result + 1);
                    }
                }
            }
            else
            {
                Result = 4;
            }

            return Result;
        }

        // Hero.PAS:2812
        public TMagicSphere GetSpheres(int Index) => (TMagicSphere)FSpheres.List[Index];

        // Hero.PAS:2815
        public int GetSphereCount() => FSpheres.Count;

        // Hero.PAS:2818
        public void SetSpherePicksMax(byte Value)
        {
            FSpherePicksMax = Value;
            while (FSpheres.Count > FSpherePicksMax)
            {
                FSpheres.Delete(FSpheres.Count - 1);
            }
        }

        // Hero.PAS:2824
        public bool CanAddSphere(TMagicSphere Sphere)
        {
            bool Result;
            if (FSpheres.Count < FSpherePicksMax)
            {
                if (Sphere == TMagicSphere.msCosmos)
                {
                    Result = false;
                }
                else
                {
                    if (AoWE.AoWEngine.FDemo && GetSpherePicks(Sphere) >= 2)
                    {
                        Result = false;
                    }
                    else
                    {
                        if (GetSpherePicks(Sphere) == 4)
                        {
                            Result = false;
                        }
                        else
                        {
                            if (Sphere == TMagicSphere.msFire && GetSpherePicks(TMagicSphere.msWater) != 0)
                            {
                                Result = false;
                            }
                            else
                            {
                                if (Sphere == TMagicSphere.msWater && GetSpherePicks(TMagicSphere.msFire) != 0)
                                {
                                    Result = false;
                                }
                                else
                                {
                                    if (Sphere == TMagicSphere.msLife && GetSpherePicks(TMagicSphere.msDeath) != 0)
                                    {
                                        Result = false;
                                    }
                                    else
                                    {
                                        if (Sphere == TMagicSphere.msDeath && GetSpherePicks(TMagicSphere.msLife) != 0)
                                        {
                                            Result = false;
                                        }
                                        else
                                        {
                                            if (Sphere == TMagicSphere.msEarth && GetSpherePicks(TMagicSphere.msAir) != 0)
                                            {
                                                Result = false;
                                            }
                                            else
                                            {
                                                if (Sphere == TMagicSphere.msAir && GetSpherePicks(TMagicSphere.msEarth) != 0)
                                                {
                                                    Result = false;
                                                }
                                                else
                                                {
                                                    Result = true;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2842
        public bool AddSphere(TMagicSphere Sphere)
        {
            bool Result = CanAddSphere(Sphere);
            if (Result)
            {
                FSpheres.Add((byte)Sphere);
            }

            return Result;
        }

        // Hero.PAS:2863
        public bool DeleteSphereIndex(int Index)
        {
            bool Result;
            if (Index >= 0 && Index < FSpheres.Count)
            {
                FSpheres.Delete(Index);
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2870
        public bool DeleteSphere(TMagicSphere Sphere)
        {
            int I;
            I = FSpheres.Count;
            bool Result = false;
            while (!Result && I != 0)
            {
                I -= 1;
                Result = FSpheres[I] == (byte)Sphere;
            }

            if (Result)
            {
                FSpheres.Delete(I);
            }

            return Result;
        }

        // Hero.PAS:2883
        public void ClearSpheres()
        {
            FSpheres.Clear();
        }

    }

