            {
                Hero = (THero)FHeroes.FChildren.List[I];
                if (!Hero.FUnitStatus.Contains(TUnitStatusElement.usActivated) && Hero.Owner == null)
                {
                    Hero.Activate();
                }
            }
        }

        // Hero.PAS:2505
