        {
            int Count;
            THero Hero;
            int Result = 0;
            Count = 0;
            for (int I = FHeroes.FChildren.Count - 1; I >= 0; I--)
            {
                Hero = (THero)FHeroes.FChildren.List[I];
                if (!Hero.FHeroStatus.Contains(THeroStatusElement.hsDied) && Hero.FPlayer <= 0)
                {
                    Result += Hero.GetLevel();
                    Count += 1;
                }
            }

            if (Count != 0)
            {
                Result = Result / Count;
            }
            else
            {
                Result = 0;
            }

            return Result;
