        // Army.PAS:370
        public void ReturnBattleFieldInfo(ref TBattleFieldInfo Info)
        {
            int Strength;
            TAbstractUnit AUnit;
            TDiplomaticRelation Relation;
            TGroupBehavior Behavior;
            bool IncludeUnit;
            Relation = AoWE.DiplomaticRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation);
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                if (AUnit.FGroup != null)
                {
                    Behavior = AUnit.FGroup.GroupClass.Behavior;
                }
                else
                {
                    Behavior = TGroupBehavior.gbPassive;
                }

                IncludeUnit = Info.Units == null || Info.Units.FChildren.IndexOf(AUnit) == -1;
                if (IncludeUnit && Info.Requests.Contains(TBattleFieldInfoRequestsElement.bfrIgnorePassiveIndependents))
                {
                    IncludeUnit = AUnit.FPlayer != 0 || AUnit.FGroup != null && AUnit.FGroup.GroupClass.Behavior != TGroupBehavior.gbPassive && AUnit.FGroup.GroupClass.Behavior != TGroupBehavior.gbGuard;
                }

                if (IncludeUnit && Info.Requests.Contains(TBattleFieldInfoRequestsElement.bfrIgnoreIndependents) && AUnit.FPlayer == 0)
                {
                    IncludeUnit = false;
                }

                if (IncludeUnit)
                {
                    Strength = AUnit.GetStrengthMax(Info.DamageTypes);
                    if (Info.FriendlyRelations.Contains((byte)(int)Relation))
                    {
                        Info.FriendlyStrength += Strength;
                    }

                    if (Info.EnemyRelations.Contains((byte)(int)Relation) || Behavior == TGroupBehavior.gbGuardArea)
                    {
                        Info.Strength += Strength;
                    }
                }
            }
        }

