        // Army.PAS:613
        public void UpdateConcealment()
        {
            bool Concealed;
            TLeader ALeader;
            bool Changed;
            bool ShowCrown;
            if (FStatus.Contains(TArmyStatusElement.asActivated))
            {
                if (FConcealedUnits != 0 && AoWE.AoWHSMap.FSeatedPlayer != FPlayer && !AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting))
                {
                    Concealed = GetConcealedForPlayer(AoWE.AoWHSMap.FSeatedPlayer);
                }
                else
                {
                    Concealed = false;
                }

                ALeader = Leader(255);
                ShowCrown = ALeader != null;
                if (ShowCrown && Concealed)
                {
                    var indexOf = IndexOf(ALeader);
                    if ((((int)(((uint)FConcealedUnits) >> indexOf)) & 1) != 0)
                    {
                        ShowCrown = false;
                    }
                }

                Changed = false;
                if (ShowCrown)
                {
                    FStatus = FStatus + TSet<TArmyStatusElement>.Of(TArmyStatusElement.asShowCrown);
                }
                else
                {
                    FStatus = FStatus - TSet<TArmyStatusElement>.Of(TArmyStatusElement.asShowCrown);
                }

                if (Concealed != FStatus.Contains(TArmyStatusElement.asConcealed))
                {
                    if (Concealed)
                    {
                        FStatus = FStatus + TSet<TArmyStatusElement>.Of(TArmyStatusElement.asConcealed);
                    }
                    else
                    {
                        FStatus = FStatus - TSet<TArmyStatusElement>.Of(TArmyStatusElement.asConcealed);
                    }

                    Changed = true;
                }

                Concealed = Concealed && GetCount() == ConcealedUnitsCount();
                if (Concealed != GetFullyConcealed())
                {
                    SetFullyConcealed(Concealed);
                    Changed = true;
                }

                if (Changed)
                {
                    TriggerOnUpdateEvent();
                }
            }
        }

