        // Army.PAS:647
        public int GetRace(byte Selection)
        {
            bool Same;
            int Race;
            int Result = -1;
            Same = true;
            for (int I = 0, last = GetCount() - 1; I <= last; I++)
            {
                if ((Selection & 1) != 0)
                {
                    Race = ((TAbstractUnit)FChildren.List[I]).GetRace();
                    if (Race != -1)
                    {
                        if (Result != -1)
                        {
                            Same = Same && Race == Result;
                        }
                        else
                        {
                            Result = Race;
                        }
                    }
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            if (!Same)
            {
                Result = -1;
            }

            return Result;
        }

