        // Army.PAS:687
        public void UpdateConcealedUnits()
        {
            int I;
            TAoWMapField Field;
            if (FX != -1 && FL != -1 && FStatus.Contains(TArmyStatusElement.asActivated))
            {
                FConcealedUnits = 0;
                I = FChildren.Count;
                Field = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(FX, FY, FL);
                while (I != 0)
                {
                    I -= 1;
                    FConcealedUnits = (byte)(FConcealedUnits << 1);
                    if (((TAbstractUnit)FChildren.List[I]).ConcealedOnMapF(Field))
                    {
                        FConcealedUnits = (byte)(FConcealedUnits | 1);
                    }
                }
            }
        }

        // Army.PAS:705
        public void UpdateUpkeep()
        {
            byte Upkeep;
            byte Previous;
            int Delta;
            Upkeep = 0;
            for (int I = 0, last = GetCount() - 1; I <= last; I++)
            {
                Upkeep = (byte)(Upkeep + ((TAbstractUnit)FChildren.List[I]).GetUpkeep());
            }

            Previous = FUpkeep;
            if (Previous != Upkeep && FStatus.Contains(TArmyStatusElement.asActivated))
            {
                Delta = Upkeep - Previous;
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep + Delta);
            }

            FUpkeep = Upkeep;
        }

        // Army.PAS:719
        public void ValidateTerrainEx(sbyte TerrainType, sbyte OverlayType, sbyte Player)
        {
            TAbstractUnit Transport;
            byte Selection;
            TArmyEventLog Log;
            TAbstractUnit AUnit;
            Transport = Transporter(255);
            if (Transport == null || !Transport.ValidTerrain(TerrainType, OverlayType))
            {
                Selection = 0;
                for (int I = GetCount() - 1; I >= 0; I--)
                {
                    Selection = (byte)(Selection << 1);
                    if (!((TAbstractUnit)FChildren.List[I]).ValidTerrain(TerrainType, OverlayType))
                    {
                        Selection = (byte)(Selection | 1);
                    }
                }
            }
            else
            {
                Selection = 0;
            }

            if (Selection != 0)
            {
                if (!AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && AoWE.AoWHSMap.FDay != 0)
                {
                    BeginUpdate();
                    Log = new TArmyEventLog(null);
                    Log.FPlayer = Player;
                    if (TSet<byte>.WithBounds(0, 255).With(0).With(10).Contains((byte)TerrainType))
                    {
                        Log.FArmyText = AoWE.TranslateRStr(AoWE.UnitsDrownRStr);
                        var translateRStr = AoWE.TranslateRStr(AoWE.UnitsDrownRStr);
                        Log.FArmyMessages.Add(translateRStr);
                        Log.FArmyIcon = 3;
                    }
                    else
                    {
                        switch (TerrainType)
                        {
                            case 9:
                                Log.FArmyText = AoWE.TranslateRStr(AoWE.UnitsBurnedRStr);
                                var translateRStr = AoWE.TranslateRStr(AoWE.UnitsBurnedRStr);
                                Log.FArmyMessages.Add(translateRStr);
                                Log.FArmyIcon = 0;
                                break;
                            default:
                                Log.FArmyText = AoWE.TranslateRStr(AoWE.UnitsCrushedRStr);
                                var aoWETranslateRStr = AoWE.TranslateRStr(AoWE.UnitsCrushedRStr);
                                Log.FArmyMessages.Add(aoWETranslateRStr);
                                Log.FArmyIcon = 2;
                                break;
                        }
                    }

                    Log.FArmyView.Setup(this, 255);
                    for (int I = 0, last = GetCount() - 1; I <= last; I++)
                    {
                        AUnit = GetUnit(I);
                        if ((((int)(((uint)Selection) >> I)) & 1) != 0)
                        {
                            var hitPoints = AUnit.GetHitPoints();
                            Log.FDamageValues.Add((byte)hitPoints);
                            Log.FDamageTypes.Add(9);
                            AUnit.SetHitPoints(0);
                        }
                        else
                        {
                            Log.FDamageValues.Add(0);
                            Log.FDamageTypes.Add(9);
                        }
                    }

                    Log.ValidateGameOver();
                    DistributeLocationEventLog(Log, FPlayer, FX, FY, FL, true);
                    Log.Release();
                    EndUpdate();
                }

                Validate();
            }
        }

        // Army.PAS:785
        public void ValidateTerrain(sbyte TerrainType, sbyte OverlayType)
        {
            ValidateTerrainEx(TerrainType, OverlayType, FPlayer);
        }

        // Army.PAS:790
        public void Validate()
        {
            TAbstractUnit AUnit;
            TUnit NewUnit;
            AoWE.AoWHSMap.LockGameOverEvent();
            BeginUpdate();
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                if (AUnit.GetHitPoints() == 0)
                {
                    if (AUnit.GetAbilityEnabled(107))
                    {
                        NewUnit = new TUnit(null);
                        NewUnit.SetUnitResource(AoWE.AoWHSSet.FUnitResources.GetUnitResource(152));
                        AUnit.Killed();
                        AddUnit(NewUnit);
                    }
                    else
                    {
                        AUnit.Killed();
                    }
                }
            }

            EndUpdate();
            AoWE.AoWHSMap.UnlockGameOverEvent();
        }

        // Army.PAS:812
        public void UpdateFormation()
        {
            int Level;
            int UnitLevel;
            TAbstractUnit AUnit;
            AnsiString SourceName = default;
            Level = 0;
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                AUnit.UpdateMoraleValue();
                if (AUnit.GetAbilityEnabled(46) || AUnit.GetAbilityLevel(46) > 0)
                {
                    ((TLeadershipAbility)AoWE.AoWHSSet.FAbilityControl.GetAbility(46)).ResetExternalSource(AUnit);
                    UnitLevel = AUnit.GetAbilityLevel(46);
                    if (UnitLevel > Level)
                    {
                        Level = UnitLevel;
                        SourceName = AUnit.GetAbilityOwner(46).GetOwnerName();
                        if (SourceName == AoWE.TranslateRStr(AoWE.ArmyInherentRStr))
                        {
                            SourceName = AUnit.GetName();
                        }
                    }
                }
            }

            if (Level > 0)
            {
                for (int I = FChildren.Count - 1; I >= 0; I--)
                {
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    if (AUnit.GetAbilityLevel(46) < Level)
                    {
                        ((TLeadershipAbility)AoWE.AoWHSSet.FAbilityControl.GetAbility(46)).SetExternalSource(AUnit, (byte)Level, SourceName);
                    }
                }
            }
        }

        // Army.PAS:841
        public void Update()
        {
            if (UpdateCount == 0 && FStatus.Contains(TArmyStatusElement.asActivated))
            {
                LockChanged();
                SortUnits();
                UpdateVisibilityRanges();
                UpdateUnfog();
                UpdateUpkeep();
                UpdateConcealedUnits();
                UpdateConcealment();
                UpdateFormation();
                UpdateIndependentRelation();
                if (AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && FX != -1)
                {
                    AoWE.AoWHSMap.ScannerIconsChangedRad(FX, FY, FL, 0);
                }

                UnlockChanged();
                TriggerOnUpdateEvent();
            }
        }

        // Army.PAS:861
        public void TriggerOnUpdateEvent()
        {
            if (UpdateCount == 0 && FStatus.Contains(TArmyStatusElement.asActivated))
            {
                AoWE.AoWHSMap.ArmyChanged(this);
                if (FOnUpdate != null)
                {
                    FOnUpdate(this);
                }
            }
        }

        // Army.PAS:870
        public void Activate()
        {
            TAbstractUnit AUnit;
            Assert(!FStatus.Contains(TArmyStatusElement.asActivated), (AnsiString)"Army already activated", "Army.PAS", 1171);
            if (FOldAIBehavior == TGroupBehavior.gbNone)
            {
                FOldAIBehavior = GetOldAIBehavior();
            }

            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                if (!AUnit.FUnitStatus.Contains(TUnitStatusElement.usActivated))
                {
                    AUnit.Activate();
                }
            }

            FStatus = FStatus + TSet<TArmyStatusElement>.Of(TArmyStatusElement.asActivated);
            FUpkeep = 0;
            if (FPlayer != -1)
            {
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.AddChild(this);
            }

            // { Original treats X = 0 as an unset location. }
            if (FX == 0)
            {
                FX = -1;
                FY = -1;
                FL = -1;
            }

            Update();
        }

        // Army.PAS:1186
        public void Deactivate()
        {
            TAbstractUnit AUnit;
            if (FStatus.Contains(TArmyStatusElement.asActivated))
            {
                if (FUnfogRange != 0)
                {
                    AoWE.AoWHSMap.FogArea(FX, FY, FL, FUnfogRange);
                    FUnfogRange = 0;
                }

                for (int I = FChildren.Count - 1; I >= 0; I--)
                {
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    if (AUnit.FUnitStatus.Contains(TUnitStatusElement.usActivated))
                    {
                        AUnit.Deactivate();
                    }
                }

                if (FPlayer != -1)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.RemoveChild(this);
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep - FUpkeep);
                }

                FStatus = FStatus - TSet<TArmyStatusElement>.Of(TArmyStatusElement.asActivated);
            }
        }

