        // Army.PAS:1298
        public void SetPlayer(sbyte Player)
        {
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player) == null)
            {
                Player = 0;
            }

            if (Player != FPlayer)
            {
                BeginUpdate();
                if (FStatus.Contains(TArmyStatusElement.asActivated))
                {
                    if (FPlayer != -1)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep - FUpkeep);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.RemoveChild(this);
                    }

                    FPlayer = Player;
                    if (FPlayer != -1)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep + FUpkeep);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FArmies.AddChild(this);
                    }

                    for (int I = FChildren.Count - 1; I >= 0; I--)
                    {
                        ((TAbstractUnit)FChildren.List[I]).SetPlayer(FPlayer);
                    }

                    if (FX != -1)
                    {
                        AoWE.AoWHSMap.ScannerIconsChangedRad(FX, FY, FL, 0);
                    }

                    if (FPlayer > 0 && AoWE.AoWHSMap.FDay > 0)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
                        {
                            SetBehavior(255, TGroupBehavior.gbPassive);
                        }
                    }

                    UpdateUnfog();
                    UpdateExploration();
                }
                else
                {
                    FPlayer = Player;
                }

                EndUpdate();
            }
        }

