                if (Races.List[I] != null)
                {
                    ArmyHS = PlaceIndependentArmy(X, Y, L, (TArmy)Races.List[I]);
                    if (Armies != null && ArmyHS != null)
                    {
                        Armies.AddChild(ArmyHS);
                    }

                    ((TArmy)Races.List[I]).Free();
                    Races.List[I] = null;
                }
            }

            if (GoodArmy != null)
            {
                ArmyHS = PlaceIndependentArmy(X, Y, L, GoodArmy);
                if (Armies != null && ArmyHS != null)
                {
                    Armies.AddChild(ArmyHS);
                }

                GoodArmy.Free();
            }

            if (EvilArmy != null)
            {
                ArmyHS = PlaceIndependentArmy(X, Y, L, EvilArmy);
                if (Armies != null && ArmyHS != null)
                {
                    Armies.AddChild(ArmyHS);
                }

                EvilArmy.Free();
            }

            Units.Free();
            Races.Free();
        }

        // Army.PAS:2029
        public void UpdateIndependentRelation()
        {
            sbyte Race;
            bool Valid;
            bool Evil;
            bool Good;
            bool Neutral;
            int I;
            int UnitRace;
            TAbstractUnit AUnit;
            TAlignment Alignment;
            if (FPlayer == 0)
            {
                Race = -1;
                Valid = true;
                I = FChildren.Count;
                while (Valid && I != 0)
                {
                    I -= 1;
                    if (!((TAbstractUnit)FChildren.List[I]).GetAbilityEnabled(107))
                    {
                        UnitRace = ((TAbstractUnit)FChildren.List[I]).GetRace();
                    }
                    else
                    {
                        UnitRace = -1;
                    }

                    if (UnitRace != -1 && UnitRace != Race)
                    {
                        if (Race == -1)
                        {
                            Race = (sbyte)UnitRace;
                        }
                        else
                        {
                            Valid = false;
                        }
                    }
                }

                if (Valid && Race == -1)
                {
                    if (FX != -1)
                    {
                        Race = FIndependentRelation;
                        FIndependentRelation = -1;
                        FIndependentRelation = (sbyte)((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(FX, FY, FL)).GetIndependentRelation();
                        if (FIndependentRelation >= 0)
                        {
                            Race = FIndependentRelation;
                        }
                        else
                        {
                            FIndependentRelation = Race;
                            Race = -1;
                        }
                    }

                    if (Race == -1)
                    {
                        if (FIndependentRelation >= 0)
                        {
                            Race = FIndependentRelation;
                        }
                        else
                        {
                            Valid = false;
                        }
                    }
                }

                I = FChildren.Count;
                while (Valid && I != 0)
                {
                    I -= 1;
                    bool condition = Race == ((TAbstractUnit)FChildren.List[I]).GetRace();
                    if (!condition)
                    {
                        var alignment = ((TAbstractUnit)FChildren.List[I]).GetAlignment();
                        condition = AoWE.AoWHSSet.FRaceResources.GetRaceResource(Race).FAlignments.Contains(alignment);
                    }

                    Valid = condition;
                }

                if (!Valid)
                {
                    Evil = true;
                    Good = true;
                    Neutral = true;
                    I = 0;
                    int last = FChildren.Count - 1;
                    for (; I <= last; I += 1)
                    {
                        AUnit = (TAbstractUnit)FChildren.List[I];
                        Alignment = AUnit.GetAlignment();
                        Evil = Evil && AoWE.alsEvil.Contains(Alignment) && (AUnit.GetRace() == -1 || TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(Alignment));
                        Good = Good && AoWE.alsGood.Contains(Alignment) && (AUnit.GetRace() == -1 || TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(Alignment));
                        Neutral = Neutral && AoWE.alsNeutral.Contains(Alignment);
                    }

                    if (Good && !Evil)
                    {
                        FIndependentRelation = -2;
                    }
                    else
                    {
                        if (Evil && !Good)
                        {
                            FIndependentRelation = -4;
                        }
                        else
                        {
                            FIndependentRelation = -3;
                        }
                    }
                }
                else
                {
                    FIndependentRelation = Race;
                }
            }
            else
            {
                FIndependentRelation = -1;
            }
        }

        // Army.PAS:2091
        public void Desert(byte Selection)
        {
            TList Units;
            sbyte Player;
            TArmyHSList Armies;
            int Count;
            int Bit;
            TArmyInfoEventLog Log;
            TAbstractUnit AUnit;
            AoWE.AoWHSMap.LockGameOverEvent();
            Units = new TList();
            Count = SelectionCount(Selection);
            Log = new TArmyInfoEventLog(null);
            Log.FArmyView.Setup(this, 255);
            Log.FSelection = Selection;
            Log.FPlayer = FPlayer;
            Log.FTitle = AoWE.TranslateRStr(AoWE.DesertionRStr);
            Log.FTriggers = TSet<TExecuteTrigger>.Of(TExecuteTrigger.etUser);
            if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWE.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpRebellion))
            {
                Log.FTriggers = Log.FTriggers + TSet<TExecuteTrigger>.Of(TExecuteTrigger.etEvent);
                if (AoWE.AoWHSMap.FRequestCombatType)
                {
                    Log.FTriggers = Log.FTriggers + TSet<TExecuteTrigger>.Of(TExecuteTrigger.etNewTurn);
                }
            }

            if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWE.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpRebellion))
            {
                Log.FTriggers = Log.FTriggers + TSet<TExecuteTrigger>.Of(TExecuteTrigger.etEvent, TExecuteTrigger.etNewTurn);
            }

            Log.FDescription = AoWE.TranslateRStr(AoWE.TheLeaderOfThePartyStepsForwardRStr);
            if (Count == 1)
            {
                Log.FText = AoWE.TranslateRStr(AoWE.OneUnitDesertedRStr);
            }
            else
            {
                Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.XUnitsDesertedRStr), [IntToStr(Count)]);
            }

            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FGems == 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetUpkeep() > AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FIncome)
            {
                if (Count == 1)
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.DesertUnitNoUpkeepRStr);
                    Log.FMessages.Text = translateRStr;
                }
                else
                {
                    var translateRStr = AoWE.TranslateRStr(AoWE.DesertUnitsNoUpkeepRStr);
                    Log.FMessages.Text = translateRStr;
                }
            }
            else
            {
                if (ValidateSelection(255) == Selection)
                {
                    if (Count == 1)
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.DesertUnitLowMoraleRStr);
                        Log.FMessages.Text = translateRStr;
                    }
                    else
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.DesertUnitsLowMoraleRStr);
                        Log.FMessages.Text = translateRStr;
                    }
                }
                else
                {
                    if (Count == 1)
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.DesertUnitLowMoraleSplitRStr);
                        Log.FMessages.Text = translateRStr;
                    }
                    else
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.DesertUnitsLowMoraleSplitRStr);
                        Log.FMessages.Text = translateRStr;
                    }
                }
            }

            DistributeLocationEventLog(Log, -1, FX, FY, FL, true);
            Log.Release();
            for (int I = GetCount() - 1; I >= 0; I--)
            {
                Bit = 1 << I;
                if ((Bit & Selection) != 0 && GetUnit(I).GetAbilityEnabled(155))
                {
                    Units.Add(GetUnit(I));
                    Selection = (byte)(Selection & ~(byte)Bit);
                }
            }

            Armies = new TArmyHSList(null);
            Player = FPlayer;
            MakeIndependent(Selection, ref Armies);
            while (Units.Count != 0)
            {
                AUnit = (TAbstractUnit)Units[0];
                AUnit.AddRef();
                AUnit.Killed();
                AUnit.SetOwner(null);
                AUnit.Release();
                Units.Delete(0);
            }

            for (int I = 0, last = Armies.GetCount() - 1; I <= last; I++)
            {
                if (AoWE.DiplomaticRelation(0, Armies.GetArmyHS(I).FArmy.FIndependentRelation, Player, 0) == TDiplomaticRelation.drWar)
                {
                    Armies.GetArmyHS(I).FArmy.SetBehavior(255, TGroupBehavior.gbRaid);
                }
                else
                {
                    Armies.GetArmyHS(I).FArmy.SetBehavior(255, TGroupBehavior.gbScout);
                }
            }

            Armies.Free();
            Units.Free();
            AoWE.AoWHSMap.UnlockGameOverEvent();
        }

        // Army.PAS:2155
        public TPartyStatus GetPartyStatus(byte Selection)
        {
            TPartyStatus Result;
            int Morale;
            int Count;
            TCombatPredictor Predictor;
            int UnitMorale;
            TAbstractUnit AUnit;
            Morale = 100;
            Count = 0;
            Predictor = new TCombatPredictor();
            for (int I = 0, last = FChildren.Count - 1; I <= last; I++)
            {
                if ((Selection & 1) != 0)
                {
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    UnitMorale = AUnit.FMoraleValue;
                    if (AUnit.GetUnitType() != TUnitType.utMachine)
                    {
                        if (UnitMorale < Morale)
                        {
                            Morale = UnitMorale;
                        }

                        Count += 1;
                    }

                    if (UnitMorale <= 40)
                    {
                        Predictor.AddOpponent(AUnit, 0);
                    }
                    else
                    {
                        Predictor.AddUnit(AUnit);
                    }
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            if (Predictor.Execute() == TCombatResult.crDefeat)
            {
                if (Predictor.GetSuperiority() < 50)
                {
                    Result = TPartyStatus.psUnruly;
                }
                else
                {
                    Result = TPartyStatus.psUnrest;
                }
            }
            else
            {
                if (Count == 0 || Morale <= 60)
                {
                    Result = TPartyStatus.psStable;
                }
                else
                {
                    if (Morale <= 80)
                    {
                        Result = TPartyStatus.psContent;
                    }
                    else
                    {
                        Result = TPartyStatus.psCheerful;
                    }
                }
            }

            Predictor.Free();
            return Result;
        }

        // Army.PAS:2185
        public void UpdateDesertion()
        {
            TPartyStatus Status;
            int Chance;
            byte Selection;
            if (FX != -1 && FPlayer != 0)
            {
                Status = GetPartyStatus(255);
                if (TSet<TPartyStatus>.Of(TPartyStatus.psUnruly, TPartyStatus.psUnrest).Contains(Status))
                {
                    if (Status == TPartyStatus.psUnrest)
                    {
                        Chance = 10;
                    }
                    else
                    {
                        Chance = 50;
                    }

                    if (Chance > AoWE.AoWHSMap.Random(100))
                    {
                        Selection = 0;
                        for (int I = FChildren.Count - 1; I >= 0; I--)
                        {
                            Selection = (byte)(Selection << 1);
                            if (((TAbstractUnit)FChildren.List[I]).FMoraleValue <= 40)
                            {
                                Selection = (byte)(Selection | 1);
                            }
                        }

                        if (Selection != 0)
                        {
                            Desert(Selection);
                        }
                    }
                }
            }
        }

        // Army.PAS:2208
        public bool ValidateCrusaders()
        {
            int I;
            I = GetCount();
            bool Result = false;
            while (I != 0 && !Result)
            {
                I -= 1;
                if (((TAbstractUnit)FChildren.List[I]).GetAbilityEnabled(101))
                {
                    Result = true;
                }
            }

            if (Result)
            {
                BeginUpdate();
                I = GetCount() - 1;
                for (; I >= 0; I -= 1)
                {
                    if (((TAbstractUnit)FChildren.List[I]).GetAbilityEnabled(101))
                    {
                        ((TAbstractUnit)FChildren.List[I]).ValidateCrusader();
                    }
                }

                Result = GetCount() != 0;
                EndUpdate();
            }
            else
            {
                Result = true;
            }

            return Result;
        }

