            TAbstractUnit AUnit;
            if (Player > 0)
            {
                Result = 0;
                for (int I = Count - 1; I >= 0; I--)
                {
                    Result = (byte)(Result << 1);
                    AUnit = (TAbstractUnit)FChildren.List[I];
                    if (AUnit.CanJoin(Player))
                    {
