        // Army.PAS:2365
        public bool IncommingNegotiateOffer(TNegotiateTE Offer)
        {
            bool Result;
            TArmyInfoEventLog Log;
            byte Selection;
            THero AHero;
            TXYLList Locations;
            int I;
            int J;
            int Direction;
            int X = default;
            int Y = default;
            int JoinCount;
            int Side;
            bool Placed;
            if (Offer.FObject == TNegotiateObject.noArmy)
            {
                if (Offer.FResult == TNegotiateResult.nrAccept)
                {
                    Selection = GetJoinSelection(Offer.FPlayer);
                    JoinCount = SelectionCount(Selection);
                    if (Offer.FMode.Contains(TNegotiateModeElement.nmPrisonerJoin) || JoinAmount(Offer.FPlayer, Selection) <= Offer.FGold)
                    {
                        BeginUpdate();
                        Offer.FMode = Offer.FMode + TSet<TNegotiateModeElement>.Of(TNegotiateModeElement.nmMoveOnAccept);
                        Log = new TArmyInfoEventLog(null);
                        Log.FArmyView.Setup(this, Selection);
                        Log.FSelection = 255;
                        Log.FDescription = (AnsiString)"";
                        Log.FTitle = AoWE.TranslateRStr(AoWE.P2PartyJoinRStr);
                        Log.FTriggers = TSet<TExecuteTrigger>.Of(TExecuteTrigger.etUser);
                        AHero = Hero(Selection, TSet<THeroType>.Of(THeroType.htHero));
                        if (AHero == null)
                        {
                            if (JoinCount == 1)
                            {
                                Log.FText = AoWE.TranslateRStr(AoWE.P2OneUnitJoinedRStr);
                                var name = AoWE.AoWHSMap.FPlayers.GetPlayers(Offer.FPlayer).GetName();
                                var format = AoWE.Format(AoWE.TranslateRStr(AoWE.P2AUnitJoinedTheForcesofYRStr), [name]);
                                Log.FMessages.Text = format;
                            }
                            else
                            {
                                Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.P2XUnitsJoinedRStr), [IntToStr(JoinCount)]);
                                var selectionCount = SelectionCount(Selection);
                                var name = AoWE.AoWHSMap.FPlayers.GetPlayers(Offer.FPlayer).GetName();
                                var format = AoWE.Format(AoWE.TranslateRStr(AoWE.P2XUnitsJoinedTheForcesofYRStr), [selectionCount, name]);
                                Log.FMessages.Text = format;
                            }
                        }
                        else
                        {
                            Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.P2XJoinedRStr), [AHero.FHeroName]);
                            var name = AoWE.AoWHSMap.FPlayers.GetPlayers(Offer.FPlayer).GetName();
                            var format = AoWE.Format(AoWE.TranslateRStr(AoWE.P2XJoinedTheForcesOfYRStr), [AHero.FHeroName, name]);
                            Log.FMessages.Text = format;
                        }

                        DistributeLocationEventLog(Log, -1, FX, FY, FL, false);
                        Log.Release();
                        if (ValidateSelection(255) != Selection)
                        {
                            Locations = new TXYLList();
                            if (Offer.FArmyHS != null)
                            {
                                var yhx = Offer.FArmyHS.GetYhx();
                                var xhx = Offer.FArmyHS.GetXhx();
                                Direction = dHXtoHNfast(FX, FY, xhx, yhx);
                                if (Direction > 0 && Direction <= 6)
                                {
                                    Locations.AddXYL(FX, FY, FL);
                                    Side = Direction + 1;
                                    if (Side > 6)
                                    {
                                        Side = 1;
                                    }

                                    // { Original sign extends the wrapped byte coordinates here. }
                                    CenterHNtoHX((sbyte)Offer.FX, (sbyte)Offer.FY, Side, ref X, ref Y);
                                    Locations.AddXYL((sbyte)X, (sbyte)Y, FL);
                                    Side = Direction - 1;
                                    if (Side == 0)
                                    {
                                        Side = 6;
                                    }

                                    CenterHNtoHX((sbyte)Offer.FX, (sbyte)Offer.FY, Side, ref X, ref Y);
                                    Locations.AddXYL((sbyte)X, (sbyte)Y, FL);
                                }
                            }

                            J = 0;
                            I = Count;
                            while (I != 0)
                            {
                                I -= 1;
                                if ((Selection & (1 << I)) != 0)
                                {
                                    Placed = false;
                                    while (!Placed && J < Locations.Count)
                                    {
                                        var item = Locations[J];
                                        var locationsItem = Locations[J];
                                        var item2 = Locations[J];
                                        Placed = GetUnit(I).Place(item2.X, locationsItem.Y, item.L, Offer.FPlayer, TSet<TUnitPlaceModeElement>.Of()) != null;
                                        if (!Placed)
                                        {
                                            J += 1;
                                        }
                                    }

                                    if (!Placed)
                                    {
                                        GetUnit(I).Place(FX, FY, FL, Offer.FPlayer, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                                    }
                                }
                            }

                            Locations.Free();
                        }
                        else
                        {
                            SetPlayer(Offer.FPlayer);
                        }

                        EndUpdate();
                        Offer.Accept();
                    }
                    else
                    {
                        Offer.FMode = TSet<TNegotiateModeElement>.Of(TNegotiateModeElement.nmAttackOnReject);
                        Offer.Reject();
                    }
                }
                else
                {
                    if (Offer.FResult == TNegotiateResult.nrReject && !Offer.FMode.Contains(TNegotiateModeElement.nmPrisonerJoin))
                    {
                        Offer.Reject();
                    }
                }

                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Army.PAS:2468
        public void TriggerFireDamage()
        {
            TArmyEventLog Log;
            TAbstractUnit AUnit;
            int Damage;
            bool Damaged;
            RandSeed = AoWE.AoWHSMap.Random(16777215);
            Log = new TArmyEventLog(null);
            Log.FArmyText = AoWE.TranslateRStr(AoWE.P2FireDamageRStr);
            Log.FPlayer = GetArmyHS().FArmy.FPlayer;
            var translateRStr = AoWE.TranslateRStr(AoWE.P2FireDamageRStr);
            Log.FArmyMessages.Add(translateRStr);
            Log.FArmyIcon = 0;
            var armyHS = GetArmyHS();
            Log.FArmyView.Setup(armyHS.FArmy, 255);
            BeginUpdate();
            Damaged = false;
            for (int I = 0, last = Count - 1; I <= last; I++)
            {
                AUnit = GetUnit(I);
                if (!AUnit.GetImmunityTypes().Contains(TDamageType.dtFire))
                {
                    Damage = AUnit.ExecuteDamageRole(4, 4, TSet<TDamageType>.Of(TDamageType.dtFire));
                    if (Damage > AUnit.GetHitPoints())
                    {
                        Damage = AUnit.GetHitPoints();
                    }

                    if (Damage != 0)
                    {
                        Damaged = true;
                        AUnit.SetHitPoints((sbyte)(AUnit.GetHitPoints() - (sbyte)Damage));
                    }

                    Log.FDamageValues.Add((byte)Damage);
                    Log.FDamageTypes.Add((int)TDamageType.dtFire);
                }
                else
                {
                    Log.FDamageValues.Add(0);
                    Log.FDamageTypes.Add((int)TDamageType.dtNone);
                }
            }

            Log.ValidateGameOver();
            if (Damaged)
            {
                DistributeLocationEventLog(Log, -1, FX, FY, FL, true);
            }

            Log.Release();
            Validate();
            EndUpdate();
        }

        // Army.PAS:2508
        public void RetrieveStormDamageInfo(TStormType Storm, int Distance, ref TStormDamageInfo Info)
        {
            int Attack;
            int Damage;
            byte Relation;
            int Value = default;
            int Amount = default;
            TAbstractUnit AUnit;
            Relation = (byte)(int)AoWE.DiplomaticRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation);
            if (Info.FriendlyRelations.Contains(Relation) || Info.EnemyRelations.Contains(Relation))
            {
                switch (Storm)
                {
                    case TStormType.stIce:
                        Attack = 7;
                        Damage = 5;
                        break;
                    case TStormType.stLightning:
                        Attack = 8;
                        Damage = 7;
                        break;
                    case TStormType.stDeath:
                        Attack = 7;
                        Damage = 4;
                        break;
                    case TStormType.stHoly:
                        Attack = 7;
                        Damage = 5;
                        break;
                    case TStormType.stFire:
                        Attack = 7;
                        Damage = 5;
                        break;
                    case TStormType.stPestilence:
                        Attack = 4;
                        Damage = 3;
                        break;
                    default:
                        Attack = 0;
                        Damage = 0;
                        break;
                }

                for (int I = Count - 1; I >= 0; I--)
                {
                    AUnit = GetUnit(I);
                    if (AUnit.FPlayer != 0 || AUnit.FGroup != null && AUnit.FGroup.GroupClass.Behavior != TGroupBehavior.gbPassive)
                    {
                        AUnit.RetrieveDamageInfo((sbyte)Attack, (sbyte)Damage, TSet<TDamageType>.Of(AoWE.StormDamageType[(int)Storm]), ref Value, ref Amount);
                        if (Info.FriendlyRelations.Contains(Relation))
                        {
                            Info.FriendlyDamage += Amount;
                            // { Original assigns the second return to damage. }
                            Info.FriendlyValue += Value;
                        }

                        if (Info.EnemyRelations.Contains(Relation))
                        {
                            Info.EnemyDamage += Amount;
                            Info.EnemyValue += Value;
                        }
                    }
                }
            }
        }

        // Army.PAS:2538
        public void IncommingStorm(TStormType A1, int A2, sbyte A3)
        {
            TArmyEventLog Log;
            bool Damaged;
            int Damage;
            RandSeed = AoWE.AoWHSMap.Random(16777215);
            Log = new TArmyEventLog(null);
            Log.FArmyText = AoWE.TranslateRStr(AoWE.TStormTypeRStr[(int)A1]);
            Log.FPlayer = A3;
            // { Original appends the storm message. }
            var translateRStr = AoWE.TranslateRStr(AoWE.TStormTypeRStr[(int)A1]);
            Log.FArmyMessages.Add(translateRStr);
            Log.FArmyIcon = 2;
            Log.FArmyView.Setup(this, 255);
            BeginUpdate();
            Damaged = false;
            for (int I = 0, last = Count - 1; I <= last; I++)
            {
                Damage = ((TAbstractUnit)FChildren.List[I]).ExecuteStormDamage(A1, A2);
                if (Damage != 0)
                {
                    Damaged = true;
                }

                Log.FDamageValues.Add((byte)Damage);
                Log.FDamageTypes.Add((byte)(int)AoWE.StormDamageType[(int)A1]);
            }

            if (Damaged)
            {
                Log.ValidateGameOver();
                DistributeLocationEventLog(Log, FPlayer, FX, FY, FL, true);
            }

            Log.Release();
            Validate();
            EndUpdate();
        }

        // Army.PAS:2567
        public void UpdateAITarget(in TAITargetInfo Info, ref TAITargetData Data)
        {
            byte Selection;
            switch (Info.Mode)
            {
                case TAITargetMode.tmAttack:
                case TAITargetMode.tmRaid:
                case TAITargetMode.tmAttackArmies:
                    if (!GetUnitsConcealedForPlayer(255, Info.Player) && Info.Player != FPlayer)
                    {
                        if (FPlayer > 0)
                        {
                            if (AoWE.ValidAttackRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation) || Info.Mode == TAITargetMode.tmRaid)
                            {
                                if (Info.Player != 0 && Leader(255) != null)
                                {
                                    Data.Priority = 300;
                                }
                                else
                                {
                                    if (Info.Player != 0 && Hero(255, TSet<THeroType>.Of(THeroType.htHero)) != null)
                                    {
                                        Data.Priority = 100;
                                    }
                                    else
                                    {
                                        Data.Priority = 50;
                                    }
                                }
                            }
                            else
                            {
                                Data.Priority = 0;
                            }
                        }
                        else
                        {
                            if (FPlayer == 0)
                            {
                                Selection = GetJoinSelection(Info.Player);
                                if (Selection != 0)
                                {
                                    var joinAmount = JoinAmount(Info.Player, Selection);
                                    Data.Cost = joinAmount;
                                    Data.TargetType = TAITargetType.attNegotiate;
                                }
                                else
                                {
                                    if (AoWE.ValidAttackRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation))
                                    {
                                        Data.Priority = 50;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TAITargetMode.tmGuardArea:
                    if (!GetUnitsConcealedForPlayer(255, Info.Player) && Info.Player != FPlayer)
                    {
                        Data.Priority = 50;
                    }
                    else
                    {
                        Data.Priority = 0;
                    }

                    break;
                case TAITargetMode.tmHunt:
                    Data.Priority = 10;
                    break;
                case TAITargetMode.tmRecruit:
                    if (Info.Player == FPlayer && (FPlayer != 0 || AoWE.DiplomaticRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation) != TDiplomaticRelation.drWar))
                    {
                        Data.Priority = Data.Priority | 1;
                    }

                    break;
            }
        }

        // Army.PAS:2605
        public int AIMovePriority()
        {
            int Result = 0;
            if (Leader(255) != null)
            {
                Result += 50000;
            }

            if (Hero(255, TSet<THeroType>.Of(THeroType.htHero, THeroType.htHeroLeader)) != null)
            {
