            }

            Result += ObtainValue(255);
            return Result;
        }

        // Army.PAS:2613
        public void ResetMoveDone()
        {
            TAbstractUnit AUnit;
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (TAbstractUnit)FChildren.List[I];
                AUnit.FUnitStatus = AUnit.FUnitStatus - TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoveDone);
            }
        }

        // Army.PAS:2623
        public bool CanCombine(TArmy Army, byte Selection)
        {
            bool Result;
            int I;
            int MaxCount;
            byte Temp;
            TAbstractUnit OwnTransporter;
            TAbstractUnit OtherTransporter;
            Selection = Army.ValidateSelection(Selection);
            I = 0;
            Temp = Selection;
            while (Temp != 0)
            {
                if ((Temp & 1) != 0)
                {
                    I += 1;
                }

                Temp = (byte)(int)(((uint)Temp) >> 1);
            }

            OwnTransporter = Transporter(255);
            if (OwnTransporter != null)
            {
                MaxCount = OwnTransporter.GetTransportCapacity() + 1;
            }
            else
            {
                MaxCount = 8;
            }

            I += Count;
            if (I <= MaxCount)
            {
                OtherTransporter = Army.Transporter(Selection);
                if (OtherTransporter != null && (I > OtherTransporter.GetTransportCapacity() + 1 || OwnTransporter != null))
                {
                    Result = false;
                }
                else
                {
                    Result = true;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

