        // Army.PAS:3517
        public override sbyte MoveFirst(int Direction, bool Instant)
        {
            sbyte[] Result__cell = new sbyte[1];
            ref sbyte Result = ref Result__cell[0];
            TMapLevel Level;
            int X = default;
            int Y = default;
            int DX = default;
            int DY = default;
            TImageSequenceAnimation Animation;
            Result = base.MoveFirst(Direction, Instant);
            switch (AoWE.AoWEngine.FRegistry.GetMovementSpeed())
            {
                case TMovementSpeed.mmsNormal:
                    FMoveSteps = (sbyte)base.GetMoveSteps();
                    break;
                case TMovementSpeed.mmsFast:
                    FMoveSteps = (sbyte)base.GetMoveSteps();
                    if (FMoveSteps > 8)
                    {
                        FMoveSteps = (sbyte)(FMoveSteps - 4);
                    }
                    else
                    {
                        FMoveSteps = 4;
                    }

                    break;
                case TMovementSpeed.mmsTurbo:
                    FMoveSteps = 2;
                    break;
            }

            if (AoWE.AoWHSMap.FFPS > 0)
            {
                if (AoWE.AoWHSMap.FFPS < 15)
                {
                    FMoveSteps = (sbyte)(FMoveSteps / 2);
                }
                else
                {
                    if (AoWE.AoWHSMap.FFPS < 25)
                    {
                        FMoveSteps = (sbyte)(FMoveSteps - 2);
                    }
                }

                if (FMoveSteps < 2)
                {
                    FMoveSteps = 2;
                }
            }

            if (GetLhx() > 0)
            {
                Level = (TMapLevel)Owner.Owner;
                var yhx = GetYhx();
                CenterHNtoHX(GetXhx(), yhx, Direction, ref X, ref Y);
                if (X >= 0 && Y >= 0 && X < Level.Width && Y < Level.Height)
                {
                    if (Level.GetField(X, Y).TerrainType == 7)
                    {
                        if (AoWE.AoWHSSet.FAbilityControl.GetAbility(42).FImageSequences.GetImageSequence(0) != null)
                        {
                            Animation = new TImageSequenceAnimation(null);
                            Animation.SetImageSequence(AoWE.AoWHSSet.FAbilityControl.GetAbility(42).FImageSequences.GetImageSequence(0));
                            Animation.FAnimationLevel = 27;
                            HNtoHP(Direction, ref DX, ref DY);
                            Animation.SetXhpOffset(DX / 2);
                            Animation.SetYhpOffset(DY / 2);
                            var lhx = GetLhx();
                            var yhx2 = GetYhx();
                            var xhx = GetXhx();
                            AoWE.AoWHSMap.PlaceHX(Animation, xhx, yhx2, lhx);
                        }
                    }
                }
            }

            return Result;
        }

