        {
            THNWalkData Walk = default;
            int Count;
            TMapLevel Level;
            if (FShadowStatus.Contains(TStructureShadowStatusElement.sssConnected))
            {
                Count = FStructure.GetTerrainCount();
                FShadowStatus = FShadowStatus - TSet<TStructureShadowStatusElement>.Of(TStructureShadowStatusElement.sssConnected);
                Level = (TMapLevel)FStructure.Owner.Owner;
