            Group = (THuntAG)AoWE.AoWHSMap.FAIGroupManager.CreateGroup(0, unitsToIndependentRelation, TGroupBehavior.gbHunt);
            Group.AddUnits(Defenders);
            for (int I = Attackers.Count - 1; I >= 0; I--)
