            Collection = ((TStructureResource)FResource).FDefenders.GetRndCollection();
            if (Collection != -1)
            {
                Indexes = new TUnitIndexList();
                var unitIndexListCollection = ((TStructureResource)FResource).FDefenders;
                for (int I = unitIndexListCollection.GetCollectionCount(Collection) - 1; I >= 0; I--)
                {
                    Indexes.Add(unitIndexListCollection.GetU(Collection, I));
                }

                AoWE.FillWithRandomUnits(Indexes, Units, 4, ((TStructureResource)FResource).FRazeDefenderBudget, TSet<TUnitType>.Of(TUnitType.utHumanoid, TUnitType.utCreature, TUnitType.utMachine));
                while (Units.Count > 8)
