        // Structur.PAS:2370
        public override void MapFieldMsgProc(ref TMapFieldMsg Msg)
        {
            if (Msg.MsgID == 4364 && Msg.HN == 0 && FResource.TerrainList.Terrain[Msg.HN] >= 0)
            {
                if (!AoWE.AoWHSMap.FFogEnabled || !FFogged)
                {
                    if (FPlayer >= 0)
                    {
                        if (FPlayer > 0)
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                            Msg.Param[0] = Msg.Param[0].Value + (players.FPlayerRace + 1) * 256;
                        }
                        else
                        {
                            Msg.Param[0] = Msg.Param[0].Value + 3328;
                        }
                    }
                    else
                    {
                        Msg.Param[0] = Msg.Param[0].Value + 3584;
                    }

                    if (AoWE.AoWHSMap.FVictoryCondition == TVictoryCondition.vcCaptureLocations && FVictoryLocations[AoWE.AoWHSMap.FSeatedPlayer])
                    {
                        Msg.Param[0] = Msg.Param[0].Value | 16777216;
                    }
                }
                else
                {
                    Msg.Param[0] = Msg.Param[0].Value + 3584;
                }
            }
            else
            {
                base.MapFieldMsgProc(ref Msg);
            }

            if (Msg.MsgID == 4352)
            {
                if (FResource.TerrainList.Terrain[Msg.HN] >= 0 && !GetRazed())
                {
                    if (FPlayer == 0)
                    {
                        if (((TPlayerStructureResource)FResource).FClaimed)
                        {
                            Msg.Result = 0;
                        }
                        else
                        {
                            Msg.Result = -1;
                        }
                    }
                    else
                    {
                        Msg.Result = FPlayer;
                    }
                }
            }
            else
            {
                if (Msg.MsgID == 4365 && FResource.TerrainList.Terrain[Msg.HN] >= 0)
                {
                    bool condition = FPlayer > 0;
                    if (condition)
                    {
                        var visibilityRange = VisibilityRange();
                        condition = Msg.Param[0].Value <= visibilityRange;
                    }

                    if (condition)
                    {
                        var trueVisionRange = TrueVisionRange();
                        AoWE.AoWHSMap.UpdatePlayerSeen(FPlayer, Msg.MapField.Xhx, Msg.MapField.Yhx, Msg.MapField.Lhx, Msg.Param[0].Value, trueVisionRange);
                    }
                }
                else
                {
                    if (Msg.MsgID == 4400 && FResource.TerrainList.Terrain[Msg.HN] >= 0)
                    {
                        Msg.Result = FPlayer;
                    }
                    else
                    {
                        if (Msg.MsgID == 4353 && FResource.TerrainList.Terrain[Msg.HN] >= 0)
                        {
                            var moveAction = GetMoveAction((sbyte)Msg.Param[0].Value, (TMoveAction)Msg.Param[1].Value);
                            Msg.Param[1] = (int)moveAction;
                        }
                        else
                        {
                            if (Msg.MsgID == 4362 && FPlayer > 0)
                            {
                                if (FPlayer == Msg.Param[1].Value || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Msg.Param[1].Value) == TDiplomaticRelation.drAlliance)
                                {
                                    var visibilityRange = VisibilityRange();
                                    if (Msg.Param[0].Value <= visibilityRange)
                                    {
                                        Msg.Result = 1;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            if (Msg.MsgID == 4363 && FPlayer > 0)
            {
                if (FPlayer == Msg.Param[1].Value || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Msg.Param[1].Value) == TDiplomaticRelation.drAlliance)
                {
                    var trueVisionRange = TrueVisionRange();
                    if (Msg.Param[0].Value <= trueVisionRange)
                    {
                        Msg.Result = 1;
                    }
                }
            }
            else
            {
                if (Msg.MsgID == 4368 && FResource.TerrainList.Terrain[Msg.HN] >= 0)
                {
                    FinalizeCombat(Msg.Param[0].As<TCombat>());
                }
                else
                {
                    if (Msg.MsgID == 4361 && FResource.TerrainList.Terrain[Msg.HN] >= 0)
                    {
                        var combatEventText = GetCombatEventText(Msg.Param[0].As<TCombat>());
                        ((CombatResultQuery)Msg.Result.Ref).Text = combatEventText;
                    }
                }
            }
        }

