        // Structur.PAS:2130
        public virtual void SetPlayer(sbyte Player)
        {
            if (Player != FPlayer)
            {
                if (GetRazed() && !GetBuilding())
                {
                    return;
                }

                FProductionPriority = 0;
                if (FPlayer != -1)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FStructures.RemoveChild(this);
                }

                if (AoWE.AoWHSMap.FDay > 0)
                {
                    StructureCaptured(FPlayer, Player);
                }

                FPlayer = Player;
                UpdateUnfog();
                UpdatePlayerSeen();
                UpdateExploration();
                var hNtoRad = HNtoRad(FResource.TerrainList.Count);
                var lhx = GetLhx();
                var yhx = GetYhx();
                var xhx = GetXhx();
                AoWE.AoWHSMap.ScannerIconsChangedRad(xhx, yhx, lhx, hNtoRad);
                UpdateFlagID();
                FogChanged();
                var lhx2 = GetLhx();
                var yhx2 = GetYhx();
                var xhx2 = GetXhx();
                AoWE.AoWHSMap.NotifyPlayerChanged(xhx2, yhx2, lhx2);
                if (FPlayer != -1)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FStructures.AddChild(this);
                }

                if (FPlayer > 0 && AoWE.AoWHSMap.FVictoryCondition == TVictoryCondition.vcCaptureLocations)
                {
                    for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        if (FVictoryLocations[I])
                        {
                            if (I == FPlayer || AoWE.AoWHSMap.FAlliedVictory && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation(FPlayer, (sbyte)I) == TDiplomaticRelation.drAlliance)
                            {
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).CheckCaptureLocations();
                            }
                        }
                    }
                }

                Update();
            }
        }

