        public virtual void UpdateUnfog()
        {
            int Range;
            int X = default;
            int Y = default;
            if (!FStatus.Contains(TMapObjectStatusElement.moPlacedOnMap))
            {
                return;
            }

            if (FStatus.Contains(TMapObjectStatusElement.moActivated) && FPlayer != -1 && AoWE.AoWHSMap.FSeatedPlayer != -1 && (AoWE.AoWHSMap.FSeatedPlayer == FPlayer || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation(AoWE.AoWHSMap.FSeatedPlayer) == TDiplomaticRelation.drAlliance))
            {
                Range = VisibilityRange();
            }
            else
            {
                Range = 0;
            }

            if (Range != FUnfogRange)
            {
                if (FUnfogRange != 0)
                {
                    for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                    {
                        if (FResource.TerrainList.Terrain[I] >= 0)
                        {
                            CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                            AoWE.AoWHSMap.FogArea(X, Y, ((TMapField)Owner).Lhx, FUnfogRange);
                        }
                    }
                }

                FUnfogRange = (byte)Range;
                if (FUnfogRange != 0)
                {
                    for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                    {
                        if (FResource.TerrainList.Terrain[I] >= 0)
                        {
                            CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
