                {
                    if (Player == FPlayer || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Player) == TDiplomaticRelation.drAlliance)
                    {
                        for (int I = 0, lastI = FResource.TerrainList.Count - 1; I <= lastI; I++)
