                if (Combat.FCombatResult == TCombatResult.crVictory || Combat.FCombatResult == TCombatResult.crNoDefenders)
                {
                    var editName = EditName();
                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.StructureCapturedRStr), [editName]);
