        // Structur.PAS:2094
        public virtual void StructureCaptured(sbyte OldPlayer, sbyte NewPlayer)
        {
            TLocationTextEventLog Log;
            if (!GetRazed() && !GetBuilding() && OldPlayer == 0 && !AoWE.AoWHSMap.Status.Contains(THSMapStatusElement.msEditting) && FStatus.Contains(TMapObjectStatusElement.moActivated) && !((TPlayerStructureResource)FResource).FClaimed)
            {
                Log = new TLocationTextEventLog(null);
                Log.FPlayer = NewPlayer;
                var editName = EditName();
                Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.StructureCapturedRStr), [editName]);
                Log.FXhx = GetXhx();
                Log.FYhx = GetYhx();
                Log.FLhx = GetLhx();
