                Log.Release();
            }
        }

        // Structur.PAS:2363
        public virtual TMoveAction GetMoveAction(sbyte Player, TMoveAction Action)
        {
            TMoveAction Result;
            if (Player != FPlayer && !GetRazed() && (FPlayer != 0 || ((TPlayerStructureResource)FResource).FClaimed))
            {
                Result = TMoveAction.maAttack;
            }
            else
            {
                Result = Action;
            }

            return Result;
        }

        // Structur.PAS:2349
        public virtual int GetDefaultAITargetPriority() => 10;

        // Structur.PAS:2047
        public virtual bool UpdatePlayer()
        {
            sbyte Player;
            bool Different;
            int Count;
            TMapLevel Level;
            THNWalkData Walk = default;
            TArmyHS Army;
            Player = -1;
            Different = false;
            Count = GetTerrainCount();
            Level = (TMapLevel)Owner.Owner;
            InitHNWalk(ref Walk, FXhx, FYhx, 0);
            while (Walk.HN < Count && !Different)
            {
                if (FResource.TerrainList.Terrain[Walk.HN] >= 0 && Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    Army = (TArmyHS)Level.GetField(Walk.X, Walk.Y).FindOwnedChild(131607);
                    if (Army != null)
                    {
                        if (Player != -1)
                        {
                            Different = Army.FArmy.FPlayer != Player;
                        }
                        else
                        {
                            Player = Army.FArmy.FPlayer;
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }

            if (Player != -1)
            {
                if (Different)
                {
                    SetPlayer(-1);
                }
                else
                {
                    SetPlayer(Player);
                }
            }

            return !Different;
        }

        // Structur.PAS:1986
        public bool GetVictoryLocation(sbyte Player) => FVictoryLocations[Player];

        // Structur.PAS:1991
        public void SetVictoryLocation(sbyte Player, bool Value)
        {
            if (FVictoryLocations[Player] != Value)
            {
                FVictoryLocations[Player] = Value;
                if (Value)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).RegisterVictoryLocation(this);
                }
                else
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(Player).UnregisterVictoryLocation(this);
                }

                Update();
            }
        }

        // Structur.PAS:2002
        public void RegisterVictoryLocations()
        {
            for (int I = 1, last = FVictoryLocations.Count - 1; I <= last; I++)
            {
                if (FVictoryLocations[I])
                {
                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(I) != null)
                    {
                        AoWE.AoWHSMap.FPlayers.GetPlayers(I).RegisterVictoryLocation(this);
                    }
                    else
                    {
                        FVictoryLocations[I] = false;
                    }
                }
            }
        }

        // Structur.PAS:2013
        public void UnregisterVictoryLocations()
        {
            for (int I = 1, last = FVictoryLocations.Count - 1; I <= last; I++)
            {
                if (FVictoryLocations[I] && AoWE.AoWHSMap.FPlayers.GetPlayers(I) != null)
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(I).UnregisterVictoryLocation(this);
                }
            }
        }

        // Structur.PAS:2205
        public int TrueVisionRange() => 1;

        // Structur.PAS:2220
        public void UpdatePlayerSeen()
        {
            int X = default;
            int Y = default;
            if (FStatus.Contains(TMapObjectStatusElement.moPlacedOnMap) && FPlayer > 0)
            {
                for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                {
                    if (FResource.TerrainList.Terrain[I] >= 0)
                    {
                        CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
