                        var visibilityRange = VisibilityRange();
                        var trueVisionRange = TrueVisionRange();
                        AoWE.AoWHSMap.UpdatePlayerSeen(FPlayer, X, Y, lhx, visibilityRange, trueVisionRange);
                    }
                }
            }
        }

