    // inherited . fields listed below. Shared resources and controls for a game pack
    public partial class TAoWHSSet : THSSet
    {
        public new const int ClassID = 131088;

        public TCustomImageLibrary FGeneralImages;
        public TCustomImageLibrary FCursorImages;
        public TCustomImageLibrary FCombatImages;
        public TRaceResourceList FRaceResources;
        public TPadControl FPadControl;
