        // Diplomacy.pas:2576
        public void ValidateIncommingGame(AnsiString FileName, ref AnsiString Destination)
        {
            TAoWHSMap Map;
            TAoWHSMap PreviousMap;
            TEmailGame LocalGame;
            bool Overwrite;
            int I;
            AnsiString Name = default;
            // { Addressability survives elimination of this assignment. }
            try
            {
                Destination = (AnsiString)"";
                Overwrite = false;
                Map = (TAoWHSMap)AoWE.AoWEngine.CreatePreviewHSM(FileName);
                bool condition = Map != null && Map.FConnectionType == TPlayerConnectionType.pcEmail && Map.FCurrentPlayer > 0;
                if (condition)
                {
                    var count = Map.FPlayers.Count;
                    condition = Map.FCurrentPlayer < count;
                }

                if (condition && Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FStatus.Contains(TPBEMPlayerStatusElement.pbsNewTurn))
                {
                    var localEmailAddress = AoWE.AoWEngine.FRegistry.GetLocalEmailAddress();
                    if (CompareText(Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame.FEmailAddress, localEmailAddress) == 0)
                    {
                        LocalGame = FindEmailGame(Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame);
                        if (LocalGame != null)
                        {
                            if (Map.FDay > LocalGame.FLastDay)
                            {
                                Name = Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame.FName;
                                if (FileExists(AoWE.AoWEngine.StartupDirectory + (AnsiString)"EmailIn\\" + Name + (AnsiString)".asg"))
                                {
                                    PreviousMap = (TAoWHSMap)AoWE.AoWEngine.CreatePreviewHSM(AoWE.AoWEngine.StartupDirectory + (AnsiString)"EmailIn\\" + Name + (AnsiString)".asg");
                                    if (PreviousMap != null)
                                    {
                                        // { Original bug: the previous map's player is checked against the new map's count. }
                                        bool test = PreviousMap.FCurrentPlayer > 0;
                                        if (test)
                                        {
                                            var count = Map.FPlayers.Count;
                                            test = PreviousMap.FCurrentPlayer < count;
                                        }

                                        if (test)
                                        {
                                            var players = PreviousMap.FPlayers.GetPlayers(PreviousMap.FCurrentPlayer);
                                            var fPlayersPlayers = Map.FPlayers.GetPlayers(Map.FCurrentPlayer);
                                            bool passed = players.FPBEMSettings.FEmailGame.FUniqueLocalID == fPlayersPlayers.FPBEMSettings.FEmailGame.FUniqueLocalID;
                                            if (passed)
                                            {
                                                var players2 = PreviousMap.FPlayers.GetPlayers(PreviousMap.FCurrentPlayer);
                                                var players3 = Map.FPlayers.GetPlayers(Map.FCurrentPlayer);
                                                passed = players2.FPBEMSettings.FEmailGame.FUniqueID == players3.FPBEMSettings.FEmailGame.FUniqueID;
                                            }

                                            if (passed)
                                            {
                                                Overwrite = true;
                                            }
                                        }

                                        PreviousMap.Free();
                                    }
                                }
                            }
                        }
                        else
                        {
                            Name = Map.FPlayers.GetPlayers(Map.FCurrentPlayer).FPBEMSettings.FEmailGame.FName;
                        }

                        if (Name != (AnsiString)"")
                        {
                            I = 0;
                            Destination = AoWE.AoWEngine.StartupDirectory + (AnsiString)"EmailIn\\" + Name + (AnsiString)".asg";
                            while (!Overwrite && FileExists(Destination))
                            {
                                I += 1;
                                Destination = AoWE.AoWEngine.StartupDirectory + (AnsiString)"EmailIn\\" + Name + IntToStr(I) + (AnsiString)".asg";
                            }
                        }
                    }
                }

                Map.Free();
            }
            catch (System.Exception)
            {
            }
        }

