        public override sbyte GetMostFrequentMapFieldTerrainType(TMapLevel MapLevel, sbyte Xhx, sbyte Yhx, sbyte Default)
        {
            TTerrainList Terrains;
            FixedArray_byte_128 Counts;
            THNWalkData Walk = default;
            sbyte TerrainType;
            sbyte Result = Default;
            Terrains = FResource.TerrainList;
            if (Result < 0)
            {
                Result = 0;
            }

            Counts = default;
            InitHNWalk(ref Walk, Xhx, Yhx, 0);
            while (Walk.HN < Terrains.Count)
            {
                if (FResource.TerrainList.GetTerrain(Walk.HN) >= 0 && Walk.X >= 0 && Walk.Y >= 0 && Walk.X < MapLevel.Width && Walk.Y < MapLevel.Height)
                {
                    TerrainType = MapLevel.GetField(Walk.X, Walk.Y).TerrainType;
                    if (TerrainType >= 0)
                    {
                        Counts[TerrainType] = (byte)(Counts[TerrainType] + 1);
                        if (Counts[TerrainType] > Counts[Result])
                        {
                            Result = TerrainType;
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }

            if (Default >= 0)
            {
                if (Counts[Result] == Counts[Default])
                {
                    Result = Default;
                }
            }

            return Result;
        }

        // Structur.PAS:3422
        public void CalcShowPriority(TMapField MapField)
