            HXtoHP(MapField.Xhx, MapField.Yhx, ref X, ref Y);
            HS = MapField.GetMaxLevelNoneTransparentHS();
            FShowPriority = 1744830464 + ((Y + 36) << 13) + (X + 16);
            if (HS != this && HS != null)
            {
                if (HS.GetShowPriority() >= FShowPriority)
                {
                    FShowPriority = HS.GetShowPriority() + 1;
                }
            }
