        // Structur.PAS:3627
        public void NewTurnDone()
        {
            THNWalkData Walk = default;
            TMapLevel MapLevel;
            int Chance;
            TFire Fire;
            if (FAge > 0)
            {
                MapLevel = (TMapLevel)((TMapField)Owner).Owner;
                var yhx = GetYhx();
                var xhx = GetXhx();
                InitHNWalk(ref Walk, xhx, yhx, 1);
                while (Walk.Radius == 1)
                {
                    // { Original excludes the top row when spreading fire. }
                    if (Walk.X >= 0 && Walk.X < MapLevel.Width && Walk.Y > 0 && Walk.Y < MapLevel.Height)
                    {
                        Chance = AoWE.IgnitionChance((TAoWMapField)MapLevel.GetField(Walk.X, Walk.Y));
                        if (Chance > AoWE.AoWHSMap.Random(1000))
                        {
                            RandSeed = AoWE.AoWHSMap.Random(16777215);
                            var lhx = GetLhx();
                            Fire = AoWE.AoWHSSet.FFireControl.PlaceFire(Walk.X, Walk.Y, lhx, TFireType.ftLarge);
                            if (Fire != null)
                            {
                                Fire.FPlayer = FPlayer;
                                Fire.FTurnsLeft = 3;
                            }
                        }
                    }

                    WalkToNextHN(ref Walk);
                }
            }

            if (FTurnsLeft != 0)
            {
                FTurnsLeft = (sbyte)(FTurnsLeft - 1);
                if (FTurnsLeft != 0)
                {
                    TriggerDamage();
                }
                else
                {
                    Destroy();
                }
            }
            else
            {
                TriggerDamage();
            }
        }

