        // Structur.PAS:3732
        public TFireResource GetRndFireResource(TFireType FireType)
        {
            TFireResource Result;
            TList Resources;
            Resources = new TList();
            for (int I = 0, last = FResources.Count - 1; I <= last; I++)
            {
                if (((TFireResource)FResources.List[I]).FFireType == FireType)
                {
                    Resources.Add(FResources.List[I]);
                }
            }

            if (Resources.Count != 0)
            {
                var random = Random(Resources.Count);
                Result = (TFireResource)Resources.List[random];
            }
            else
