                Result = null;
            }

            Resources.Free();
            return Result;
        }

        // Structur.PAS:3747
        public TFire PlaceFire(int X, int Y, int L, TFireType FireType)
        {
            TFire Result;
            TFireResource Resource;
            TFire Fire;
            Resource = GetRndFireResource(FireType);
            if (Resource != null)
            {
                Fire = (TFire)Resource.CreateResourceUser();
                Fire.FPlayer = AoWE.AoWHSMap.FCurrentPlayer;
                if (!AoWE.AoWHSMap.PlaceHX(Fire, X, Y, L))
                {
                    Fire.Free();
                    Result = null;
                }
                else
                {
                    Result = Fire;
                    Fire.TriggerDamage();
                }
            }
            else
