            for (int I = FAllUnits.Count - 1; I >= 0; I--)
            {
                ((TCombatPredictorUnit)FAllUnits.List[I]).SetupRoundTargets(A1);
            }

            for (int I = FAllUnits.Count - 1; I >= 0; I--)
            {
                ((TCombatPredictorUnit)FAllUnits.List[I]).UpdateRoundTargetPriority();
            }

            for (int I = FAllUnits.Count - 1; I >= 0; I--)
