            TCombatPredictorUnit U;
            bool Result = false;
            for (int I = FActiveUnits.Count - 1; I >= 0; I--)
            {
                U = (TCombatPredictorUnit)FActiveUnits.List[I];
                if (!U.ExecuteRound())
                {
                    FActiveUnits.Delete(I);
                }
                else
                {
                    Result = true;
                }
            }

            for (int I = FActiveUnits.Count - 1; I >= 0; I--)
            {
                U = (TCombatPredictorUnit)FActiveUnits.List[I];
                if (U.FHitPoints <= 0)
