        // CombatPredictor.pas:398
        public bool CanPassWall()
        {
            bool Result;
            int I;
            try
            {
                Result = false;
                I = FAllUnits.Count;
                while (!Result && I != 0)
                {
                    I -= 1;
                    if (FAllUnits.GetUnits(I).FUnit != null)
                    {
                        Result = FAllUnits.GetUnits(I).FUnit.GetWallCombatFeatures().Contains(TWallCombatFeaturesElement.wcWallPassing);
