        // CombatPredictor.pas:415
        public void FinishCombat()
        {
            TCombatPredictorUnit Wall;
            FixedArray_int_2 Surviving;
            FixedArray_int_2 Hits;
            TCombatPredictorUnit U;
            Surviving = default;
            Hits = default;
            for (int I = FAllUnits.Count - 1; I >= 0; I--)
            {
                U = (TCombatPredictorUnit)FAllUnits.List[I];
                U.FinishCombat();
                if (!U.FStatus.Contains(TCombatPredictorUnitStatusElement.usDestroyed))
                {
                    Surviving[U.FSide] += 1;
                }

                Hits[U.FSide] += U.FHitPoints;
            }

            if (Surviving[1] == 0 && Surviving[0] == 0)
            {
                if (Hits[0] >= Hits[1])
                {
                    FResult = 3;
                }
                else
                {
                    FResult = 4;
                }
            }
            else
            {
                if (Surviving[1] == 0)
                {
                    FResult = 3;
                }
                else
                {
                    Wall = FWall;
                    if (Wall != null && Wall.FHitPoints > 0)
                    {
                        if (Surviving[1] == 1 && CanPassWall())
                        {
                            FResult = 3;
                        }
                        else
                        {
                            FResult = 8;
                        }
                    }
                    else
                    {
                        if (Surviving[0] == 0)
                        {
                            FResult = 4;
                        }
                        else
                        {
                            FResult = 2;
                        }
                    }
                }
            }

            FActiveUnits.Clear();
        }

        // CombatPredictor.pas:440
        public TCombatResult Execute()
        {
            if (FWall != null)
            {
                ResetCombat();
                SetupCombat(1);
                while (FWall.FHitPoints > 0 && ExecuteCombatRound())
                {
                }

                if (FWall.FHitPoints <= 0)
                {
                    SetupCombat(0);
                    while (ExecuteCombatRound())
                    {
                    }
                }

                FinishCombat();
            }
            else
            {
                ResetCombat();
                SetupCombat(0);
                while (ExecuteCombatRound())
                {
                }

                FinishCombat();
            }

            AoWE.AoWHSMap.FAIExecuter.UseProcessTime(FWork * 58);
            TCombatResult Result = (TCombatResult)FResult;
            FInvalid = 0;
            return Result;
        }

