        public void InitAdjacentArmies(TArmyHS A1, sbyte A2, sbyte A3, sbyte A4)
        {
            TMapLevel Level;
            TArmyHS ArmyHS;
            TAbstractUnit U;
            byte Defender;
            byte Player;
            byte Relation;
            byte DefenderRelation;
            TCombatSideIndex Side;
            TMapField Field;
            TMapFieldMsg Msg = default;
            THNWalkData Walk = default;
            AddUnits(A1.FArmy);
            Level = AoWE.AoWHSMap.MapContainer.GetMapLevel(A4);
            var army = A1.FArmy;
            Player = (byte)army.FPlayer;
            Relation = (byte)army.FIndependentRelation;

            Defender = (byte)((TAoWMapField)Level.GetField(A2, A3)).GetPlayer();
            DefenderRelation = ((TAoWMapField)Level.GetField(A2, A3)).GetIndependentRelation();
            if (Defender != 255)
            {
                Msg.MsgID = 4387;
                var fieldValue = Level.GetField(A2, A3);
                Msg.Param[0] = fieldValue;
                Msg.Result = 0;
                Level.GetField(A2, A3).SendMapFieldMsg(ref Msg);
                if ((TWallType)Msg.Result.Value != TWallType.wtNone)
                {
                    AddWall((TWallType)Msg.Result.Value);
                }

                InitHNWalk(ref Walk, A2, A3, 0);
                while (Walk.Radius <= 1)
                {
                    if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                    {
                        ArmyHS = (TArmyHS)Level.GetField(Walk.X, Walk.Y).FindOwnedChild(131607);
                        if (ArmyHS != null && ArmyHS != A1)
                        {
                            Side = AoWE.GetCombatSide((sbyte)Player, (sbyte)Relation, (sbyte)Defender, (sbyte)DefenderRelation, ArmyHS.FArmy.FPlayer, ArmyHS.FArmy.FIndependentRelation);
                            if (Side != TCombatSideIndex.csNeutral)
                            {
                                Field = Level.GetField(A2, A3);
                                Msg.MsgID = 4387;
                                var levelField = Level.GetField(Walk.X, Walk.Y);
                                Msg.Param[0] = levelField;
                                Msg.Result = 0;
                                Field.SendMapFieldMsg(ref Msg);
                                for (int I = 0, last = ArmyHS.FArmy.Count - 1; I <= last; I++)
                                {
                                    U = ArmyHS.FArmy.GetUnit(I);
                                    if (U.ValidTerrain(Field.TerrainType, Field.OverlayType))
                                    {
                                        AddUnitEx(U, (byte)(int)Side, (byte)((TWallType)Msg.Result.Value != TWallType.wtNone ? 1 : 0));
                                    }
                                }
                            }
                        }
                    }

                    WalkToNextHN(ref Walk);
                }
            }
        }

