        // CombatPredictor.pas:835
        public int GetSuperiority()
        {
            TCombatPredictorUnit U;
            int Total;
            int Left;
            int Value;
            if (FSuperiority == -1)
            {
                if (FResult == 3)
                {
                    Total = 0;
                    Left = 0;
                    for (int I = FSides[0].Count - 1; I >= 0; I--)
                    {
                        U = (TCombatPredictorUnit)FSides[0].List[I];
                        Value = U.FCombatValueTotal;
                        Total += Value;
                        if (U.FHitPoints > 0)
                        {
                            Left += U.FHitPoints * Value / U.FInitialHitPoints;
                        }
                    }

                    if (Total == Left)
                    {
                        FSuperiority = 999;
                    }
                    else
                    {
                        if (Left > 0)
                        {
                            FSuperiority = Total * 100 / (Total - Left);
                        }
                        else
                        {
                            FSuperiority = 100;
                        }
                    }
                }
                else
                {
                    if (TSet<byte>.WithBounds(0, 255).With(2).With(4).With(8).Contains(FResult))
                    {
                        Total = 0;
                        Left = 0;
                        for (int I = FSides[1].Count - 1; I >= 0; I--)
                        {
                            U = (TCombatPredictorUnit)FSides[1].List[I];
                            Value = U.FCombatValueTotal;
                            Total += Value;
                            if (U.FHitPoints > 0)
                            {
                                Left += U.FHitPoints * Value / U.FInitialHitPoints;
                            }
                        }

                        if (Total == 0)
                        {
                            FSuperiority = 0;
                        }
                        else
                        {
                            if (Left > 0)
                            {
                                FSuperiority = (Total - Left) * 100 / Total;
                            }
                            else
                            {
                                FSuperiority = 100;
                            }
                        }
                    }
                    else
                    {
                        if (FResult == 6)
                        {
                            FSuperiority = 200;
                        }
                        else
                        {
                            FSuperiority = 0;
                        }
                    }
                }
            }

            return FSuperiority;
        }

        // CombatPredictor.pas:872
        public int GetEfficiency()
        {
            FixedArray_int_2 Lost = default;
            byte Side;
            TCombatPredictorUnit U;
            if (FEfficiency == -1)
            {
                for (int sideOrdinal = 0; sideOrdinal <= 1; sideOrdinal++)
                {
                    Side = (byte)sideOrdinal;
                    Lost[Side] = 0;
                    for (int I = FSides[Side].Count - 1; I >= 0; I--)
                    {
                        U = (TCombatPredictorUnit)FSides[Side].List[I];
                        if (U.FStatus.Contains(TCombatPredictorUnitStatusElement.usDestroyed))
                        {
                            var obtainValue = U.FUnit.GetObtainValue();
                            Lost[Side] += obtainValue;
                        }
                        else
                        {
                            if (U.FHitPoints < U.FInitialHitPoints)
                            {
                                var obtainValue = U.FUnit.GetObtainValue();
                                Lost[Side] += Round((double)(obtainValue * U.FHitPoints) / (U.FInitialHitPoints * 2));
                            }
                        }
                    }
                }

                if (Lost[0] != 0)
                {
                    FEfficiency = Lost[1] * 100 / Lost[0];
                }
                else
                {
                    if (Lost[1] != 0 || FSides[1].Count == 0)
                    {
                        FEfficiency = 999;
                    }
                    else
                    {
                        FEfficiency = 100;
                    }
                }
            }

            return FEfficiency;
        }

