        public void ListRequiredUnitsEx(TUnitList A1, TUnitList A2, TUnitList A3, int A4)
        {
            TDoubleItemList List = default;
            int Total = default;
            int Score = default;
            int Budget = default;
            TCombatPredictorUnit U = default;
            int Maximum = default;
            int Minimum = default;
            int Count = default;
            int Previous = default;
            bool Done = default;
            EnableAllUnits();
            Validate();
            if (GetSuperiority() > A4 && FSides[0].Count != 0)
            {
                List = new TDoubleItemList();
                Total = 0;
                for (int I = FSides[0].Count - 1; I >= 0; I--)
                {
                    U = (TCombatPredictorUnit)FSides[0].List[I];
                    if (U.FIncomingCombatValue != 0)
                    {
                        Score = U.FCombatValueTotal * 100 / U.FIncomingCombatValue;
                    }
                    else
                    {
                        Score = 9999;
                    }

                    Total += U.FCombatValueTotal;
                    List.AddAB(ObjectToInt(U), Score);
                }

                List.Sort(AoWE.P3CompareRequiredUnits);
                Minimum = 1;
                Maximum = List.Count;
                if (A4 != 0 && GetSuperiority() != 0)
                {
                    Budget = Round((double)((double)((double)100 / A4) - (double)100 / GetSuperiority()) * ((double)Total * 0.65));
                    Count = List.Count;
                    while (Count > 1 && Budget > 0)
                    {
                        Count -= 1;
                        Budget -= ReferenceFromId<TCombatPredictorUnit>(List[Count].A).FCombatValueTotal;
                    }

                    if (Count < Minimum)
                    {
                        Count = Minimum;
                    }

                    if (Count >= Maximum)
                    {
                        Count = Maximum - 1;
                    }
                }
                else
                {
                    Count = Maximum - 1;
                }

                Previous = Maximum;
                Done = List.Count <= 1;
                while (!Done)
                {
                    for (int I = Count - 1; I >= 0; I--)
                    {
                        ReferenceFromId<TCombatPredictorUnit>(List.List[I].A).SetEnabled(1);
                    }

                    for (int I = List.Count - 1; I >= Count; I--)
                    {
                        ReferenceFromId<TCombatPredictorUnit>(List.List[I].A).SetEnabled(0);
                    }

                    Execute();
                    if (GetSuperiority() >= A4)
                    {
                        Previous = Count;
                        Done = Minimum == Previous;
                        if (!Done)
                        {
                            Count -= 1;
                            if (Count > Minimum && GetSuperiority() - A4 > 300 / List.Count)
                            {
                                Count -= 1;
                            }

                            if (Count > Minimum && GetSuperiority() - A4 > 600 / List.Count)
                            {
                                Count -= 1;
                            }
                        }
                    }
                    else
                    {
                        if (GetSuperiority() < A4)
                        {
                            Minimum = Count + 1;
                            Done = Previous == Minimum;
                            if (!Done)
                            {
                                Count += 1;
                                if (Count + 1 != Previous && A4 - GetSuperiority() > 300 / List.Count)
                                {
                                    Count += 1;
                                }

                                if (Count + 1 != Previous && A4 - GetSuperiority() > 600 / List.Count)
                                {
                                    Count += 1;
                                }
                            }
                        }
                    }
                }

                if (A1 != null)
                {
                    for (int I = 0; I <= Minimum - 1; I++)
                    {
                        A1.AddUnit(ReferenceFromId<TCombatPredictorUnit>(List.List[I].A).FUnit);
                    }
                }

                if (A2 != null)
                {
                    for (int I = List.Count - 1; I >= Minimum; I--)
                    {
                        A2.AddUnit(ReferenceFromId<TCombatPredictorUnit>(List.List[I].A).FUnit);
                    }
                }

                if (A3 != null)
                {
                    for (int I = List.Count - 1; I >= Minimum; I--)
                    {
                        U = ReferenceFromId<TCombatPredictorUnit>(List.List[I].A);
                        if (U.FCombatValueTotal <= 0)
                        {
                            A3.AddUnit(U.FUnit);
                        }
                    }
                }

                List.Free();
            }
            else
            {
                for (int I = FSides[0].Count - 1; I >= 0; I--)
                {
                    U = (TCombatPredictorUnit)FSides[0].List[I];
                    if (U.FCombatValueTotal == 0)
                    {
                        if (A3 != null)
                        {
                            A3.AddUnit(U.FUnit);
                        }
                    }
                    else
                    {
                        if (A1 != null)
                        {
                            A1.AddUnit(U.FUnit);
                        }
                    }
                }
            }
        }

