        // Combat.pas:1941
        public void AddTarget(TCombatObject Target, int CV, int WallCV, int DV)
        {
            Assert(FTargets.IndexOfItemA(ObjectToInt(Target)) == -1, (AnsiString)"target already exists use update target", "Combat.pas", 5473);
            FCombatValue += CV;
            FWallCombatValue += WallCV;
            FTargets.AddABCD(ObjectToInt(Target), CV, WallCV, DV);
            Target.FTargetedBy.AddABCD(ObjectToInt(this), CV, WallCV, DV);
            Target.FIncomingCombatValue += CV;
            Target.FIncomingWallCombatValue += WallCV;
            if (CV > 0)
            {
                FTargetCount += 1;
                Target.FAttackerCount += 1;
            }

            if (WallCV > 0)
            {
                FWallTargetCount += 1;
                Target.FWallAttackerCount += 1;
            }

            TargetsChanged();
            Target.TargetsChanged();
        }

        // Combat.pas:5488
        public void DeleteTarget(int Index)
        {
            TCombatObject Target;
            int CV;
            int DV;
            if (Index != -1)
            {
                Target = ReferenceFromId<TCombatObject>(FTargets.List[Index].A);
                CV = FTargets.List[Index].B;
                DV = FTargets.List[Index].C;
                FCombatValue -= CV;
                FWallCombatValue -= DV;
                FTargets.Delete(Index);
                if (CV > 0)
                {
                    FTargetCount -= 1;
                }

                if (DV > 0)
                {
                    FWallTargetCount -= 1;
                }

                TargetsChanged();
                Index = Target.FTargetedBy.IndexOfItemA(ObjectToInt(this));
                if (Index != -1)
                {
                    Target.FIncomingCombatValue -= Target.FTargetedBy.List[Index].B;
                    // { Original bug: FIncomingWallCombatValue is not decremented. }
                    Target.FTargetedBy.Delete(Index);
                    if (CV > 0)
                    {
                        Target.FAttackerCount -= 1;
                    }

                    if (DV > 0)
                    {
                        Target.FWallAttackerCount -= 1;
                    }

                    Target.TargetsChanged();
                }
            }
        }

