        public override void Finalize(TFinalizeMode A1)
        {
            TCombatParty Party;
            TArmyHS Placed;
            if (!FStatus.Contains(TCombatObjectStatusElement.csDestroyed) && !FUnit.GetAbilityEnabled(130) && !FUnit.GetAbilityEnabled(131))
            {
                if (A1 != TFinalizeMode.fmAll)
                {
                    if ((FPosition & 15) <= 7)
                    {
                        Party = FCombat.FCombatData.FParties.GetParty((byte)(int)(((uint)FPosition) >> 4));
                        if (Party != null && (sbyte)Party.FPlayerIndex == FCombatPlayer)
                        {
                            var player = GetPlayer();
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(player).FGameOverStatus == TGameOverStatus.goLost)
                            {
                                Placed = FUnit.Place(Party.F_CombatParty_0C, Party.F_CombatParty_10, Party.F_CombatParty_14, 0, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmNeglectEmptyPlayerLocation));
                            }
                            else
                            {
                                var player2 = GetPlayer();
                                Placed = FUnit.Place(Party.F_CombatParty_0C, Party.F_CombatParty_10, Party.F_CombatParty_14, player2, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmNeglectEmptyPlayerLocation));
                            }

                            if (Placed != null)
                            {
                                Destroy();
                            }
                        }
                    }
                }
                else
                {
                    if ((FPosition & 15) <= 7)
                    {
                        Party = FCombat.FCombatData.FParties.GetParty((byte)(int)(((uint)FPosition) >> 4));
                    }
                    else
                    {
                        Party = null;
                    }

                    if (Party == null || Party.F_CombatParty_0C != -1)
                    {
                        var player = GetPlayer();
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(player).FGameOverStatus == TGameOverStatus.goLost)
                        {
                            FUnit.Place(FCombat.FCombatData.FX, FCombat.FCombatData.FY, FCombat.FCombatData.FL, 0, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                        }
                        else
                        {
                            var player2 = GetPlayer();
                            FUnit.Place(FCombat.FCombatData.FX, FCombat.FCombatData.FY, FCombat.FCombatData.FL, player2, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                        }

                        Destroy();
                    }
                    else
                    {
                        if (Party != null && (sbyte)Party.FPlayerIndex != FCombatPlayer)
                        {
                            var player = GetPlayer();
                            FUnit.Place(FCombat.FCombatData.FX, FCombat.FCombatData.FY, FCombat.FCombatData.FL, player, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
