        // Combat.pas:1525
        public override void DestroyObject()
        {
            TAbstractUnit U;
            if (GetHitPoints() != 0)
            {
                SetHitPoints(0);
            }

            FStatus = FStatus + TSet<TCombatObjectStatusElement>.Of(TCombatObjectStatusElement.csDestroyed);
            U = FUnit;
            if (U != null)
            {
                for (int I = U.GetAbilityCount() - 1; I >= 0; I--)
                {
                    if (FUnit.GetAbilityEnabled(I))
                    {
                        AoWE.AoWHSSet.FAbilityControl.GetAbility(I).CombatObjectDestroyed(this);
                    }
                }
            }

            if (FStatus.Contains(TCombatObjectStatusElement.csDestroyed))
            {
                ResetTargets();
                if (FUnit is TLeader)
                {
                    FCombat.FCombatData.FDefeatedLeaders.Add((byte)FCombatPlayer);
                }

                FCombat.ObjectDestroyed(this);
                if (FUnit != null)
                {
                    KillUnit();
                }
            }
        }

