        {
            if (FLogbook.FActions.Count >= FPosition)
            {
                FLogbook.FActions.GetCombatActions(FPosition - 1).ShowObject(this, A1, A2, A3, A4, A5, A6);
            }
            else
            {
                A1.Show(A2, A3, A4, A5, A6);
            }
        }

