        // Combat2.pas:826
        public override bool Play(TCombatViewer A1)
        {
            int HitFrame;
            int Duration;
            int EffectFrames;
            TCombatObject Target;
            if (A1.FDelay < 5)
            {
                HitFrame = A1.FDelay;
            }
            else
            {
                HitFrame = 5;
            }

            if (HitFrame == A1.FTime)
            {
                Execute(A1.FCombat);
                Target = A1.FCombat.FCombatData.FindID(FTargetID);
                if (FDamageDone != 0)
                {
                    if (!Target.FStatus.Contains(TCombatObjectStatusElement.csDestroyed))
                    {
                        Target.PlaySFX(2);
                    }
                    else
                    {
                        Target.PlaySFX(3);
                    }
                }
            }

            Duration = A1.FDelay * 2;
            if (FEffects.Value != TSet<TDamageType>.Of())
            {
                EffectFrames = AoWE.DamageEffectsAnimationFrames(FEffects.Value) + A1.FDelay;
                HitFrame = A1.FDelay * 3;
                if (EffectFrames > HitFrame)
                {
                    EffectFrames = HitFrame;
                }

                if (Duration < EffectFrames)
                {
                    Duration = EffectFrames;
                }
            }

            return Duration > A1.FTime;
        }

