        // Combat.pas:6446
        public virtual void Finalize()
        {
            int PlayerIndex;
            int ArmyIndex;
            int UnitIndex;
            TPlayer Player;
            bool Alive;
            TFinalizeMode Mode;
            TCombatData Data;
            TCombatData FinalData;
            TMapFieldMsg Msg = default;
            Assert((FStatus & TSet<TCombatStatusElement>.Of(TCombatStatusElement.cExecuting, TCombatStatusElement.cActivated)) == TSet<TCombatStatusElement>.Of(TCombatStatusElement.cExecuting), (AnsiString)"Combat Finalize Failure", "Combat.pas", 6523);
            for (int I = 0, last = FCombatData.FDefeatedLeaders.Count - 1; I <= last; I++)
            {
                Data = FCombatData;
                var item = Data.FDefeatedLeaders[I];
                var players = Data.FPlayers.GetPlayers((sbyte)item);
                AoWE.AoWHSMap.GameOver(players.FPlayer, TGameOverStatus.goLost);
                FLogbook.F_CombatLogbook_19 = true;
            }

            FLogbook.SetFinalData(FCombatData);
            FStatus = FStatus - TSet<TCombatStatusElement>.Of(TCombatStatusElement.cExecuting);
            Data = FCombatData;
            for (int I = Data.GetCount() - 1; I >= 0; I--)
            {
                FCombatData.GetObjects(I).CombatDone();
            }

            for (int modeOrdinal = (int)TFinalizeMode.fmOriginal; modeOrdinal <= (int)TFinalizeMode.fmAll; modeOrdinal++)
            {
                Mode = (TFinalizeMode)modeOrdinal;
                for (int I = Data.GetCount() - 1; I >= 0; I--)
                {
                    FCombatData.GetObjects(I).Finalize(Mode);
                }
            }

            var combatResultText = GetCombatResultText();
            FLogbook.FFinalData.FHeader = combatResultText;
            FLogbook.FFinalData.F_CombatData_30 = (byte)(int)FCombatResult;
            PlayerIndex = FCombatData.FPlayers.Count;
            while (PlayerIndex != 0 && !FLogbook.F_CombatLogbook_19)
            {
                PlayerIndex -= 1;
                var players = FCombatData.FPlayers.GetPlayers((sbyte)PlayerIndex);
                Player = AoWE.AoWHSMap.FPlayers.GetPlayers(players.FPlayer);
                ArmyIndex = Player.FArmies.Count;
                Alive = false;
                while (ArmyIndex != 0 && !Alive)
                {
                    ArmyIndex -= 1;
                    UnitIndex = Player.FArmies.GetArmy(ArmyIndex).Count;
                    while (!Alive && UnitIndex != 0)
                    {
                        UnitIndex -= 1;
                        Alive = Player.FArmies.GetArmy(ArmyIndex).GetUnit(UnitIndex).GetHitPoints() != 0;
                    }
                }

                FLogbook.F_CombatLogbook_19 = !Alive;
            }

            FinalData = FCombatData;
            if (FinalData.FX != -1)
            {
                Msg.MsgID = 4368;
                Msg.Param[0] = this;
                Msg.Result = 0;
                AoWE.AoWHSMap.MapContainer.GetField(FinalData.FX, FinalData.FY, FinalData.FL).SendMapFieldMsg(ref Msg);
            }

            UnlockExecuted();
        }

