        public void AddAdjacentArmies()
        {
            TCombatData Data;
            TMapLevel Level;
            THNWalkData Walk = default;
            TArmyHS ArmyHS;
            TCombatSideIndex Side;
            Data = FCombatData;
            Level = AoWE.AoWHSMap.MapContainer.GetMapLevel(Data.FL);
            InitHNWalk(ref Walk, Data.FX, Data.FY, 0);
            while (Walk.Radius <= 1)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    ArmyHS = (TArmyHS)Level.GetField(Walk.X, Walk.Y).FindOwnedChild(131607);
                    if (ArmyHS != null)
                    {
                        if (Walk.HN != 0)
                        {
                            var players = Data.FPlayers.GetPlayers(Data.FDefenderPlayer);
                            var fPlayersPlayers = Data.FPlayers.GetPlayers(Data.FDefenderPlayer);
                            var players2 = Data.FPlayers.GetPlayers(Data.FAttackerPlayer);
                            Side = AoWE.GetCombatSide(Data.FPlayers.GetPlayers(Data.FAttackerPlayer).FPlayer, (sbyte)players2.FIndependentRelation, fPlayersPlayers.FPlayer, (sbyte)players.FIndependentRelation, ArmyHS.FArmy.FPlayer, ArmyHS.FArmy.FIndependentRelation);
                        }
                        else
                        {
                            Side = TCombatSideIndex.csDefender;
                        }

                        if (Side != TCombatSideIndex.csNeutral)
                        {
                            AddArmy(ArmyHS.FArmy, Side, Walk.X, Walk.Y, Data.FL);
                        }
                    }
                    else
                    {
                        if (Walk.HN == 0)
                        {
                            var players = Data.FPlayers.GetPlayers(Data.FDefenderPlayer);
                            AddEmptyArmy((byte)Data.FPlayers.GetPlayers(Data.FDefenderPlayer).FPlayer, players.FIndependentRelation, Walk.X, Walk.Y, Data.FL);
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }
        }

