        // Combat2.pas:474
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool ShowCombat = default;
            TCombatData Data = default;
            bool Result = false;
            switch (Trigger)
            {
                case TExecuteTrigger.etUser:
                    AoWE.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                    Result = true;
                    break;
                case TExecuteTrigger.etEvent:
                case TExecuteTrigger.etNewTurn:
                    if (FLogbook.FInitialData.FPlayers.IndexOfPlayer((byte)AoWE.AoWHSMap.FSeatedPlayer) != -1)
                    {
                        Data = FLogbook.FInitialData;
                        ShowCombat = Data.FPlayers.GetPlayers(Data.FAttackerPlayer).FPlayer == AoWE.AoWHSMap.FSeatedPlayer;
                        ShowCombat = ShowCombat || AoWE.AoWHSMap.FRequestCombatType && AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcEmail && FLogbook.FInitialData.FPlayers.GetPlayers(FLogbook.FInitialData.FDefenderPlayer).FPlayer == AoWE.AoWHSMap.FSeatedPlayer;
                        ShowCombat = ShowCombat || Trigger == TExecuteTrigger.etEvent && AoWE.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWE.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpCombat);
                        ShowCombat = ShowCombat || Trigger == TExecuteTrigger.etEvent && AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWE.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpCombat);
                        ShowCombat = ShowCombat && FLogbook.FCombatResult != TCombatResult.crNoDefenders;
                    }
                    else
                    {
                        ShowCombat = false;
                    }

                    ShowCombat = ShowCombat || FLogbook.F_CombatLogbook_19;
                    if (ShowCombat)
                    {
                        AoWE.AoWHSMap.TriggerExecuteEventLog(this, false, Done);
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                    }

                    break;
            }

            return Result;
        }

