    // cycles, players, current player, player cycles, status, token done, time mode, time, used
    // time, start, token cycles, token cycle, lock count
    public partial class TAIExecuter : TEObject
    {

        // AI.pas:559
        public TAIExecuter(TECustomNode owner) : base(owner)
        {
            FPlayers = new TByteList();
            FPlayer = -1;
            FProcessTimeMode = TProcessTimeMode.ptmStatic;
            FProcessTime = 5000;
            FTokenCycles = 5;
        }

        public int FProcessCycles;
        public TByteList FPlayers;
        public sbyte FPlayer;
        public int FPlayerProcessCycles;
        public TSet<TAIExecuterStatusElement> FStatus;
        public bool FTokenControlDone;
        public TProcessTimeMode FProcessTimeMode;
        public int FProcessTime;
        public int FProcessTimeUsed;
        public int FProcessStarted;
        public int FTokenCycles;
        public int FTokenCycle;
        public int FLockCount;
        // AI.pas:569
        public override void Destroy()
        {
            FPlayers.Free();
            base.Destroy();
        }

        // AI.pas:575
        public bool RequestProcessTime(int Time)
        {
            bool Result;
            int Used;
            switch (FProcessTimeMode)
            {
                case TProcessTimeMode.ptmStatic:
                    Used = FProcessTimeUsed;
                    if (Used != 0)
                    {
                        Result = Time <= FProcessTime - Used;
                    }
                    else
                    {
                        Result = true;
                    }

                    break;
                case TProcessTimeMode.ptmDynamic:
                    if (FProcessTimeUsed != 0)
                    {
                        Result = Time < GetProcessTimeLeft();
                    }
                    else
                    {
                        Result = true;
                    }

                    break;
                default:
                    Result = false;
                    break;
            }

            return Result;
        }

        // AI.pas:593
        public int GetProcessTimeLeft()
        {
            int Result;
            switch (FProcessTimeMode)
            {
                case TProcessTimeMode.ptmStatic:
                    Result = FProcessTime - FProcessTimeUsed;
                    break;
                case TProcessTimeMode.ptmDynamic:
                    // { Original behavior: the millisecond delta is multiplied by 1000. }
                    var elapsedMilliSeconds = GetElapsedMilliSeconds();
                    Result = FProcessTime - (elapsedMilliSeconds - FProcessStarted) * 1000;
                    break;
                default:
                    Result = -1;
                    break;
            }

            return Result;
        }

        // AI.pas:603
        public int GetProcessTimeElapsed()
        {
            int Result;
            switch (FProcessTimeMode)
            {
                case TProcessTimeMode.ptmStatic:
                    Result = FProcessTimeUsed;
                    break;
                case TProcessTimeMode.ptmDynamic:
                    Result = (GetElapsedMilliSeconds() - FProcessStarted) * 1000;
                    break;
                default:
                    Result = -1;
                    break;
            }

            return Result;
        }

        // AI.pas:617
        public bool ActivatePlayer(sbyte Player)
        {
            bool Result;
            if (FPlayers.IndexOf((byte)Player) == -1)
            {
                FPlayers.Add((byte)Player);
                FStatus = FStatus + TSet<TAIExecuterStatusElement>.Of(TAIExecuterStatusElement.aesEnabled);
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FAIControl.Activate(this);
                if (FPlayer == -1)
                {
                    FPlayer = Player;
                }

                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AI.pas:630
        public void DeactivatePlayer(sbyte Player)
        {
            if (FPlayers.IndexOf((byte)Player) != -1)
            {
                FPlayers.Remove((byte)Player);
                AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FAIControl.Deactivate();
                if (FPlayers.Count == 0)
                {
                    FPlayer = -1;
                    FStatus = FStatus - TSet<TAIExecuterStatusElement>.Of(TAIExecuterStatusElement.aesEnabled);
                }
            }
        }

        // AI.pas:644
        public void TokenControlDoneEvent(TObject Sender)
        {
            if (FStatus.Contains(TAIExecuterStatusElement.aesEnabled) && AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous)
            {
                FTokenControlDone = true;
                if (AoWE.AoWHSMap.FCurrentPlayer == 0 && AoWE.AoWHSMap.FCombatMap == null)
                {
                    CaptureTokenCycles(5);
                }
            }
        }

        // AI.pas:654
        public void Lock()
        {
            FLockCount += 1;
        }

        // AI.pas:659
        public void Unlock()
        {
            Assert(FLockCount != 0, (AnsiString)"", "AI.pas", 931);
            FLockCount -= 1;
        }

        // AI.pas:935
        public void CaptureTokenCycles(int Cycles)
        {
            Assert(!FStatus.Contains(TAIExecuterStatusElement.aesTokenLocked), (AnsiString)"", "AI.pas", 937);
            FStatus = FStatus + TSet<TAIExecuterStatusElement>.Of(TAIExecuterStatusElement.aesTokenLocked);
            AoWE.AoWHSMap.FTokenManager.TokenExecuter.Lock();
            FTokenCycle = 0;
            FTokenCycles = Cycles;
        }

        // AI.pas:944
        public void TokenCyclesCaptured()
        {
            Assert(FStatus.Contains(TAIExecuterStatusElement.aesTokenLocked), (AnsiString)"", "AI.pas", 947);
            FStatus = FStatus - TSet<TAIExecuterStatusElement>.Of(TAIExecuterStatusElement.aesTokenLocked);
            AoWE.AoWHSMap.FTokenManager.TokenExecuter.Unlock();
        }

        // AI.pas:952
        public void Process()
        {
            bool Done;
            int I;
            int Index;
            if (FStatus.Contains(TAIExecuterStatusElement.aesEnabled) && FLockCount == 0)
            {
                FStatus = FStatus + TSet<TAIExecuterStatusElement>.Of(TAIExecuterStatusElement.aesExecuting);
                AoWE.AoWHSMap.SynchroniseBegin();
                FProcessTimeUsed = 0;
                if (FProcessTimeMode == TProcessTimeMode.ptmDynamic)
                {
                    FProcessStarted = GetElapsedMilliSeconds();
                }
                else
                {
                    FProcessStarted = 0;
                }

                try
                {
                    switch (AoWE.AoWHSMap.FPlayMode)
                    {
                        case TPlayMode.pmTurn:
                            if (!AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).GetBusy() && AoWE.AoWHSMap.FTokenManager.PlayerReady(FPlayer))
                            {
                                FProcessCycles += 1;
                                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIControl.Process(this, FTokenControlDone);
                                FTokenControlDone = false;
                            }

                            break;
                        case TPlayMode.pmSimultaneous:
                            if (FStatus.Contains(TAIExecuterStatusElement.aesTokenLocked))
                            {
                                FProcessCycles += 1;
                                Done = false;
                                I = 0;
                                while (!Done && GetProcessTimeLeft() > 0 && FStatus.Contains(TAIExecuterStatusElement.aesEnabled) && I < FPlayers.Count)
                                {
                                    Done = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIControl.Process(this, FTokenControlDone);
                                    if (Done)
                                    {
                                        FPlayerProcessCycles += 1;
                                        I = 0;
                                    }
                                    else
                                    {
                                        I += 1;
                                    }

                                    FTokenControlDone = false;
                                    if (!Done || AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FAIControl.GetProcessCyclesMax() <= FPlayerProcessCycles)
                                    {
                                        Index = FPlayers.IndexOf((byte)FPlayer);
                                        Index += 1;
                                        FPlayerProcessCycles = 0;
                                        // { Original behavior: Index = Count is not wrapped here. }
                                        if (Index > FPlayers.Count)
                                        {
                                            Index = 0;
                                        }

                                        FPlayer = (sbyte)FPlayers[Index];
                                    }
                                }

                                FTokenCycle += 1;
                                if (I >= FPlayers.Count || FTokenCycle >= FTokenCycles)
                                {
                                    TokenCyclesCaptured();
                                }
                            }

                            break;
                    }
                }
                catch (System.Exception)
                {
                    ShowMessage((AnsiString)"AI ERROR");
                }

                AoWE.AoWHSMap.SynchroniseEnd();
                FStatus = FStatus - TSet<TAIExecuterStatusElement>.Of(TAIExecuterStatusElement.aesExecuting);
            }
        }

        // intf_P5_06.inc:108

    }

