                    }

                    break;
                case 1:
                    FPathSettings.FMovePointsMax = FSettings.FMovePointsMax;
                    var canMove = AoWE.AoWHSMap.FMoveControl.CanMove(FPathSettings, TSet<TCanMoveModeElement>.Of(TCanMoveModeElement.mmExact));
