        public void SelectCombinedTransporterArmyMpT()
        {
            sbyte Points;
            for (int Terrain = 0; Terrain <= 15; Terrain++)
            {
                for (int Overlay = -1; Overlay <= 11; Overlay++)
                {
                    Points = FMovePointTable[Terrain][Overlay - -1];
                    if (Points == -1)
                    {
                        Points = FTransportMovePointTable[Terrain][Overlay - -1];
                        if (Points != -1)
                        {
                            Points = 8;
                        }
                    }

                    FPathSettings.FMovePointTable[Terrain][Overlay - -1] = Points;
                }
            }
        }

        // AIGroup.pas:3993
        public bool CalculateTransportGaps(TMovepath Path, FixedArray_Aow_Units_FixedArray_sbyte_16_16 Table)
        {
            bool Result;
            int I;
            int FirstGap;
            int LastGap;
            int Gaps;
            bool InGap;
            TAoWMapField MapF;
            Gaps = 0;
            FirstGap = -1;
            LastGap = -1;
            I = Path.Count - 1;
            InGap = false;
            while (I > 1)
            {
                I -= 1;
                var item = Path[I];
                var pathItem = Path[I];
                var item2 = Path[I];
                MapF = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(item2.X, pathItem.Y, item.L);
                if (Table[MapF.TerrainType][MapF.OverlayType - -1] == -1)
                {
                    if (!InGap)
                    {
                        if (FirstGap == -1)
                        {
                            FirstGap = I;
                        }

                        Gaps += 1;
                        InGap = true;
                    }
                }
                else
                {
                    if (InGap)
                    {
                        LastGap = I + 1;
                        InGap = false;
                    }
                }
            }

            if (InGap)
            {
                LastGap = 1;
            }

            if (Gaps != 0)
            {
                var item = Path[FirstGap + 1];
                FSettings.FBoardingPoint = item;
                var pathItem = Path[FirstGap];
                FSettings.FTransportSource = pathItem;
                var item2 = Path[LastGap - 1];
                FSettings.FArrivalPoint = item2;
                var item3 = Path[LastGap];
                FSettings.FTransportDestination = item3;
                Result = true;
                FMultipleTransportGaps = Gaps > 1;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AIGroup.pas:4037
        public void ProcessTransporterCanMove()
        {
            int Points;
            TXYL Location = default;
            switch (FState)
            {
                case 0:
                    FPathSettings.FMovePointTable = FMovePointTable;
                    FPathSettings.FMovePointsMax = FSettings.FQuickMovePointsMax;
                    Points = AoWE.AoWHSMap.FMoveControl.CanMove(FPathSettings, TSet<TCanMoveModeElement>.Of(TCanMoveModeElement.mmFast));
                    FSettings.FMovePoints = Points;
                    if (Points == -1)
                    {
                        FState += 1;
                        if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 6)
                        {
                            ProcessTransporterCanMove();
                        }
                    }
                    else
                    {
                        ProcessingDone(TAIMoveControlStatus.amsDone);
                    }

                    break;
                case 1:
                    SelectCombinedTransporterArmyMpT();
                    FPathSettings.FMovePointsMax = FSettings.FMovePointsMax;
                    FPathSettings.FMode = FSettings.FMoveMode + TSet<TMoveModeElement>.Of(TMoveModeElement.mmAvoidArmies);
                    AoWE.AoWHSMap.FMoveControl.ProcessMove(FPathSettings);
                    if (FPathSettings.FPath.Count != 0)
                    {
                        var item = FPathSettings.FPath[0];
                        var fPathItem = FPathSettings.FPath[0];
                        var item2 = FPathSettings.FPath[0];
                        var movePoints = FPathSettings.GetMovePoints(item2.X, fPathItem.Y, item.L);
                        FSettings.FMovePoints = movePoints;
                        FSettings.FTransportPath.Assign(FPathSettings.FPath);
                        if (CalculateTransportGaps(FPathSettings.FPath, FMovePointTable))
                        {
                            FState = 2;
                            FPathSettings.FMovePointTable = FTransportMovePointTable;
                            FSettings.FTransporter.GetLocation(ref Location.X, ref Location.Y, ref Location.L);
                            FPathSettings.SetSourcePos(Location.X, Location.Y, Location.L);
                            ref var location = ref FSettings.FTransportSource;
                            FPathSettings.SetDestinationPos(location.X, location.Y, location.L);

                            if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 1)
                            {
                                ProcessTransporterCanMove();
                            }
                        }
                        else
                        {
                            ProcessingDone(TAIMoveControlStatus.amsDone);
                        }
                    }
                    else
                    {
                        ProcessingDone(TAIMoveControlStatus.amsDone);
                    }

                    break;
                case 2:
                    FPathSettings.FMovePointsMax = FSettings.FQuickMovePointsMax;
                    Points = AoWE.AoWHSMap.FMoveControl.CanMove(FPathSettings, TSet<TCanMoveModeElement>.Of(TCanMoveModeElement.mmFast));
                    if (Points == -1)
                    {
                        FState = 3;
                        if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 6)
                        {
                            ProcessTransporterCanMove();
                        }
                    }
                    else
                    {
                        FSettings.FMovePoints += Points;
                        if (FMultipleTransportGaps)
                        {
                            // { Original repeats the first gap source before continuing. }
                            ref var location2 = ref FSettings.FTransportSource;
                            FPathSettings.SetDestinationPos(location2.X, location2.Y, location2.L);

                            FMultipleTransportGaps = false;
                            if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 1)
                            {
                                ProcessTransporterCanMove();
                            }
                        }
                        else
                        {
                            ProcessingDone(TAIMoveControlStatus.amsDone);
                        }
                    }

                    break;
                case 3:
                    FPathSettings.FMovePointTable = FTransportMovePointTable;
                    FPathSettings.FMovePointsMax = FSettings.FMovePointsMax;
                    Points = AoWE.AoWHSMap.FMoveControl.CanMove(FPathSettings, TSet<TCanMoveModeElement>.Of(TCanMoveModeElement.mmExact));
                    if (Points == -1)
                    {
                        FSettings.FMovePoints = -1;
                        ProcessingDone(TAIMoveControlStatus.amsDone);
                    }
                    else
                    {
                        FSettings.FMovePoints += Points;
                        if (FMultipleTransportGaps)
                        {
                            ref var location3 = ref FSettings.FTransportDestination;
                            FPathSettings.SetDestinationPos(location3.X, location3.Y, location3.L);

                            FMultipleTransportGaps = false;
                            FState = 2;
                            if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 1)
                            {
                                ProcessTransporterCanMove();
                            }
                        }
                        else
                        {
                            ProcessingDone(TAIMoveControlStatus.amsDone);
                        }
                    }

                    break;
            }
        }

        // AIGroup.pas:4128
        public void Initialize(TAIMoveControlSettings Settings)
        {
            TAIMoveControlSettings OldSettings;
            TAbstractUnit Transporter;
            OldSettings = FSettings;
            if (OldSettings != null)
            {
                OldSettings.Release();
            }

            FSettings = Settings;
            if (FSettings != null)
            {
                FSettings.AddRef();
                FSettings.FMovePoints = -1;
                FSettings.FTransportSource.X = -1;
                FSettings.FTransportDestination.X = -1;
                FSettings.FBoardingPoint.X = -1;
                FSettings.FArrivalPoint.X = -1;
                FSettings.FStatus = TAIMoveControlStatus.amsProcessing;
                FMovePointTable = FSettings.FMovePointTable;
                Transporter = FSettings.FTransporter;
                if (Transporter != null)
                {
                    var moveTypesToInt = AoWE.MoveTypesToInt(Transporter.GetMoveTypes());
                    FTransportMovePointTable = AoWE.MovePointTables[moveTypesToInt];
                }
            }
        }

        // AIGroup.pas:4152
        public bool CanMove(TAIMoveControlSettings Settings)
        {
            bool Result;
            Reset();
            Initialize(Settings);
            FStatus = TAIMoveControlStatus.amsProcessing;
            FPathSettings.Reset();
            FPathSettings.SetSourcePos(this.FSettings.FSourceX, this.FSettings.FSourceY, this.FSettings.FSourceL);

            FPathSettings.FPlayer = FSettings.FPlayer;
            FPathSettings.SetDestinationPos(FSettings.FDestinationX, FSettings.FDestinationY, FSettings.FDestinationL);
            FPathSettings.FMovePointsMax = FSettings.FMovePointsMax;
            FPathSettings.FArmyHS = FSettings.FArmyHS;
            FPathSettings.FSelection = FSettings.FSelection;
            FPathSettings.FMode = FSettings.FMoveMode;
            if (FSettings.FTransporter == null)
            {
                FMode = TAIMoveControlMode.mcsCanMove;
                FPathSettings.FMovePointTable = FMovePointTable;
                if (FSettings.FSourceL == FSettings.FDestinationL)
                {
                    FState = 0;
                    if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 1)
                    {
                        ProcessCanMove();
                    }
                }
                else
                {
                    FState = 1;
                }

                Result = true;
            }
            else
            {
                FMode = TAIMoveControlMode.mcsTransporterCanMove;
                var armyHS = ((TArmy)FSettings.FTransporter.FOwner).GetArmyHS();
                FPathSettings.FTransporterArmy = armyHS;
                if (FSettings.FSourceL == FSettings.FDestinationL)
                {
                    FState = 0;
                    if (AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 1)
                    {
                        ProcessTransporterCanMove();
                    }
                }
                else
                {
                    FState = 1;
                }

                Result = true;
            }

            return Result;
        }

        // AIGroup.pas:4191
        public void Cancel()
        {
            if (FStatus == TAIMoveControlStatus.amsProcessing)
            {
                ProcessingDone(TAIMoveControlStatus.amsCanceled);
            }
        }

        // AIGroup.pas:4196
        public void Reset()
        {
            Cancel();
            Clear();
        }

        // AIGroup.pas:4202
        public bool Process()
        {
            if (FStatus == TAIMoveControlStatus.amsProcessing)
            {
                FProcessCycles += 1;
                switch (FMode)
                {
                    case TAIMoveControlMode.mcsCanMove:
                        ProcessCanMove();
                        break;
                    case TAIMoveControlMode.mcsTransporterCanMove:
                        ProcessTransporterCanMove();
                        break;
                }
            }

            return FStatus == TAIMoveControlStatus.amsProcessing;
        }

