                Settings.FMovePointsMax = Army.MovePoints(255);
                Settings.SetupArmy(ArmyHS, ArmySelection);
                AoWE.AoWHSMap.FMoveControl.ProcessMove(Settings);
                Level = AoWE.AoWHSMap.MapContainer.GetMapLevel(L);
                Candidates = new TDoubleItemList();
                InitHNWalk(ref Walk, X, Y, 1);
                while (Walk.Radius <= 1)
                {
                    if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                    {
                        Points = Settings.GetMovePoints(Walk.X, Walk.Y, L);
                        MapF = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(Walk.X, Walk.Y, L);
                        if (Points != 16777215 && (MapF.GetPlayer() == -1 || MapF.GetPlayer() == Army.FPlayer))
                        {
                            if (CanMoveTo(Army, Selection, (sbyte)Walk.X, (sbyte)Walk.Y, L) == Selection)
                            {
                                Candidates.AddAB(Unsafe.BitCast<TXYL, int>(PackXYL((sbyte)Walk.X, (sbyte)Walk.Y, L)), Points);
                            }
                        }
                    }

                    WalkToNextHN(ref Walk);
                }

                if (Candidates.Count != 0)
                {
                    Candidates.SortAscendingItemB();
                    var item = Candidates[0];
                    X = Unsafe.As<int, TXYL>(ref item.A).X;
                    var candidatesItem = Candidates[0];
                    Y = Unsafe.As<int, TXYL>(ref candidatesItem.A).Y;
                    var item2 = Candidates[0];
                    L = Unsafe.As<int, TXYL>(ref item2.A).L;
                    AoWE.AoWHSMap.FMoveControl.CalculatePath(Settings, Settings.FPath, X, Y, L);
                }

                Candidates.Free();
            }
            else
            {
                Settings.FMovePointsMax = FExecuter.FMovePointsMax;
                Settings.SetupArmy(ArmyHS, ArmySelection);
                Settings.SetDestinationPos(X, Y, L);
                AoWE.AoWHSMap.FMoveControl.ProcessMove(Settings);
            }

            if (Settings.FPath.Count != 0)
            {
                Points = ArmyHS.FArmy.MovePoints(ArmySelection);
                Position = Settings.FPath.MovePointsToPos(Points);
                if (!Mode.Contains(TCreateMoveModeElement.cmmSurround) && Settings.FPath[Position].X == FExecuter.FDestination.X && Settings.FPath[Position].Y == FExecuter.FDestination.Y && Settings.FPath[Position].L == FExecuter.FDestination.L)
                {
                    Army.SetMoveResult(Selection, 2);
                }

                if (Position == 0)
                {
                    MoveResult = 2;
                }
                else
                {
                    MoveResult = 0;
                }

                if (Mode.Contains(TCreateMoveModeElement.cmmSurround) && Position == 0)
