            else
            {
                if (Army.FLocation.X == X && Army.FLocation.Y == Y && Army.FLocation.L == L)
                {
                    MoveResult = 2;
                }
                else
                {
                    MoveResult = 3;
                }

                if (FExecuter.FDestination.X == Settings.FSourceX && FExecuter.FDestination.Y == Settings.FSourceY && FExecuter.FDestination.L == Settings.FSourceL)
                {
                    Army.SetMoveResult(Selection, 2);
                    Army.SetStatus(Selection, TAIMoveExecuterUnitStatus.esDone);
                }
            }

            Settings.Release();
            return Move;
        }

        // AIGroup.pas:4854
        public virtual byte CanMoveTo(TAIMoveExecuterArmy Army, byte Selection, sbyte X, sbyte Y, sbyte L)
        {
            int TransporterCount;
            int UnitCount;
            int Capacity;
            int I;
            int Index;
            int Excess;
            TAbstractUnit AUnit;
            bool Allowed;
            TArmyHS ArmyHS;
            TAoWMapField MapF;
            TAIMoveExecuterMove Move;
            TArmy ExistingArmy;
            TAIMoveExecuterUnit Transporter;
            UnitCount = 0;
            TransporterCount = 0;
            Capacity = 8;
            Allowed = true;
            MapF = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L);
            ArmyHS = MapF.GetArmyHS();
            byte Result = 0;
            if (ArmyHS != null && ArmyHS.FArmy.FPlayer == Army.FPlayer)
            {
                ExistingArmy = ArmyHS.FArmy;
                I = 0;
                int last = ExistingArmy.Count - 1;
                for (; I <= last; I += 1)
                {
                    AUnit = ArmyHS.FArmy.GetUnit(I);
                    Index = FExecuter.FUnits.IndexOfUnitID(AUnit.FUnitID);
                    if (Index == -1 || FExecuter.FUnits.GetUnits(Index).FStatus != TAIMoveExecuterUnitStatus.esQueued)
                    {
                        UnitCount += 1;
                        if (AUnit.GetTransporter())
                        {
                            TransporterCount += 1;
                            if (AUnit.GetTransportCapacity() + 1 < Capacity)
                            {
                                Capacity = AUnit.GetTransportCapacity() + 1;
                            }
                        }
                    }
                }
            }
            else
            {
                if ((FExecuter.FDestination.X != X || FExecuter.FDestination.Y != Y || FExecuter.FDestination.L != L) && MapF.GetPlayer() != -1 && MapF.GetPlayer() != Army.FPlayer)
                {
                    Allowed = false;
                }
            }

            if (Allowed)
            {
                I = 0;
                int last = FExecuter.FMoves.Count - 1;
                for (; I <= last; I += 1)
                {
                    Move = FExecuter.FMoves.GetMoves(I);
                    if (Move.FPath[0].X == X && Move.FPath[0].Y == Y && Move.FPath[0].L == L)
                    {
                        UnitCount += Move.Count;
                        Transporter = Move.Transporter(255);
                        if (Transporter != null)
                        {
                            TransporterCount += 1;
                            if (Transporter.FUnit.GetTransportCapacity() + 1 < Capacity)
                            {
                                Capacity = Transporter.FUnit.GetTransportCapacity() + 1;
                            }
                        }
                    }
                }

                Transporter = Army.Transporter(Selection);
                if (Transporter == null || TransporterCount == 0)
                {
                    if (Transporter != null)
                    {
                        if (Transporter.FUnit.GetTransportCapacity() + 1 < Capacity)
                        {
                            Capacity = Transporter.FUnit.GetTransportCapacity() + 1;
                        }
                    }

                    Excess = Army.SelectionCount(Selection) + UnitCount - Capacity;
                    if (Excess > 0)
                    {
                        if (Transporter == null)
                        {
                            I = 8;
                            Selection = Army.ValidateSelection(Selection);
                            Result = Selection;
                            while (Excess != 0 && Result != 0)
                            {
                                I -= 1;
                                if ((Selection & 128) != 0)
                                {
                                    Result = (byte)(Result & ~(1 << I));
                                    Excess -= 1;
                                }

                                Selection = (byte)((Selection & 127) << 1);
                            }
                        }
                        else
                        {
                            Result = 0;
                        }
                    }
                    else
                    {
                        Result = Selection;
                    }
                }
                else
                {
                    Result = 0;
                }
            }

            if (!Allowed)
            {
                Result = 0;
            }

            return Result;
        }

        // AIGroup.pas:4952
        public virtual void CalculateMoves()
        {
            Done();
        }

        // AIGroup.pas:4942
        public virtual void Activate(TAIMoveExecuter Executer)
        {
            FExecuter = Executer;
            FState = 0;
        }

        // AIGroup.pas:4948
        public virtual void Deactivate()
        {
        }

        // AIGroup.pas:4957
        public virtual void Done()
        {
            FState = -1;
        }

        // AIGroup.pas:4962
        public virtual bool Process()
        {
            int TimeLeft;
            TimeLeft = 5;
            if (FMoveControl.FStatus == TAIMoveControlStatus.amsProcessing)
            {
                FMoveControl.Process();
            }

            while (FMoveControl.FStatus != TAIMoveControlStatus.amsProcessing && TimeLeft > 0 && FExecuter.FStatus == TAIMoveExecuterStatus.mesBusy && FExecuter.FState == 0 && FState != -1)
            {
                CalculateMoves();
                TimeLeft = AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft();
            }

            return FState != -1;
        }

    }

    // inherited move control, executer and state
    public partial class TDefaultMEC : TAIMoveExecuterControl
    {
        public TDefaultMEC(TECustomNode owner) : base(owner)
        {}

        // AIGroup.pas:4978
        public override void CalculateMoves()
        {
            int I;
            TAIMoveExecuterArmyList Armies;
            TAIMoveExecuterMove Move;
            byte MoveResult = default;
            TSet<TCreateMoveModeElement> Mode;
            bool CannotMove;
            switch (FState)
            {
                case 0:
                    Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady));
                    if (Armies.Count != 0)
                    {
                        if (FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memAttack))
                        {
                            Mode = TSet<TCreateMoveModeElement>.Of(TCreateMoveModeElement.cmmSurround);
                        }
                        else
                        {
                            Mode = TSet<TCreateMoveModeElement>.Of();
                        }

                        Move = CreateMove(Armies.GetArmies(0), 255, FExecuter.FDestination.X, FExecuter.FDestination.Y, FExecuter.FDestination.L, Mode, ref MoveResult);
                        if (Move != null)
                        {
                            if (!FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memSimultaneous) || (FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memAttack) && MoveResult == 2))
                            {
                                FExecuter.ExecuteMoves();
                            }
                        }
                        else
                        {
                            Armies.GetArmies(0).SetStatus(255, TAIMoveExecuterUnitStatus.esDone);
                        }
                    }
                    else
                    {
                        if (FExecuter.FMoves.Count != 0)
                        {
                            FExecuter.ExecuteMoves();
                            if (FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memAttack))
                            {
                                FState = 1;
                            }
                            else
                            {
                                FState = 2;
                            }
                        }
                    }

                    if (FExecuter.FMoves.Count == 0 && Armies.Count == 0)
                    {
                        if (FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memAttack))
                        {
                            FState = 1;
                        }
                        else
                        {
                            Done();
                        }
                    }

                    Armies.Free();
                    break;
                case 1:
                    I = 0;
                    CannotMove = true;
                    Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady, TAIMoveExecuterUnitStatus.esDone));
                    while (CannotMove && I != Armies.Count)
                    {
                        Move = CreateMove(Armies.GetArmies(I), 255, FExecuter.FDestination.X, FExecuter.FDestination.Y, FExecuter.FDestination.L, TSet<TCreateMoveModeElement>.Of(TCreateMoveModeElement.cmmDontQueue, TCreateMoveModeElement.cmmSurround), ref MoveResult);
                        CannotMove = MoveResult != 0;
                        if (Move != null)
                        {
                            Move.Free();
                        }

                        I += 1;
                    }

                    if (CannotMove)
                    {
                        I = 0;
                        Move = null;
                        while (Move == null && I != Armies.Count)
                        {
                            Move = CreateMove(Armies.GetArmies(I), 255, FExecuter.FDestination.X, FExecuter.FDestination.Y, FExecuter.FDestination.L, TSet<TCreateMoveModeElement>.Of(), ref MoveResult);
                            if (Move != null)
                            {
                                FExecuter.ExecuteMoves();
                            }

                            I += 1;
                        }
                    }

                    Armies.Free();
                    Done();
                    break;
                case 2:
                    Done();
                    break;
            }
        }
    }

