        // AIGroup.pas:5129
        public bool ExecuteSurroundMove()
        {
            int I;
            int Index;
            TAIMoveExecuterArmyList Armies;
            TDoubleItemList Sorted;
            TAIMoveExecuterArmy Army;
            byte MoveResult = default;
            bool Result = true;
            Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady, TAIMoveExecuterUnitStatus.esDone));
            Sorted = new TDoubleItemList();
            I = 0;
            int last = FAdjacentArmies.Count - 1;
            for (; I <= last; I += 1)
            {
                var movementDays = FAdjacentArmies.GetAdjacentArmies(I).GetMovementDays();
                Sorted.AddAB(ObjectToInt(FAdjacentArmies.GetAdjacentArmies(I)), Round((double)movementDays * 100));
            }

            Sorted.SortDescendingItemB();
            _ = ReferenceFromId<TAdjacentArmy>(Sorted[0].A).FPath[1];
            I = 0;
            while (Result && I < Sorted.Count)
            {
                Index = Armies.IndexOfLoc(ReferenceFromId<TAdjacentArmy>(Sorted[I].A).FLocation);
                if (Index != -1)
                {
                    Army = Armies.GetArmies(Index);
                    if (Army.FLocation.L == FExecuter.FDestination.L && dHXtoRad(Army.FLocation.X, Army.FLocation.Y, FExecuter.FDestination.X, FExecuter.FDestination.Y) > 1)
                    {
                        CreateMove(Army, 255, FExecuter.FDestination.X, FExecuter.FDestination.Y, FExecuter.FDestination.L, TSet<TCreateMoveModeElement>.Of(TCreateMoveModeElement.cmmSurroundEx), ref MoveResult);
                        Result = MoveResult != 0 && MoveResult != 3;
                    }
                }

                I += 1;
            }

            if (FExecuter.FMoves.Count != 0)
            {
                if (Result)
                {
                    FExecuter.ExecuteMoves();
                }
                else
                {
                    FExecuter.FMoves.Reset();
                }
            }

            Sorted.Free();
            Armies.Free();
            return Result;
        }

        // AIGroup.pas:5170
        public int CalculateMeetingPoint()
        {
            int I;
            int Points;
            int Reserve;
            int Index;
            int Position;
            TAIMoveExecuterArmyList Armies;
            TAdjacentArmy Adjacent;
            TAIMoveExecuterArmy Army;
            Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady, TAIMoveExecuterUnitStatus.esDone));
            int Result = 16777215;
            I = FAdjacentArmies.GetSlowestArmy();
            if (I != -1)
            {
                if ((double)FAdjacentArmies.GetAdjacentArmies(I).GetMovementDays() > 1 || !FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memAttack))
                {
                    Points = FAdjacentArmies.GetAdjacentArmies(I).FMovePoints;
                    if (FExecuter.FMode.Contains(TAIMoveExecuterModeElement.memAttack))
                    {
                        Reserve = Round((double)Points * 0.75);
                        if (Reserve > FAdjacentArmies.GetAdjacentArmies(I).FPath.GetMovePoints() - Points)
                        {
                            Points = FAdjacentArmies.GetAdjacentArmies(I).FPath.GetMovePoints() - Reserve;
                        }
                    }

                    Adjacent = FAdjacentArmies.GetAdjacentArmies(I);
                    Index = Armies.IndexOfLoc(FAdjacentArmies.GetAdjacentArmies(I).FLocation);
                    if (Index != -1)
                    {
                        Army = Armies.GetArmies(Index);
                        Position = Adjacent.FPath.MovePointsToPos(Points);
                        while (true)
                        {
                            bool condition = Position > 1;
                            if (condition)
                            {
                                var item = Adjacent.FPath[Position];
                                var fPathItem = Adjacent.FPath[Position];
                                condition = CanMoveTo(Army, 255, Adjacent.FPath[Position].X, item.Y, fPathItem.L) != 255;
                            }

                            if (!condition)
                                break;
                            Position -= 1;
                        }

                        Result = Unsafe.BitCast<TXYL, int>(FAdjacentArmies.GetAdjacentArmies(I).FPath[Position]);
                    }
                }
            }

            Armies.Free();
            return Result;
        }

        // AIGroup.pas:5206
        public bool ExecuteMeetingPointMove()
        {
            int Index;
            TAIMoveExecuterArmyList Armies;
            TDoubleItemList Sorted;
            byte MoveResult = default;
            TXYL Location = default;
            bool Result = true;
            Unsafe.As<TXYL, int>(ref Location) = CalculateMeetingPoint();
            if (Unsafe.As<TXYL, int>(ref Location) == 16777215)
            {
                ref var location = ref FExecuter.FDestination;
                Location = PackXYL(location.X, location.Y, location.L);
            }

            Armies = FExecuter.CreateArmies(TSet<TAIMoveExecuterUnitStatus>.Of(TAIMoveExecuterUnitStatus.esReady));
            Sorted = new TDoubleItemList();
            for (int I = 0, last = FAdjacentArmies.Count - 1; I <= last; I++)
            {
                var movementDays = FAdjacentArmies.GetAdjacentArmies(I).GetMovementDays();
                Sorted.AddAB(ObjectToInt(FAdjacentArmies.GetAdjacentArmies(I)), Round((double)movementDays * 100));
            }

            Sorted.SortDescendingItemB();
            for (int I = 0, last = Sorted.Count - 1; I <= last; I++)
            {
                Index = Armies.IndexOfLoc(ReferenceFromId<TAdjacentArmy>(Sorted[I].A).FLocation);
                if (Index != -1)
                {
                    CreateMove(Armies.GetArmies(Index), 255, Location.X, Location.Y, Location.L, TSet<TCreateMoveModeElement>.Of(), ref MoveResult);
                    if (MoveResult == 0)
                    {
                        Result = false;
                    }
                }
            }

            if (FExecuter.FMoves.Count != 0)
            {
                FExecuter.ExecuteMoves();
            }

            Sorted.Free();
            Armies.Free();
            return Result;
        }

