    // group cycles, group control
    public partial class TGroupControlLoopAIPA : TAIPlayerAction, IAIPlayerActionClass
    {
        // AI.pas:1119
        public TGroupControlLoopAIPA(TECustomNode owner) : base(owner)
        {
        }

        public int FGroupProcessCycles;
        public TAIGroupControl FGroupControl;
        // AI.pas:1124
        public override void Destroy()
        {
            DeactivateGroupControl();
            base.Destroy();
        }

        // AI.pas:1156
        public override bool Activate()
        {
            bool Result = base.Activate();
            var player = FControl.FPlayer;
            for (int I = player.FAIGroups.Count - 1; I >= 0; I--)
            {
                var groups = player.FAIGroups.GetGroups(I);
                player.FAIGroups.GetGroups(I).FStatus = groups.FStatus - TSet<TAIGroupStatusElement>.Of(TAIGroupStatusElement.agsDone);
            }

            return Result;
        }

        // AI.pas:1166
        public override bool Process()
        {
            bool Result;
            bool Busy;
            bool Done;
            int I;
            TAIGroupControl Control;
            FGroupProcessCycles += 1;
            try
            {
                Busy = false;
                Done = false;
                while (!Done && !Busy && AoWE.AoWHSMap.FAIExecuter.GetProcessTimeLeft() > 0)
                {
                    if (FGroupControl == null)
                    {
                        FControl.FPlayer.FAIGroups.SortOnProcessPriority();
                        I = 0;
                        while (I < FControl.FPlayer.FAIGroups.Count && FControl.FPlayer.FAIGroups.GetGroups(I).FStatus.Contains(TAIGroupStatusElement.agsDone))
                        {
                            I += 1;
                        }

                        if (I < FControl.FPlayer.FAIGroups.Count)
                        {
                            ActivateGroupControl(FControl.FPlayer.FAIGroups.GetGroups(I));
                        }
                        else
                        {
                            Done = true;
                        }
                    }

                    Control = FGroupControl;
                    if (Control != null)
                    {
                        Busy = Control.Process(true);
                        if (!Busy)
                        {
                            DeactivateGroupControl();
                        }
                    }
                    else
                    {
                        Done = true;
                    }
                }

                Result = !Done;
            }
            catch (System.Exception)
            {
                Result = false;
            }

            return Result;
        }

