        public void ActivateGroupControl(TAIGroup Group)
        {
            DeactivateGroupControl();
            FGroupControl = Group.CreateGroupControl();
            FGroupControl.Activate();
        }

        // AI.pas:1143
        public void DeactivateGroupControl()
        {
            TAIGroupControl Control;
            Control = FGroupControl;
            if (Control != null)
            {
                Control.Deactivate();
                FGroupControl.Free();
                FGroupControl = null;
            }
        }

