            if (GoldUpkeep < 0)
            {
                GoldUpkeep = 0;
            }

            return RequestBudgetExpense(Gold, Mana, Budget, UsePool) && (GoldUpkeep == 0 || GoldUpkeep <= FGoldUpkeep) && (ManaUpkeep == 0 || ManaUpkeep <= FManaUpkeep);
        }

        // AI.pas:2124
        public bool BudgetExpenseMadeEx(int Gold, int Mana, int GoldUpkeep, int ManaUpkeep, TAIBudget Budget, TBudgetExpenseMode Mode)
        {
            bool Result;
            if (RequestBudgetExpenseEx(Gold, Mana, GoldUpkeep, ManaUpkeep, Budget, Mode != TBudgetExpenseMode.bemBudget))
            {
                if (Gold < 0)
                {
                    Gold = 0;
                }

                if (Mana < 0)
                {
                    Mana = 0;
                }

                if (ManaUpkeep < 0)
                {
                    ManaUpkeep = 0;
                }

                if (GoldUpkeep < 0)
                {
                    GoldUpkeep = 0;
                }

                Result = BudgetExpenseMade(Gold, Mana, Budget, Mode);
                FGoldUpkeep -= GoldUpkeep;
                FManaUpkeep -= ManaUpkeep;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AI.pas:2139
        public bool RequestExpense(int Gold, int Mana) => Gold >= 0 && Mana >= 0 && Gold <= FGold && Mana <= FMana;

        // AI.pas:2144
        public bool ExpenseMade(int Gold, int Mana)
        {
            bool Result;
            if (RequestExpense(Gold, Mana))
            {
                if (Gold < 0)
                {
                    Gold = 0;
                }

                if (Mana < 0)
                {
                    Mana = 0;
                }

                FGold -= Gold;
                FMana -= Mana;
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AI.pas:2157
        public bool ReturnExpense(int Gold, int Mana)
        {
            if (Gold < 0)
            {
                Gold = 0;
            }

            if (Mana < 0)
            {
                Mana = 0;
            }

            FGold += Gold;
            FMana += Mana;
            return true;
        }

        // intf_P5_06.inc:593

    }

