        public override bool Process()
        {
            bool Done;
            TEventLog Log;
            Done = false;
            while (!FControl.FPlayer.GetBusy() && !Done)
            {
                if (FLogIndex == -1)
                {
                    FLogIndex = FControl.FPlayer.FEventLogbook.FindFirstLogEx(131811, FControl.FPlayer.FPlayerIndex, AoWE.AoWHSMap.FDay - 1) + 1;
                }
                else
                {
                    FLogIndex += 1;
                }

                var count = FControl.FPlayer.FEventLogbook.GetCount();
                if (FLogIndex < count)
                {
                    Log = FControl.FPlayer.FEventLogbook.GetLogs(FLogIndex);
                    if (Log is THeroEmergeEventLog)
                    {
                        ((THeroEmergeEventLog)Log).ExecuteAI();
                    }
                    else
                    {
                        if (Log is TDiplomaticActionEventLog)
                        {
                            ((TDiplomaticActionEventLog)Log).FAction.ExecuteAI(FControl.FPlayer.FPlayerIndex);
                        }
                    }
                }
                else
                {
                    Done = true;
                }
            }

            return !Done;
        }

