            {
                var xyl = MapF.GetXYL();
                FDefenseLocation.XYL = xyl;
            }
        }

        // AIGroup.pas:1728
        public bool Execute(TAIGroup Group, sbyte X, sbyte Y, sbyte L, TUnitList Units)
        {
            bool Result = default;
            TUnitUserList Candidates = default;
            int Start = default;
            int I = default;
            TMapLevel Level = default;
            TAbstractUnit AUnit = default;
            TAoWMapField MapF = default;
            TDamageType DamageType = default;
            TDefenseRequirements Strengths = default;
            THNWalkData Walk = default;
            FDefenders.Clear();
            Level = AoWE.AoWHSMap.MapContainer.GetMapLevel(L);
            FDefenseLocation.XYL = 16777215;
            Candidates = new TUnitUserList(null);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Walk.Radius <= 1 && FDefenders.Count != Group.Count)
            {
                MapF = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                if (MapF.GetPlayer() == Group.FPlayer)
                {
                    Candidates.Clear();
                    MapF.GetDefenseRequirements(Group.FPlayer, ref Strengths);
                    if (!EnoughStrength(ref Strengths.DamageStrengths))
                    {
                        UpdateDefenseLocation(MapF);
                        GetDefenders(Group.FPlayer, (sbyte)Walk.X, (sbyte)Walk.Y, L, Candidates);
                        AoWE.DefenseSortGroupID = Group.FGroupID;
                        AoWE.DefenseSortUnits = Units;
                        Candidates.FChildren.Sort(AoWE.CompareDefenseUnits);
                        I = 0;
                        while (Candidates.Count != I && Candidates.GetUnit(I).FGroupID != Group.FGroupID)
                        {
                            AUnit = Candidates.GetUnit(I);
                            for (int damageTypeOrdinal = (int)(TDamageType)0; damageTypeOrdinal <= (int)(TDamageType)9; damageTypeOrdinal++)
                            {
                                DamageType = (TDamageType)damageTypeOrdinal;
                                var strength = AUnit.GetStrength(DamageType);
                                Strengths.DamageStrengths[(int)DamageType] -= strength;
                            }

                            I += 1;
                        }

                        Start = I;
                        I = 0;
                        int last = FDefenders.Count - 1;
                        for (; I <= last; I += 1)
                        {
                            AUnit = FDefenders.GetUnit(I);
                            for (int damageTypeOrdinal = (int)(TDamageType)0; damageTypeOrdinal <= (int)(TDamageType)9; damageTypeOrdinal++)
                            {
                                DamageType = (TDamageType)damageTypeOrdinal;
                                var strength = AUnit.GetStrength(DamageType);
                                Strengths.DamageStrengths[(int)DamageType] -= strength;
                            }
                        }

                        I = Start;
                        while (!EnoughStrength(ref Strengths.DamageStrengths) && Candidates.Count > I && Candidates.GetUnit(I).FGroupID == Group.FGroupID)
                        {
                            AUnit = Candidates.GetUnit(I);
                            if (FDefenders.FChildren.IndexOf(AUnit) == -1 && UsefullUnit(AUnit, ref Strengths.DamageStrengths))
                            {
                                FDefenders.AddUnit(AUnit);
                                for (int damageTypeOrdinal = (int)(TDamageType)0; damageTypeOrdinal <= (int)(TDamageType)9; damageTypeOrdinal++)
                                {
                                    DamageType = (TDamageType)damageTypeOrdinal;
                                    var strength = AUnit.GetStrength(DamageType);
                                    Strengths.DamageStrengths[(int)DamageType] -= strength;
                                }
                            }

                            I += 1;
                        }
                    }
                }

                WalkToNextHN(ref Walk);
            }

            Candidates.Free();
            if (Units != null)
            {
                Result = true;
                I = Units.Count;
                while (Result && I != 0)
                {
                    I -= 1;
                    var unit = Units.GetUnit(I);
                    if (FDefenders.IndexOf(unit) != -1)
                    {
                        Result = false;
                    }
                }
            }
            else
            {
                Result = FDefenders.Count == 0;
            }

            AoWE.AoWHSMap.FAIExecuter.UseProcessTime(30);
            return Result;
        }

        // intf_P5_07.inc:320

    }

