            Units = new TUnitUserList(null);
            I = Group.FGroup.Count - 1;
            for (; I >= 0; I -= 1)
            {
                if (UsefullRecruitUnit(Group.FGroup.GetUnit(I)))
                {
                    Units.AddUnit(Group.FGroup.GetUnit(I));
                }
            }

            if (Units.Count != 0)
            {
