        // AIGroup.pas:3067
        public bool TargetOverlapFound(TAIGroupControlTarget Target, TAIGroup IgnoreGroup)
        {
            TPlayer Player;
            int I;
            TAIGroup Group;
            Player = AoWE.AoWHSMap.FPlayers.GetPlayers(FGroupControl.FGroup.FPlayer);
            I = Player.FAIGroups.Count;
            bool Result = false;
            while (I != 0 && !Result)
            {
                I -= 1;
                Group = Player.FAIGroups.GetGroups(I);
                Result = Group != IgnoreGroup && Group.FTargetType == TAIGroupTargetStatus.gtsExecute && Target.FLocation.L == Group.FTargetXYL.L && dHXtoRad(Group.FTargetXYL.X, Group.FTargetXYL.Y, Target.FLocation.X, Target.FLocation.Y) <= 1;
            }

            return Result;
        }

        // AIGroup.pas:3088
        public bool ValidateTargetOverlap(TAIGroup Group, TAIGroupControlTarget Target)
        {
            int I;
            int Moves;
            int Points;
            int OtherDays;
            int Days;
            TPlayer Player;
            TAIGroup Other;
            Player = AoWE.AoWHSMap.FPlayers.GetPlayers(FGroupControl.FGroup.FPlayer);
            I = Player.FAIGroups.Count;
            bool Result = true;
            while (I != 0 && Result)
            {
                I -= 1;
                Other = Player.FAIGroups.GetGroups(I);
                if (Other != Group && Other.FTargetType == TAIGroupTargetStatus.gtsExecute && Other.FTargetXYL.L == Target.FLocation.L && dHXtoRad(Other.FTargetXYL.X, Other.FTargetXYL.Y, Target.FLocation.X, Target.FLocation.Y) <= 1)
                {
                    Moves = Other.GetMovesMin();
                    Points = Other.FTargetMovePoints;
                    if (!Other.FStatus.Contains(TAIGroupStatusElement.agsDone))
                    {
                        Points -= Other.GetMovePointsMin();
                    }

                    OtherDays = Points / Moves;
                    if (Points % Moves != 0)
                    {
                        OtherDays += 1;
                    }

                    Moves = Group.GetMovesMin();
                    var movePointsMin = Group.GetMovePointsMin();
                    Points = Target.FMovePoints - movePointsMin;
                    if (Points > 0)
                    {
                        Days = Points / Moves;
                        if (Points % Moves != 0)
                        {
                            Days += 1;
                        }
                    }
                    else
                    {
                        Days = 0;
                    }

                    Result = Days + 1 <= OtherDays;
                }
            }

            return Result;
        }

        // AIGroup.pas:3125
        public int GetValidTargets()
        {
            int Result = 0;
            for (int I = FGroupControl.FTargets.Count - 1; I >= 0; I--)
            {
                if (FGroupControl.FTargets.GetTargets(I).FStatus.Contains(TAIGroupControlTargetStatusElement.gtsValid))
                {
                    Result += 1;
                }
            }

            return Result;
        }

