        // AIGroup.pas:3190
        public int GetTargetSetupPriority(TAIGroupControlTarget Target)
        {
            TAIGroup Group;
            int Days;
            int Priority;
            Priority = Round((double)Target.FData.Priority * FPrioritySettings.FTargetFactor);
            var movesMin = FGroupControl.FGroup.GetMovesMin();
            Days = (Target.FMovePoints - 1) / movesMin;
            if (Days > 0)
            {
                Priority += Round(FPrioritySettings.FMoveDayPenalty * Days);
            }

            if (Target.FTransporterID != -1)
            {
                Priority += FPrioritySettings.FTransportPenalty;
            }

            Group = FGroupControl.FGroup;
            if (Unsafe.As<TXYL, int>(ref Group.FTargetXYL) == Unsafe.As<TXYL, int>(ref Target.FLocation))
            {
                if (Group.FTargetType == TAIGroupTargetStatus.gtsExecute)
                {
                    Priority += FPrioritySettings.FExecuteBonus;
                }
                else
                {
                    if (Group.FTargetType == TAIGroupTargetStatus.gtsSetup)
                    {
                        Priority += FPrioritySettings.FSetupBonus;
                    }
                }
            }

            if (TargetOverlapFound(Target, Group))
            {
                if (Target.FMovePoints <= FMovesMin)
                {
                    Priority += FPrioritySettings.FNearOverlapPenalty;
                }
                else
                {
                    Priority += FPrioritySettings.FFarOverlapPenalty;
                }
            }

            return Priority;
        }

        // AIGroup.pas:3211
        public bool Setup(TAIGroupControl Control)
        {
            Reset();
            switch ((int)AoWE.AoWHSMap.FPlayers.GetPlayers(Control.FGroup.FPlayer).FPlayerType)
            {
                case (int)TPlayerType.ptCPU1:
                    FValidTargetLimit = 5;
                    break;
                case (int)TPlayerType.ptCPU2:
                    FValidTargetLimit = 7;
                    break;
                case (int)TPlayerType.ptCPU3:
                case (int)TPlayerType.ptCPU4:
                case (int)TPlayerType.ptCPU5:
                    FValidTargetLimit = 10;
                    break;
                default:
                    FValidTargetLimit = 5;
                    break;
            }

            return true;
        }

