        // AIGroup.pas:3273
        public float GetRequiredSuperiority(TAIGroupControlTarget Target)
        {
            float Result;
            int Days;
            if (Target.FData.TargetType != TAITargetType.attNegotiate)
            {
                var group = FGroupControl.FGroup;
                if (Unsafe.As<TXYL, int>(ref group.FTargetXYL) == Unsafe.As<TXYL, int>(ref Target.FLocation) && group.FTargetType == TAIGroupTargetStatus.gtsExecute || group.GetMovesMin() >= Target.FMovePoints)
                {
                    Result = FNearSuperiority;
                }
                else
                {
                    Result = FSuperiority;
                }

                if (FGroupControl.FGroup.GetMovesMin() > 0)
                {
                    var movesMin = FGroupControl.FGroup.GetMovesMin();
                    Days = (Target.FMovePoints - 1) / movesMin;
                    Result = (float)((double)Result + Round((double)Days * FMoveDayFactor));
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

