        public int GetRequiredTargetStrength(TAIGroupControlTarget Target)
        {
            int Result;
            TDefenseRequirements Strengths = default;
            TBattleFieldInfo Info = default;
            if (Target.FData.TargetType != TAITargetType.attNegotiate)
            {
                AoWE.SetupBattleFieldInfo(ref Info, FGroupControl.FGroup.FPlayer, FGroupControl.FGroup.FIndependentRelation, TSet<TBattleFieldInfoRequestsElement>.Of(), FDamageTypes);
                Info.FriendlyRelations = TSet<byte>.WithBounds(0, 7);
                AoWE.AoWHSMap.RetrieveBattleFieldInfo(Target.FLocation.X, Target.FLocation.Y, Target.FLocation.L, 1, ref Info);
                Result = Round((double)GetRequiredSuperiority(Target) * Info.Strength);
                ((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetFieldXYL(Unsafe.As<TXYL, int>(ref Target.FLocation))).GetDefenseRequirements(FGroupControl.FGroup.FPlayer, ref Strengths);
                Result += AoWE.StrengthInfoMax(Bytes.Of(ref Strengths)) / 2;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // AIGroup.pas:3317
        public float GetRequiredBattleFieldSuperiority(TAIGroupControlTarget Target)
        {
            float Result;
            if (Unsafe.As<TXYL, int>(ref Target.FLocation) == Unsafe.As<TXYL, int>(ref FGroupControl.FGroup.FTargetXYL) && FGroupControl.FGroup.FTargetType == TAIGroupTargetStatus.gtsExecute)
            {
                Result = FCurrentBattleFieldFactor;
            }
            else
            {
                Result = FBattleFieldFactor;
            }

            return (float)((double)Result + Round((double)Target.FMovePoints * FBattleFieldMoveFactor));
        }

        // AIGroup.pas:3325
        public int GetRequiredBattleFieldStrength(TAIGroupControlTarget Target)
        {
            int Result;
            TBattleFieldInfo Info = default;
            int PathStrength;
            if (((double)FBattleFieldFactor > 0 || (double)FCurrentBattleFieldFactor > 0) && Target.FData.TargetType != TAITargetType.attNegotiate)
            {
                AoWE.SetupBattleFieldInfo(ref Info, FGroupControl.FGroup.FPlayer, FGroupControl.FGroup.FIndependentRelation, TSet<TBattleFieldInfoRequestsElement>.Of(), FDamageTypes);
                Info.Units = FGroupControl.FGroup;
                Info.Requests = Info.Requests + TSet<TBattleFieldInfoRequestsElement>.Of(TBattleFieldInfoRequestsElement.bfrIgnorePassiveIndependents);
                AoWE.AoWHSMap.RetrieveBattleFieldInfo(Target.FLocation.X, Target.FLocation.Y, Target.FLocation.L, FBattleFieldRadius, ref Info);
                Result = Round((double)GetRequiredBattleFieldSuperiority(Target) * (Info.Strength - Info.FriendlyStrength));
