        // AIGroup.pas:3476
        public bool AllowMultiTargets(TAIGroupControlTarget Target)
        {
            bool Result = FMode.Contains(TAIGroupTargetSelectorModeElement.tsmMultiTargets);
            Result = Result && (Target.FStatus & TSet<TAIGroupControlTargetStatusElement>.Of(TAIGroupControlTargetStatusElement.gtsRecruit, TAIGroupControlTargetStatusElement.gtsProduce)) == TSet<TAIGroupControlTargetStatusElement>.Of();
            bool condition = Result;
            if (condition)
            {
                var requiredStrength = GetRequiredStrength(Target);
                condition = (double)FGroupControl.FStrengthMax >= (double)requiredStrength * FMultiTargetFactor;
            }

            Result = condition;
            Result = Result && FGroupControl.FStrengthMax >= FMinimumStrength;
            bool test = Result;
            if (test)
            {
                bool passed = Target.FData.TargetType != TAITargetType.attNegotiate;
                if (!passed)
                {
                    var movePointsMin = FGroupControl.FGroup.GetMovePointsMin();
                    passed = Target.FMovePoints >= movePointsMin;
                }

                test = passed;
            }

            return test;
        }

