        public override void TargetFoundEvent(TAIGroupControlPlugin Sender, TAIGroupControlTarget Target, ref bool SearchDone)
        {
            TAoWMapField Field;
            TArmyHS Army;
            int I;
            THuntAG Group;
            bool Found;
            Field = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetFieldXYL(Unsafe.As<TXYL, int>(ref Target.FLocation));
            if (Field.GetPlayer() != FGroup.FPlayer)
            {
                Army = Field.GetArmyHS();
                if (Army != null)
                {
                    Group = (THuntAG)FGroup;
                    Found = false;
                    I = Group.FTargetUnitIDs.Count;
                    while (!Found && I != 0)
                    {
                        I -= 1;
                        var item = Group.FTargetUnitIDs[I];
                        Found = Army.FArmy.IndexOfID(item) != -1;
                    }

                    if (Found)
                    {
                        SetupCP(Target);
                        var execute = FCombatPredictor.Execute();
                        if (TSet<TCombatResult>.Of(TCombatResult.crVictory, TCombatResult.crDefeat, TCombatResult.crNoDefenders).Contains(execute))
                        {
                            if (FCombatPredictor.GetEfficiency() != 0)
                            {
                                Target.FData.Priority = 1000 - Target.FMovePoints;
                                base.TargetFoundEvent(Sender, Target, ref SearchDone);
                            }
                        }
                    }
                }
            }
        }

        // AIGroup.pas:1515
        public override void ProcessStates()
        {
            TAIGroupTargetFinder Finder;
            THuntAG Group;
            TAbstractUnit AUnit;
            TAIGroup NewGroup;
            switch (FState)
            {
                case 0:
                    Group = (THuntAG)FGroup;
                {
                    for (int I = Group.FTargetUnitIDs.Count - 1; I >= 0; I--)
                    {
                        var item = Group.FTargetUnitIDs[I];
                        AUnit = AoWE.AoWHSMap.FUnitControl.FindUnit(item);
                        if (AUnit == null || AUnit.FPlayer == 0)
                        {
                            Group.FTargetUnitIDs.Delete(I);
                        }
                    }
                }

                    if (Group.FTargetUnitIDs.Count != 0)
                    {
                        Finder = new TAIGroupTargetFinder(null);
                        Finder.Setup(this);
                        Finder.FSelector.FTargetInfo.Mode = TAITargetMode.tmHunt;
                        ActivatePlugin(Finder);
                        Finder.Release();
                        FState += 1;
                    }
                    else
                    {
                        NewGroup = AoWE.AoWHSMap.FAIGroupManager.CreateGroup(FGroup.FPlayer, FGroup.FIndependentRelation, TGroupBehavior.gbPatrol);
                        NewGroup.AddUnits(FGroup);
                        NewGroup.Release();
                        Done();
                    }

                    break;
                case 1:
                    if (FTargets.Count != 0)
                    {
                        SetupME();
                        var targets = FTargets.GetTargets(0);
                        var fTargetsTargets = FTargets.GetTargets(0);
                        ExecuteME(FTargets.GetTargets(0).FLocation.X, fTargetsTargets.FLocation.Y, targets.FLocation.L);
                        FTargets.Delete(0);
                    }
                    else
                    {
                        Done();
                    }

                    break;
            }
        }
    }

