    // status, path, move index
    public partial class TMoveTE : TTokenEvent
    {
        public TMoveTE(TECustomNode owner) : base(owner)
        {
            FPath = new TMovepath();
            FMoveIndex = 0;
            FStatus = TMoveStatus.msIdle;
        }

        public TMoveStatus FStatus;
        public TMovepath FPath;
        public int FMoveIndex;
        // MoveT.PAS:1958
        public override void Destroy()
        {
            FPath.Free();
            base.Destroy();
        }

        // MoveT.PAS:1964
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(20, FPath.LoadFromStream, FPath.SaveToStream);
        }


        // MoveT.PAS:2027
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            base.Execute(TE);
            if (FStatus == TMoveStatus.msIdle)
            {
                if (Validate())
                {
                    FStatus = TMoveStatus.msMoving;
                    InitializeMove();
                    AoWE.AoWHSMap.Random(1048575);
                    switch (FPath.Count)
                    {
                        case >= 0 and <= 1:
                            FStatus = TMoveStatus.msDone;
                            break;
                        case 2:
                            FStatus = LastMove();
                            break;
                        default:
                            FStatus = DefaultMove();
                            break;
                    }
                }
                else
                {
                    FStatus = TMoveStatus.msFailed;
                }
            }
            else
            {
                if (FStatus == TMoveStatus.msMoving)
                {
                    FStatus = ProcessMove();
                }
            }

            if (FStatus == TMoveStatus.msDone)
            {
                FinishMove();
                Result = TExecuteResult.erDone;
            }
            else
            {
                if (FStatus == TMoveStatus.msFailed)
                {
                    FinishMove();
                    Result = TExecuteResult.erDoneHalt;
                }
                else
                {
                    if (FStatus == TMoveStatus.msFinished)
                    {
                        Result = TExecuteResult.erDone;
                    }
                    else
                    {
                        Result = TExecuteResult.erRetry;
                    }
                }
            }

            return Result;
        }

        // MoveT.PAS:1970
