        public virtual TMoveStatus ProcessMove()
        {
            TMoveStatus Result;
            if (FMoveIndex == 1)
            {
                Result = LastMove();
            }
            else
            {
                if (FMoveIndex > 1 && FMoveIndex < FPath.Count)
                {
                    Result = DefaultMove();
                }
                else
                {
                    Result = TMoveStatus.msDone;
                }
            }

            return Result;
        }

        // MoveT.PAS:2004
        public virtual bool Validate() => true;

        // MoveT.PAS:2010
        public virtual void FinishMove()
        {
            FStatus = TMoveStatus.msFinished;
        }

        // MoveT.PAS:1997
        public virtual TMoveStatus Move()
        {
            TMoveStatus Result;
            FMoveIndex -= 1;
            if (FMoveIndex == 0)
            {
                Result = TMoveStatus.msDone;
            }
            else
            {
                Result = TMoveStatus.msMoving;
            }

            return Result;
        }

        // MoveT.PAS:2016
        public virtual TMoveStatus LastMove() => DefaultMove();

        // MoveT.PAS:2013
