    public partial class TArmyNegotiateMoveTE : TMoveArmyTE
    {
        public TArmyNegotiateMoveTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135430;

        // MoveT.PAS:2400
        public override bool Validate()
        {
            // { Matches: Assign inherited Validate to Result before the conjunction. }
            bool Result = base.Validate();
            return Result && ((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(FTargetX, FTargetY, FTargetL)).GetMoveAction(FArmyHS.FArmy.FPlayer) == TMoveAction.maNegotiate;
        }

        // MoveT.PAS:2442
        public override bool Animating()
        {
            bool Result;
            if (FMoveIndex == 1)
            {
                if (FArmyHS.GetMoveStatus() != -1)
                {
                    // { Process the negotiate or ordinary move animation. }
                    // { Evaluate the map field directly. }
                    if (GetMapF(FPath[0]).GetMoveAction(FArmyHS.FArmy.FPlayer) == TMoveAction.maNegotiate)
                    {
                        Result = FArmyHS.GetMoveStatus() < 50;
                    }
                    else
                    {
                        Result = FArmyHS.GetMoveStatus() < 100;
                    }
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = base.Animating();
            }

            return Result;
        }

        // MoveT.PAS:2407
        public override bool CanMoveNext()
        {
            bool Result;
            if (FMoveIndex == 1)
            {
                // { Evaluate the map field directly. }
                Result = GetMapF(FPath[0]).GetMoveAction(FArmyHS.FArmy.FPlayer) == TMoveAction.maNegotiate || base.CanMoveNext();
            }
            else
            {
                // { Otherwise retain the successful negotiation test. }
                Result = base.CanMoveNext();
            }

            return Result;
        }

        // MoveT.PAS:2419
        public override TMoveStatus ExecuteMove()
        {
            TMoveStatus Result;
            TAoWMapField Field;
            int Direction;
            if (FMoveIndex == 1)
            {
                Field = GetMapF(FPath[0]);
                if (Field.GetMoveAction(FArmyHS.FArmy.FPlayer) == TMoveAction.maNegotiate)
                {
                    Direction = GetDirection(1);
                    if (Direction == 0)
                    {
                        Direction = GetHT(1);
                    }

                    if (Direction > 0 && Direction <= 6)
                    {
                        FArmyHS.SetDirection((byte)Direction);
                    }
                    else
                    {
                        FArmyHS.SetDirection(0);
                    }

                    var item = FPath[0];
                    var fPathItem = FPath[0];
                    var item2 = FPath[0];
                    var item3 = FPath[0];
                    AoWE.NegotiateArmy(FArmyHS.FArmy.FPlayer, FArmyHS, FSelection, item.X, fPathItem.Y, item2.L, item3.Flag);
                    Result = TMoveStatus.msDone;
                }
                else
                {
                    Result = base.ExecuteMove();
                }
            }
            else
            {
                Result = base.ExecuteMove();
            }

            return Result;
        }

        // intf_P5_07.inc:816


    }

    public partial class TArmyCombineMoveTE : TMoveArmyTE
    {
        public TArmyCombineMoveTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135427;

        // MoveT.PAS:2471
        public override bool CanMoveNext()
        {
            TArmyHS ArmyHS;
            TArmy SourceArmy;
            TArmy TargetArmy;
            TAddUnitsResult CombineResult;
            if (FMoveIndex == 1 && FPath[0].X == FTargetX && FPath[0].Y == FTargetY && FPath[0].L == FTargetL && FArmyHS.FArmy.FPlayer == AoWE.AoWHSMap.FSeatedPlayer)
            {
                ArmyHS = GetMapF(FPath[0]).GetArmyHS();
                if (ArmyHS != null && ArmyHS.FArmy.FPlayer == FArmyHS.FArmy.FPlayer)
                {
                    SourceArmy = FArmyHS.FArmy;
                    TargetArmy = ArmyHS.FArmy;
                    CombineResult = TargetArmy.CanAddUnitSelection(SourceArmy, 255);
                    if (CombineResult != TAddUnitsResult.arOK)
                    {
                        ShowCombineFailure(CombineResult);
                        FMode = FMode - TSet<TArmyMoveModeElement>.Of(TArmyMoveModeElement.mmSelectEndLocation);
                    }
                }
            }

            return base.CanMoveNext();
        }

        // MoveT.PAS:2462
        public void ShowCombineFailure(TAddUnitsResult Reason)
        {
            switch (Reason)
            {
                case TAddUnitsResult.arInvalidMoveType:
                    var translateRStr = AoWE.TranslateRStr(AoWE.P5CannotCombineArmiesRStr);
                    AoWE.AoWHSMap.ShowMessage(translateRStr);
                    break;
                case TAddUnitsResult.arTooManyUnits:
                    var aoWETranslateRStr = AoWE.TranslateRStr(AoWE.P5CannotCombineArmiesRStr);
                    AoWE.AoWHSMap.ShowMessage(aoWETranslateRStr);
                    break;
                case TAddUnitsResult.arMultipleTransporters:
                    var translateRStr2 = AoWE.TranslateRStr(AoWE.P5CannotCombineTransportersRStr);
                    AoWE.AoWHSMap.ShowMessage(translateRStr2);
                    break;
            }
        }

        // intf_P5_07.inc:816


    }

    // combat mode, combat type, ignore defenders
    public partial class TArmyCombatMoveTE : TMoveArmyTE
    {
        public TArmyCombatMoveTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135426;

        public TCombatMoveMode FCombatMode;
        public TCombatType FCombatType;
        public bool FIgnoreDefenders;
        // MoveT.PAS:2513
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwData(Bytes.Of(ref FCombatType, 1), 1, 50);
        }

        // MoveT.PAS:3085
        public override TMoveStatus ProcessMove()
        {
            // { Retain Result assignment and place combat execution first. }
            TMoveStatus Result = TMoveStatus.msMoving;
            if (FCombatMode == TCombatMoveMode.cmRestoringHotseat)
            {
                return TMoveStatus.msMoving;
            }

            if (FCombatMode == TCombatMoveMode.cmSetupHotseat)
            {
                Result = TMoveStatus.msMoving;
            }
            else
            {
                if (FCombatMode == TCombatMoveMode.cmCancelCombat)
                {
                    Result = TMoveStatus.msDone;
                }
                else
                {
                    if (FCombatMode != TCombatMoveMode.cmRequestingCombatType)
                    {
                        if (FCombatMode != TCombatMoveMode.cmSetupReady)
                        {
                            Result = base.ProcessMove();
                        }

                        if (FCombatMode == TCombatMoveMode.cmSetupReady)
                        {
                            if (FCombatType != TCombatType.ctNone)
                            {
                                ExecuteCombat();
                                if (FArmyHS == null)
                                {
                                    Result = TMoveStatus.msDone;
                                }
                                else
                                {
                                    Result = TMoveStatus.msMoving;
                                }
                            }
                            else
                            {
                                Result = TMoveStatus.msDone;
                            }
                        }
                    }
                }
            }

            return Result;
        }

        // MoveT.PAS:2519
        public override bool Validate() => base.Validate();

        // MoveT.PAS:2522
        public override void InitializeMove()
        {
            base.InitializeMove();
        }

        // MoveT.PAS:3030
        public override bool Animating()
        {
            bool Result;
            TAoWMapField Field;
            if (FMoveIndex == 1 && FCombatMode != TCombatMoveMode.cmCombatExecuted)
            {
                if (FArmyHS.GetMoveStatus() != -1)
                {
                    Field = GetMapF(FPath[FMoveIndex - 1]);
                    if (Field.GetPlayer() != -1)
                    {
                        Result = FArmyHS.GetMoveStatus() < 50;
                    }
                    else
                    {
                        Result = FArmyHS.GetMoveStatus() < 100;
                    }
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = base.Animating();
            }

            return Result;
        }

        // MoveT.PAS:3046
        public override bool CanMoveNext()
        {
            if (FMoveIndex == 1)
            {
                // { Evaluate the field without retaining a second reference. }
                var player = GetMapF(FPath[0]).GetPlayer();
                if (FArmyHS.FArmy.FPlayer != player)
                {
                    return AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FGameOverStatus == TGameOverStatus.goNone;
                }
            }

            return base.CanMoveNext();
        }

        // MoveT.PAS:3061
        public override TMoveStatus ExecuteMove()
        {
            TMoveStatus Result;
            TAoWMapField Field;
            sbyte Player;
            int Direction;
            if (FMoveIndex == 1 && FCombatMode == TCombatMoveMode.cmMoving)
            {
                Field = GetMapF(FPath[0]);
                Player = Field.GetPlayer();
                if (Player != -1 && Player != FArmyHS.FArmy.FPlayer && !FIgnoreDefenders)
                {
                    Direction = GetDirection(FMoveIndex + 1);
                    if (Direction == 0)
                    {
                        Direction = GetHT(FMoveIndex + 1);
                    }

                    if (Direction > 0 && Direction <= 6)
                    {
                        FArmyHS.SetDirection((byte)Direction);
                    }
                    else
                    {
                        FArmyHS.SetDirection(0);
                    }

                    SetupCombat();
                    Result = TMoveStatus.msMoving;
                }
                else
                {
                    Result = base.ExecuteMove();
                }
            }
            else
            {
                Result = base.ExecuteMove();
            }

            return Result;
        }

        // MoveT.PAS:2504
        public override bool Setup(TArmyHS ArmyHS, byte Selection, TMovepath Path, TSet<TArmyMoveModeElement> Mode)
        {
            bool Result = base.Setup(ArmyHS, Selection, Path, Mode);
            if (Result && ArmyHS.FArmy.FPlayer == FTargetPlayer)
            {
                Result = false;
            }

            bool condition = Result && ArmyHS.FArmy.FPlayer > 0 && FTargetPlayer > 0;
            if (condition)
            {
                var diplomaticRelation = AoWE.AoWHSMap.FPlayers.GetPlayers(ArmyHS.FArmy.FPlayer).FDiplomaticRelations.GetDiplomaticRelation(FTargetPlayer);
                condition = TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drAlliance).Contains(diplomaticRelation);
            }

            if (condition)
            {
                Result = false;
            }

            return Result;
        }

        // MoveT.PAS:2525
        public void RequestCombatTypeCallBack(TEventLog Log)
        {
            TCombatFlowControlTE Flow;
            TCombatTypeRequestEventLog Request;
            TArmyCombatMoveTE Move;
            Request = (TCombatTypeRequestEventLog)Log;
            FCombatType = Request.FCombatType;
            if (Request.FCreateNewMove)
            {
                if (FCombatType != TCombatType.ctNone)
                {
                    Flow = new TCombatFlowControlTE(null);
                    Flow.FMode = TSet<TCombatFlowControlModeElement>.Of(TCombatFlowControlModeElement.cfmUnlockAIExecuter, TCombatFlowControlModeElement.cfmActivateTC, TCombatFlowControlModeElement.cfmEnableTurnTimer);
                    if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous)
                    {
                        Flow.FMode = Flow.FMode + TSet<TCombatFlowControlModeElement>.Of(TCombatFlowControlModeElement.cfmSetAutoSwitch);
                    }

                    Flow.FPlayer = Request.FPlayer;
                    AoWE.AoWHSMap.FTokenManager.GetTokenControl(AoWE.AoWHSMap.FSeatedPlayer).AddEvent(Flow);
                    Flow.Release();
                    if (Request.FArmyID.RetrieveArmy(ref FArmyHS, ref FSelection))
                    {
                        while (FPath.Count > 2)
                        {
                            FPath.Delete(2);
                        }

                        if (FPath.Count == 2)
                        {
                            FPath.List[1].Flag = 0;
                        }

                        Move = (TArmyCombatMoveTE)AoWE.CreateArmyMoveTE(FArmyHS, FSelection, FPath, TMoveAction.maAttack, TSet<TArmyMoveModeElement>.Of());
                        if (Move != null)
                        {
                            // { created combat move }
                            Move.FCombatType = ((TCombatTypeRequestEventLog)Log).FCombatType;
                            AoWE.AoWHSMap.FTokenManager.GetTokenControl(AoWE.AoWHSMap.FSeatedPlayer).AddEvent(Move);
                            Move.Release();
                        }
                        else
                        {
                            AoWE.AoWEngine.OutputDebugStr((AnsiString)"Cannot create CombatMoveTE");
                        }
                    }
                }
                else
                {
                    if (AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous)
                    {
                        Flow = new TCombatFlowControlTE(null);
                        Flow.FMode = TSet<TCombatFlowControlModeElement>.Of(TCombatFlowControlModeElement.cfmSetAutoSwitch, TCombatFlowControlModeElement.cfmUnlockAIExecuter, TCombatFlowControlModeElement.cfmEnableTurnTimer);
                        AoWE.AoWHSMap.FTokenManager.GetTokenControl(AoWE.AoWHSMap.FSeatedPlayer).AddEvent(Flow);
                        Flow.Release();
                    }
                }
            }
            else
            {
                FCombatMode = TCombatMoveMode.cmSetupReady;
            }
        }

        // MoveT.PAS:2568
        public void RestoreHotseatMode()
        {
            TNewTurnEventLog Log;
            AoWE.AoWHSMap.SetSeatedPlayer(-1);
            Log = new TNewTurnEventLog(null);
            Log.FTurnPlayer = AoWE.AoWHSMap.FCurrentPlayer;
            Log.FMode = TNewTurnEventLogMode.ntDialog;
            Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of();
            if (AoWE.AoWHSMap.FCurrentPlayer == 0)
            {
                Log.FText = AoWE.TranslateRStr(AoWE.P5IndependentsAreMovingRStr);
            }
            else
            {
                var name = AoWE.AoWHSMap.FPlayers.GetPlayers(AoWE.AoWHSMap.FCurrentPlayer).GetName();
                Log.FText = AoWE.Format(AoWE.TranslateRStr(AoWE.P5PlayerIsMovingRStr), [name]);
            }

            AoWE.AoWHSMap.TriggerExecuteEventLog(Log, true, null);
            Log.Release();
        }

        // MoveT.PAS:2584
        public void RestoreHotSeatModeCallBack(TEventLog Log)
        {
            AoWE.AoWHSMap.SynchroniseBegin();
            RestoreHotseatMode();
            AoWE.AoWHSMap.FAIExecuter.Unlock();
            AoWE.AoWHSMap.UnlockGameOverEvent();
            FCombatMode = TCombatMoveMode.cmMoving;
            AoWE.AoWHSMap.SynchroniseEnd();
        }

        // MoveT.PAS:2594
        public void ShowHotSeatPlayerCallBack(TEventLog Log)
        {
            AoWE.AoWHSMap.SetSeatedPlayer(((TNewTurnEventLog)Log).FTurnPlayer);
            if (FCombatMode == TCombatMoveMode.cmSetupHotseat)
            {
                FCombatMode = TCombatMoveMode.cmSetupReady;
            }
        }

        // MoveT.PAS:2600
        public void SetupCombat()
        {
            TAoWMapField Field = default;
            sbyte Player = default;
            TCombat Combat = default;
            TMapFieldMsg Msg = default;
            TCombatTypeRequestEventLog Request = default;
            TNewTurnEventLog Log = default;
            Field = GetMapF(FPath[0]);
            if (FCombatType == TCombatType.ctNone)
            {
                if (AoWE.AoWHSMap.FRequestCombatType && AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcLocal)
                {
                    if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysFC)
                    {
                        FCombatType = TCombatType.ctFast;
                        FCombatMode = TCombatMoveMode.cmSetupReady;
                    }
                    else
                    {
                        if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysTC)
                        {
                            bool condition = AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman;
                            if (!condition)
                            {
                                bool test = Field.GetPlayer() > 0;
                                if (test)
                                {
                                    var player = Field.GetPlayer();
                                    test = AoWE.AoWHSMap.FPlayers.GetPlayers(player).FPlayerType == TPlayerType.ptHuman;
                                }

                                condition = test;
                            }

                            if (condition)
                            {
                                FCombatType = TCombatType.ctTactical;
                                FCombatMode = TCombatMoveMode.cmSetupReady;
                            }
                            else
                            {
                                FCombatType = TCombatType.ctFast;
                                FCombatMode = TCombatMoveMode.cmSetupReady;
                            }
                        }
                        else
                        {
                            // { Set the mode in both branches, as in the original. }
                            FCombatMode = TCombatMoveMode.cmRequestingCombatType;
                        }
                    }
                }
                else
                {
                    if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcLocal && (!AoWE.AoWHSMap.FRequestCombatType && AoWE.AoWHSMap.FPlayers.FLocalPlayers.Count == 1 || AoWE.AoWHSMap.FRequestCombatType && AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman))
                    {
                        if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysFC)
                        {
                            FCombatType = TCombatType.ctFast;
                            FCombatMode = TCombatMoveMode.cmSetupReady;
                        }
                        else
                        {
                            if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysTC)
                            {
                                bool condition = AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman;
                                if (!condition)
                                {
                                    bool test = Field.GetPlayer() > 0;
                                    if (test)
                                    {
                                        var player = Field.GetPlayer();
                                        test = AoWE.AoWHSMap.FPlayers.GetPlayers(player).FPlayerType == TPlayerType.ptHuman;
                                    }

                                    condition = test;
                                }

                                if (condition)
                                {
                                    FCombatType = TCombatType.ctTactical;
                                    FCombatMode = TCombatMoveMode.cmSetupReady;
                                }
                                else
                                {
                                    FCombatType = TCombatType.ctFast;
                                    FCombatMode = TCombatMoveMode.cmSetupReady;
                                }
                            }
                            else
                            {
                                // { Set the mode in both branches, as in the original. }
                                FCombatMode = TCombatMoveMode.cmRequestingCombatType;
                            }
                        }
                    }
                    else
                    {
                        bool condition = AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcEmail && AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman && Field.GetPlayer() >= 0;
                        if (condition)
                        {
                            var player = Field.GetPlayer();
                            condition = AoWE.AoWHSMap.FPlayers.GetPlayers(player).FPlayerType != TPlayerType.ptHuman;
                        }

                        if (condition)
                        {
                            if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysFC)
                            {
                                FCombatType = TCombatType.ctFast;
                                FCombatMode = TCombatMoveMode.cmSetupReady;
                            }
                            else
                            {
                                if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysTC)
                                {
                                    bool test = AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman;
                                    if (!test)
                                    {
                                        bool passed = Field.GetPlayer() > 0;
                                        if (passed)
                                        {
                                            var player = Field.GetPlayer();
                                            passed = AoWE.AoWHSMap.FPlayers.GetPlayers(player).FPlayerType == TPlayerType.ptHuman;
                                        }

                                        test = passed;
                                    }

                                    if (test)
                                    {
                                        FCombatType = TCombatType.ctTactical;
                                        FCombatMode = TCombatMoveMode.cmSetupReady;
                                    }
                                    else
                                    {
                                        FCombatType = TCombatType.ctFast;
                                        FCombatMode = TCombatMoveMode.cmSetupReady;
                                    }
                                }
                                else
                                {
                                    // { Set the mode in both branches, as in the original. }
                                    FCombatMode = TCombatMoveMode.cmRequestingCombatType;
                                }
                            }
                        }
                        else
                        {
                            // { Original tests connection type here, not play mode. }
                            if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork)
                            {
                                bool test = AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman;
                                if (!test)
                                {
                                    bool passed = Field.GetPlayer() > 0;
                                    if (passed)
                                    {
                                        var player = Field.GetPlayer();
                                        passed = AoWE.AoWHSMap.FPlayers.GetPlayers(player).FPlayerType == TPlayerType.ptHuman;
                                    }

                                    test = passed;
                                }

                                if (test)
                                {
                                    switch (AoWE.AoWHSMap.FVictoryMode)
                                    {
                                        case 0:
                                            FCombatType = TCombatType.ctFast;
                                            FCombatMode = TCombatMoveMode.cmSetupReady;
                                            break;
                                        case 2:
                                            FCombatMode = TCombatMoveMode.cmRequestingCombatType;
                                            break;
                                        case 1:
                                            bool passed = AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman && Field.GetPlayer() > 0;
                                            if (passed)
                                            {
                                                var player = Field.GetPlayer();
                                                passed = AoWE.AoWHSMap.FPlayers.GetPlayers(player).FPlayerType == TPlayerType.ptHuman;
                                            }

                                            if (passed)
                                            {
                                                FCombatMode = TCombatMoveMode.cmRequestingCombatType;
                                            }
                                            else
                                            {
                                                FCombatType = TCombatType.ctFast;
                                                FCombatMode = TCombatMoveMode.cmSetupReady;
                                            }

                                            break;
                                        default:
                                        {
                                            // { The original tests the always-available case before the human-only case. }
                                            FCombatType = TCombatType.ctFast;
                                            FCombatMode = TCombatMoveMode.cmSetupReady;
                                        }

                                            break;
                                    }
                                }
                                else
                                {
                                    FCombatType = TCombatType.ctFast;
                                    FCombatMode = TCombatMoveMode.cmSetupReady;
                                }
                            }
                            else
                            {
                                FCombatType = TCombatType.ctFast;
                                FCombatMode = TCombatMoveMode.cmSetupReady;
                            }
                        }
                    }
                }
            }
            else
            {
                FCombatMode = TCombatMoveMode.cmSetupReady;
            }

            if (FCombatMode == TCombatMoveMode.cmRequestingCombatType || (FCombatType == TCombatType.ctTactical && FCombatMode == TCombatMoveMode.cmSetupReady))
            {
                Combat = new TCombat(null);
                var yhx = FArmyHS.GetYhx();
                var lhx = FArmyHS.GetLhx();
                var player = Field.GetPlayer();
                var independentRelation = Field.GetIndependentRelation();
                var item = FPath[0];
                var fPathItem = FPath[0];
                var item2 = FPath[0];
                var xhx = FArmyHS.GetXhx();
                Combat.Setup((byte)FArmyHS.FArmy.FPlayer, (byte)FArmyHS.FArmy.FIndependentRelation, xhx, yhx, lhx, (byte)player, independentRelation, item.X, fPathItem.Y, item2.L, false);
                Msg.MsgID = 4359;
                Msg.Param[0] = Combat;
                Msg.Param[1] = FArmyHS;
                Msg.Result = 0;
                Field.SendMapFieldMsg(ref Msg);
                if (Msg.Result.Value == 0)
                {
                    var fArmyHSLhx = FArmyHS.GetLhx();
                    var fArmyHSYhx = FArmyHS.GetYhx();
                    var fArmyHSXhx = FArmyHS.GetXhx();
                    Combat.InitDefaultArmies(FArmyHS.FArmy, fArmyHSXhx, fArmyHSYhx, fArmyHSLhx);
                }

                if (!Combat.DefendersAvailable() || !Combat.PlayerTypeInvolved(TSet<TPlayerType>.Of(TPlayerType.ptHuman)))
                {
                    FCombatType = TCombatType.ctFast;
                    FCombatMode = TCombatMoveMode.cmSetupReady;
                }

                Combat.Free();
            }

            // { Original uses connection type here too. }
            if (AoWE.AoWHSMap.FConnectionType == TPlayerConnectionType.pcNetwork && FCombatMode == TCombatMoveMode.cmRequestingCombatType)
            {
                AoWE.AoWHSMap.DisableTurnTimer();
                AoWE.AoWHSMap.FAIExecuter.Lock();
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman)
                {
                    Player = FArmyHS.FArmy.FPlayer;
                }
                else
                {
                    Player = Field.GetPlayer();
                }

                if (AoWE.AoWHSMap.FTokenManager.GetTokenControl(Player).Local())
                {
                    AoWE.AoWHSMap.FTokenManager.GetTokenControl(Player).ClearEvents();
                }

                AoWE.AoWHSMap.FTokenManager.TokenExecuter.HoldTC = true;
                AoWE.AoWHSMap.FTokenManager.TokenExecuter.ActivateTC(Player);
                if (AoWE.AoWHSMap.FSeatedPlayer == Player)
                {
                    Request = new TCombatTypeRequestEventLog(null);
                    Request.FPlayer = FArmyHS.FArmy.FPlayer;
                    Request.FDefenderPlayer = Field.GetPlayer();
                    Request.FX = Field.Xhx;
                    Request.FY = Field.Yhx;
                    Request.FL = Field.Lhx;
                    Request.SetTokenEvent(this);
                    Request.FCreateNewMove = true;
                    Request.FArmyID = FArmyHS.FArmy.CreateID(FSelection);
                    if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmChoose)
                    {
                        if (AoWE.AoWHSMap.FSeatedPlayer != Request.FPlayer)
                        {
                            var lhx = FArmyHS.GetLhx();
                            var yhx = FArmyHS.GetYhx();
                            var xhx = FArmyHS.GetXhx();
                            AoWE.AoWHSMap.CenterViewTo(xhx, yhx, lhx);
                        }

                        FinishMove();
                        FArmyHS = null;
                        AoWE.AoWHSMap.TriggerExecuteEventLog(Request, false, RequestCombatTypeCallBack);
                    }
                    else
                    {
                        FinishMove();
                        FArmyHS = null;
                        if (AoWE.AoWEngine.FRegistry.GetCombatResolveMode() == TCombatResolveMode.crmAlwaysTC)
                        {
                            Request.Select(TCombatType.ctTactical);
                        }
                        else
                        {
                            Request.Select(TCombatType.ctFast);
                        }

                        RequestCombatTypeCallBack(Request);
                    }

                    Request.Release();
                }
                else
                {
                    FinishMove();
                    FArmyHS = null;
                }

                FCombatMode = TCombatMoveMode.cmCancelCombat;
            }

            if (FCombatMode == TCombatMoveMode.cmRequestingCombatType && AoWE.AoWHSMap.FRequestCombatType && AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType != TPlayerType.ptHuman)
            {
                Log = new TNewTurnEventLog(null);
                Log.FTurnPlayer = Field.GetPlayer();
                Log.FMode = TNewTurnEventLogMode.ntDialog;
                Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                Log.FText = AoWE.TranslateRStr(AoWE.P5YouAreBeingAttackedRStr);
                AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, ShowHotSeatPlayerCallBack);
                Log.Release();
            }
            else
            {
                if (FCombatMode == TCombatMoveMode.cmSetupReady && FCombatType == TCombatType.ctTactical && AoWE.AoWHSMap.FRequestCombatType && AoWE.AoWHSMap.FPlayers.GetPlayers(FArmyHS.FArmy.FPlayer).FPlayerType != TPlayerType.ptHuman)
                {
                    FCombatMode = TCombatMoveMode.cmSetupHotseat;
                    Log = new TNewTurnEventLog(null);
                    Log.FTurnPlayer = Field.GetPlayer();
                    Log.FMode = TNewTurnEventLogMode.ntDialog;
                    Log.FDialogStyle = TSet<TNewTurnEventLogDialogStyleElement>.Of(TNewTurnEventLogDialogStyleElement.nsCloseable);
                    Log.FText = AoWE.TranslateRStr(AoWE.P5YouAreBeingAttackedRStr);
                    AoWE.AoWHSMap.TriggerExecuteEventLog(Log, false, ShowHotSeatPlayerCallBack);
                    Log.Release();
                }
            }

            if (FCombatMode == TCombatMoveMode.cmRequestingCombatType)
            {
                FArmyHS.PauseMove();
                Request = new TCombatTypeRequestEventLog(null);
                Request.FPlayer = FArmyHS.FArmy.FPlayer;
                Request.FDefenderPlayer = Field.GetPlayer();
                Request.FX = Field.Xhx;
                Request.FY = Field.Yhx;
                Request.FL = Field.Lhx;
                if (AoWE.AoWHSMap.FSeatedPlayer != Request.FPlayer)
                {
                    var lhx = FArmyHS.GetLhx();
                    var yhx = FArmyHS.GetYhx();
                    var xhx = FArmyHS.GetXhx();
                    AoWE.AoWHSMap.CenterViewTo(xhx, yhx, lhx);
                }

                AoWE.AoWHSMap.TriggerExecuteEventLog(Request, false, RequestCombatTypeCallBack);
                Request.Release();
            }
        }

        // MoveT.PAS:2801
        public void CombatExecuted(TCombat Combat)
        {
            TArmyHS ArmyHS;
            TArmy Army;
            byte Selection;
            TMoveArmyTE Move;
            TAoWMapField Field;
            if (!(Combat is TFastCombat))
            {
                if (TSet<TCombatResult>.Of(TCombatResult.crVictory).Contains(Combat.FCombatResult))
                {
                    ArmyHS = (TArmyHS)AoWE.AoWHSMap.MapContainer.GetField(Combat.FCombatData.FAttackerX, Combat.FCombatData.FAttackerY, Combat.FCombatData.FAttackerL).FindOwnedChild(131607);
                    if (ArmyHS != null)
                    {
                        Army = ArmyHS.FArmy;
                        Selection = 0;
                        for (int I = Army.Count - 1; I >= 0; I--)
                        {
                            Selection = (byte)(Selection << 1);
                            if (Army.GetUnit(I).FUnitStatus.Contains(TUnitStatusElement.usMoving))
                            {
                                Selection = (byte)(Selection | 1);
                                var unit = Army.GetUnit(I);
                                Army.GetUnit(I).FUnitStatus = unit.FUnitStatus - TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoving);
                            }
                        }

                        if (Selection != 0)
                        {
                            Field = (TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(Combat.FCombatData.FX, Combat.FCombatData.FY, Combat.FCombatData.FL);
                            if (Field.GetPlayer() == ArmyHS.FArmy.FPlayer)
                            {
                                Move = AoWE.CreateArmyMoveXYLTE(ArmyHS, Selection, (sbyte)Combat.FCombatData.FX, (sbyte)Combat.FCombatData.FY, (sbyte)Combat.FCombatData.FL, TMoveAction.maNormal, TSet<TArmyMoveModeElement>.Of());
                            }
                            else
                            {
                                Move = AoWE.CreateArmyMoveXYLTE(ArmyHS, Selection, (sbyte)Combat.FCombatData.FX, (sbyte)Combat.FCombatData.FY, (sbyte)Combat.FCombatData.FL, TMoveAction.maAttack, TSet<TArmyMoveModeElement>.Of());
                                if (Move != null)
                                {
                                    ((TArmyCombatMoveTE)Move).FIgnoreDefenders = true;
                                }
                            }

                            if (Move != null)
                            {
                                AoWE.AoWHSMap.FTokenManager.TokenExecuter.AddSystemEvent(Move);
                                Move.Release();
                            }
                        }
                    }
                }
                else
                {
                    ArmyHS = (TArmyHS)AoWE.AoWHSMap.MapContainer.GetField(Combat.FCombatData.FAttackerX, Combat.FCombatData.FAttackerY, Combat.FCombatData.FAttackerL).FindOwnedChild(131607);
                    if (ArmyHS != null)
                    {
                        for (int I = ArmyHS.FArmy.Count - 1; I >= 0; I--)
                        {
                            var unit = ArmyHS.FArmy.GetUnit(I);
                            ArmyHS.FArmy.GetUnit(I).FUnitStatus = unit.FUnitStatus - TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoving);
                        }

                        if (ArmyHS.FArmy.FPlayer == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            AoWE.AoWHSMap.FSelectedArmy.Select(ArmyHS);
                        }
                    }
                }

                if (AoWE.AoWHSMap.FRequestCombatType && Combat.FCombatData.FPlayers.GetPlayers(Combat.FCombatData.FAttackerPlayer).FPlayer != AoWE.AoWHSMap.FSeatedPlayer)
                {
                    RestoreHotseatMode();
                }

                AoWE.AoWHSMap.SynchroniseBegin();
                AoWE.DistributeCombatEvent(Combat.FLogbook, false);
                AoWE.AoWHSMap.SynchroniseEnd();
            }
        }

        // MoveT.PAS:3019
        public TMoveStatus ExecuteLastMove()
        {
