            if (Result && FX != 255)
            {
                Result = (byte)((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField((sbyte)FX, (sbyte)FY, (sbyte)FL)).GetPlayer() == FOwnerPlayer;
