            {
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).SetGems(players.FGems - FGold);
                if (FEventLogID != -1)
                {
                    Log = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FEventLogbook.FindID(FEventLogID);
                    if (Log != null)
                    {
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FEventLogbook.RemoveEvent(Log);
                    }
