                if (FArmyHS != null && FMode.Contains(TNegotiateModeElement.nmMoveOnAccept))
                {
                    Path = new TMovepath();
                    Path.AddXYL((sbyte)FX, (sbyte)FY, (sbyte)FL);
                    var yhx = FArmyHS.Yhx;
                    Path.AddXYL(FArmyHS.Xhx, yhx, FArmyHS.Lhx);
                    Path.List[0].Flag = (sbyte)FMovePoints;
                    Move = AoWE.CreateArmyMoveTE(FArmyHS, FSelection, Path, (TMoveAction)(byte)3, TSet<TArmyMoveModeElement>.Of(TArmyMoveModeElement.mmSelectEndLocation));
                    AoWE.AoWHSMap.FTokenManager.TokenExecuter.InsertExecuteEvent(Move);
                    // { Original bug: no nil check after CreateArmyMoveTE can return nil. }
                    Move.Release();
                    Path.Free();
                }
            }
        }

