        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result = default;
            base.Execute(TE);
            if (AoWE.AoWHSMap.FSeatedPlayer == TE.ActiveTCIndex)
            {
                if (TE.ExecuteCount == 0)
                {
                    var fileName = ExtractFileName(FFileName);
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.P5SavingGameRStr), [fileName]);
                    AoWE.AoWHSMap.ShowMessage(format);
                    Result = TExecuteResult.erRetry;
                }
                else
                {
                    var fileName = ExtractFileName(FFileName);
                    var format = AoWE.Format(AoWE.TranslateRStr(AoWE.GameSavedRStr), [fileName]);
                    AoWE.AoWHSMap.ShowMessage(format);
                    try
                    {
                        AoWE.AoWHSMap.DisableTurnTimer();
                        if (AoWE.AoWEngine.FCampaign != null)
                        {
                            AoWE.AoWEngine.SaveCampaign(FFileName);
                            AoWE.AoWEngine.FCampaign.FFileName = FFileName;
                        }
                        else
                        {
                            AoWE.AoWEngine.SaveHSM(FFileName, null);
                            AoWE.AoWHSMap.FileName = FFileName;
                        }

                        AoWE.AoWHSMap.EnableTurnTimer();
                    }
                    catch (System.Exception)
                    {
                        // { Original leaves the turn timer disabled after a save failure. }
                        var aoWEFormat = AoWE.Format(AoWE.TranslateRStr(AoWE.P5ErrorSavingRStr), [FFileName]);
                        AoWE.AoWHSMap.ShowMessage(aoWEFormat);
                    }

                    Result = TExecuteResult.erDone;
                }
            }
            else
            {
                Result = TExecuteResult.erDone;
            }

            return Result;
        }

        // NetworkE.pas:230


    }

