        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            base.Execute(TE);
            switch (FCheatID)
            {
                case 0:
                {
                    for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(I);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(I).SetGems(players.FGems + 1000);
                    }
                }

                    break;
                case 1:
                {
                    for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        var players = AoWE.AoWHSMap.FPlayers.GetPlayers(I);
                        AoWE.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.SetMana(players.FMagicControl.FMana + 1000);
                    }
                }

                    break;
                case 2:
                    AoWE.AoWHSMap.SetExplorationEnabled(!AoWE.AoWHSMap.FExplorationEnabled);
                    if (AoWE.AoWHSMap.FExplorationEnabled)
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5ExplorationEnabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }
                    else
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5ExplorationDisabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }

                    break;
                case 3:
                    AoWE.AoWHSMap.SetFogEnabled(!AoWE.AoWHSMap.FFogEnabled);
                    if (AoWE.AoWHSMap.FFogEnabled)
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5FogEnabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }
                    else
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5FogDisabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }

                    break;
                case 4:
                    var cheatEnabled = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled();
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.FCheatEnabled = !cheatEnabled;
                    if (AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5SpellCheatEnabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }
                    else
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5SpellCheatDisabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }

                {
                    for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        var fMagicControlCheatEnabled = AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled();
                        AoWE.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FCheatEnabled = fMagicControlCheatEnabled;
                    }
                }

                    break;
                case 5:
                    AoWE.AoWHSMap.FPlayerControl.GameOver(FPlayer, TGameOverStatus.goWon);
                    break;
                case 6:
                    AoWE.AoWHSMap.FUnlimitedMoves = !AoWE.AoWHSMap.FUnlimitedMoves;
                    if (AoWE.AoWHSMap.FUnlimitedMoves)
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5FreeMovementEnabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }
                    else
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5FreeMovementDisabledRStr);
                        AoWE.AoWHSMap.ShowMessage(translateRStr);
                    }

                    break;
                case 7:
                {
                    for (int I = AoWE.AoWHSMap.FPlayers.GetPlayers(0).FStructures.Count - 1; I >= 0; I--)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(0).FStructures.GetStructure(I).EClass.ClassID == 131336)
                        {
                            AoWE.AoWHSMap.FPlayers.GetPlayers(0).FStructures.GetStructure(I).SetPlayer(FPlayer);
                        }
                    }
                }

                    break;
                case 8:
                    AoWE.AoWHSMap.FPlayerControl.GameOver(FPlayer, TGameOverStatus.goLost);
                    break;
                case 9:
                {
                    for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
                    {
                        AoWE.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.Clear();
                        for (int J = 1, lastJ = AoWE.AoWHSSet.FSpellControl.GetCount() - 1; J <= lastJ; J++)
                        {
                            if (AoWE.AoWHSSet.FSpellControl.GetSpell(J) != null)
                            {
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.Add(J);
                            }
                        }
                    }
                }

                    break;
            }

            PlaySample((AnsiString)"SFX\\ATTACK\\MAGICB01.WAV");
            return TExecuteResult.erDone;
        }

        // NetworkE.pas:230


    }

    // unit ID, player
    public partial class TDisbandUnitTE : TTokenEvent
    {
        public TDisbandUnitTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135447;

        public int FUnitID;
        public sbyte FPlayer;
        // MoveT.PAS:3532
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 20);
            Stream.rwInteger(ref FUnitID, 21);
        }

        // MoveT.PAS:3539
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TAbstractUnit AUnit;
            TPlayerStructure Structure;
            TArmyHS ArmyHS;
            TGroupBehavior Behavior;
            int I;
            int N;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            AUnit = AoWE.AoWHSMap.FUnitControl.FindUnit(FUnitID);
            if (AUnit != null && AUnit.FPlayer == FPlayer)
            {
                AUnit.AddRef();
                if (AUnit.GetRace() == 5 && AUnit.FPlayer > 0 && AoWE.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).FPlayerRace == 5 && (AUnit.GetAbilityEnabled(162) || AUnit.GetAbilityEnabled(164) || AUnit.GetAbilityEnabled(165)))
                {
                    AoWE.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).FHeroEmerging = true;
                }

                if (!AUnit.GetAbilityEnabled(155))
                {
                    AUnit.GetLocation(ref X, ref Y, ref L);
                    Structure = (TPlayerStructure)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L).FindNoneTransparentHS(typeof(TPlayerStructure));
                    if (!(AUnit.Owner is TArmy) || ((TArmy)AUnit.Owner).Count > 1 || (Structure != null && Structure.FPlayer > 0))
                    {
                        AUnit.GetLocation(ref X, ref Y, ref L);
                        AUnit.SetOwner(null);
                        ArmyHS = AUnit.Place(X, Y, L, 0, TSet<TUnitPlaceModeElement>.Of(TUnitPlaceModeElement.pmScanArea));
                    }
                    else
                    {
                        ((TArmy)AUnit.Owner).SetPlayer(0);
                        ArmyHS = ((TArmy)AUnit.Owner).GetArmyHS();
                    }

                    if (ArmyHS != null)
                    {
                        N = AoWE.AoWHSMap.Random(10);
                        if (N == 0)
                        {
                            Behavior = TGroupBehavior.gbGuardArea;
                        }
                        else
                        {
                            if (N < 7)
                            {
                                Behavior = TGroupBehavior.gbScout;
                            }
                            else
                            {
                                Behavior = TGroupBehavior.gbRaid;
                            }
                        }

                        I = ArmyHS.FArmy.IndexOfBehavior(Behavior);
                        if (I == -1)
                        {
                            var indexOf = ArmyHS.FArmy.IndexOf(AUnit);
                            ArmyHS.FArmy.SetBehavior((byte)(1 << indexOf), Behavior);
                        }
                        else
                        {
                            var unit = ArmyHS.FArmy.GetUnit(I);
                            var indexOf = ArmyHS.FArmy.IndexOf(AUnit);
                            ArmyHS.FArmy.SetGroup((byte)(1 << indexOf), unit.FGroup);
                        }
                    }
                }
                else
                {
                    AUnit.Killed();
                }

                AUnit.RemoveEnchantments();
                AUnit.Release();
                if (AoWE.AoWHSMap.FSeatedPlayer == FPlayer)
                {
                    AoWE.AoWHSMap.FSelectedArmy.Unselect();
                }

                AoWE.AoWHSMap.FPlayers.GetPlayers(FPlayer).UpdateIncome();
            }

            return TExecuteResult.erDone;
        }

        // NetworkE.pas:230


    }

