            if (Wall != null && !Wall.FStatus.Contains(TCombatObjectStatusElement.csDestroyed) && FWallSiegeObjectCount == 0)
            {
                FCombatResult = TCombatResult.crCannotBreachWall;
                Result = false;
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // AIGroup.pas:7268
        public void ExecuteCombatRound()
        {
            bool Idle;
            int I;
            int MoveCost;
            TCombatObjectList Objects;
            TCombatObject Obj;
            NewRound();
            Idle = true;
            Objects = new TCombatObjectList();
            var round = GetRound();
            SetLogbookHeader(AoWE.Format(AoWE.TranslateRStr(AoWE.P5RoundXRStr), [IntToStr(round)]));
            for (int PlayerIndex = 0, last = FCombatData.FTurnOrder.Count - 1; PlayerIndex <= last; PlayerIndex++)
            {
                NewTurn(FCombatData.FTurnOrder[PlayerIndex]);
                Objects.Clear();
                I = FCombatData.GetCount() - 1;
                for (; I >= 0; I -= 1)
                {
                    Obj = FCombatData.GetObjects(I);
                    if (Obj.FCombatPlayer == (sbyte)FCombatData.FCurrentPlayer && Obj.GetEnabled() && !Obj.GetLocked() && !Obj.FStatus.Contains(TCombatObjectStatusElement.csTurnDone))
                    {
                        Objects.Add(Obj);
                    }
                }

                MoveCost = 0;
                do
                {
                    I = Objects.Count;
                    while (I != 0)
                    {
                        I -= 1;
                        if (Objects.GetObject(I).GetEnabled())
                        {
                            if (Objects.GetObject(I).fcExecute(MoveCost))
                            {
                                Idle = false;
                                Objects.Delete(I);
                            }
                        }
                    }

                    MoveCost += 1;
                }
                while (!(MoveCost >= 3));
            }

            if (Idle)
            {
                if (GetRound() > GetRoundDistanceMax())
                {
                    Terminate();
                }
            }

            Objects.Free();
        }

        // intf_P5_07.inc:1073

    }

