            FDefender = A2;
            FAttackerDamageTypes = AoWE.MeleeDamageTypes(A1);
            FDefenderDamageTypes = TSet<TDamageType>.Of();
            if (FAttackerDamageTypes != TSet<TDamageType>.Of() && !FAttacker.GetLocked())
            {
                FAttackerStrikes = 2;
                if (FAttacker.GetAbilityEnabled(115))
                {
                    FAttackerStrikes += 1;
