        // AoWAb.PAS:1754
        public TStrikeCA CreateStrikeCA(int A1)
        {
            TStrikeCA Result = null;
            if (A1 < FCount)
            {
                ref var Strike = ref FStrikes[A1];
                switch (Strike.Side)
                {
                    case TCombatSideIndex.csAttacker:
                        if (!FAttacker.GetLocked())
                        {
                            Result = new TStrikeCA(null);
                            var damage = FAttacker.GetDamage();
                            var attack = FAttacker.GetAttack();
                            Result.Generate(FAttacker, FDefender, (sbyte)(attack + Strike.AttackBonus), (sbyte)(damage + Strike.DamageBonus), FAttackerDamageTypes);
                            if (FAttacker.GetAbilityEnabled(118))
                            {
                                Result.FStrikeMode = Result.FStrikeMode + TSet<TStrikeModeElement>.Of(TStrikeModeElement.smLifeStealing);
                            }
                        }

                        break;
                    case TCombatSideIndex.csDefender:
                        if (!FDefender.GetLocked())
                        {
                            Result = new TStrikeCA(null);
                            Result.SetDefensive(true);
                            var damage = FDefender.GetDamage();
                            var attack = FDefender.GetAttack();
                            Result.Generate(FDefender, FAttacker, (sbyte)(attack + Strike.AttackBonus), (sbyte)(damage + Strike.DamageBonus), FDefenderDamageTypes);
                        }

                        break;
                }
            }

            return Result;
        }

        // AoWAb.PAS:1786
        public void CalculateDV()
        {
            int I;
            int LifeStealingDV;
            bool LifeStealing;
            TCombatObject Source;
            FAttackerDV = 0;
            FDefenderDV = 0;
            I = 0;
            LifeStealingDV = 0;
            Source = FAttacker;
            if (Source != null)
            {
                LifeStealing = Source.GetAbilityEnabled(118);
                if (LifeStealing && FDefender is TCombatUnit && ((TCombatUnit)FDefender).FUnit.GetUnitType() == TUnitType.utMachine)
                {
                    LifeStealing = false;
                }
            }
            else
            {
                LifeStealing = FAttackerUnit.GetAbilityEnabled(118);
                if (LifeStealing && FDefenderUnit.GetUnitType() == TUnitType.utMachine)
                {
                    LifeStealing = false;
                }
            }

            while (I != FCount)
            {
                if (FStrikes[I].Side == TCombatSideIndex.csAttacker)
                {
                    FAttackerDV += FStrikes[I].DamageValue;
                    if (FStrikes[I].DamageValue > 100)
                    {
                        LifeStealingDV += 100;
                    }
                    else
                    {
                        LifeStealingDV += FStrikes[I].DamageValue;
                    }
                }
                else
                {
                    FDefenderDV += FStrikes[I].DamageValue;
                }

                I += 1;
            }

            if (LifeStealing && FDefenderDV > 0)
            {
                FDefenderDV -= LifeStealingDV;
                if (FDefenderDV <= 0)
                {
                    FDefenderDV = 1;
                }
            }
        }

        // AoWAb.PAS:1831
        public int GetAttackerDV()
        {
            if (FAttackerDV == -1)
            {
                CalculateDV();
            }

            return FAttackerDV;
        }

        // AoWAb.PAS:1837
        public int GetDefenderDV()
        {
            if (FDefenderDV == -1)
            {
                CalculateDV();
            }

            return FDefenderDV;
        }

