        // AoWAb.PAS:4894
        public override bool fcExecuteCombatCommand(TCombatObject A1, TFastCombatCommand A2)
        {
            TFastCombat Combat;
            TList Targets;
            TCombatObject Target;
            TCombatObject Other;
            int Count;
            TRangedAttackCA Action;
            bool Result = base.fcExecuteCombatCommand(A1, A2);
            if (Result)
            {
                Combat = (TFastCombat)A1.FCombat;
                Targets = new TList();
                Target = A2.FTarget;
                for (int I = Combat.FSides[(int)Target.GetSide()].GetCount() - 1; I >= 0; I--)
                {
                    var side = Target.GetSide();
                    Other = Combat.FSides[(int)side].GetObjects(I);
                    bool condition = Other != Target && Other.GetEnabled() && (int)(((uint)Other.FPosition) >> 4) == (int)(((uint)Target.FPosition) >> 4) && Other.fcRoundDistance() <= Combat.GetRoundDistance();
                    if (condition)
                    {
                        var immunityTypes = Other.GetImmunityTypes();
                        condition = FDamageTypesRA.Value - immunityTypes != TSet<TDamageType>.Of();
                    }

                    if (condition)
                    {
                        Targets.Add(Other);
                    }
                }

                Count = AoWE.AoWHSMap.Random(2) + 1;
                while (Count != 0 && Targets.Count != 0)
                {
                    Other = (TCombatObject)Targets[AoWE.AoWHSMap.Random(Targets.Count)];
                    Action = CreateRangedAttackCA(A1, Other, 2);
                    A1.FCombat.ExecuteCombatAction(Action);
                    Action.Release();
                    Targets.Remove(Other);
                    Count -= 1;
                }

                Targets.Free();
            }

            return Result;
        }

