            TCombatObject Target;
            base.fcGetDamageValueEx(A1, A2, A3, ref A4);
            if (A4.SourceDamage != 0)
            {
                Combat = (TFastCombat)A1.FCombat;
                Count = 0;
                for (int I = Combat.FSides[(int)A2.GetSide()].GetCount() - 1; I >= 0; I--)
                {
                    var side = A2.GetSide();
                    Target = Combat.FSides[(int)side].GetObjects(I);
                    bool condition = Target != A2 && Target.GetEnabled() && (int)(((uint)Target.FPosition) >> 4) == (int)(((uint)A2.FPosition) >> 4) && Target.fcRoundDistance() <= Combat.GetRoundDistance();
                    if (condition)
                    {
