    // (possession succeeded)
    public partial class TPossessCA : TSingleTargetCA
    {
        public new const int ClassID = 131765;

        public TPossessCA(TECustomNode owner) : base(owner)
        {}

        public bool FSuccessful;
        // AoWAb.PAS:2471
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwBool(ref FSuccessful, 20);
        }

        // AoWAb.PAS:2484
        public override void Execute(TCombat A1)
        {
            TCombatUnit Source;
            TCombatUnit Target;
            TAbstractUnit NewUnit;
            TAbstractUnit OldUnit;
            TPossessedAbilityData Data;
            int Experience;
            if (FSuccessful)
            {
                Source = (TCombatUnit)A1.FCombatData.FindID(FSourceID);
                Target = (TCombatUnit)A1.FCombatData.FindID(FTargetID);
                for (int I = 0; I <= 2; I++)
                {
                    ((TCommandAbility)AoWE.AoWHSSet.FAbilityControl.GetAbility(AoWE.CommandAbilityIDs[I])).ResetCommandedUnits(Target);
                }

                for (int I = 0; I <= 2; I++)
                {
                    ((TCommandAbility)AoWE.AoWHSSet.FAbilityControl.GetAbility(AoWE.CommandAbilityIDs[I])).Uncommand(Target);
                }

                NewUnit = Target.FUnit;
                NewUnit.AddRef();
                Target.SetUnit(null);
                Target.DestroyObject();
                OldUnit = Source.FUnit;
                OldUnit.AddRef();
                OldUnit.Killed();
                OldUnit.SetOwner(null);
                Source.SetUnit(NewUnit);
                if (OldUnit.FUnitStatus.Contains(TUnitStatusElement.usMoving))
                {
                    Source.FUnit.FUnitStatus = Source.FUnit.FUnitStatus + TSet<TUnitStatusElement>.Of(TUnitStatusElement.usMoving);
                }

                AoWE.AoWHSSet.FAbilityControl.GetAbility(107).Expand(Source.FUnit);
                if (OldUnit.GetAbilityEnabled(107))
                {
                    Data = (TPossessedAbilityData)OldUnit.GetAbilityData(107);
                    if (Data != null)
                    {
                        Experience = Data.FSourceExperience;
                    }
                    else
                    {
                        Experience = 0;
                    }
                }
                else
                {
                    Experience = OldUnit.GetExperience();
                }

                Data = (TPossessedAbilityData)Source.FUnit.GetAbilityData(107);
                if (Data != null)
                {
                    Data.FSourceExperience = Source.FUnit.GetUnitLevel() + Experience;
                }

                NewUnit.Release();
                OldUnit.Release();
            }
        }

