    // (unit IDs, players)
    public partial class THealingTE : TTokenEvent
    {
        public THealingTE(TECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131826;

        public int FSourceID;
        public byte FSourcePlayer;
        public int FTargetID;
        public byte FTargetPlayer;
        // AoWAb.PAS:3853
        public override void ReadWrite(TEStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FSourceID, 25);
            Stream.rwByte(ref FSourcePlayer, 26);
            Stream.rwInteger(ref FTargetID, 27);
            Stream.rwByte(ref FTargetPlayer, 28);
        }

        // AoWAb.PAS:3861
        public override TExecuteResult Execute(TTokenExecuter TE)
        {
            TExecuteResult Result;
            TAbstractUnit Source;
            TAbstractUnit Target;
            THealingAbility Ability;
            TImageSequenceAnimation Anim;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            base.Execute(TE);
            Source = AoWE.AoWHSMap.FUnitControl.FindUnit(FSourceID);
            Target = AoWE.AoWHSMap.FUnitControl.FindUnit(FTargetID);
            if (Source != null && (byte)Source.FPlayer == FSourcePlayer && Target != null && (byte)Target.FPlayer == FTargetPlayer)
            {
                Ability = (THealingAbility)AoWE.AoWHSSet.FAbilityControl.GetAbility(47);
                if (Ability.GetEnabled(Source))
                {
                    Ability.SetEnabled(Source, false);
                    Ability.HealUnit(Target);
                    Target.GetLocation(ref X, ref Y, ref L);
                    AoWE.AoWHSMap.ValidateObservation((sbyte)FSourcePlayer, X, Y, L, 0);
                    if (AoWE.AoWHSMap.Visible(X, Y, L, 0))
                    {
                        Anim = new TImageSequenceAnimation(null);
                        Anim.SetImageSequence(Ability.FImageSequences.GetImageSequence(0));
                        AoWE.AoWHSMap.PlaceHX(Anim, X, Y, L);
                    }

                    if ((byte)AoWE.AoWHSMap.FSeatedPlayer == FSourcePlayer || AoWE.AoWHSMap.Watching(X, Y, L, 0))
                    {
                        Ability.FSFXLibrary.Play(0);
                    }
                }

                Result = TExecuteResult.erDone;
            }
            else
            {
                Result = TExecuteResult.erDoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230


    }

    public partial class THealingUnitSelector : TUnitSelector
    {
        public THealingUnitSelector() : base()
        {}

        // AoWAb.PAS:3894
        public override bool CanSelectUnit(TUnit A1)
        {
            var unitType = A1.GetUnitType();
            if (!(TSet<TUnitType>.Of(TUnitType.utHumanoid, TUnitType.utCreature).Contains(unitType) && A1.GetHits() != A1.GetHitPoints()))
            {
                return false;
            }

            return true;
