        // AoWAb.PAS:3904
        public override bool Select()
        {
            bool Result;
            TAbstractUnit Source;
            TAbstractUnit Target;
            AnsiString Error = default;
            int I;
            THealingTE Event;
            Source = AoWE.AoWHSMap.FUnitControl.FindUnit(FSourceUnitID);
            if (CanSelect(ref Error) && !AoWE.AoWHSMap.FPlayers.GetPlayers(Source.FPlayer).GetBusy())
            {
                I = 0;
                Target = null;
                while (Target == null && I != FUnits.GetCount())
                {
                    if ((FSelection & (1 << I)) != 0)
                    {
                        Target = FUnits.GetUnit(I);
                    }

                    I += 1;
                }

                if (Target != null)
                {
                    Event = new THealingTE(null);
                    Event.FSourceID = Source.FUnitID;
                    Event.FSourcePlayer = (byte)Source.FPlayer;
                    Event.FTargetID = Target.FUnitID;
                    Event.FTargetPlayer = (byte)Target.FPlayer;
                    AoWE.AoWHSMap.FTokenManager.GetTokenControl(Source.FPlayer).AddEvent(Event);
                    Event.Release();
                    Result = true;
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

