                // { Original also reports player zero as unknown. }
                if (Data.FEnchantment.FSource <= 0)
                {
                    Result = AoWE.TranslateRStr(AoWE.UnknownRStr);
                }
                else
                {
                    if (Source != null && Source.FPlayer == Data.FEnchantment.FSource)
                    {
                        Result = AoWE.TranslateRStr(AoWE.P4ManaRStr);
                    }
                    else
                    {
                        Result = AoWE.AoWHSMap.FPlayers.GetPlayers(Data.FEnchantment.FSource).FLeader.FHeroName;
