        // Spells.PAS:674
        public int GetRandomSpell(int MinLevel, int MaxLevel, TSet<TMagicSphere> Spheres)
        {
            int Result;
            TIntegerList Candidates;
            TSpell Spell;
            Candidates = new TIntegerList();
            for (int I = this.FRegisteredSpells.Count - 1; I >= 0; I--)
            {
                Spell = (TSpell)this.FRegisteredSpells.List[I];
                if (Spell != null && Spheres.Contains(Spell.FMagicSphere) && Spell.FSpellLevel >= MinLevel && Spell.FSpellLevel <= MaxLevel)
                {
