        // Spells.PAS:1422
        public virtual bool AIRetrieveOptimalTargetUnit(TAbstractUnit Source, TUnitList Targets, ref TAbstractUnit Target, ref int Priority)
        {
            bool Result;
            TDoubleItemList List;
            int Value;
            List = new TDoubleItemList();
            for (int I = 0, last = Targets.GetCount() - 1; I <= last; I++)
            {
                if (ValidTargetUnit(Source, Targets.GetUnit(I)) && Targets.GetUnit(I).GetUnitType() != TUnitType.utMachine)
                {
                    Value = Targets.GetUnit(I).GetUnitLevel() + FAIValue;
                    List.AddAB(ObjectToInt(Targets.GetUnit(I)), Value);
                }
            }

            if (List.Count != 0)
            {
                List.SortDescendingItemB();
                Target = ReferenceFromId<TAbstractUnit>(List[0].A);
                Priority = List[0].B;
                Result = true;
            }
            else
            {
                Result = false;
            }

            List.Free();
            return Result;
        }

        // Spells.PAS:1269
        public void OnValidateTarget(TTargetSelectionControl Control, sbyte X, sbyte Y, sbyte L, ref bool Valid)
        {
            TAbstractUnit Source;
            TArmyHS Party;
            Source = AoWE.AoWHSMap.FUnitControl.FindUnit(Control.FSourceUnitID);
            if (Source != null)
            {
                if (AoWE.AoWHSMap.Visible(X, Y, L, 0))
                {
                    Party = ((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L)).GetArmyHS();
                    if (Party != null && (Party.FArmy.FPlayer == Source.FPlayer || !((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L)).GetMagicShieldActive()))
                    {
                        Valid = ValidTargetParty(Source, Party);
                    }
                    else
                    {
                        Valid = false;
                    }
                }
                else
                {
                    Valid = false;
                }
            }
            else
            {
                ResetTargetSelection();
            }
        }

        // Spells.PAS:1289
        public void OnTargetSelectionChange(TObject Sender)
        {
            TTargetSelectionControl Control;
            TAbstractUnit Source;
            TArmyHS Party;
            Control = (TTargetSelectionControl)Sender;
            Source = AoWE.AoWHSMap.FUnitControl.FindUnit(Control.FSourceUnitID);
            if (Source != null)
            {
                switch (Control.FChange)
                {
                    case TTargetSelectionChange.tscDeactivated:
                        ResetTargetSelection();
                        break;
                    case TTargetSelectionChange.tscSelected:
                        if (Control.FTargetX != -1)
                        {
                            Party = ((TAoWMapField)AoWE.AoWHSMap.MapContainer.GetField(Control.FTargetX, Control.FTargetY, Control.FTargetL)).GetArmyHS();
                            if (Party != null && ValidTargetParty(Source, Party))
                            {
                                TargetPartySelected(Source, Party);
                            }
                        }

                        break;
                }
            }
            else
            {
                ResetTargetSelection();
            }
        }

        // Spells.PAS:1310
        public void ResetTargetSelection()
        {
            var targetSelectionControl = AoWE.AoWHSMap.FTargetSelection;
            targetSelectionControl.FOnChange.Remove(OnTargetSelectionChange);
            targetSelectionControl.Deactivate();
        }

        // Spells.PAS:1318
        public void SetupTargetSelection(TAbstractUnit Source, TTargetSelectionControl Control)
        {
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            Control.Initialize(Source);
            Control.FTargetMode = Control.FTargetMode + TSet<TTargetSelectionModeElement>.Of(TTargetSelectionModeElement.tmExternalFloater);
            if (FTargetRange != -1)
            {
                Control.FTargetMode = Control.FTargetMode + TSet<TTargetSelectionModeElement>.Of(TTargetSelectionModeElement.tmValidateDistance);
                Control.FRange = FTargetRange;
            }
            else
            {
                Control.FRange = 0;
            }

            Source.GetLocation(ref X, ref Y, ref L);
            Control.FSourceX = X;
            Control.FSourceY = Y;
            Control.FSourceL = L;
            Control.FOnChange.Add(OnTargetSelectionChange);
            Control.FOnValidateTarget = OnValidateTarget;
            var format = AoWE.Format(AoWE.TranslateRStr(AoWE.P4SelectTargetPartyForXRStr), [FSpellName]);
            Control.FText.Text = format;
            Control.FTitle = FSpellName;
            Control.FCancelText = AoWE.TranslateRStr(AoWE.CancelRStr);
            Control.FSourceUnitID = Source.FUnitID;
            Control.FSourceImage = AoWE.AoWHSSet.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(20).GetPreviewImage();
            Control.FValidTargetImage = AoWE.AoWHSSet.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(21).GetPreviewImage();
            Control.FInvalidTargetImage = AoWE.AoWHSSet.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(22).GetPreviewImage();
        }
    }

    public partial class TResearchSpellAIPA : TAIPlayerAction, IAIPlayerActionClass
    {
        public TResearchSpellAIPA(TECustomNode owner) : base(owner)
        {}

        // Spells.PAS:1504
        public override bool Process()
        {
            TDoubleItemList Choices;
            TSpellList Spells;
            int Value;
            int Index;
            if (FControl.FPlayer.FPlayerIndex != 0 && FControl.FPlayer.FMagicControl.FResearchSpellID == 0)
            {
                Spells = new TSpellList();
                Choices = new TDoubleItemList();
                FControl.FPlayer.FMagicControl.ListResearchSpells(ref Spells, TSet<TSpellType>.Of(TSpellType.stCombat, TSpellType.stUnit, TSpellType.stGlobal));
                for (int I = 0, last = Spells.GetCount() - 1; I <= last; I++)
                {
                    Value = Spells.GetSpell(I).FCastDuration * 100 + 100;
                    var spell = Spells.GetSpell(I);
                    var netPowerToResearch = FControl.FPlayer.FMagicControl.GetNetPowerToResearch();
                    Value = Value - FControl.FPlayer.FMagicControl.ResearchTurns(netPowerToResearch, spell.FResearchCost);
                    if (Value <= 0)
                    {
                        Value = 1;
                    }

                    Choices.AddAB(Spells.GetSpell(I).FSpellID, Value);
                }

                if (Choices.Count != 0)
                {
                    RandSeed = AoWE.AoWHSMap.Random(16777215);
                    Index = Choices.RandomChanceItemB(0);
                    var item = Choices[Index];
                    FControl.FPlayer.FMagicControl.ExecuteResearchSpell(item.A);
                }

                Choices.Free();
                Spells.Free();
            }

            return false;
        }

        // Spells.PAS:1502
        // inherited player control
        public static new int Priority => 22;

    }

