            if (AoWE.AoWEngine.FCampaign.FDifficultyLevel == TCampaignDifficultyLevel.cdlEasy)
            {
                FTransferPointsMax = Round((double)FTransferPointsMax * 1.5);
            }

            if (AoWE.AoWEngine.FCampaign.FDifficultyLevel == TCampaignDifficultyLevel.cdlHard)
            {
                FTransferPointsMax = Round((double)FTransferPointsMax * 0.5);
            }

