                Player = (sbyte)(Player - 1);
            }

            Level = 1 + FCompletedScenarios.Count / 4;
            for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (I != Player)
                {
                    for (int J = 0, lastJ = AoWE.AoWHSSet.FSpellControl.GetCount() - 1; J <= lastJ; J++)
                    {
                        Spell = AoWE.AoWHSSet.FSpellControl.GetSpell(J);
                        bool condition = Spell != null && Spell.FSpellLevel <= Level;
                        if (condition)
                        {
                            var spherePicks = AoWE.AoWHSMap.FPlayers.GetPlayers(I).FLeader.GetSpherePicks(Spell.FMagicSphere);
                            condition = Spell.FSpellLevel <= spherePicks;
                        }

                        if (condition)
                        {
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.IndexOf(J) == -1)
                            {
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FMagicControl.FSpells.Add(J);
                            }
                        }
                    }
                }
            }

            for (int I = 1, last = AoWE.AoWHSMap.FPlayers.Count - 1; I <= last; I++)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType != TPlayerType.ptHuman && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)I, Player) != TDiplomaticRelation.drAlliance)
                {
                    if (FDifficultyLevel == TCampaignDifficultyLevel.cdlEasy)
                    {
                        switch (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType)
                        {
                            case TPlayerType.ptCPU2:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU1;
                                break;
                            case TPlayerType.ptCPU3:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU2;
                                break;
                            case TPlayerType.ptCPU4:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU3;
                                break;
                            case TPlayerType.ptCPU5:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU3;
                                break;
                        }
                    }

                    if (FDifficultyLevel == TCampaignDifficultyLevel.cdlHard)
                    {
                        switch (AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType)
                        {
                            case TPlayerType.ptCPU1:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU3;
                                break;
                            case TPlayerType.ptCPU2:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU4;
                                break;
                            case TPlayerType.ptCPU3:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU5;
                                break;
                            case TPlayerType.ptCPU4:
                                AoWE.AoWHSMap.FPlayers.GetPlayers(I).FPlayerType = TPlayerType.ptCPU5;
                                break;
                        }
                    }
                }
            }

            AoWE.AoWHSMap.SetupPlayerControl(FPlayMode, TPlayerConnectionType.pcLocal);
            for (int R = 0, last = AoWE.AoWHSMap.FRaces.Count - 1; R <= last; R++)
            {
                if (AoWE.AoWHSMap.FRaces.GetRace(R) != null)
                {
                    Race = AoWE.AoWHSMap.FRaces.GetRace(R);
                    if (Race != null)
                    {
                        for (int I = 0; I <= 11; I++)
                        {
                            if ((FRaceHistory.IndexOf((byte)I) != -1 || I == AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace) && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace == R || (FRaceHistory.IndexOf((byte)R) != -1 || AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace == R) && I == AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerRace)
                            {
                                Relation = Race.FDefaultRelations[I];
                                switch (Relation)
                                {
                                    case 0:
                                        Relation = 3;
                                        break;
                                    case 1:
                                        Relation = 3;
                                        break;
                                    case 2:
                                        Relation = 4;
                                        break;
                                    case 3:
                                        Relation = 4;
                                        break;
                                }

                                Race.FDefaultRelations[I] = Relation;
                            }
                        }
                    }
                }
            }

            AoWE.AoWHSMap.FAlliedVictory = AoWE.AoWHSMap.FCampaignSettings.FAlliedVictory;
            FTransferSettings.ExecuteSelection();
            FScenarioStarted = true;
        }

        // Diplomacy.pas:2416
        public virtual void FinishScenario()
        {
            sbyte Player;
            AnsiString FileName;
            FScenarioStarted = false;
            FCompletedScenarios.Add(FCurrentScenarioID);
            FTransferSettings.Retrieve();
            FStream.Clear();
            Player = (sbyte)(AoWE.AoWHSMap.FPlayers.Count - 1);
            while (Player > 1 && AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FPlayerType != TPlayerType.ptHuman)
            {
                Player = (sbyte)(Player - 1);
            }

            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
            if (FRaceHistory.IndexOf((byte)players.FPlayerRace) == -1)
            {
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
                FRaceHistory.Add((byte)fPlayersPlayers.FPlayerRace);
            }

            FileName = GetAutoSaveFileName(TCampaignAutoSaveType.casScenarioFinished);
            AoWE.AoWEngine.SaveCampaign(AoWE.AoWEngine.StartupDirectory + (AnsiString)"Save\\" + FileName);
        }

        // Diplomacy.pas:2432
        public virtual void RestartScenario()
        {
            if (FCompletedScenarios.Count != 0)
            {
                FCurrentScenarioID = FCompletedScenarios[FCompletedScenarios.Count - 1];
            }
            else
            {
                FCurrentScenarioID = 0;
            }

            FScenarioStarted = false;
            FStream.Clear();
        }

        // Diplomacy.pas:2285
        public virtual TAoWCampaignScenario AddScenario()
        {
            TAoWCampaignScenario Result = CreateScenario();
            Result.FID = FScenarios.CreateUniqueID();
            Result.SetOwner(FScenarios);
            return Result;
        }

        // Diplomacy.pas:2292
        public bool GetContainsMap() => FStream.Size != 0;

        // intf_P5_08.inc:107

    }

