        // Diplomacy.pas:613
        public override void MsgProc(ref TEMsg Msg, TEObject Sender)
        {
            bool Ignore;
            TEventLog Log;
            base.MsgProc(ref Msg, Sender);
            if (Msg.MsgID == 537001986 && Msg.Payload.Value == FSource && FReaction == TDiplomaticActionReaction.darNone)
            {
                Ignore = FActionType == TDiplomaticActionType.daOfferPeace && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drPeace;
                Ignore = Ignore || FActionType == TDiplomaticActionType.daBreakAllianceWithY && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) != TDiplomaticRelation.drAlliance;
                Ignore = Ignore || FActionType == TDiplomaticActionType.daDeclareWarToY && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) != TDiplomaticRelation.drWar;
                Ignore = Ignore || FActionType == TDiplomaticActionType.daProposeAlliance && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drAlliance;
                Ignore = Ignore || FActionType == TDiplomaticActionType.daMakeTribute;
                if (Ignore && (AoWE.AoWHSMap.FPlayMode != TPlayMode.pmSimultaneous || AoWE.AoWHSMap.FDay > FDay + 1))
                {
                    FReaction = TDiplomaticActionReaction.darIgnore;
                    Log = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    Assert(Log is TDiplomaticActionEventLog, (AnsiString)"", "Diplomacy.pas", 697);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).SetGems(players.FGems + FEscrowGold);
                    var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
                    FEscrowGold = 0;
                    FEscrowMana = 0;
                }
            }
        }

        // Diplomacy.pas:992
        public virtual void ExecuteSend(TDiplomaticActionTE TE)
        {
            TDiplomaticActionEventLog Log;
            if (FReaction == TDiplomaticActionReaction.darNone)
            {
                FEscrowGold = FGold;
                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).SetGems(players.FGems - FGold);
                FEscrowMana = FMana;
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana - FMana);
                switch (FActionType)
                {
                    case >= TDiplomaticActionType.daOfferPeace and <= TDiplomaticActionType.daMakeTribute:
                    case >= TDiplomaticActionType.daSendMessageAsY and <= TDiplomaticActionType.daDeclareWarToY:
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).PlayerSeen((sbyte)(byte)FSource);
                        if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5MessageSentRStr);
                            AoWE.AoWHSMap.ShowMessage(translateRStr);
                        }

                        Log = CreateEventLog();
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.AddEvent(Log);
                        if (FTarget == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            Log.Execute(false, false ? 1 : 0, null);
                        }

                        Log.Release();
                        AoWE.AoWHSMap.FDiplomaticRelationsChangedEvents.TriggerNotifyEvents(this);
                        break;
                    case TDiplomaticActionType.daBreakAlliance:
                        AoWE.AoWHSMap.LockRelationsChanged();
                    {
                        for (int I = 0, last = AoWE.AoWHSMap.FRaces.Count - 1; I <= last; I++)
                        {
                            var playerRelationValue = AoWE.AoWHSMap.FRaces.GetRace(I).GetPlayerRelationValue(FSource);
                            var relationModifier = GetRelationModifier(FSource, (sbyte)I);
                            AoWE.AoWHSMap.FRaces.GetRace(I).SetPlayerRelationValue(FSource, relationModifier + playerRelationValue);
                            var playerRelationValue2 = AoWE.AoWHSMap.FRaces.GetRace(I).GetPlayerRelationValue(FTarget);
                            var relationModifier2 = GetRelationModifier(FTarget, (sbyte)I);
                            AoWE.AoWHSMap.FRaces.GetRace(I).SetPlayerRelationValue(FTarget, relationModifier2 + playerRelationValue2);
                        }
                    }

                        AoWE.AoWHSMap.UnlockRelationsChanged();
                        AoWE.AoWHSMap.FPlayers.SetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget, TDiplomaticRelation.drPeace);
                        if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5AllianceBrokenRStr);
                            AoWE.AoWHSMap.ShowMessage(translateRStr);
                        }

                        Log = CreateEventLog();
                        AoWE.BroadcastDiplomaticEvent(Log, -1);
                        if (FTarget == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            Log.Execute(false, false ? 1 : 0, null);
                        }

                        Log.Release();
                        break;
                    case TDiplomaticActionType.daDeclareWar:
                        AoWE.AoWHSMap.LockRelationsChanged();
                    {
                        for (int I = 0, last = AoWE.AoWHSMap.FRaces.Count - 1; I <= last; I++)
                        {
                            var playerRelationValue = AoWE.AoWHSMap.FRaces.GetRace(I).GetPlayerRelationValue(FSource);
                            var relationModifier = GetRelationModifier(FSource, (sbyte)I);
                            AoWE.AoWHSMap.FRaces.GetRace(I).SetPlayerRelationValue(FSource, relationModifier + playerRelationValue);
                            var playerRelationValue2 = AoWE.AoWHSMap.FRaces.GetRace(I).GetPlayerRelationValue(FTarget);
                            var relationModifier2 = GetRelationModifier(FTarget, (sbyte)I);
                            AoWE.AoWHSMap.FRaces.GetRace(I).SetPlayerRelationValue(FTarget, relationModifier2 + playerRelationValue2);
                        }
                    }

                        AoWE.AoWHSMap.UnlockRelationsChanged();
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).PlayerSeen((sbyte)(byte)FSource);
                        AoWE.AoWHSMap.FPlayers.SetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget, TDiplomaticRelation.drWar);
                        if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5WarDeclaredRStr);
                            AoWE.AoWHSMap.ShowMessage(translateRStr);
                        }

                        Log = CreateEventLog();
                        AoWE.BroadcastDiplomaticEvent(Log, -1);
                        if (FTarget == AoWE.AoWHSMap.FSeatedPlayer)
                        {
                            Log.Execute(false, false ? 1 : 0, null);
                        }

                        Log.Release();
                        break;
                }
            }
        }

        // Diplomacy.pas:826
        public virtual void ExecuteAccept(TDiplomaticActionTE TE)
        {
            TDiplomaticActionEventLog Log;
            TDiplomaticAction Action = default;
            FReaction = TDiplomaticActionReaction.darAccept;
            AoWE.RetrieveDefaultDiplomaticActionMessage(FSource, FTarget, FOtherPlayer, FActionType, FReaction, FMessage);
            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget);
            AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).SetGems(players.FGems + FEscrowGold);
            FEscrowGold = 0;
            var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget);
            AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
            FEscrowMana = 0;
            AoWE.AoWHSMap.LockRelationsChanged();
            for (int I = 0, last = AoWE.AoWHSMap.FRaces.Count - 1; I <= last; I++)
            {
                var playerRelationValue = AoWE.AoWHSMap.FRaces.GetRace(I).GetPlayerRelationValue(FSource);
                var relationModifier = GetRelationModifier(FSource, (sbyte)I);
                AoWE.AoWHSMap.FRaces.GetRace(I).SetPlayerRelationValue(FSource, relationModifier + playerRelationValue);
                var playerRelationValue2 = AoWE.AoWHSMap.FRaces.GetRace(I).GetPlayerRelationValue(FTarget);
                var relationModifier2 = GetRelationModifier(FTarget, (sbyte)I);
                AoWE.AoWHSMap.FRaces.GetRace(I).SetPlayerRelationValue(FTarget, relationModifier2 + playerRelationValue2);
            }

            AoWE.AoWHSMap.UnlockRelationsChanged();
            switch (FActionType)
            {
                case TDiplomaticActionType.daOfferPeace:
                    AoWE.AoWHSMap.FPlayers.SetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget, TDiplomaticRelation.drPeace);
                    Log = CreateEventLog();
                    AoWE.BroadcastDiplomaticEvent(Log, -1);
                    if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        Log.Execute(false, false ? 1 : 0, null);
                    }

                    Log.Release();
                    Log = (TDiplomaticActionEventLog)AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    if (Log != null)
                    {
                        Log.SetOwner(null);
                    }

                    break;
                case TDiplomaticActionType.daProposeAlliance:
                    AoWE.AoWHSMap.FPlayers.SetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget, TDiplomaticRelation.drAlliance);
                    Log = CreateEventLog();
                    AoWE.BroadcastDiplomaticEvent(Log, -1);
                    if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        Log.Execute(false, false ? 1 : 0, null);
                    }

                    Log.Release();
                    Log = (TDiplomaticActionEventLog)AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    if (Log != null)
                    {
                        Log.SetOwner(null);
                    }

                    break;
                case TDiplomaticActionType.daDeclareWarToY:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) != TDiplomaticRelation.drWar)
                    {
                        AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer).PlayerSeen((sbyte)(byte)FTarget);
                        AoWE.AoWHSMap.FPlayers.SetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer, TDiplomaticRelation.drWar);
                        Action = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).CreateDiplomaticAction(TDiplomaticActionType.daDeclareWar, FOtherPlayer, -1);
                        if (Action != null)
                        {
                            Log = Action.CreateEventLog();
                            AoWE.BroadcastDiplomaticEvent(Log, FSource);
                            if (FOtherPlayer == AoWE.AoWHSMap.FSeatedPlayer)
                            {
                                Log.Execute(false, false ? 1 : 0, null);
                            }

                            Log.Release();
                            Action.Release();
                        }
                    }

                    Log = (TDiplomaticActionEventLog)AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    Log.SetDiplomaticAction(this);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
                    if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        Log.Execute(false, false ? 1 : 0, null);
                    }

                    break;
                case TDiplomaticActionType.daMakeTribute:
                    Log = (TDiplomaticActionEventLog)AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    Log.SetDiplomaticAction(this);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
                    if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        Log.Execute(false, false ? 1 : 0, null);
                    }

                    break;
                case TDiplomaticActionType.daBreakAllianceWithY:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) == TDiplomaticRelation.drAlliance)
                    {
                        AoWE.AoWHSMap.FPlayers.SetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer, TDiplomaticRelation.drPeace);
                        Action = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).CreateDiplomaticAction(TDiplomaticActionType.daBreakAlliance, FOtherPlayer, -1);
                        if (Action != null)
                        {
                            Log = Action.CreateEventLog();
                            AoWE.BroadcastDiplomaticEvent(Log, FSource);
                            if (FOtherPlayer == AoWE.AoWHSMap.FSeatedPlayer)
                            {
                                Log.Execute(false, false ? 1 : 0, null);
                            }

                            Log.Release();
                            Action.Release();
                        }
                    }

                    Log = (TDiplomaticActionEventLog)AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    Log.SetDiplomaticAction(this);
                    AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
                    if (FSource == AoWE.AoWHSMap.FSeatedPlayer)
                    {
                        Log.Execute(false, false ? 1 : 0, null);
                    }

                    break;
            }
        }

        // Diplomacy.pas:950
        public virtual void ExecuteReject(TDiplomaticActionTE TE)
        {
            TDiplomaticActionEventLog Log;
            switch (FActionType)
            {
                case TDiplomaticActionType.daOfferPeace:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drPeace)
                    {
                        FReaction = TDiplomaticActionReaction.darReject;
                    }
                    else
                    {
                        FReaction = TDiplomaticActionReaction.darIgnore;
                    }

                    break;
                case TDiplomaticActionType.daProposeAlliance:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drAlliance)
                    {
                        FReaction = TDiplomaticActionReaction.darReject;
                    }
                    else
                    {
                        FReaction = TDiplomaticActionReaction.darIgnore;
                    }

                    break;
                case TDiplomaticActionType.daDeclareWarToY:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) != TDiplomaticRelation.drWar)
                    {
                        FReaction = TDiplomaticActionReaction.darReject;
                    }
                    else
                    {
                        FReaction = TDiplomaticActionReaction.darIgnore;
                    }

                    break;
                case TDiplomaticActionType.daBreakAllianceWithY:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) == TDiplomaticRelation.drAlliance)
                    {
                        FReaction = TDiplomaticActionReaction.darReject;
                    }
                    else
                    {
                        FReaction = TDiplomaticActionReaction.darIgnore;
                    }

                    break;
                default:
                    FReaction = TDiplomaticActionReaction.darReject;
                    break;
            }

            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
            AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).SetGems(players.FGems + FEscrowGold);
            FEscrowGold = 0;
            var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
            AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
            FEscrowMana = 0;
            AoWE.RetrieveDefaultDiplomaticActionMessage(FSource, FTarget, FOtherPlayer, FActionType, FReaction, FMessage);
            Log = (TDiplomaticActionEventLog)AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
            Log.SetDiplomaticAction(this);
            AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
        }

        // Diplomacy.pas:722
        public virtual void ExecuteAI(sbyte Player)
        {
            TByteList Peace;
            TByteList War;
            TByteList Unknown;
            TByteList IdealPeace;
            TByteList IdealWar;
            TDiplomaticRelation Relation;
            TDiplomaticActionReaction Reaction;
            TDiplomaticAction Last;
            int Chance;
            AnsiString ErrorText = default;
            Reaction = FReaction;
            if (Reaction == TDiplomaticActionReaction.darNone)
            {
                Relation = AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget);
                IdealPeace = new TByteList();
                IdealWar = new TByteList();
                Peace = new TByteList();
                War = new TByteList();
                Unknown = new TByteList();
                AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.ListPeaceWarUnknownPlayers(Peace, War, Unknown);
                AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
                switch (FActionType)
                {
                    case TDiplomaticActionType.daOfferPeace:
                        Last = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FDiplomaticActions.FindLastAction(TDiplomaticActionType.daOfferPeace, TDiplomaticActionReaction.darNone, FTarget, FSource, -1);
                        if (IdealPeace.IndexOf((byte)FSource) != -1 || (Last != null && AoWE.AoWHSMap.FDay - Last.FDay <= 1))
                        {
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.CanOfferPeace((byte)FSource))
                            {
                                Accept(ref ErrorText);
                            }
                            else
                            {
                                Reject(ref ErrorText);
                            }
                        }
                        else
                        {
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.CanOfferPeace((byte)FSource))
                            {
                                if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)FSource, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drAlliance)) + 1 < AoWE.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)FSource, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drWar)))
                                {
                                    Last = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FDiplomaticActions.FindLastAction(TDiplomaticActionType.daOfferPeace, TDiplomaticActionReaction.darReject, FSource, FTarget, -1);
                                    if (Last == null || AoWE.AoWHSMap.FDay - Last.FDay > 8)
                                    {
                                        // { Original bug: escrow gold is counted twice. }
                                        if (AoWE.AoWHSMap.Random(3) == 1 && AoWE.AoWHSMap.Random(250) + 100 < FEscrowGold + FEscrowGold)
                                        {
                                            Accept(ref ErrorText);
                                        }
                                        else
                                        {
                                            Reject(ref ErrorText);
                                        }
                                    }
                                    else
                                    {
                                        Reject(ref ErrorText);
                                    }
                                }
                                else
                                {
                                    Reject(ref ErrorText);
                                }
                            }
                            else
                            {
                                Reject(ref ErrorText);
                            }
                        }

                        break;
                    case TDiplomaticActionType.daProposeAlliance:
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.CanProposeAlliance((byte)FSource))
                        {
                            RandSeed = (int)(((uint)(AoWE.AoWHSMap.FInitialRandomSeed + AoWE.AoWHSMap.FDay + FSource + FTarget)) >> 2);
                            Chance = (FEscrowGold + FEscrowMana) / 25 + 30;
                            if (Chance > 60)
                            {
                                Chance = 60;
                            }

                            if (Random(100) < Chance)
                            {
                                Accept(ref ErrorText);
                            }
                            else
                            {
                                Reject(ref ErrorText);
                            }
                        }
                        else
                        {
                            Reject(ref ErrorText);
                        }

                        break;
                    case TDiplomaticActionType.daDeclareWarToY:
                        if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) == TDiplomaticRelation.drWar)
                        {
                            Accept(ref ErrorText);
                        }
                        else
                        {
                            if (IdealWar.IndexOf((byte)FOtherPlayer) != -1)
                            {
                                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FAIControl.CanDeclareWar((byte)FOtherPlayer))
                                {
                                    if (AoWE.AoWHSMap.Random(5) == 1 && AoWE.AoWHSMap.Random(550) + 250 < FEscrowGold + FEscrowMana)
                                    {
                                        Accept(ref ErrorText);
                                    }
                                    else
                                    {
                                        Reject(ref ErrorText);
                                    }
                                }
                                else
                                {
                                    Reject(ref ErrorText);
                                }
                            }
                            else
                            {
                                Reject(ref ErrorText);
                            }
                        }

                        break;
                    case TDiplomaticActionType.daMakeTribute:
                        if (TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drAlliance).Contains(Relation))
                        {
                            Accept(ref ErrorText);
                        }
                        else
                        {
                            if (AoWE.AoWHSMap.Random(200) + 50 < FGold + FMana)
                            {
                                Accept(ref ErrorText);
                            }
                            else
                            {
                                Reject(ref ErrorText);
                            }
                        }

                        break;
                    case TDiplomaticActionType.daBreakAllianceWithY:
                        if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) != TDiplomaticRelation.drAlliance)
                        {
                            Accept(ref ErrorText);
                        }
                        else
                        {
                            Reject(ref ErrorText);
                        }

                        break;
                    case TDiplomaticActionType.daDeclareWar:
                        UpdateAIDiplomaticActionsLog(Player);
                        break;
                }

                Peace.Free();
                War.Free();
                Unknown.Free();
                IdealPeace.Free();
                IdealWar.Free();
            }
            else
            {
                if (TSet<TDiplomaticActionReaction>.Of(TDiplomaticActionReaction.darReject, TDiplomaticActionReaction.darIgnore).Contains(Reaction))
                {
                    switch (FActionType)
                    {
                        case TDiplomaticActionType.daOfferPeace:
                            var diplomaticRelation = AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget);
                            if (!TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace, TDiplomaticRelation.drWar).Contains(diplomaticRelation))
                            {
                                Last = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).CreateDiplomaticAction(TDiplomaticActionType.daDeclareWar, FTarget, -1);
                                if (Last != null)
                                {
                                    Last.Send(ref ErrorText);
                                    Last.Release();
                                }
                            }

                            break;
                    }
                }
            }
        }

        // Diplomacy.pas:1055
        public virtual bool CanSend(ref AnsiString ErrorText)
        {
            bool Result;
            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FGems >= FGold)
            {
                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FMagicControl.FMana >= FMana)
                {
                    Result = true;
                    if (FActionType == TDiplomaticActionType.daMakeTribute && FGold == 0 && FMana == 0)
                    {
                        ErrorText = AoWE.TranslateRStr(AoWE.P5NoGoldManaSpecifiedRStr);
                        Result = false;
                    }
                }
                else
                {
                    Result = false;
                    ErrorText = AoWE.TranslateRStr(AoWE.P5NotEnoughManaRStr);
                }
            }
            else
            {
                Result = false;
                ErrorText = AoWE.TranslateRStr(AoWE.P5NotEnoughGoldRStr);
            }

            return Result;
        }

        // Diplomacy.pas:1081
        public virtual bool Send(ref AnsiString ErrorText)
        {
            bool Result;
            TDiplomaticActionTE TE;
            if (CanSend(ref ErrorText) && !AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).GetBusy())
            {
                FDay = AoWE.AoWHSMap.FDay;
                TE = new TDiplomaticActionTE(null);
                TE.SetDiplomaticAction(this);
                TE.FOperation = 0;
                AoWE.AoWHSMap.FTokenManager.TokenControls[FSource].AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:920
        public virtual bool CanAccept(ref AnsiString ErrorText) => true;

        // Diplomacy.pas:923
        public virtual bool Accept(ref AnsiString ErrorText)
        {
            bool Result;
            TDiplomaticActionTE TE;
            if (CanAccept(ref ErrorText) && !AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).GetBusy())
            {
                TE = new TDiplomaticActionTE(null);
                TE.SetDiplomaticAction(this);
                TE.FOperation = 1;
                AoWE.AoWHSMap.FTokenManager.TokenControls[FTarget].AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:974
        public virtual bool CanReject(ref AnsiString ErrorText) => true;

        // Diplomacy.pas:977
        public virtual bool Reject(ref AnsiString ErrorText)
        {
            bool Result;
            TDiplomaticActionTE TE;
            if (CanReject(ref ErrorText) && !AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).GetBusy())
            {
                TE = new TDiplomaticActionTE(null);
                TE.SetDiplomaticAction(this);
                TE.FOperation = 2;
                AoWE.AoWHSMap.FTokenManager.TokenControls[FTarget].AddEvent(TE);
                TE.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:505
        public AnsiString GetName(sbyte Player)
        {
            AnsiString Result;
            switch (FActionType)
            {
                case TDiplomaticActionType.daDeclareWar:
                    Result = AoWE.TranslateRStr(AoWE.P5DeclareWarRStr);
                    break;
                case TDiplomaticActionType.daOfferPeace:
                    Result = AoWE.TranslateRStr(AoWE.P5OfferPeaceRStr);
                    break;
                case TDiplomaticActionType.daProposeAlliance:
                    Result = AoWE.TranslateRStr(AoWE.P5ProposeAllianceRStr);
                    break;
                case TDiplomaticActionType.daSendMessage:
                    Result = AoWE.TranslateRStr(AoWE.P5SendMessageRStr);
                    break;
                case TDiplomaticActionType.daThreatenToAttack:
                    Result = AoWE.TranslateRStr(AoWE.P5ThreatenToAttackRStr);
                    break;
                case TDiplomaticActionType.daMakeTribute:
                    Result = AoWE.TranslateRStr(AoWE.P5MakeTributeRStr);
                    break;
                case TDiplomaticActionType.daBreakAlliance:
                    Result = AoWE.TranslateRStr(AoWE.P5BreakAllianceRStr);
                    break;
                case TDiplomaticActionType.daBreakAllianceWithY:
                    var name = AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer).GetName();
                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5SuggestAllianceBreakWithYRStr), [name]);
                    break;
                case TDiplomaticActionType.daDeclareWarToY:
                    var name2 = AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer).GetName();
                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5SuggestWarWithYRStr), [name2]);
                    break;
                case TDiplomaticActionType.daSendMessageAsY:
                    var name3 = AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer).GetName();
                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5SendMessageAsXRStr), [name3]);
                    break;
                default:
                    Result = (AnsiString)"";
                    break;
            }

            return Result;
        }

        // Diplomacy.pas:527
        public int GetRelationModifier(sbyte Player, sbyte Race)
        {
            int Modifier;
            int Result = 0;
            switch (FActionType)
            {
                case TDiplomaticActionType.daBreakAlliance:
                    if (Player == FSource && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) == TDiplomaticRelation.drAlliance)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FPlayerRace != Race)
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget);
                            Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * -40) * 0.01);
                        }
                        else
                        {
                            Result = -40;
                        }
                    }

                    break;
                case TDiplomaticActionType.daBreakAllianceWithY:
                    if (Player == FTarget && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) == TDiplomaticRelation.drAlliance)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer).FPlayerRace != Race)
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer);
                            Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * -40) * 0.01);
                        }
                        else
                        {
                            Result = -40;
                        }
                    }

                    break;
                case TDiplomaticActionType.daDeclareWar:
                    if (Player == FSource && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drWar)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) == TDiplomaticRelation.drAlliance)
                        {
                            Modifier = -60;
                        }
                        else
                        {
                            Modifier = -20;
                        }

                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FPlayerRace != Race)
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget);
                            Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * Modifier) * 0.01);
                        }
                        else
                        {
                            Result = Modifier;
                        }
                    }
                    else
                    {
                        if (Player == FTarget && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drWar && AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FPlayerRace == Race)
                        {
                            Result = -20;
                        }
                    }

                    break;
                case TDiplomaticActionType.daDeclareWarToY:
                    if (Player == FTarget && AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) != TDiplomaticRelation.drWar)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FTarget, (sbyte)(byte)FOtherPlayer) == TDiplomaticRelation.drAlliance)
                        {
                            Modifier = -60;
                        }
                        else
                        {
                            Modifier = -20;
                        }

                        if (AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer).FPlayerRace != Race)
                        {
                            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FOtherPlayer);
                            Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * Modifier) * 0.01);
                        }
                        else
                        {
                            Result = Modifier;
                        }
                    }

                    break;
                case TDiplomaticActionType.daProposeAlliance:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drAlliance)
                    {
                        if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) == TDiplomaticRelation.drWar)
                        {
                            Modifier = 30;
                        }
                        else
                        {
                            Modifier = 20;
                        }

                        if (Player == FSource)
                        {
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FPlayerRace != Race)
                            {
                                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget);
                                Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * Modifier) * 0.01);
                            }
                            else
                            {
                                Result = Modifier;
                            }
                        }
                        else
                        {
                            if (Player == FTarget)
                            {
                                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FPlayerRace != Race)
                                {
                                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
                                    Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * Modifier) * 0.01);
                                }
                                else
                                {
                                    Result = Modifier;
                                }
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daOfferPeace:
                    if (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget) != TDiplomaticRelation.drPeace)
                    {
                        if (Player == FSource)
                        {
                            if (AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget).FPlayerRace != Race)
                            {
                                var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FTarget);
                                Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * 10) * 0.01);
                            }
                            else
                            {
                                Result = 10;
                            }
                        }
                        else
                        {
                            if (Player == FTarget)
                            {
                                if (AoWE.AoWHSMap.FPlayers.GetPlayers(FSource).FPlayerRace != Race)
                                {
                                    var players = AoWE.AoWHSMap.FPlayers.GetPlayers(FSource);
                                    Result = Round((double)((AoWE.AoWHSMap.FRaces.GetRace(Race).GetRelationValue(players.FPlayerRace) - 50) * 10) * 0.01);
                                }
                                else
                                {
                                    Result = 10;
                                }
                            }
                        }
                    }

                    break;
            }

            return Result;
        }

