        // Diplomacy.pas:1265
        public override AnsiString GetText()
        {
            AnsiString Result = default;
            TDiplomaticAction Action;
            Action = FAction;
            switch (Action.FActionType)
            {
                case TDiplomaticActionType.daDeclareWar:
                    Result = AoWE.TranslateRStr(AoWE.P5WarRStr);
                    break;
                case TDiplomaticActionType.daProposeAlliance:
                    Result = AoWE.TranslateRStr(AoWE.P5AllianceProposalRStr);
                    if (Action.FReaction == TDiplomaticActionReaction.darReject)
                    {
                        var translateRStr = AoWE.TranslateRStr(AoWE.P5AllianceProposalRStr);
                        Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XRejectedRStr), [translateRStr]);
                    }
                    else
                    {
                        if (Action.FReaction == TDiplomaticActionReaction.darAccept)
                        {
                            if (Action.FSource == AoWE.AoWHSMap.FSeatedPlayer)
                            {
                                var translateRStr = AoWE.TranslateRStr(AoWE.P5AllianceProposalRStr);
                                Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XAcceptedRStr), [translateRStr]);
                            }
                            else
                            {
                                Result = AoWE.TranslateRStr(AoWE.P5MadeAllianceRStr);
                            }
                        }
                        else
                        {
                            if (Action.FReaction == TDiplomaticActionReaction.darIgnore)
                            {
                                var translateRStr = AoWE.TranslateRStr(AoWE.P5AllianceProposalRStr);
                                Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XIgnoredRStr), [translateRStr]);
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daOfferPeace:
                    if (Action.FReaction == TDiplomaticActionReaction.darNone)
                    {
                        Result = AoWE.TranslateRStr(AoWE.P5PeaceOfferRStr);
                    }
                    else
                    {
                        if (Action.FReaction == TDiplomaticActionReaction.darReject)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5PeaceOfferRStr);
                            Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XRejectedRStr), [translateRStr]);
                        }
                        else
                        {
                            if (Action.FReaction == TDiplomaticActionReaction.darAccept)
                            {
                                if (Action.FSource == AoWE.AoWHSMap.FSeatedPlayer)
                                {
                                    var translateRStr = AoWE.TranslateRStr(AoWE.P5PeaceOfferRStr);
                                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XAcceptedRStr), [translateRStr]);
                                }
                                else
                                {
                                    Result = AoWE.TranslateRStr(AoWE.P5PeaceRStr);
                                }
                            }
                            else
                            {
                                if (Action.FReaction == TDiplomaticActionReaction.darIgnore)
                                {
                                    var translateRStr = AoWE.TranslateRStr(AoWE.P5PeaceOfferRStr);
                                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XIgnoredRStr), [translateRStr]);
                                }
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daMakeTribute:
                    if (Action.FReaction == TDiplomaticActionReaction.darNone)
                    {
                        Result = AoWE.TranslateRStr(AoWE.P5TributeRStr);
                    }
                    else
                    {
                        if (Action.FReaction == TDiplomaticActionReaction.darReject)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5TributeRStr);
                            Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XRejectedRStr), [translateRStr]);
                        }
                        else
                        {
                            if (Action.FReaction == TDiplomaticActionReaction.darAccept)
                            {
                                var translateRStr = AoWE.TranslateRStr(AoWE.P5TributeRStr);
                                Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XAcceptedRStr), [translateRStr]);
                            }
                            else
                            {
                                if (Action.FReaction == TDiplomaticActionReaction.darIgnore)
                                {
                                    var translateRStr = AoWE.TranslateRStr(AoWE.P5TributeRStr);
                                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XIgnoredRStr), [translateRStr]);
                                }
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daDeclareWarToY:
                    if (Action.FReaction == TDiplomaticActionReaction.darNone)
                    {
                        Result = AoWE.TranslateRStr(AoWE.P5DeclareWarSuggestionRStr);
                    }
                    else
                    {
                        if (Action.FReaction == TDiplomaticActionReaction.darReject)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5DeclareWarRStr);
                            Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XRejectedRStr), [translateRStr]);
                        }
                        else
                        {
                            if (Action.FReaction == TDiplomaticActionReaction.darAccept)
                            {
                                var translateRStr = AoWE.TranslateRStr(AoWE.P5DeclareWarRStr);
                                Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XAcceptedRStr), [translateRStr]);
                            }
                            else
                            {
                                if (Action.FReaction == TDiplomaticActionReaction.darIgnore)
                                {
                                    var translateRStr = AoWE.TranslateRStr(AoWE.P5DeclareWarRStr);
                                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XIgnoredRStr), [translateRStr]);
                                }
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daBreakAllianceWithY:
                    if (Action.FReaction == TDiplomaticActionReaction.darNone)
                    {
                        Result = AoWE.TranslateRStr(AoWE.P5BreakAllianceSuggestionRStr);
                    }
                    else
                    {
                        if (Action.FReaction == TDiplomaticActionReaction.darReject)
                        {
                            var translateRStr = AoWE.TranslateRStr(AoWE.P5BreakAllianceRStr);
                            Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XRejectedRStr), [translateRStr]);
                        }
                        else
                        {
                            if (Action.FReaction == TDiplomaticActionReaction.darAccept)
                            {
                                var translateRStr = AoWE.TranslateRStr(AoWE.P5BreakAllianceRStr);
                                Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XAcceptedRStr), [translateRStr]);
                            }
                            else
                            {
                                if (Action.FReaction == TDiplomaticActionReaction.darIgnore)
                                {
                                    var translateRStr = AoWE.TranslateRStr(AoWE.P5BreakAllianceRStr);
                                    Result = AoWE.Format(AoWE.TranslateRStr(AoWE.P5XIgnoredRStr), [translateRStr]);
                                }
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daBreakAlliance:
                    Result = AoWE.TranslateRStr(AoWE.P5AllianceBrokenRStr);
                    break;
                case TDiplomaticActionType.daSendMessage:
                    Result = AoWE.TranslateRStr(AoWE.P5MessageRStr);
                    break;
                case TDiplomaticActionType.daSendMessageAsY:
                    Result = AoWE.TranslateRStr(AoWE.P5MessageRStr);
                    break;
                case TDiplomaticActionType.daThreatenToAttack:
                    Result = AoWE.TranslateRStr(AoWE.P5ThreatRStr);
                    break;
                default:
                    Result = (AnsiString)"TDiplomaticActionEventLog";
                    break;
            }

            return Result;
        }

