        public override int GetTextColor()
        {
            int Result;
            int Race;
            if (FAction.FActionType == TDiplomaticActionType.daSendMessageAsY)
            {
                bool condition = FAction.FOtherPlayer > 0;
                if (condition)
                {
                    var count = AoWE.AoWHSMap.FPlayers.Count;
                    condition = FAction.FOtherPlayer < count;
                }

                if (condition)
                {
                    Race = AoWE.AoWHSMap.FPlayers.GetPlayers(FAction.FOtherPlayer).FPlayerRace;
                }
                else
                {
                    Race = 12;
                }

                Result = AoWE.P5RaceColors[Race];
            }
            else
            {
                if (FAction.FReaction == TDiplomaticActionReaction.darAccept)
                {
                    bool condition = FAction.FTarget > 0;
                    if (condition)
                    {
                        var count = AoWE.AoWHSMap.FPlayers.Count;
                        condition = FAction.FTarget < count;
                    }

                    if (condition)
                    {
                        Race = AoWE.AoWHSMap.FPlayers.GetPlayers(FAction.FTarget).FPlayerRace;
                    }
                    else
                    {
                        Race = 12;
                    }

                    Result = AoWE.P5RaceColors[Race];
                }
                else
                {
                    if (AoWE.AoWHSMap.FSeatedPlayer != FAction.FSource)
                    {
                        bool condition = FAction.FSource > 0;
                        if (condition)
                        {
                            var count = AoWE.AoWHSMap.FPlayers.Count;
                            condition = FAction.FSource < count;
                        }

                        if (condition)
                        {
                            Race = AoWE.AoWHSMap.FPlayers.GetPlayers(FAction.FSource).FPlayerRace;
                        }
                        else
                        {
                            Race = 12;
                        }

                        Result = AoWE.P5RaceColors[Race];
                    }
                    else
                    {
                        bool condition = FAction.FTarget > 0;
                        if (condition)
                        {
                            var count = AoWE.AoWHSMap.FPlayers.Count;
                            condition = FAction.FTarget < count;
                        }

                        if (condition)
                        {
                            Race = AoWE.AoWHSMap.FPlayers.GetPlayers(FAction.FTarget).FPlayerRace;
                        }
                        else
                        {
                            Race = 12;
                        }

                        Result = AoWE.P5RaceColors[Race];
                    }
                }
            }

            return Result;
        }

