        // Diplomacy.pas:1414
        public override bool Execute(bool Mode, TExecuteTrigger Trigger, TExecuteDoneEvent Done)
        {
            bool Result = default;
            bool Show;
            Show = Trigger == TExecuteTrigger.etUser;
            if (AoWE.AoWHSMap.FSeatedPlayer == FAction.FTarget || AoWE.AoWHSMap.FSeatedPlayer == FAction.FSource)
            {
                Show = Show || AoWE.AoWHSMap.FPlayMode == TPlayMode.pmTurn && AoWE.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(TWindowPopupEvent.wpDiplomacy) && Trigger == TExecuteTrigger.etNewTurn;
                Show = Show || AoWE.AoWHSMap.FPlayMode == TPlayMode.pmSimultaneous && AoWE.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(TWindowPopupEvent.wpDiplomacy);
            }

            Show = Show && (Trigger == TExecuteTrigger.etUser || FAction.FReaction != TDiplomaticActionReaction.darIgnore);
            if (Show)
            {
                AoWE.AoWHSMap.TriggerExecuteEventLog(this, Mode, Done);
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:1188
        public void SetDiplomaticAction(TDiplomaticAction Action)
        {
            TDiplomaticAction Old;
            Old = FAction;
            if (Old != Action)
            {
                if (Old != null)
                {
                    Old.Release();
                }

                if (Action != null)
                {
                    FAction = (TDiplomaticAction)Action.Copy(AoWE.AoWEngine);
                }
                else
                {
                    FAction = null;
                }
            }
        }

