    public partial class TDiplomacyAIPA : TAIPlayerAction, IAIPlayerActionClass
    {
        // Diplomacy.pas:1540
        public TDiplomacyAIPA(TECustomNode owner) : base(owner)
        {
        }

        public sbyte FNextPlayer;
        // Diplomacy.pas:1543
        public override void Destroy()
        {
            base.Destroy();
        }

        // Diplomacy.pas:1549
        public override bool Activate()
        {
            bool Result = base.Activate();
            FNextPlayer = 0;
            return Result;
        }

        // Diplomacy.pas:1699
        public override bool Process()
        {
            bool Result;
            base.Process();
            if (FControl.FPlayer.FPlayerIndex != 0)
            {
                while (true)
                {
                    var count = AoWE.AoWHSMap.FPlayers.Count;
                    if (!(FNextPlayer < count && !FControl.FPlayer.GetBusy()))
                        break;
                    FNextPlayer = (sbyte)(FNextPlayer + 1);
                    while (true)
                    {
                        var fPlayersCount = AoWE.AoWHSMap.FPlayers.Count;
                        if (!(FNextPlayer < fPlayersCount && (FControl.FPlayer.GetFirstDaySeen((sbyte)(byte)FNextPlayer) == -1 || FControl.FPlayer.FPlayerIndex == FNextPlayer)))
                            break;
                        FNextPlayer = (sbyte)(FNextPlayer + 1);
                    }

                    var count2 = AoWE.AoWHSMap.FPlayers.Count;
                    if (FNextPlayer < count2)
                    {
                        ExecuteDiplomacy(FNextPlayer);
                    }
                }

                var count3 = AoWE.AoWHSMap.FPlayers.Count;
                Result = FNextPlayer < count3;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Diplomacy.pas:1552
        public TDiplomaticAction CreateDA(TDiplomaticActionType Action, sbyte Target, sbyte Other, int MinDays)
        {
            TDiplomaticAction Result;
            sbyte Player;
            TDiplomaticAction Last;
            Player = FControl.FPlayer.FPlayerIndex;
            Last = AoWE.AoWHSMap.FPlayers.GetPlayers(Player).FDiplomaticActions.FindLastAction(Action, TDiplomaticActionReaction.darNone, Player, Target, Other);
            if (Last == null || AoWE.AoWHSMap.FDay - Last.FDay >= MinDays)
            {
                Result = AoWE.AoWHSMap.FPlayers.GetPlayers(Player).CreateDiplomaticAction(Action, Target, Other);
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Diplomacy.pas:1563
        public bool ExecuteDiplomacy(sbyte Player)
        {
            TDiplomaticAction Action;
            TByteList Peace;
            TByteList War;
            TByteList Unknown;
            TByteList IdealPeace;
            TByteList IdealWar;
            TDoubleItemList Candidates;
            int Index;
            int Score;
            sbyte Source;
            sbyte Candidate;
            AnsiString ErrorText = default;
            // { Original bug: the result remains False even when an action is sent. }
            bool Result = false;
            Action = null;
            Source = FControl.FPlayer.FPlayerIndex;
            IdealPeace = new TByteList();
            IdealWar = new TByteList();
            Peace = new TByteList();
            War = new TByteList();
            Unknown = new TByteList();
            FControl.ListPeaceWarUnknownPlayers(Peace, War, Unknown);
            FControl.ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
            switch (AoWE.AoWHSMap.FPlayers.GetDiplomaticRelation((sbyte)(byte)Source, (sbyte)(byte)Player))
            {
                case TDiplomaticRelation.drUnknown:
                    if (IdealPeace.IndexOf((byte)Player) != -1)
                    {
                        if (FControl.CanOfferPeace((byte)Player))
                        {
                            Action = CreateDA(TDiplomaticActionType.daOfferPeace, Player, -1, 10);
                        }
                        else
                        {
                            Action = CreateDA(TDiplomaticActionType.daDeclareWar, Player, -1, -1);
                        }
                    }

                    if (IdealWar.IndexOf((byte)Player) != -1)
                    {
                        if (FControl.CanDeclareWar((byte)Player))
                        {
                            Action = CreateDA(TDiplomaticActionType.daDeclareWar, Player, -1, -1);
                        }
                        else
                        {
                            Action = CreateDA(TDiplomaticActionType.daOfferPeace, Player, -1, 10);
                        }
                    }

                    break;
                case TDiplomaticRelation.drPeace:
                    if (!FControl.CanOfferPeace((byte)Player) && IdealWar.IndexOf((byte)Player) != -1)
                    {
                        RandSeed = AoWE.AoWHSMap.FInitialRandomSeed + AoWE.AoWHSMap.FDay + Source;
                        Index = Random(IdealWar.Count);
                        if (IdealWar[Index] == Player)
                        {
                            Action = CreateDA(TDiplomaticActionType.daDeclareWar, Player, -1, -1);
                        }
                    }
                    else
                    {
                        if (FControl.CanProposeAlliance((byte)Player))
                        {
                            RandSeed = (int)(((uint)(AoWE.AoWHSMap.FInitialRandomSeed + AoWE.AoWHSMap.FDay + Source)) >> 2);
                            if (Random(100) < 30)
                            {
                                Action = CreateDA(TDiplomaticActionType.daProposeAlliance, Player, -1, 10);
                            }
                        }
                    }

                    break;
                case TDiplomaticRelation.drAlliance:
                    if (!FControl.CanOfferPeace((byte)Player) && IdealWar.IndexOf((byte)Player) != -1)
                    {
                        RandSeed = AoWE.AoWHSMap.FInitialRandomSeed + AoWE.AoWHSMap.FDay + Source + 1;
                        Index = Random(IdealWar.Count);
                        if (IdealWar[Index] == Player)
                        {
                            Action = CreateDA(TDiplomaticActionType.daBreakAlliance, Player, -1, -1);
                        }
                    }

                    break;
                case TDiplomaticRelation.drWar:
                    if (!FControl.CanDeclareWar((byte)Player))
                    {
                        Candidates = new TDoubleItemList();
                        for (int I = 0, last = IdealPeace.Count - 1; I <= last; I++)
                        {
                            Candidate = (sbyte)IdealPeace[I];
                            if (War.IndexOf((byte)Candidate) != -1 && FControl.CanOfferPeace((byte)Candidate))
                            {
                                Action = AoWE.AoWHSMap.FPlayers.GetPlayers(Source).FDiplomaticActions.FindLastAction(TDiplomaticActionType.daOfferPeace, TDiplomaticActionReaction.darNone, Source, Candidate, -1);
                                if (Action == null || AoWE.AoWHSMap.FDay - Action.FDay > 12)
                                {
                                    Score = -I;
                                    Score -= AoWE.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace)) * 5;
                                    Score -= AoWE.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drAlliance)) * 10;
                                    Candidates.AddAB(Candidate, Score);
                                }

                                Action = null;
                            }
                        }

                        if (Candidates.Count == 0 && War.Count - Peace.Count > 2)
                        {
                            for (int J = 0, last = IdealWar.Count - 1; J <= last; J++)
                            {
                                Candidate = (sbyte)IdealWar[J];
                                if (War.IndexOf((byte)Candidate) != -1)
                                {
                                    Action = AoWE.AoWHSMap.FPlayers.GetPlayers(Source).FDiplomaticActions.FindLastAction(TDiplomaticActionType.daOfferPeace, TDiplomaticActionReaction.darNone, Source, Candidate, -1);
                                    if (Action == null || AoWE.AoWHSMap.FDay - Action.FDay > 12)
                                    {
                                        Score = J;
                                        Score -= AoWE.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drPeace)) * 5;
                                        Score -= AoWE.AoWHSMap.FPlayers.GetDiplomaticRelationCount((sbyte)(byte)Candidate, TSet<TDiplomaticRelation>.Of(TDiplomaticRelation.drAlliance)) * 10;
                                        Candidates.AddAB(Candidate, Score);
                                    }

                                    Action = null;
                                }
                            }
                        }

                        if (Candidates.Count != 0)
                        {
                            Candidates.SortDescendingItemB();
                            if (Candidates[0].A == Player)
                            {
                                Action = CreateDA(TDiplomaticActionType.daOfferPeace, (sbyte)Candidates[0].A, -1, -1);
                            }
                        }

                        Candidates.Free();
                    }

                    break;
            }

            if (Action != null)
            {
                Action.Send(ref ErrorText);
                Action.Release();
            }

            Peace.Free();
            War.Free();
            Unknown.Free();
            IdealPeace.Free();
            IdealWar.Free();
            return Result;
        }

        // Diplomacy.pas:1670
        public void ListDebugInfo()
        {
            TByteList IdealPeace;
            TByteList IdealWar;
            int Player;
            AnsiString S;
            IdealPeace = new TByteList();
            IdealWar = new TByteList();
            FControl.ListIdealPeaceWarPlayers(IdealPeace, IdealWar);
            Player = FControl.FPlayer.FPlayerIndex;
            var players = AoWE.AoWHSMap.FPlayers.GetPlayers(Player);
            S = AoWE.TranslateRStr(AoWE.RaceNamesPluralRStr[players.FPlayerRace]);
            var name = AoWE.AoWHSMap.FPlayers.GetPlayers(Player).GetName();
            S = S + AnsiString.FromBytes(47) + name;
            AoWE.AoWEngine.OutputDebugMessage(AoWE.AIDID, (AnsiString)"DIPLOMACY (" + S + AnsiString.FromBytes(41));
            AoWE.AoWEngine.OutputDebugMessage(AoWE.AIDID, (AnsiString)"IDEAL PEACE PLAYERS");
            for (int I = 0, last = IdealPeace.Count - 1; I <= last; I++)
            {
                var item = IdealPeace[I];
                var fPlayersPlayers = AoWE.AoWHSMap.FPlayers.GetPlayers(item);
                S = AoWE.TranslateRStr(AoWE.RaceNamesPluralRStr[fPlayersPlayers.FPlayerRace]);
                var idealPeaceItem = IdealPeace[I];
                var name2 = AoWE.AoWHSMap.FPlayers.GetPlayers(idealPeaceItem).GetName();
                S = S + AnsiString.FromBytes(47) + name2;
                AoWE.AoWEngine.OutputDebugMessage(AoWE.AIDID, S);
            }

            AoWE.AoWEngine.OutputDebugMessage(AoWE.AIDID, (AnsiString)"IDEAL WAR PLAYERS");
            for (int I = 0, last = IdealWar.Count - 1; I <= last; I++)
            {
                var item = IdealWar[I];
                var name2 = AoWE.AoWHSMap.FPlayers.GetPlayers(item).GetName();
                AoWE.AoWEngine.OutputDebugMessage(AoWE.AIDID, name2);
            }

            IdealPeace.Free();
            IdealWar.Free();
        }

