        // Army.PAS:5915
        public int GetMajorVersion() => ((int)(((uint)FVersion) >> 24)) & 255;

        // Army.PAS:5918
        public int GetMinorVersion()
        {
            int Result = ((int)(((uint)FVersion) >> 16)) & 255;
            if (Result > 99)
            {
                Result = 99;
            }

            return Result;
        }

        // Army.PAS:5924
        public int GetBuildNumber()
        {
            int Result = FVersion & 65535;
            if (Result > 9999)
            {
                Result = 9999;
            }

            return Result;
        }

        // Army.PAS:5930
        public void SetVersion(int Major, int Minor, int Build)
        {
            if (Major < 0)
            {
                Major = 0;
            }

            if (Major > 99)
            {
                Major = 99;
            }

            if (Minor < 0)
            {
                Minor = 0;
            }

            if (Minor > 99)
            {
                Minor = 99;
            }

            if (Build < 0)
            {
                Build = 0;
            }

            if (Build > 9999)
            {
                Build = 9999;
            }

            FVersion = (Major << 24) + (Minor << 16) + Build;
        }

        // Army.PAS:5941
        public AnsiString GetVersionStr()
        {
            int Version;
            AnsiString Result = IntToStr(GetMajorVersion()) + AnsiString.FromBytes(46);
            Version = GetMinorVersion();
            if (Version < 10)
            {
                Result = Result + AnsiString.FromBytes(48) + IntToStr(Version) + AnsiString.FromBytes(46);
            }
            else
            {
                Result = Result + IntToStr(Version) + AnsiString.FromBytes(46);
            }

            Version = GetBuildNumber();
            if (Version < 1000)
            {
                Result = Result + AnsiString.FromBytes(48);
            }

            if (Version < 100)
            {
                Result = Result + AnsiString.FromBytes(48);
            }

            if (Version < 10)
            {
                Result = Result + AnsiString.FromBytes(48);
            }

            return Result + IntToStr(Version);
        }

