    public partial class TStructureConstructionControl : TConstructionControl
    {

        public TStructureConstructionControl(TECustomNode owner) : base(owner)
        {}

        // Structur.PAS:3195
        public override bool CanConstruct(TAbstractUnit A1, ref AnsiString A2) => ValidateLocation(A1, ref A2) && (base.CanConstruct(A1, ref A2) && StructureResource(A1) != null);

        // Structur.PAS:3201
        public override bool Construct(TAbstractUnit AUnit)
        {
            bool Result;
            TConstructStructureTE Event;
            AnsiString Reason = default;
            if (CanConstruct(AUnit, ref Reason) && !AoWE.AoWHSMap.FPlayers.GetPlayers(AUnit.FPlayer).GetBusy())
            {
                Event = new TConstructStructureTE(null);
                Event.FUnitID = AUnit.FUnitID;
                Event.FPlayer = AUnit.FPlayer;
                Event.FControlID = ID();
                AoWE.AoWHSMap.FTokenManager.GetTokenControl(AUnit.FPlayer).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:3162
        public virtual bool ValidateLocation(TAbstractUnit AUnit, ref AnsiString Reason)
        {
            TStructureResource Resource;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            TMapLevel Level;
            TAoWMapField MapField;
            THNWalkData Walk = default;
            bool Result = true;
            Resource = StructureResource(AUnit);
            AUnit.GetLocation(ref X, ref Y, ref L);
            Level = AoWE.AoWHSMap.MapContainer.GetMapLevel(L);
            InitHNWalk(ref Walk, X, Y, 0);
            while (Resource.TerrainList.Count > Walk.HN && Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    if (Resource.TerrainList.GetUsed(Walk.HN))
                    {
                        MapField = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                        Result = MapField.GetPlayer() == -1 || MapField.GetPlayer() == AUnit.FPlayer;
                        Result = Result && MapField.FindNoneTransparentHS(typeof(TStructure)) == null;
                        Result = Result && !TSet<byte>.WithBounds(0, 255).With(0).With(2).Contains((byte)MapField.OverlayType);
                        Result = Result && TSet<byte>.WithBounds(0, 255).With(12).WithRange(1, 5).Contains((byte)MapField.TerrainType);
                    }
                }
                else
                {
                    Result = false;
                }

                WalkToNextHN(ref Walk);
            }

            if (!Result)
            {
                Reason = AoWE.TranslateRStr(AoWE.CannotBuildOnCurrentLocationRStr);
            }

            return Result;
        }

