    public partial class TRebuildConstructionControl : TConstructionControl
    {
        public TRebuildConstructionControl(TECustomNode owner) : base(owner)
        {}

        // AoWAb.PAS:5404
        public TStructure GetStructure(TAbstractUnit AUnit)
        {
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            AUnit.GetLocation(ref X, ref Y, ref L);
            TStructure Result = (TStructure)AoWE.AoWHSMap.MapContainer.GetField(X, Y, L).FindNoneTransparentHS(typeof(TStructure));
            if (Result != null)
            {
                if (!Result.GetRazed() || Result.GetBuilding())
                {
                    Result = null;
                }
            }

            return Result;
        }

        // AoWAb.PAS:5413
        public override void GetInfo(TAbstractUnit AUnit, ref AnsiString Text, ref int Gold, ref int Days)
        {
            TStructure Structure;
            Structure = GetStructure(AUnit);
            if (Structure != null)
            {
                var editName = Structure.EditName();
                Text = AoWE.Format(AoWE.TranslateRStr(AoWE.P4RebuildXRStr), [editName]);
                Structure.GetRebuildInfo(ref Gold, ref Days);
            }
            else
            {
                var translateRStr = AoWE.TranslateRStr(AoWE.P4StructureRStr);
                Text = AoWE.Format(AoWE.TranslateRStr(AoWE.P4RebuildXRStr), [translateRStr]);
                Gold = 0;
                Days = 0;
            }
        }

        // AoWAb.PAS:5430
        public override bool CanConstruct(TAbstractUnit A1, ref AnsiString A2)
        {
            bool Result;
            if (GetStructure(A1) != null)
            {
                Result = base.CanConstruct(A1, ref A2);
            }
            else
            {
                A2 = AoWE.TranslateRStr(AoWE.P4NoRazedStructuresRStr);
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:5439
        public override bool Construct(TAbstractUnit AUnit)
        {
            bool Result;
            AnsiString Reason = default;
            if (CanConstruct(AUnit, ref Reason))
            {
                Result = GetStructure(AUnit).Rebuild(AUnit);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Engine.pas:524

        // AoWAb.PAS:5400
        public override int ID() => 1;

    }

