        public static bool HitRole(int AttackDefense)
        {
            AttackDefense = AttackDefense * 10 + 50;
            if (AttackDefense < 10)
            {
                AttackDefense = 10;
            }

            if (AttackDefense > 90)
            {
                AttackDefense = 90;
            }

            return Random(100) < AttackDefense;
        }

