            Chance = AttackDefense * 10 + 50;
            if (Chance < 10)
            {
                Chance = 10;
            }

            if (Chance > 90)
            {
                Chance = 90;
            }

            return (float)((double)Chance / 100);
        }

        // Combat.pas:1803
        public static int DMmaxDCtoDV(int Damage, int AttackDefense, int Maximum)
        {
            int Result;
            if (Damage > 0)
            {
                Result = DMDCtoDV(Damage, AttackDefense);
                // { Original updates only the unused Maximum parameter, leaving Result uncapped. }
                if (Damage > Maximum)
                {
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1814
        public static int DMDCtoDV(int Damage, int AttackDefense)
        {
            int Result;
            int Threshold;
            int Correction;
            if (Damage > 0)
            {
                Threshold = 10 - AttackDefense * 2;
                if (Threshold > 18)
                {
                    Result = Damage;
                }
                else
                {
                    if (Threshold >= 0)
                    {
                        Result = (int)(((uint)((Damage - 1) * (18 - Threshold) + 1)) >> 1) + (Damage + (18 - Threshold));
                        if (Threshold != 0)
                        {
                            Result += 1;
                        }
                    }
                    else
                    {
                        Result = Damage + 1 + (18 - Threshold) + (int)(((uint)((Damage - 1) * (18 - Threshold) + 1)) >> 1);
                        Threshold = -Threshold;
                        Correction = (int)(((uint)(((Damage - 1) * Threshold * Threshold + (Threshold + 19)) / (Threshold + 19))) >> 1);
                        Threshold = Correction + Threshold + 1;
                        Result = Result - Threshold;
                    }
                }

                Result = Result * 5;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1842
        public static int ExecuteDamageRole(int Damage, int AttackDefense)
        {
            int Result;
            int Roll;
            if (Damage > 0)
            {
                Roll = Random(20);
                if (Roll <= 1)
                {
                    Result = 0;
                }
                else
                {
                    if (Roll >= 18)
                    {
                        Result = Damage;
                    }
                    else
                    {
                        AttackDefense = 10 - AttackDefense * 2;
                        if (Roll >= AttackDefense && AttackDefense < 18)
                        {
                            Result = ((Damage - 1) * (Roll - AttackDefense) + (int)(((uint)(18 - AttackDefense)) >> 1)) / (18 - AttackDefense) + 1;
                        }
                        else
                        {
                            Result = 0;
                        }
                    }
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1863
        public static int DVtoDEV(int SourceDV, int TargetDV, TCombatObject Source, TCombatObject Target)
        {
            int Result;
            if (Target.GetTargetPriority() != 0)
            {
                var targetPriority = Target.GetTargetPriority();
                var hitPoints = Target.GetHitPoints();
                Result = Target.GetTargetPriority() + Round((double)targetPriority * ((double)SourceDV / (hitPoints * 100)));
                if (TargetDV != 0)
                {
                    var sourceTargetPriority = Source.GetTargetPriority();
                    var sourceHitPoints = Source.GetHitPoints();
                    Result = Result - (Source.GetTargetPriority() + Round((double)sourceTargetPriority * ((double)TargetDV / (sourceHitPoints * 100))));
                }
            }
            else
            {
                Result = SourceDV + -99999 - Source.GetTargetPriority() * TargetDV;
            }

            return Result;
        }

        // Combat.pas:1876
        public static int StatisticsToMaxDamage(int Damage, TSet<TDamageType> DamageTypes, TSet<TDamageType> ImmunityTypes, TSet<TDamageType> ProtectionTypes)
        {
            int Result;
            DamageTypes = DamageTypes - ImmunityTypes;
            if (DamageTypes != TSet<TDamageType>.Of())
            {
                if (DamageTypes - ProtectionTypes == TSet<TDamageType>.Of())
                {
                    Result = (int)(((uint)(Damage + 1)) >> 1);
                }
                else
                {
                    Result = Damage;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1888
        public static int StatisticsToDV(int Attack, int Damage, TSet<TDamageType> DamageTypes, int Defense, int Resistance, TSet<TDamageType> ImmunityTypes, TSet<TDamageType> ProtectionTypes)
        {
            int Result;
            DamageTypes = DamageTypes - ImmunityTypes;
            if (DamageTypes != TSet<TDamageType>.Of())
            {
                Attack = Attack - Defense;
                if (DamageTypes - ProtectionTypes == TSet<TDamageType>.Of())
                {
                    Damage = (int)(((uint)(Damage + 1)) >> 1);
                }

                Result = DMDCtoDV(Damage, Attack);
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1900
        public static int StatisticsToLimitedDV(int Attack, int Damage, TSet<TDamageType> DamageTypes, int Maximum, int Defense, int Resistance, TSet<TDamageType> ImmunityTypes, TSet<TDamageType> ProtectionTypes)
        {
            int Result;
            int Limit;
            int Limit100;
            Limit = Maximum;
            DamageTypes = DamageTypes - ImmunityTypes;
            if (DamageTypes != TSet<TDamageType>.Of())
            {
                Attack = Attack - Defense;
                if (DamageTypes - ProtectionTypes == TSet<TDamageType>.Of())
                {
                    Damage = (int)(((uint)(Damage + 1)) >> 1);
                }

                Result = DMmaxDCtoDV(Damage, Attack, Limit);
                Limit100 = Limit * 100;
                if (Result > Limit100)
                {
                    Result = Limit100;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat2.pas:523
        public static void DistributeCombatEvent(TCombatLogbook Logbook, bool Execute)
        {
            TCombatData Data;
            TCombatEventLog Event;
            Data = Logbook.FFinalData;
            for (int I = 1, last = AoWHSMap.FPlayers.GetCount() - 1; I <= last; I++)
            {
                if (AoWHSMap.VisibleForPlayer(Data.FX, Data.FY, Data.FL, (sbyte)I) || Logbook.FInitialData.FPlayers.IndexOfPlayer((byte)I) != -1)
                {
                    Event = new TCombatEventLog(null);
                    Event.SetCombatLogbook(Logbook);
                    AoWHSMap.FPlayers.GetPlayers(I).FEventLogbook.AddEvent(Event);
                    if (Execute && I == AoWHSMap.FSeatedPlayer && AoWHSMap.FPlayers.GetPlayers(I).FPlayerType == TPlayerType.ptHuman && Logbook.FFinalData.F_CombatData_30 != 6)
                    {
                        Event.Execute(false, TExecuteTrigger.etEvent, null);
                    }

                    Event.Release();
                }
            }
        }

