        // Diplomacy.pas:1420
        public static void RetrieveDefaultDiplomaticActionMessage(sbyte Source, sbyte Target, sbyte Other, TDiplomaticActionType Action, TDiplomaticActionReaction Reaction, TStrings Text)
        {
            AnsiString SourceRace;
            AnsiString TargetRace;
            AnsiString OtherRace;
            TDiplomaticRelation Relation;
            TTextControl TextControl;
            int Alignment;
            Text.Clear();
            TextControl = AoWHSSet.FTextControl;
            Relation = AoWHSMap.FPlayers.GetDiplomaticRelation(Source, Target);
            var players = AoWHSMap.FPlayers.GetPlayers(Source);
            SourceRace = TranslateRStr(RaceNamesPluralRStr[players.FPlayerRace]);
            var fPlayersPlayers = AoWHSMap.FPlayers.GetPlayers(Target);
            TargetRace = TranslateRStr(RaceNamesPluralRStr[fPlayersPlayers.FPlayerRace]);
            if (Other > 0)
            {
                var players2 = AoWHSMap.FPlayers.GetPlayers(Other);
                OtherRace = TranslateRStr(RaceNamesPluralRStr[players2.FPlayerRace]);
            }
            else
            {
                OtherRace = (AnsiString)"";
            }

            var players3 = AoWHSMap.FPlayers.GetPlayers(Source);
            var alignment = AoWHSSet.FRaceResources.GetRaceResource(players3.FPlayerRace).GetAlignment();
            if (TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(alignment))
            {
                Alignment = 0;
            }
            else
            {
                var players2 = AoWHSMap.FPlayers.GetPlayers(Source);
                var alignment2 = AoWHSSet.FRaceResources.GetRaceResource(players2.FPlayerRace).GetAlignment();
                if (TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(alignment2))
                {
                    Alignment = 2;
                }
                else
                {
                    Alignment = 1;
                }
            }

            switch (Action)
            {
                case TDiplomaticActionType.daDeclareWar:
                    if (Relation == TDiplomaticRelation.drUnknown)
                    {
                        TextControl.RetrieveText(Alignment + 151, Text);
                    }
                    else
                    {
                        TextControl.RetrieveText(Alignment + 100, Text);
                    }

                    Text.Text = Format(Text.Text, [SourceRace, TargetRace]);
                    break;
                case TDiplomaticActionType.daOfferPeace:
                    if (Reaction == TDiplomaticActionReaction.darNone)
                    {
                        if (Relation == TDiplomaticRelation.drUnknown)
                        {
                            TextControl.RetrieveText(Alignment + 103, Text);
                        }
                        else
                        {
                            TextControl.RetrieveText(Alignment + 154, Text);
                        }

                        Text.Text = Format(Text.Text, [SourceRace, TargetRace]);
                    }
                    else
                    {
                        if (Reaction == TDiplomaticActionReaction.darAccept)
                        {
                            TextControl.RetrieveText(Alignment + 127, Text);
                            Text.Text = Format(Text.Text, [TargetRace, SourceRace]);
                        }
                        else
                        {
                            if (Reaction == TDiplomaticActionReaction.darReject)
                            {
                                TextControl.RetrieveText(Alignment + 130, Text);
                                Text.Text = Format(Text.Text, [TargetRace, SourceRace]);
                            }
                        }
                    }

                    break;
                case TDiplomaticActionType.daProposeAlliance:
                    if (Reaction == TDiplomaticActionReaction.darNone)
                    {
                        TextControl.RetrieveText(Alignment + 106, Text);
                        Text.Text = Format(Text.Text, [SourceRace, TargetRace]);
                    }
                    else
                    {
                        if (Reaction == TDiplomaticActionReaction.darAccept)
                        {
                            TextControl.RetrieveText(Alignment + 121, Text);
