        // MoveT.PAS:1
        public static void MaximizeMovePointTable(Span<byte> Table, ReadOnlySpan<byte> Other)
        {
            sbyte OldValue;
            sbyte Value;
            for (int I = 0; I <= 12; I++)
            {
                for (int J = 0; J <= 15; J++)
                {
                    OldValue = MemoryMarshal.Cast<byte, FixedArray_Aow_Units_FixedArray_sbyte_16_16>(Table)[0][J][I];
                    Value = MemoryMarshal.Cast<byte, FixedArray_Aow_Units_FixedArray_sbyte_16_16>(Other)[0][J][I];
                    if (OldValue != -1 && (OldValue < Value || Value == -1))
                    {
                        MemoryMarshal.Cast<byte, FixedArray_Aow_Units_FixedArray_sbyte_16_16>(Table)[0][J][I] = Value;
                    }
                }
            }
        }

        // AoWAb.PAS:5492
        // { Shared original helper declarations required by the selected-army calls. }
        public static int RoadConstructionCost(sbyte Player, TMovepath Path, int MovePoints)
        {
            int I;
            int Points;
            TAoWMapField Field;
            int Result = 0;
            I = Path.Count;
            Points = 0;
            while (I != 0 && Points <= MovePoints)
            {
                I -= 1;
                Points += Path[I].Flag;
                if (Points <= MovePoints)
                {
                    var item = Path[I];
                    Field = (TAoWMapField)AoWHSMap.MapContainer.GetFieldXYL(item.XYL);
                    if (CanConstructRoad(Player, Field))
                    {
                        Result += 10;
                    }
                }
            }

            return Result;
        }

        // MoveT.PAS:3413
        public static bool ExecuteMultiArmyMove(TMoveSettingsList Moves)
        {
            bool Result = default;
            TMultiMoveTE Multi = default;
            TMovepath Path = default;
            TMoveSettings Settings = default;
            TArmyDefaultMoveTE Move = default;
            bool condition = Moves.Count != 0;
            if (condition)
            {
                var moveSettings = Moves.GetMoveSettings(0);
                condition = AoWHSMap.FTokenManager.PlayerReady(((TArmyHS)moveSettings.FMoveObject).FArmy.FPlayer);
            }

            if (condition)
            {
                Path = new TMovepath();
                Multi = new TMultiMoveTE(null);
                Multi.FSimultaneous = false;
                Moves.CalculateMovePositions(ValidateMultiArmyMove);
                for (int I = 0, last = Moves.Count - 1; I <= last; I++)
                {
                    Settings = Moves.GetMoveSettings(I);
                    if (Settings.FMovePos < Settings.FPath.Count - 1)
                    {
                        Path.Clear();
                        for (int J = Settings.FMovePos, lastJ = Settings.FPath.Count - 1; J <= lastJ; J++)
                        {
                            Path.Add(Settings.FPath[J]);
                        }

                        Move = new TArmyDefaultMoveTE(null);
                        var item = Path[0];
                        var pathItem = Path[0];
                        var item2 = Path[0];
                        AoWEngine.OutputDebugStr((AnsiString)"Moving to: " + IntToStr(item.X) + AnsiString.FromBytes(44) + IntToStr(pathItem.Y) + AnsiString.FromBytes(44) + IntToStr(item2.L));
                        if (Move.Setup((TArmyHS)Settings.FMoveObject, (byte)Settings.FSelection, Path, TSet<TArmyMoveModeElement>.Of()))
                        {
                            Multi.FEvents.Add(Move);
                        }

                        Move.Release();
                    }
                }

                if (Multi.FEvents.Count != 0)
                {
                    var moveSettings = Moves.GetMoveSettings(0);
                    AoWHSMap.FTokenManager.GetTokenControl(((TArmyHS)moveSettings.FMoveObject).FArmy.FPlayer).AddEvent(Multi);
                    Result = true;
                }
                else
                {
                    Result = false;
                }

                Multi.Release();
                Path.Free();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // MoveT.PAS:3107
        public static TMoveArmyTE CreateArmyMoveTE(TArmyHS Army, byte Selection, TMovepath Path, TMoveAction Action, TSet<TArmyMoveModeElement> Mode)
        {
            TMoveArmyTE Move;
            TMoveArmyTE Result = null;
            switch (Action)
            {
                case TMoveAction.maNormal:
                    Move = new TArmyDefaultMoveTE(null);
                    break;
                case TMoveAction.maCombine:
                    Move = new TArmyCombineMoveTE(null);
                    break;
                case TMoveAction.maAttack:
                    Move = new TArmyCombatMoveTE(null);
                    break;
                case TMoveAction.maNegotiate:
                    Move = new TArmyNegotiateMoveTE(null);
                    break;
                default:
                    Move = null;
                    break;
            }

            if (Move != null)
            {
                if (!Move.Setup(Army, Selection, Path, Mode))
                {
                    Result = null;
                    Move.Release();
                }
                else
                {
                    Result = Move;
                }
            }

            return Result;
        }

        // MoveT.PAS:3128
        public static TMoveArmyTE CreateArmyMoveXYLTE(TArmyHS Army, byte Selection, sbyte X, sbyte Y, sbyte L, TMoveAction Action, TSet<TArmyMoveModeElement> Mode)
        {
            TMoveArmyTE Result;
            TMoveControlSettings Settings;
            Settings = new TMoveControlSettings(null);
            var lhx = Army.GetLhx();
            var yhx = Army.GetYhx();
            Settings.SetSourcePos(Army.GetXhx(), yhx, lhx);
            Settings.FPlayer = Army.FArmy.FPlayer;
            Settings.FArmyHS = Army;
            Settings.FSelection = Selection;
            Settings.SetDestinationPos(X, Y, L);
            Army.FArmy.CreateMovePointTable(Selection, Bytes.Of(ref Settings.FMovePointTable));
            AoWHSMap.FMoveControl.ProcessMove(Settings);
            if (Settings.FPath.Count != 0)
            {
                Result = CreateArmyMoveTE(Army, Selection, Settings.FPath, Action, TSet<TArmyMoveModeElement>.Of());
            }
            else
            {
                Result = null;
            }

            Settings.Release();
            return Result;
        }

        // MoveT.PAS:3146
        public static bool MoveArmyEx(TArmyHS Army, byte Selection, TMovepath Path, TSet<TArmyMoveModeElement> Mode, bool Force)
        {
            int Pos;
            TMoveArmyTE Move;
            TMoveAction Action;
            bool Moved;
            Moved = false;
            if (Force || !AoWHSMap.FPlayers.GetPlayers(Army.FArmy.FPlayer).GetBusy())
            {
                if (Path.Count > 1)
                {
                    Pos = Path.MovePointsToPos(Army.FArmy.MovePoints(Selection));
                    if (Pos == 0)
                    {
                        var item = Path[Pos];
                        var pathItem = Path[Pos];
                        var item2 = Path[Pos];
                        Action = ((TAoWMapField)AoWHSMap.MapContainer.GetField(item2.X, pathItem.Y, item.L)).GetMoveAction(Army.FArmy.FPlayer);
                    }
                    else
                    {
                        Action = TMoveAction.maNormal;
                    }

                    bool condition = Action == TMoveAction.maAttack && AoWHSMap.FPlayers.GetPlayers(Army.FArmy.FPlayer).FPlayerType == TPlayerType.ptHuman;
                    if (condition)
                    {
                        var item = Path[0];
                        var pathItem = Path[0];
                        var item2 = Path[0];
                        condition = !AoWHSMap.VisibleForPlayer(item2.X, pathItem.Y, item.L, Army.FArmy.FPlayer);
                    }

                    if (condition)
                    {
                        Action = TMoveAction.maNormal;
                    }

                    Move = CreateArmyMoveTE(Army, Selection, Path, Action, Mode);
                    if (Move != null)
                    {
                        AoWHSMap.FTokenManager.GetTokenControl(Army.FArmy.FPlayer).AddEvent(Move);
                        Move.Release();
                        Moved = true;
                    }
                }
            }

            return Moved;
        }

