        public static TMoveArmyTE MoveArmyXYLEx(sbyte Player, TArmyHS Army, byte Selection, sbyte X, sbyte Y, sbyte L, TMoveAction Action, bool Force)
        {
            TMoveArmyTE Result;
            TMoveControlSettings Settings;
            Settings = new TMoveControlSettings(null);
            var lhx = Army.GetLhx();
            var yhx = Army.GetYhx();
            Settings.SetSourcePos(Army.GetXhx(), yhx, lhx);
            Settings.FPlayer = Army.FArmy.FPlayer;
            Settings.FArmyHS = Army;
            Settings.FSelection = Selection;
            Settings.SetDestinationPos(X, Y, L);
            Army.FArmy.CreateMovePointTable(Selection, Bytes.Of(ref Settings.FMovePointTable));
            AoWHSMap.FMoveControl.ProcessMove(Settings);
            if (Settings.FPath.Count != 0)
            {
                if ((Force || AoWHSMap.FTokenManager.PlayerReady(Player)) && Settings.FPath.Count > 1)
                {
                    Result = CreateArmyMoveTE(Army, Selection, Settings.FPath, Action, TSet<TArmyMoveModeElement>.Of());
                    if (Result != null)
                    {
                        AoWHSMap.FTokenManager.GetTokenControl(Player).AddEvent(Result);
                        // { Original returns the token-event pointer after releasing its reference. }
                        Result.Release();
                    }
                    else
                    {
                        Result = null;
                    }
                }
                else
                {
                    Result = null;
                }
            }
            else
            {
                Result = null;
            }

            Settings.Release();
            return Result;
        }

