        public static int StatusToStatusValue(TStatus Status)
        {
            int Result;
            switch ((int)Status)
            {
                case 0:
                    Result = 10;
                    break;
                case 1:
                    Result = 30;
                    break;
                case 2:
                    Result = 50;
                    break;
                case 3:
                    Result = 70;
                    break;
                case 4:
                    Result = 90;
                    break;
                default:
                    Result = 50;
                    // { Original constructs and leaks this exception without raising it. }
                    Exception.Create((AnsiString)"Invalid TStatus Value");
                    break;
            }

            return Result;
        }

        // PlayerC.PAS:2102
        public static TStatus StatusValueToStatus(int Value)
        {
            TStatus Result;
            if (Value <= 20)
            {
                Result = TStatus.sHostile;
            }
            else
            {
                if (Value > 80)
                {
                    Result = TStatus.sFriendly;
                }
                else
                {
                    switch (Value)
                    {
                        case >= 21 and <= 40:
                            Result = TStatus.sWary;
                            break;
                        case >= 41 and <= 60:
                            Result = TStatus.sNeutral;
                            break;
                        case >= 61 and <= 80:
                            Result = TStatus.sPolite;
                            break;
                        default:
                            Result = TStatus.sNeutral;
                            // { Original constructs and leaks this exception without raising it. }
                            Exception.Create((AnsiString)"Invalid StatusValue");
                            break;
                    }
                }
            }

            return Result;
        }

