        public static void TriggerStormDamage(TStormType Storm, sbyte X, sbyte Y, sbyte L, sbyte InnerRadius, sbyte OuterRadius, sbyte Player)
        {
            TMapFieldMsg Msg = default;
            THNWalkData Walk = default;
            TMapLevel Level;
            Level = AoWHSMap.MapContainer.MapLevels[L];
            Msg.MsgID = 4432;
            Msg.Param[0] = (int)Storm;
            Msg.Param[2] = Player;
            InitHNWalk(ref Walk, X, Y, InnerRadius);
            while (Walk.Radius <= OuterRadius)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
