        public static int GetUnitIndexAIPriority(int UnitIndex, sbyte Player, sbyte Relation)
        {
            int Result;
            TUnitResource Resource;
            int Value;
            TUnit Unit_;
            TAdjustableUnit DefaultUnit;
            Resource = AoWHSSet.FUnitResources.GetUnitResource(UnitIndex);
            if (Resource != null && Resource.GetTransportCapacity() == 0)
            {
                if (Player != 0)
                {
                    if (Resource.FRace != -1)
                    {
                        Value = AoWHSMap.FRaces.GetRace(Resource.FRace).GetPlayerRelationValue(Player);
                    }
                    else
                    {
                        var players = AoWHSMap.FPlayers.GetPlayers(Player);
                        var alignment = AoWHSSet.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                        Value = dAlignmentToStatusValue[(int)Resource.FAlignment][(int)alignment];
                    }
                }
                else
                {
                    var iRtoAlignment = IRtoAlignment(Relation);
                    Value = dAlignmentToStatusValue[(int)Resource.FAlignment][(int)iRtoAlignment];
                }

                if (Value >= 50)
                {
                    Unit_ = new TUnit(null);
                    Unit_.SetUnitResource(Resource);
                    DefaultUnit = new TAdjustableUnit(null);
                    DefaultUnit.MakeDefaultLevelUnit(1);
                    if (Unit_.GetCombatValue(DefaultUnit, 0) > 0)
                    {
                        Result = Unit_.GetStrengthMax(dtAll - TSet<TDamageType>.Of(TDamageType.dtWall)) / 100 + (Resource.FLevel * 100 + Resource.FMoves * 10 + Value / 2);
                        if (Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(57) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(58))
                        {
                            Result += 100;
                        }

                        if (Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(13))
                        {
                            Result += 150;
                        }

                        if (AoWHSMap != null && AoWHSMap.FDay > 20 && (Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(20) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(19) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(18) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(121) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(88) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(89)))
                        {
                            Result += 100;
                        }

                        if (Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(1) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(36) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(66) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(24) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(44) || Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(117) && Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(21))
                        {
                            Result += 100;
                        }

                        if (Resource.FAbilities[(int)TUnitRank.urNone].GetAbSet(65))
                        {
                            Result = Result / 2;
                        }
                    }
                    else
                    {
                        Result = -1;
                    }

                    DefaultUnit.Free();
                    Unit_.Free();
                }
                else
                {
                    Result = -1;
                }
            }
            else
            {
                Result = -1;
            }

            return Result;
