        // PlayerC.PAS:2543
        public static sbyte UnitsToIndependentRelation(TUnitList Units, sbyte DefaultRelation)
        {
            sbyte Result;
            bool SameRace;
            bool Evil;
            bool Good;
            bool Neutral;
            int I;
            int Race;
            TAbstractUnit Unit_;
            TAlignment Alignment;
            sbyte Relation;
            Relation = -1;
            SameRace = true;
            I = Units.FChildren.Count;
            while (SameRace && I != 0)
            {
                I -= 1;
                Race = ((TAbstractUnit)Units.FChildren.List[I]).GetRace();
                if (Race != -1 && Race != Relation)
                {
                    if (Relation == -1)
                    {
                        Relation = (sbyte)Race;
                    }
                    else
                    {
                        SameRace = false;
                    }
                }
            }

            if (SameRace && Relation == -1)
            {
                Relation = DefaultRelation;
            }

            if (Relation == -1)
            {
                SameRace = false;
            }

            I = Units.FChildren.Count;
            while (SameRace && I != 0)
            {
                I -= 1;
                bool condition = Relation == ((TAbstractUnit)Units.FChildren.List[I]).GetRace();
                if (!condition)
                {
                    var alignment = ((TAbstractUnit)Units.FChildren.List[I]).GetAlignment();
                    condition = AoWHSSet.FRaceResources.GetRaceResource(Relation).FAlignments.Contains(alignment);
                }

                SameRace = condition;
            }

            if (!SameRace)
            {
                Evil = true;
                Good = true;
                Neutral = true;
                I = 0;
                int last = Units.FChildren.Count - 1;
                for (; I <= last; I += 1)
                {
                    Unit_ = (TAbstractUnit)Units.FChildren.List[I];
                    Alignment = Unit_.GetAlignment();
                    Evil = Evil && alsEvil.Contains(Alignment) && (Unit_.GetRace() == -1 || TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(Alignment));
                    Good = Good && alsGood.Contains(Alignment) && (Unit_.GetRace() == -1 || TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(Alignment));
                    Neutral = Neutral && alsNeutral.Contains(Alignment);
                }

                if (Good && !Evil)
                {
                    Result = -2;
                }
                else
                {
                    if (Evil && !Good)
                    {
                        Result = -4;
                    }
                    else
                    {
                        Result = -3;
                    }
                }
            }
            else
            {
                Result = Relation;
            }

            return Result;
        }

