        // PlayerC.PAS:2623
        public static int ListMovementGaps(TAoWHSMap Map, TMovepath Path, FixedArray_Aow_Units_FixedArray_sbyte_16_16 Table, TIntegerList Starts, TIntegerList Ends)
        {
            int I;
            bool Gap;
            TMapField Field;
            I = Path.Count - 1;
            int Result = 0;
            Gap = false;
            while (I > 1)
            {
                I -= 1;
                var item = Path[I];
                var pathItem = Path[I];
                var item2 = Path[I];
                Field = Map.MapContainer.GetField(item2.X, pathItem.Y, item.L);
                if (Table[Field.TerrainType][Field.OverlayType - -1] == -1)
                {
                    if (!Gap)
                    {
                        Result += 1;
                        if (Starts != null)
                        {
                            Starts.Add(I);
                        }

                        Gap = true;
                    }
                }
                else
                {
                    if (Gap)
                    {
                        if (Ends != null)
                        {
                            Ends.Add(I);
                        }

                        Gap = false;
                    }
                }
            }

            if (Gap && Ends != null)
            {
                Ends.Add(1);
            }

            return Result;
        }

        // PlayerC.PAS:2649
        public static int GetMovepathBattleFieldStrength(sbyte Player, sbyte IndependentRelation, TMovepath Movepath, int TargetRange, int Range, int Step)
        {
            int Result;
            TUnitUserList Units;
            int I;
            int J;
            int Distance;
            THNWalkData Walk = default;
            TBattleFieldInfo Info = default;
            TMapLevel Level;
            TAoWMapField Field;
            TArmyHS Army;
            if (Movepath != null && Movepath.Count > 0)
            {
                Distance = Round((double)Range * 0.5);
                Result = 0;
                I = Movepath.Count - 1;
                Units = null;
                if (Movepath.Count - TargetRange < I)
                {
                    I = Movepath.Count - TargetRange;
                }

                SetupBattleFieldInfo(ref Info, Player, IndependentRelation, TSet<TBattleFieldInfoRequestsElement>.Of(), dtAll - TSet<TDamageType>.Of(TDamageType.dtWall));
                Info.FriendlyRelations = TSet<byte>.WithBounds(0, 7);
                Info.Requests = Info.Requests + TSet<TBattleFieldInfoRequestsElement>.Of(TBattleFieldInfoRequestsElement.bfrIgnorePassiveIndependents, TBattleFieldInfoRequestsElement.bfrEffectiveStrength);
                if (Step > 0)
                {
                    Units = new TUnitUserList(null);
                    var item = Movepath[Movepath.Count - 1];
                    Level = AoWHSMap.MapContainer.MapLevels[item.L];
                    var movepathItem = Movepath[Movepath.Count - 1];
                    var item2 = Movepath[Movepath.Count - 1];
                    InitHNWalk(ref Walk, item2.X, movepathItem.Y, 0);
                    while (Walk.Radius <= Step)
                    {
                        if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                        {
                            Field = (TAoWMapField)Level.GetField(Walk.X, Walk.Y);
                            if ((Field.FFieldFlags & 67108864) != 0)
                            {
                                Army = Field.GetArmyHS();
                                if (Army != null && Army.FArmy.FPlayer != Player)
                                {
                                    Units.AddUnits(Army.FArmy);
                                }
                            }
                        }

                        WalkToNextHN(ref Walk);
                    }

                    Info.Units = Units;
                }

                while (I >= 0)
                {
                    Info.Strength = 0;
                    var item = Movepath[I];
                    var movepathItem = Movepath[I];
                    var item2 = Movepath[I];
                    AoWHSMap.RetrieveBattleFieldInfo(item2.X, movepathItem.Y, item.L, Range, ref Info);
                    if (Info.Strength > Result)
                    {
                        Result = Info.Strength;
                    }

                    J = I;
                    while (true)
                    {
                        bool condition = J >= 0;
                        if (condition)
                        {
                            var item3 = Movepath[J];
                            var item4 = Movepath[I];
                            condition = item3.L == item4.L;
                        }

                        if (!(condition && J > I - Distance))
                            break;
                        J -= 1;
                    }

                    bool test = J == 0;
                    if (!test)
                    {
                        var item3 = Movepath[I];
                        var item4 = Movepath[J];
                        test = item3.L != item4.L;
                    }

                    if (test)
                    {
                        if (J - 1 != I)
                        {
                            Info.Strength = 0;
                            var item3 = Movepath[J + 1];
                            var item4 = Movepath[J + 1];
                            var item5 = Movepath[J + 1];
                            AoWHSMap.RetrieveBattleFieldInfo(item5.X, item4.Y, item3.L, Range, ref Info);
                            if (Info.Strength > Result)
                            {
                                Result = Info.Strength;
                            }
                        }
                    }

                    I = J;
                }

                if (Units != null)
                {
                    Units.Free();
                }

                AoWHSMap.FAIExecuter.UseProcessTime(50);
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // PlayerC.PAS:2704
        public static int GetBattleFieldStrengthAdvantage(int Location, sbyte Player, sbyte Relation, TUnitList Units, int FriendlyRadius, int EnemyRadius, TSet<TDamageType> DamageTypes)
        {
            TBattleFieldInfo Info = default;
            int FriendlyStrength;
            int EnemyStrength;
            SetupBattleFieldInfo(ref Info, Player, Relation, TSet<TBattleFieldInfoRequestsElement>.Of(), DamageTypes);
            Info.EnemyRelations = TSet<byte>.WithBounds(0, 7);
            Info.Units = Units;
            Info.Requests = Info.Requests + TSet<TBattleFieldInfoRequestsElement>.Of(TBattleFieldInfoRequestsElement.bfrIgnorePassiveIndependents);
            AoWHSMap.RetrieveBattleFieldInfo(Unsafe.As<int, TXYL>(ref Location).X, Unsafe.As<int, TXYL>(ref Location).Y, Unsafe.As<int, TXYL>(ref Location).L, FriendlyRadius, ref Info);
            FriendlyStrength = Info.FriendlyStrength;
            SetupBattleFieldInfo(ref Info, Player, Relation, TSet<TBattleFieldInfoRequestsElement>.Of(), DamageTypes);
            Info.FriendlyRelations = TSet<byte>.WithBounds(0, 7);
            Info.Units = Units;
            Info.Requests = Info.Requests + TSet<TBattleFieldInfoRequestsElement>.Of(TBattleFieldInfoRequestsElement.bfrIgnorePassiveIndependents);
            AoWHSMap.RetrieveBattleFieldInfo(Unsafe.As<int, TXYL>(ref Location).X, Unsafe.As<int, TXYL>(ref Location).Y, Unsafe.As<int, TXYL>(ref Location).L, EnemyRadius, ref Info);
            EnemyStrength = Info.Strength;
            return FriendlyStrength - EnemyStrength;
        }

        // Structur.PAS:3601
        public static int IgnitionChance(TAoWMapField MapField)
        {
            int Result;
            if (TSet<byte>.WithBounds(0, 255).With(12).WithRange(1, 5).Contains((byte)MapField.TerrainType) && MapField.FindOwnedChild(132990) == null && !MapField.GetMagicShieldActive())
            {
                if (MapField.OverlayType == 1)
                {
                    if (MapField.TerrainType == 3)
                    {
                        Result = 40;
                    }
                    else
                    {
                        if (MapField.TerrainType == 2)
                        {
                            Result = 80;
                        }
                        else
                        {
                            Result = 60;
                        }
                    }
                }
                else
                {
                    if (MapField.OverlayType == 3)
                    {
                        if (MapField.TerrainType == 3)
                        {
                            Result = 10;
                        }
                        else
                        {
                            if (MapField.TerrainType == 2)
                            {
                                Result = 30;
                            }
                            else
                            {
                                Result = 20;
                            }
                        }
                    }
                    else
                    {
                        if (MapField.TerrainType == 3)
                        {
                            Result = 1;
                        }
                        else
                        {
                            Result = 5;
                        }
                    }
                }

                if (MapField.FindNoneTransparentHS(typeof(TStructure)) != null)
                {
                    Result += 5;
                    if (AoWHSMap != null && AoWHSMap.FGlobalMagicControl.FActiveEnchantments.Contains(TGlobalEnchantmentType.getFireMastery))
                    {
                        Result += 5;
                    }
                }

                if (Result < 0)
                {
                    Result = 0;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

