        public static int StrikeDV(TCombatObject A1, TCombatObject A2)
        {
            int Result;
            sbyte Attack;
            sbyte Damage;
            TSet<TDamageType> Types;
            if (A1.GetAbilityEnabled(21))
            {
                Attack = A1.GetAttack();
                Damage = A1.GetDamage();
                Types = MeleeDamageTypes(A1);
                bool condition = A1.GetAbilityEnabled(146) || A1.GetAbilityEnabled(160);
                if (condition)
                {
                    var alignment = A2.GetAlignment();
                    condition = TSet<TAlignment>.Of(TAlignment.alEvil, TAlignment.alPureEvil).Contains(alignment);
                }

                if (condition)
                {
                    Attack = (sbyte)(Attack + 2);
                    Damage = (sbyte)(Damage + 2);
                }

                bool test = A1.GetAbilityEnabled(147) || A1.GetAbilityEnabled(161);
                if (test)
                {
                    var alignment = A2.GetAlignment();
                    test = TSet<TAlignment>.Of(TAlignment.alPureGood, TAlignment.alGood).Contains(alignment);
                }

                if (test)
                {
                    Attack = (sbyte)(Attack + 2);
                    Damage = (sbyte)(Damage + 2);
                }

                if (A1.GetAbilityEnabled(112) && A2.GetAbilityEnabled(63))
                {
                    Attack = (sbyte)(Attack + 3);
                    Damage = (sbyte)(Damage + 3);
                }

                Result = StatisticsToLimitedDV(Attack, Damage, Types, A2.GetHitPoints(), A2.GetDefense(), A2.GetResistance(), A2.GetImmunityTypes(), A2.GetProtectionTypes());
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

