        public static int CompareUnitProductionLevel(object Item1, object Item2)
        {
            int Level1;
            int Level2;
            var unitProduction = (TUnitProduction)Item1;
            if (AoWHSSet.FUnitResources.GetUnitResource(unitProduction.FUnitIndex) != null)
            {
                Level1 = AoWHSSet.FUnitResources.GetUnitResource(unitProduction.FUnitIndex).FLevel * 2;
            }
            else
            {
                Level1 = 0;
            }

            if (AoWHSSet.FUnitResources.GetUnitResource(((TUnitProduction)Item2).FUnitIndex) != null)
            {
                Level2 = AoWHSSet.FUnitResources.GetUnitResource(((TUnitProduction)Item2).FUnitIndex).FLevel * 2;
            }
            else
            {
                Level2 = 0;
            }

            int Result = Level1 - Level2;
            if (Result == 0)
            {
                Result = ((TUnitProduction)Item1).FUnitIndex - ((TUnitProduction)Item2).FUnitIndex;
            }

            return Result;
        }

