        // UnitRes.PAS:254
        public static int P2CompareUnitIndexes(int Item1, int Item2)
        {
            Assert(AoWHSSet.FUnitResources.GetUnitResource(Item1) != null && AoWHSSet.FUnitResources.GetUnitResource(Item1) != null, (AnsiString)"Undefined UnitResource Used!", "UnitRes.PAS", 256);
            var unitResource = AoWHSSet.FUnitResources.GetUnitResource(Item2);
            var fUnitResourcesUnitResource = AoWHSSet.FUnitResources.GetUnitResource(Item1);
            return unitResource.FLevel - fUnitResourcesUnitResource.FLevel;
        }

        // Army.PAS:4599
        public static int CompareItemNames(object Item1, object Item2)
        {
            int Result;
            if (Item1 != null && Item2 != null)
            {
                Result = CompareText(((TItem)Item1).FOwnerName, ((TItem)Item2).FOwnerName);
                if (Result == 0)
                {
                    Result = ((TObject)Item1).InstanceId - ((TObject)Item2).InstanceId;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Army.PAS:4612
        public static int CompareItemTypes(object Item1, object Item2)
        {
            // { Original type comparison assumes both entries are non-nil. }
            int Result = (int)((TItem)Item1).FItemType - (int)((TItem)Item2).FItemType;
            if (Result == 0)
            {
                Result = ((TObject)Item1).InstanceId - ((TObject)Item2).InstanceId;
            }

            return Result;
        }

